def _env_num(name, default):
    try:
        return float(os.environ.get(name, "") or default)
    except ValueError:
        return default


def _port_arg():
    """--port N on the command line, else KIRU_PORT (set by the launcher for a second window), else 5000."""
    try:
        if "--port" in sys.argv:
            return int(sys.argv[sys.argv.index("--port") + 1])
        return int(os.environ.get("KIRU_PORT") or PORT_FIRST)
    except (ValueError, IndexError):
        return PORT_FIRST


