def wipe_temp():
    """Delete the whole temp folder (best effort - files may be locked)."""
    if os.path.isdir(TEMP_DIR):
        shutil.rmtree(TEMP_DIR, ignore_errors=True)


def wipe_stale_instances():
    """Temp folders and tab auto-saves of Kiru windows that are not running any more (a window that ended badly leaves them behind)."""
    try:
        names = os.listdir(BASE_DIR)
    except OSError:
        return
    for name in names:
        m = re.fullmatch(r"_temp_(\d{4,5})", name)
        if m and int(m.group(1)) != PORT and not _port_open(int(m.group(1))):
            shutil.rmtree(os.path.join(BASE_DIR, name), ignore_errors=True)
        if name.startswith(os.path.basename(AUTOSAVE_FILE) + "_tab"):
            _rm(os.path.join(BASE_DIR, name))


def _port_open(port):
    """Is something listening on this port? Asked by trying to take the port ourselves, which answers at once.
    (Knocking on a closed local port makes Windows wait: with twenty ports to look at that was the slow start.)"""
    import socket as _s
    sk = _s.socket(_s.AF_INET, _s.SOCK_STREAM)
    try:
        sk.setsockopt(_s.SOL_SOCKET, _s.SO_EXCLUSIVEADDRUSE if os.name == "nt" else _s.SO_REUSEADDR, 1)
        sk.bind((HOST, port))
        return False
    except OSError:
        pass
    finally:
        sk.close()
    with _s.socket(_s.AF_INET, _s.SOCK_STREAM) as ck:      # the port could not be taken: is somebody really listening (or is it only just closed)?
        ck.settimeout(0.3)
        return ck.connect_ex((HOST, port)) == 0


def make_temp():
    for d in (TEMP_DIR, UPLOAD_DIR, WORK_DIR, EXPORT_DIR):
        os.makedirs(d, exist_ok=True)


def purge_old_exports(max_age=EXPORT_MAX_AGE_SEC):
    """Delete export files older than max_age seconds. Returns count removed."""
    removed = 0
    now = time.time()
    if not os.path.isdir(EXPORT_DIR):
        return 0
    for name in os.listdir(EXPORT_DIR):
        path = os.path.join(EXPORT_DIR, name)
        try:
            if os.path.isfile(path) and now - os.path.getmtime(path) > max_age:
                os.remove(path)
                removed += 1
        except OSError:
            pass  # locked / already gone - try again next pass
    return removed


def job_release(jid):
    """A render has ended (finished, failed or cancelled): its plan is not needed any more. A plan carries every text picture and
    overlay of the edit, easily tens of MB, so it is dropped here instead of living on until the video is saved or thrown away."""
    j = JOBS.get(jid)
    if j:
        j["plan"], j["tl"], j["proc"] = None, None, None
        j.setdefault("ended", time.time())
    import gc
    gc.collect()


def mem_sweep(max_age=EXPORT_MAX_AGE_SEC):
    """Housekeeping for long sessions: finished work that nobody collected is forgotten, so Python's memory stays flat.
    Returns how many things were dropped."""
    now, n = time.time(), 0
    for jid, j in list(JOBS.items()):                      # renders that ended more than 2 hours ago (their file is purged then, too)
        if j.get("status") in ("done", "error", "cancelled") and now - j.get("ended", j.get("finished", j.get("started", now))) > max_age and not j.get("queue"):
            JOBS.pop(jid, None)
            n += 1
    for store in (globals().get("TPL_JOBS") or {}, globals().get("TRACK_JOBS") or {}):     # template analyses / object tracking that ended long ago
        for jid, j in list(store.items()):
            if j.get("status") != "running" and now - j.get("t0", j.setdefault("t_seen", now)) > max_age:
                store.pop(jid, None)
                n += 1
    hits = globals().get("_TPL_HITS")
    if isinstance(hits, dict) and len(hits) > 400:
        hits.clear()
        n += 1
    if n:
        import gc
        gc.collect()
    return n


def janitor_loop():
    while True:
        time.sleep(JANITOR_INTERVAL_SEC)
        n = purge_old_exports()
        if n:
            log.info(f"[cleanup] Removed {n} unsaved export(s) older than 2 hours.")
        try:
            mem_sweep()
        except Exception:
            pass
        try:
            ai_idle_free()
        except Exception:
            pass


def ai_idle_free(idle=600):
    """The picture cut-out models (several hundred MB) are dropped from memory when nothing has used them for 10 minutes.
    They load again by themselves the next time they are needed."""
    R = globals().get("_REMBG")
    if not R or (R.get("session") is None and R.get("fine") is None):
        return False
    if time.time() - R.get("used", 0) < idle or not R["lock"].acquire(blocking=False):
        return False
    try:
        R["session"], R["fine"] = None, None
    finally:
        R["lock"].release()
    import gc
    gc.collect()
    log.info("[memory] AI cut-out models unloaded after 10 idle minutes.")
    return True


_cleaned_up = False


def shutdown_cleanup():
    global _cleaned_up
    if _cleaned_up:
        return
    _cleaned_up = True
    for job in list(JOBS.values()):          # stop any running render first
        proc = job.get("proc")
        if proc and proc.poll() is None:
            try:
                proc.kill()
            except Exception:
                pass
    procs = list(CLIPS.values()) + list(TRACK_JOBS.values()) + [st for c in list(CLIPS.values()) for st in (c.get("scrub") or {}).values()]
    for mj in [c["matte"] for c in list(CLIPS.values()) if c.get("matte")]:
        mj["cancel"] = True
        procs.append(mj)
        if mj.get("proc2"):
            procs.append({"proc": mj["proc2"]})
    for q in QUEUE:
        q["cancel"] = True
    for c in procs:            # and any preview conversion / scrub copy
        proc = c.get("proc")
        if proc and proc.poll() is None:
            try:
                proc.kill()
            except Exception:
                pass
    log.info("\n[cleanup] Wiping temp folder...")
    wipe_temp()
    autosave_clear()                                       # a normal exit: there is nothing to recover
    log.info("[cleanup] Done.")


def install_close_handlers():
    """Make sure temp is wiped on Ctrl+C, normal exit AND closing the console window."""
    atexit.register(shutdown_cleanup)

    def _sig(_signum, _frame):
        shutdown_cleanup()
        os._exit(0)

    for s in ("SIGINT", "SIGTERM", "SIGBREAK"):
        if hasattr(signal, s):
            try:
                signal.signal(getattr(signal, s), _sig)
            except (ValueError, OSError):
                pass

    # Windows: clicking the X on the console window sends CTRL_CLOSE_EVENT,
    # which kills Python before atexit runs. Catch it directly.
    if sys.platform == "win32":
        try:
            import ctypes
            from ctypes import wintypes

            HandlerRoutine = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.DWORD)

            def _console_handler(ctrl_type):
                # 0=Ctrl+C 1=Ctrl+Break 2=Close 5=Logoff 6=Shutdown
                if ctrl_type in (2, 5, 6):
                    shutdown_cleanup()
                return False  # let Windows continue closing

            install_close_handlers._win_handler = HandlerRoutine(_console_handler)
            ctypes.windll.kernel32.SetConsoleCtrlHandler(
                install_close_handlers._win_handler, True)
        except Exception as e:  # never block startup over this
            log.info(f"[warn] Could not hook console close event: {e}")


