NO_WINDOW = subprocess.CREATE_NO_WINDOW if sys.platform == "win32" else 0


def run(cmd, timeout=None):
    return subprocess.run(cmd, capture_output=True, text=True, timeout=timeout,
                          creationflags=NO_WINDOW, encoding="utf-8", errors="replace")


def tool_version(name):
    """Return first line of `<tool> -version`, or None if missing."""
    exe = shutil.which(name)
    if not exe:
        return None
    try:
        out = run([exe, "-version"], timeout=10)
        return out.stdout.splitlines()[0] if out.stdout else exe
    except Exception:
        return None


_ffmpeg_major = "unset"


def ffmpeg_major():
    """6 for 'ffmpeg version 6.1.1', None for git/date builds (treated as new)."""
    global _ffmpeg_major
    if _ffmpeg_major == "unset":
        v = tool_version("ffmpeg") or ""
        m = re.search(r"version\s+n?(\d+)\.", v)
        _ffmpeg_major = int(m.group(1)) if m else None
    return _ffmpeg_major


def filter_script_args(path):
    """Long filtergraphs go in a file (Windows has a 32k command-line limit).
    FFmpeg 7+ uses '-/filter_complex file'; older uses -filter_complex_script."""
    major = ffmpeg_major()
    if major is not None and major < 7:
        return ["-filter_complex_script", path]
    return ["-/filter_complex", path]


def safe_ext(name):
    ext = os.path.splitext(name or "")[1].lower()
    return ext if re.fullmatch(r"\.[a-z0-9]{1,5}", ext) else ""


ORIGIN = {}          # upload id -> where that file lives on this PC, when Kiru knows it (lets a saved project find it again)
LOCAL_EXT = {".mp4", ".mov", ".mkv", ".webm", ".avi", ".m4v", ".wmv", ".flv", ".mpg", ".mpeg", ".ts", ".mts", ".m2ts", ".gif",
             ".png", ".jpg", ".jpeg", ".webp", ".bmp", ".tif", ".tiff", ".heic",
             ".mp3", ".wav", ".m4a", ".aac", ".flac", ".ogg", ".opus", ".wma", ".aiff", ".aif"}


class LocalFile:
    """A media file read straight from this PC (opening a saved project) instead of an upload."""

    def __init__(self, path):
        self.path = os.path.abspath(path)
        self.filename = os.path.basename(path)

    def save(self, dst):
        shutil.copyfile(self.path, dst)


def media_upload():
    """The file of this request: an upload, or 'local_path' = a media file on this PC."""
    f = request.files.get("file")
    if f and f.filename:
        return f
    p = (request.form.get("local_path") or "").strip().strip('"')
    if p and os.path.isfile(p) and os.path.splitext(p)[1].lower() in LOCAL_EXT:
        return LocalFile(p)
    return None


def save_upload(f, folder):
    uid = uuid.uuid4().hex[:12]
    path = os.path.join(folder, uid + safe_ext(f.filename))
    f.save(path)
    try:
        src = getattr(f, "path", None) or (request.form.get("src_path") or "").strip()
        if src and os.path.isfile(src):
            ORIGIN[uid] = os.path.abspath(src)
    except Exception:
        pass
    return uid, path


def probe(path):
    """Run ffprobe and return its JSON as a dict."""
    out = run(["ffprobe", "-v", "error", "-print_format", "json",
               "-show_format", "-show_streams", path], timeout=60)
    if out.returncode != 0:
        raise RuntimeError(out.stderr.strip() or "ffprobe could not read this file")
    return json.loads(out.stdout)


def err(msg, code=400):
    return jsonify({"error": msg}), code


