def get_librosa():
    global _librosa
    with _librosa_lock:
        if _librosa is None:
            import librosa  # noqa
            _librosa = librosa
    return _librosa


BOOT = {"t0": time.time(), "warm": False, "started": False}


def warm_up_librosa():
    try:
        get_librosa()
    except Exception as e:
        log.info(f"[warn] librosa failed to load: {e}")
    finally:
        BOOT["warm"] = True


# ---------------------------------------------------------------------------
# Song analysis
# ---------------------------------------------------------------------------
PEAK_DIR = os.path.join(BASE_DIR, "_cache", "waveforms")      # waveforms survive a restart: a file that was imported once is not decoded again
PEAK_LOW = 25                                                 # values per second of the small waveform (the full one has 100)


def _peak_key(path):
    """A name for this file's waveform that stays the same wherever the file lies: its size and its first and last 64 KB."""
    import hashlib
    h, n = hashlib.md5(), os.path.getsize(path)
    h.update(str(n).encode())
    with open(path, "rb") as f:
        h.update(f.read(65536))
        if n > 131072:
            f.seek(n - 65536)
            h.update(f.read(65536))
    return h.hexdigest()


def peaks_low(peaks, rate):
    """The small waveform (PEAK_LOW values a second): the loudest of every few values of the full one."""
    k = max(1, int(round(rate / PEAK_LOW)))
    return ([max(peaks[i:i + k]) for i in range(0, len(peaks), k)], rate / k) if k > 1 else (peaks, rate)


def song_peaks(path):
    """The waveform of a file's sound (full resolution). Read from the waveform cache on disk when this file was seen before;
    otherwise decoded once and written there, together with its small version."""
    key = None
    try:
        key = _peak_key(path)
        with open(os.path.join(PEAK_DIR, key + ".json"), encoding="utf-8") as f:
            j = json.load(f)
        if j.get("v") == 1 and j["peaks"]:
            return j["peaks"], j["rate"], j["dur"]
    except Exception:
        pass
    peaks, rate, dur = _decode_peaks(path)
    if key:
        try:
            os.makedirs(PEAK_DIR, exist_ok=True)
            lo, lr = peaks_low(peaks, rate)
            for name, pk, rt in ((key + ".json", peaks, rate), (key + "_low.json", lo, lr)):
                tmp = os.path.join(PEAK_DIR, name + ".tmp")
                with open(tmp, "w", encoding="utf-8") as f:
                    json.dump({"v": 1, "peaks": pk, "rate": rt, "dur": dur}, f, separators=(",", ":"))
                os.replace(tmp, os.path.join(PEAK_DIR, name))
        except Exception:
            pass
    return peaks, rate, dur


def song_peaks_low(path):
    """The small waveform only (what the Timeline draws until you zoom in): straight from the cache when it is there."""
    try:
        with open(os.path.join(PEAK_DIR, _peak_key(path) + "_low.json"), encoding="utf-8") as f:
            j = json.load(f)
        if j.get("v") == 1 and j["peaks"]:
            return j["peaks"], j["rate"], j["dur"]
    except Exception:
        pass
    peaks, rate, dur = song_peaks(path)
    lo, lr = peaks_low(peaks, rate)
    return lo, lr, dur


def _decode_peaks(path):
    """Fast full-song waveform (~100 values/second, 0..99) without librosa,
    so the range picker can show the song before anything is analyzed."""
    import numpy as np
    sr = 8000
    bucket = sr // 100
    step = bucket * 4 * 6000                    # one minute of sound at a time
    proc = subprocess.Popen(["ffmpeg", "-v", "error", "-i", path, "-vn", "-ac", "1", "-ar", str(sr), "-f", "f32le", "-"],
                            stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, creationflags=NO_WINDOW)
    parts, samples, rest = [], 0, b""
    try:
        while True:
            buf = proc.stdout.read(step)
            if not buf:
                break
            buf = rest + buf
            k = len(buf) // (bucket * 4) * (bucket * 4)
            rest = buf[k:]
            if k:
                y = np.frombuffer(buf[:k], dtype=np.float32)
                samples += len(y)
                parts.append(np.abs(y).reshape(-1, bucket).max(axis=1))
    finally:
        proc.stdout.close()
        proc.wait()
    samples += len(rest) // 4
    if not parts:
        raise RuntimeError("Could not decode audio." if proc.returncode else "Audio is too short.")
    peaks = np.concatenate(parts)
    peaks = np.round(peaks / (peaks.max() + 1e-9) * 99).astype(int).tolist()
    return peaks, sr / bucket, samples / sr


AFX_TAPS = (1.0, 1.53, 2.11, 2.87, 3.71, 4.63)      # the reverb's echoes: each one later (times the first delay) and quieter


def parse_afx(a):
    """A clip's Audio Effects (Effect Controls > Audio Effects), cleaned. None = nothing switched on."""
    if not isinstance(a, dict):
        return None
    o = {"hp": _fnum(a.get("hp"), 0, 0, 2000), "lp": _fnum(a.get("lp"), 20000, 300, 20000),
         "cOn": bool(a.get("cOn")), "cThr": _fnum(a.get("cThr"), -18, -60, 0), "cRat": _fnum(a.get("cRat"), 4, 1, 20),
         "cAtt": _fnum(a.get("cAtt"), 10, 1, 200), "cRel": _fnum(a.get("cRel"), 200, 20, 2000),
         "rOn": bool(a.get("rOn")), "rRoom": _fnum(a.get("rRoom"), 40, 0, 100), "rDec": _fnum(a.get("rDec"), 40, 0, 100)}
    return o if (o["hp"] >= 20 or o["lp"] < 19990 or o["cOn"] or o["rOn"]) else None


def afx_taps(room, dec):
    """Reverb -> the echoes (delay in ms, gain) that both the preview and the render play. Room size sets how far apart
    they are, decay how slowly they die away."""
    d0, g0 = 15 + room * 0.85, 0.12 + 0.5 * dec / 100
    return [(d0 * k, g0 * (0.80 ** i)) for i, k in enumerate(AFX_TAPS)]


def afx_filter(a):
    """The FFmpeg filters of a clip's Audio Effects, in the order they are heard: EQ -> compressor -> reverb. '' = none."""
    if not a:
        return ""
    f = []
    if a["hp"] >= 20:
        f.append(f"highpass=f={a['hp']:.1f}")
    if a["lp"] < 19990:
        f.append(f"lowpass=f={a['lp']:.1f}")
    if a["cOn"]:
        f.append(f"acompressor=threshold={max(0.001, 10 ** (a['cThr'] / 20)):.6f}:ratio={a['cRat']:.2f}:attack={a['cAtt']:.2f}:release={a['cRel']:.2f}")
    if a["rOn"]:
        taps = afx_taps(a["rRoom"], a["rDec"])
        f.append("aecho=0.85:0.9:" + "|".join(f"{d:.1f}" for d, _ in taps) + ":" + "|".join(f"{g:.4f}" for _, g in taps))
    return "," + ",".join(f) if f else ""


MACRO_MIN_SEC = 4.0      # a Macro Section is never shorter than this (or 8 beats)


def label_macros(energy):
    """Name sections from their energy shape. It's a guess - the user can rename."""
    n = len(energy)
    if n == 1:
        return ["Section"]
    labels = []
    for i, e in enumerate(energy):
        prev = energy[i - 1] if i else None
        nxt = energy[i + 1] if i + 1 < n else None
        if i == 0 and e < 0.75:
            lab = "Intro"
        elif i == n - 1 and n > 2 and e < 0.75:
            lab = "Outro"
        elif e >= 0.8:
            lab = "Drop" if (prev is not None and e - prev >= 0.35) else "Chorus"
        elif nxt is not None and nxt >= 0.8 and (prev is None or e > prev + 0.05):
            lab = "Build"
        elif e < 0.45:
            lab = "Break"
        else:
            lab = "Verse"
        labels.append(lab)
    return labels


def novelty_bounds(sync, ibi, min_len, half=8):
    """Foote novelty on a beat-synced feature matrix: compare the `half` beats
    before each beat with the `half` after. Peaks = big structural changes.
    Returns beat indices where a new Macro Section starts."""
    import numpy as np
    n = sync.shape[1]
    if n < 2 * half + 2:
        return []
    d = np.empty((n, n), dtype=sync.dtype)          # beat-to-beat distances, a block of rows at a time: all at once is features x beats x beats (gigabytes for a long song)
    for r0 in range(0, n, 64):
        d[r0:r0 + 64] = np.linalg.norm(sync[:, r0:r0 + 64, None] - sync[:, None, :], axis=0)
    S = np.exp(-(d ** 2) / (np.median(d ** 2) + 1e-9))
    g = np.exp(-0.5 * (np.linspace(-1, 1, 2 * half) / 0.5) ** 2)
    K = np.outer(g, g) * np.outer(np.r_[-np.ones(half), np.ones(half)], np.r_[-np.ones(half), np.ones(half)])
    Sp = np.pad(S, half, mode="reflect")
    nov = np.array([(K * Sp[i:i + 2 * half, i:i + 2 * half]).sum() for i in range(n)])
    nov = np.maximum(0, nov)
    nov[:half // 2] = 0
    nov[-(half // 2):] = 0
    if nov.max() <= 0:
        return []
    nov /= nov.max()
    gap = max(2, int(round(min_len / max(ibi, 1e-3))))
    thr = max(0.25, nov.mean() + 0.5 * nov.std())
    picks = []
    for i in np.argsort(-nov):           # strongest first, keep spacing
        if nov[i] < thr:
            break
        if all(abs(i - p) >= gap for p in picks):
            picks.append(int(i))
    return sorted(p for p in picks if gap // 2 <= p <= n - gap // 2)


LONG_AUDIO_SEC = 300      # a range longer than this is measured a block at a time (see _long_features)


def _long_features(librosa, np, y, sr, hop):
    """Mel power (128 bands), chroma (12) and loudness (RMS) of a LONG recording, one block of the spectrum at a time.
    librosa's own calls each build the spectrum of the whole range at once (and the chroma one twice more to find the tuning):
    more than 1 GB for ten minutes of music. This gives the same frames (same window, same padding) from blocks of about
    95 seconds, so memory stays near 100 MB however long the range is. Only the tuning is taken from two minutes in the
    middle instead of from everything."""
    import inspect
    n_fft = 2048
    try:
        mode = inspect.signature(librosa.stft).parameters["pad_mode"].default
    except Exception:
        mode = "constant"
    yp = np.pad(y, n_fft // 2, mode=mode if mode in ("constant", "reflect") else "constant")
    total = 1 + (len(yp) - n_fft) // hop
    melb = librosa.filters.mel(sr=sr, n_fft=n_fft, n_mels=128)
    mid = len(y) // 2
    try:
        tuning = float(librosa.estimate_tuning(y=y[max(0, mid - 60 * sr):mid + 60 * sr], sr=sr, n_fft=n_fft))
    except Exception:
        tuning = 0.0
    chb = librosa.filters.chroma(sr=sr, n_fft=n_fft, tuning=tuning)
    mel = np.empty((128, total), dtype=np.float32)
    chroma = np.empty((12, total), dtype=np.float32)
    rms = np.empty(total, dtype=np.float32)
    block = 4096
    for f0 in range(0, total, block):
        f1 = min(total, f0 + block)
        seg = yp[f0 * hop:(f1 - 1) * hop + n_fft]
        P = np.abs(librosa.stft(seg, n_fft=n_fft, hop_length=hop, center=False)) ** 2
        mel[:, f0:f1] = melb @ P
        chroma[:, f0:f1] = librosa.util.normalize(chb @ P, norm=np.inf, axis=0)
        fr = librosa.util.frame(seg, frame_length=n_fft, hop_length=hop)
        rms[f0:f1] = np.sqrt(np.mean(fr.astype(np.float32) ** 2, axis=0))
        del P, fr
    return mel, chroma, rms


def analyze_song(path, a, b):
    """Analyze only [a, b] of the song. Returns beats (song-absolute times),
    per-beat strength/heaviness and the big structural Macro Sections."""
    librosa = get_librosa()
    import numpy as np
    from scipy.ndimage import median_filter

    wav = os.path.join(WORK_DIR, uuid.uuid4().hex + ".wav")
    out = run(["ffmpeg", "-v", "error", "-y", "-ss", f"{a:.4f}", "-t", f"{b - a:.4f}",
               "-i", path, "-vn", "-ac", "1", "-ar", "22050", "-f", "wav", wav], timeout=600)
    if out.returncode != 0:
        raise RuntimeError("Could not decode audio: " + out.stderr[-400:])
    try:
        try:                                       # (the file is already mono 22050 Hz: read it as it is, without the extra copies of the general loader)
            import soundfile as _sf
            y, sr = _sf.read(wav, dtype="float32", always_2d=False)
            if y.ndim != 1 or sr != 22050:
                raise ValueError("unexpected audio layout")
        except Exception:
            y, sr = librosa.load(wav, sr=22050, mono=True)
    finally:
        _rm(wav)

    dur = len(y) / sr
    if dur < 2:
        raise RuntimeError("The range is shorter than 2 seconds.")
    hop = 512

    long_ = dur > LONG_AUDIO_SEC
    if long_:
        mel_p, chroma_l, rms_l = _long_features(librosa, np, y, sr, hop)
        logmel = librosa.power_to_db(mel_p)
        del mel_p
        onset_env = librosa.onset.onset_strength(S=logmel, sr=sr, hop_length=hop)
    else:
        onset_env = librosa.onset.onset_strength(y=y, sr=sr, hop_length=hop)
    # trim=False: the default trims "weak" beats at both ends (drops quiet intros)
    tempo, beats = librosa.beat.beat_track(onset_envelope=onset_env, sr=sr,
                                           hop_length=hop, trim=False)
    tempo = float(np.atleast_1d(tempo)[0]) if np.size(tempo) else 0.0
    beats = np.asarray(beats, dtype=int)
    rms = rms_l if long_ else librosa.feature.rms(y=y, hop_length=hop)[0]
    if len(beats):   # ...but no markers on silence
        n_rms = len(rms)
        level = np.array([rms[max(0, x - 2):min(n_rms, x + 3)].mean() for x in beats])
        beats = beats[level >= 0.02 * rms.max()]
    beat_times = librosa.frames_to_time(beats, sr=sr, hop_length=hop)

    beat_list = []
    if len(beats):
        n_on, n_rms = len(onset_env), len(rms)
        strength = np.array([onset_env[max(0, x - 2):min(n_on, x + 3)].max() for x in beats])
        loud = np.array([rms[max(0, x - 2):min(n_rms, x + 3)].mean() for x in beats])
        strength = np.clip(strength / (np.percentile(strength, 95) + 1e-9), 0, 1)
        loud = np.clip(loud / (np.percentile(loud, 95) + 1e-9), 0, 1)
        score = strength * loud
        heavy = score >= max(np.percentile(score, 75), 0.35)
        beat_list = [[round(float(t) + a, 4), round(float(s), 3), bool(h)]
                     for t, s, h in zip(beat_times, strength, heavy)]

    # --- Macro Sections: big energy / timbre changes, cut on beats --------
    ibi = float(np.median(np.diff(beat_times))) if len(beat_times) > 1 else 0.5
    min_len = max(MACRO_MIN_SEC, 8 * ibi)
    bounds = [0.0]
    if len(beats) >= 16:
        mfcc = librosa.feature.mfcc(S=logmel, n_mfcc=13) if long_ else librosa.feature.mfcc(y=y, sr=sr, n_mfcc=13, hop_length=hop)
        chroma = chroma_l if long_ else librosa.feature.chroma_stft(y=y, sr=sr, hop_length=hop)
        rms_db = librosa.amplitude_to_db(rms[np.newaxis, :], ref=np.max)
        m = min(mfcc.shape[1], chroma.shape[1], rms_db.shape[1])

        def z(arr):
            return (arr - arr.mean(axis=1, keepdims=True)) / (arr.std(axis=1, keepdims=True) + 1e-6)

        # energy weighted strongest, timbre next, harmony least
        feat = np.vstack([z(mfcc[:, :m]) / np.sqrt(13) * 1.0,
                          z(chroma[:, :m]) / np.sqrt(12) * 0.6,
                          z(rms_db[:, :m]) * 1.8])
        bsel = beats[beats < m]
        sync = librosa.util.sync(feat, bsel, aggregate=np.median)[:, 1:]   # column j = beat j
        sync = median_filter(sync, size=(1, 3), mode="nearest")
        bounds += [float(beat_times[j]) for j in novelty_bounds(sync, ibi, min_len)]
    else:
        bounds += [i * 15.0 for i in range(1, int(dur // 15.0))]
    bounds = sorted(set(round(x, 4) for x in bounds if 0 <= x < dur - 0.5))
    bounds.append(round(dur, 4))
    changed = True                      # merge anything shorter than min_len
    while changed and len(bounds) > 2:
        changed = False
        for i in range(len(bounds) - 1):
            if bounds[i + 1] - bounds[i] < min_len:
                drop = i + 1 if i + 1 < len(bounds) - 1 else i
                if 0 < drop < len(bounds) - 1:
                    bounds.pop(drop)
                    changed = True
                    break

    times = librosa.frames_to_time(np.arange(len(rms)), sr=sr, hop_length=hop)
    energy = []
    for s0, s1 in zip(bounds[:-1], bounds[1:]):
        sel = rms[(times >= s0) & (times < s1)]
        energy.append(float(sel.mean()) if sel.size else 0.0)
    emax = max(energy) or 1.0
    energy = [round(e / emax, 3) for e in energy]
    labels = label_macros(energy)
    macros = [{"start": round(s0 + a, 4), "end": round(s1 + a, 4), "label": lab, "energy": e}
              for s0, s1, lab, e in zip(bounds[:-1], bounds[1:], labels, energy)]
    macros[-1]["end"] = round(b, 4)

    return {"a0": round(a, 4), "b0": round(b, 4), "bpm": round(tempo, 1),
            "beats": beat_list, "macros": macros}


# ---------------------------------------------------------------------------
# Clip preview proxies (for codecs the browser can't play, e.g. HEVC, ProRes)
# ---------------------------------------------------------------------------
BROWSER_AUDIO = {".mp3", ".wav", ".ogg", ".m4a", ".aac", ".flac", ".opus", ".webm"}
BROWSER_ACODECS = {"mp3", "aac", "opus", "vorbis", "flac", "pcm_s16le", "pcm_s24le", "pcm_f32le", "pcm_u8"}


def audio_needs_play_copy(name, info):
    """True when the browser can't play this file's sound directly (WMA, ALAC, AC-3, AIFF, MKV, video files...)."""
    a = next((st for st in info.get("streams", []) if st.get("codec_type") == "audio"), {})
    return safe_ext(name) not in BROWSER_AUDIO or a.get("codec_name") not in BROWSER_ACODECS


def browser_playable(info):
    """Return a mimetype if the browser can play the original, else None."""
    v = next((s for s in info.get("streams", []) if s.get("codec_type") == "video"), None)
    if not v:
        return None
    fmt = info.get("format", {}).get("format_name", "")
    codec = v.get("codec_name", "")
    pix = v.get("pix_fmt", "")
    a = next((s for s in info.get("streams", []) if s.get("codec_type") == "audio"), None)
    if a and a.get("codec_name") not in ("aac", "mp3", "opus", "vorbis", "flac"):
        return None                     # the browser couldn't play its sound -> make a proxy
    if codec == "h264" and pix in ("yuv420p", "yuvj420p") and ("mp4" in fmt or "mov" in fmt):
        return "video/mp4"
    if codec in ("vp8", "vp9", "av1") and "webm" in fmt:
        return "video/webm"
    if codec == "av1" and "mp4" in fmt:
        return "video/mp4"
    return None


# Containers whose seeking/timestamps are unreliable (MPEG-TS, AVI, FLV, WMV, ...) and raw
# elementary streams (.hevc/.h264 - no timestamps, no duration). They are re-wrapped ONCE on
# upload, losslessly (-c copy: same pictures, same sound, nothing re-encoded) into MKV/MP4, so
# every later seek in the renderer is frame-exact. The render still uses these original pictures.
REMUX_FORMATS = {"mpegts", "mpeg", "vob", "avi", "flv", "asf", "mxf", "dv", "rm", "ogg", "nut", "wtv", "mpegtsraw"}
RAW_FORMATS = {"hevc", "h264", "mpegvideo", "m4v", "vc1", "obu", "h263", "rawvideo", "avs2", "avs3", "vvc"}


def master_mode(info):
    names = set(info.get("format", {}).get("format_name", "").split(","))
    if names & RAW_FORMATS:
        return "raw"
    if names & REMUX_FORMATS:
        return "remux"
    return None


def make_master(uid, path, info, mode):
    """Lossless re-wrap -> (path, info). Falls back to the original file if anything goes wrong."""
    v = next((st for st in info.get("streams", []) if st.get("codec_type") == "video"), {})
    out = os.path.join(UPLOAD_DIR, uid + ("_master.mp4" if mode == "raw" else "_master.mkv"))
    if mode == "raw":
        # a bare stream has no timestamps at all: picture n is shown at n / fps. It is decoded once into
        # a LOSSLESS H.264 copy (qp 0 - bit-exact pictures) with exactly those timestamps.
        rate = v.get("r_frame_rate") or "30/1"
        rate = rate if re.fullmatch(r"[1-9]\d*(/[1-9]\d*)?", rate) else "30"
        if v.get("codec_name") == "h264" and rate != "30":          # a bare H.264 stream reports its field rate (2 x fps)
            num, _, den = rate.partition("/")
            rate = f"{num}/{int(den or 1) * 2}"
        out = out[:-4] + ".mkv"
        cmd = ["ffmpeg", "-v", "error", "-y", "-framerate", rate, "-i", path, "-map", "0:v:0",
               "-vf", "setpts=N/FRAME_RATE/TB", "-c:v", "libx264", "-qp", "0", "-preset", "ultrafast", out]
    else:
        cmd = ["ffmpeg", "-v", "error", "-y", "-fflags", "+genpts", "-i", path, "-map", "0:v:0", "-map", "0:a?",
               "-c", "copy", "-avoid_negative_ts", "make_zero", out]
    try:
        r = run(cmd, timeout=7200)
        if r.returncode != 0 and mode == "raw":                    # pixel format x264 can't take -> FFV1 (also lossless)
            r = run(cmd[:cmd.index("libx264")] + ["ffv1", out], timeout=7200)
        if r.returncode != 0 and mode == "remux":                  # an odd audio codec MKV can't hold -> picture only
            i = cmd.index("0:a?")
            r = run(cmd[:i - 1] + cmd[i + 1:], timeout=7200)
        if r.returncode == 0 and os.path.getsize(out) > 0:
            info2 = probe(out)
            if any(st.get("codec_type") == "video" for st in info2.get("streams", [])) and \
                    float(info2.get("format", {}).get("duration") or 0) > 0:
                _rm(path)
                return out, info2
    except Exception as e:
        log.info(f"[clip] Re-wrap failed, using the original as-is: {e}")
    _rm(out)
    return path, info


def video_offset(info, v):
    """Seconds from the file's start (what -ss counts from) to its first picture. A proxy starts AT
    the first picture, and the renderer seeks by the same amount, so both agree to the frame."""
    try:
        d = float(v.get("start_time")) - float(info.get("format", {}).get("start_time"))
    except (TypeError, ValueError):
        return 0.0
    return round(d, 6) if 0 < d < 5 else 0.0


def make_proxy(clip_id):
    """Light H.264 MP4 the browser can play. Original frame timing is kept (no frame-rate change),
    so the preview shows exactly the frames the render takes from the original file."""
    clip = CLIPS[clip_id]
    out = os.path.join(UPLOAD_DIR, clip_id + "_proxy.mp4")
    vf = "scale=w='min(960,iw)':h='min(960,ih)':force_original_aspect_ratio=decrease,scale=trunc(iw/2)*2:trunc(ih/2)*2"
    cmd = ["ffmpeg", "-v", "error", "-y", "-ss", f"{clip.get('v0', 0):.6f}", "-i", clip["path"], "-map", "0:v:0", "-map", "0:a:0?",
           "-vf", vf, "-c:v", "libx264", "-preset", "veryfast", "-crf", "26", "-g", "30",
           "-pix_fmt", "yuv420p", "-c:a", "aac", "-b:a", "160k", "-ac", "2", "-movflags", "+faststart",
           "-progress", "pipe:1", "-nostats", out]
    dur = max(0.1, float(clip.get("duration") or 0))
    try:
        proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True,
                                creationflags=NO_WINDOW, encoding="utf-8", errors="replace")
        clip["proc"] = proc
        for line in proc.stdout:
            key, _, val = line.strip().partition("=")
            if key == "out_time_us" and val.isdigit():
                clip["pct"] = min(99, int(int(val) / 1e6 / dur * 100))
        errtxt = proc.stderr.read()
        proc.wait()
        rc = proc.returncode
    except Exception as e:
        rc, errtxt = 1, str(e)
    clip.pop("proc", None)
    if clip_id not in CLIPS:
        _rm(out)
        return
    if rc == 0 and os.path.exists(out):
        clip.update(play_path=out, play_mime="video/mp4", status="ready", pct=100)
    elif clip.get("cancelled"):
        _rm(out)
        clip.update(status="error", error="Cancelled.")
    else:
        clip.update(status="error", error="Preview conversion failed: " + (errtxt or "")[-300:])


def convert_still(cid):
    """Photo -> 10 s 30 fps looping MP4; GIF -> MP4 of its animation. Both then behave like any clip."""
    c = CLIPS[cid]
    src, out = c["path"], os.path.join(UPLOAD_DIR, cid + "_clip.mp4")
    even = "scale='trunc(min(3840,iw)/2)*2':-2:flags=lanczos,setsar=1,format=yuv420p"
    if c["kind"] == "photo":
        cmd = ["ffmpeg", "-v", "error", "-y", "-loop", "1", "-framerate", str(FPS), "-t", f"{PHOTO_SECONDS}", "-i", src,
               "-vf", even, "-c:v", "libx264", "-preset", "veryfast", "-tune", "stillimage", "-crf", "16",
               "-g", str(FPS), "-r", str(FPS), "-an", "-movflags", "+faststart", out]
    else:
        cmd = ["ffmpeg", "-v", "error", "-y", "-i", src, "-vf", even.replace("format=yuv420p", "fps=30,format=yuv420p"),
               "-c:v", "libx264", "-preset", "veryfast", "-crf", "18", "-g", str(FPS), "-an", "-movflags", "+faststart", out]
    r = run(cmd, timeout=600)
    if cid not in CLIPS:
        return
    if r.returncode != 0 or not os.path.exists(out):
        c.update(status="error", error=("Could not convert this image: " + (r.stderr or "")[-300:]))
        return
    try:
        info = probe(out)
        v = next(st for st in info["streams"] if st.get("codec_type") == "video")
        dur = float(info.get("format", {}).get("duration") or 0) or PHOTO_SECONDS
        c.update(width=int(v.get("width") or c["width"]), height=int(v.get("height") or c["height"]), duration=round(dur, 3))
    except Exception:
        pass
    if c["kind"] == "photo":
        c["image"] = src
    c.update(path=out, play_path=out, play_mime="video/mp4")
    make_thumb(cid)
    c["status"] = "ready"


def make_thumb(cid):
    """Small JPEG poster for the clip bin and the filmstrip."""
    c = CLIPS[cid]
    out = os.path.join(UPLOAD_DIR, cid + "_thumb.jpg")
    t = min(1.0, c["duration"] / 3) if c["duration"] else 0
    r = run(["ffmpeg", "-v", "error", "-y", "-ss", f"{t:.2f}", "-i", c["path"],
             "-frames:v", "1", "-vf", "scale=320:-2", "-q:v", "4", out], timeout=60)
    if r.returncode == 0 and os.path.exists(out):
        c["thumb"] = out


def clip_json(cid):
    c = CLIPS[cid]
    return {"id": cid, "name": c["name"], "duration": c["duration"],
            "width": c["width"], "height": c["height"], "status": c["status"],
            "error": c.get("error"), "url": f"/media/clip/{cid}", "audio": bool(c.get("audio")), "fps": c.get("fps", 30.0),
            "kind": c.get("kind", "video"), "pct": c.get("pct", 0), "codec": c.get("codec", ""),
            "proxy": c.get("play_path") != c.get("path") and c.get("kind", "video") == "video",
            "image": f"/media/image/{cid}" if c.get("image") else None,
            "thumb": f"/media/thumb/{cid}" if c.get("thumb") else None, "path": ORIGIN.get(cid, "")}


# ---------------------------------------------------------------------------
# Renderer
# ---------------------------------------------------------------------------
NVENC_ARGS = ["-c:v", "h264_nvenc", "-preset", "p5", "-tune", "hq", "-rc", "vbr",
              "-cq", "19", "-b:v", "0", "-maxrate", "40M", "-bufsize", "80M",
              "-profile:v", "high", "-pix_fmt", "yuv420p"]
X264_ARGS = ["-c:v", "libx264", "-preset", "veryfast", "-crf", "18",
             "-profile:v", "high", "-pix_fmt", "yuv420p"]

# Each section is one FFmpeg input = one open video decoder. Above this many
# sections the render is split into chunks so RAM stays bounded (4K phone
# footage x 100+ decoders would need several GB), then joined losslessly.
CHUNK_SECTIONS = 20
CHUNK_SECONDS = _env_num("KIRU_CHUNK_S", 120)      # ... and never a piece longer than this: a 30-minute edit is 15 short FFmpeg jobs, not one huge one
JOIN_AT = 0.94                                      # share of the progress bar for the pieces; the rest is the join
DECODER_THREADS = "4"
SEEK_MARGIN = 0.2      # seek this much early so the frame just before the start is kept
MIN_SPEED, MAX_SPEED = 0.05, 200.0     # Velocity limits (the browser preview tops out at 16x)

_nvenc_ok = None


def nvenc_available():
    """Tiny test encode - the only reliable way to know NVENC works on this PC."""
    global _nvenc_ok
    if _nvenc_ok is None:
        try:
            r = run(["ffmpeg", "-v", "error", "-f", "lavfi", "-i",
                     f"color=black:s={OUTPUT_W}x{OUTPUT_H}:r={FPS}:d=0.2"]
                    + NVENC_ARGS + ["-f", "null", "-"], timeout=30)
            _nvenc_ok = r.returncode == 0
        except Exception:
            _nvenc_ok = False
    return _nvenc_ok


SQUARE_PX = "scale='trunc(iw*sar/2)*2':'trunc(ih/2)*2':flags=bicubic,setsar=1"   # anamorphic -> square pixels first


def parse_mo(mo, L):
    """An element's Animation, already worked out by the page (the same numbers its preview uses): keyframe lists for the
    shift (px), scale and turn (degrees), the opacity ramps [first frame, frames] and the frames it is visible on."""
    if not isinstance(mo, dict):
        return None
    def keys(v):
        pts = {}
        for e in (v if isinstance(v, list) else [])[:3000]:
            try:
                pts[max(0, int(e[0]))] = float(e[1])
            except (TypeError, ValueError, IndexError):
                continue
        return sorted(pts.items()) or None
    def ramp(v):
        try:
            a, n = int(v[0]), int(v[1])
            return (a, max(1, n))
        except Exception:
            return None
    vis = mo.get("vis") if isinstance(mo.get("vis"), list) and len(mo.get("vis")) == 2 else [0, L - 1]
    out = {"blur": bool(mo.get("blur")), "dx": keys(mo.get("dx")), "dy": keys(mo.get("dy")), "sc": keys(mo.get("sc")), "rot": keys(mo.get("rot")),
           "fi": ramp(mo.get("fi")), "fo": ramp(mo.get("fo")), "vis": (int(_fnum(vis[0], 0, 0, 1e7)), int(_fnum(vis[1], L - 1, 0, 1e7)))}
    if out["sc"]:
        out["sc"] = [(k, min(8.0, max(0.001, v))) for k, v in out["sc"]]
    live = any(out[k] for k in ("dx", "dy", "sc", "rot", "fi", "fo")) or out["vis"][0] > 0 or out["vis"][1] < L - 1
    return out if live else None


def mo_expr(ks, K, d=0.0):
    """Keyframes [(frame, value)] as an FFmpeg expression of the frame number K: piecewise linear, held at both ends."""
    if not ks:
        return f"{d:.4f}"
    terms = [f"{ks[0][1]:.4f}"]
    for (k0, v0), (k1, v1) in zip(ks, ks[1:]):
        if abs(v1 - v0) > 1e-9 and k1 > k0:
            terms.append(f"{v1 - v0:.4f}*clip(({K}-{k0})/{k1 - k0},0,1)")
    return "+".join(terms).replace("+-", "-")


def mo_filters(mo, w, h, k0, N):
    """(filters for the element's own RGBA stream w x h, x expression, y expression, enable expression) for an animated element.
    The x / y expressions are the shift of its CENTRE; the caller adds where the centre rests. k0 = frames of it already played."""
    # the frame number comes from the timestamp (streams here tick once per frame from 0): `n` is not safe, overlay counts
    # it from 1 in some FFmpeg builds and from 0 in others
    Kn = f"(floor(t*{FPS}+0.5)+{k0})" if k0 else f"floor(t*{FPS}+0.5)"
    f = ""
    if mo["rot"]:
        D = int(_math.ceil(_math.hypot(w, h) / 2) * 2)
        # (turned on premultiplied colour: no fringe on see-through edges)
        f += f",premultiply=inplace=1,rotate=a='({mo_expr(mo['rot'], Kn)})*PI/180':ow={D}:oh={D}:c=black@0:bilinear=1,unpremultiply=inplace=1"
        w, h = D, D
    if mo["sc"]:
        S = mo_expr(mo["sc"], Kn, 1.0)
        f += f",scale=w='max(2,trunc({w}*({S})/2)*2)':h='max(2,trunc({h}*({S})/2)*2)':eval=frame:flags=bicubic"
    for kind, r in (("in", mo["fi"]), ("out", mo["fo"])):
        if not r:
            continue
        a, n = r[0] - k0, r[1]
        if a + n <= 0 and kind == "in":
            continue                                   # (this part starts after the fade-in is over)
        if a < 0:
            n, a = max(1, n + a), 0
        f += f",fade=t={kind}:s={a}:n={n}:alpha=1"
    en = f"between({Kn},{mo['vis'][0]},{mo['vis'][1]})"
    return f, mo_expr(mo["dx"], Kn), mo_expr(mo["dy"], Kn), en


def parse_off(o):
    """Where the picture sits inside its frame: [x, y], each -1..1 of the room it has (0 = centred). None when centred."""
    try:
        x, y = (min(1.0, max(-1.0, float(v) / 100.0)) for v in list(o)[:2])
    except Exception:
        return None
    return (x, y) if abs(x) > 1e-4 or abs(y) > 1e-4 else None


def fill_filter(mode, w, h, off=None):
    """Stretch = both axes forced to exactly w x h (aspect ignored); Crop = fill + trim; Fit = whole picture + bars.
    Every mode first turns the clip into square pixels and ends on setsar=1.
    off = (x, y) in -1..1: Crop slides the crop window through the part that hangs over (picture right = +x),
    Fit moves the picture inside its bars. Never shows more black than the centred picture does."""
    ox, oy = off or (0.0, 0.0)
    if mode == "stretch":
        core = f"scale={w}:{h}:force_original_aspect_ratio=disable:flags=bicubic"
    elif mode == "fit":
        core = (f"scale={w}:{h}:force_original_aspect_ratio=decrease:flags=bicubic,"
                f"pad={w}:{h}:(ow-iw)/2*{1 + ox:.5f}:(oh-ih)/2*{1 + oy:.5f}:color=black" if off else
                f"scale={w}:{h}:force_original_aspect_ratio=decrease:flags=bicubic,"
                f"pad={w}:{h}:(ow-iw)/2:(oh-ih)/2:color=black")
    else:
        core = (f"scale={w}:{h}:force_original_aspect_ratio=increase:flags=bicubic,"
                + (f"crop={w}:{h}:(iw-{w})/2*{1 - ox:.5f}:(ih-{h})/2*{1 - oy:.5f}" if off else f"crop={w}:{h}"))
    return f"{SQUARE_PX},{core},setsar=1"


FILL_FILTERS = {k: fill_filter(k, OUTPUT_W, OUTPUT_H) for k in ("stretch", "crop", "fit")}
PANE_GAP = 6                                   # Triptych: 3 panes of 636 px with 6 px black gaps
TRI_FITS = ("gaps", "sides", "all", "custom")  # equal thirds with gaps / sides stretch / 3 x 640 / your own widths


def tri_geometry(fit, centre_clip, custom=None):
    """(left, centre, right) pane widths + gap for a triptych layout."""
    if fit == "custom" and custom:
        a = round(OUTPUT_W * custom[0] / 100 / 2) * 2
        b = round(OUTPUT_W * custom[1] / 100 / 2) * 2
        return (a, b, OUTPUT_W - a - b), 0
    if fit == "all":
        a = round(OUTPUT_W / 3 / 2) * 2
        return (a, OUTPUT_W - 2 * a, a), 0
    if fit == "sides" and centre_clip and centre_clip.get("width") and centre_clip.get("height"):
        cw = round(OUTPUT_H * centre_clip["width"] / centre_clip["height"] / 4) * 4   # its own shape at full height
        cw = max(round(OUTPUT_W * 0.1875 / 4) * 4, min(round(OUTPUT_W * 0.8125 / 4) * 4, cw))
        side = (OUTPUT_W - cw) // 2
        return (side, cw, OUTPUT_W - cw - side), 0
    pw = (OUTPUT_W - 2 * PANE_GAP) // 3 // 2 * 2                 # even pane widths; the centre takes the odd pixels
    return (pw, OUTPUT_W - 2 * PANE_GAP - 2 * pw, pw), PANE_GAP
DUO_FITS = ("gaps", "all")                     # Duo: thin gap between the two panes / no gap


def duo_geometry(left_pct, gap_on):
    """(left, right) pane widths + gap for a Duo layout (left_pct = left pane share, 20-80 %)."""
    gap = PANE_GAP if gap_on else 0
    a = round((OUTPUT_W - gap) * left_pct / 100 / 2) * 2
    return (a, OUTPUT_W - gap - a), gap


def split_geometry(top_pct):
    """(top, bottom) pane heights for the 9:16 Split layout (top share 20-80 %)."""
    a = round(OUTPUT_H * top_pct / 100 / 2) * 2
    return (a, OUTPUT_H - a), 0


def pane_geometry(s):
    if s.get("layout") == "split":
        return split_geometry(s.get("splitH", 50.0))
    if s.get("layout") == "duo":
        return duo_geometry(s.get("duoW", 50.0), s.get("duoFit", "gaps") == "gaps")
    return tri_geometry(s.get("triFit", "gaps"), (s["panes"][1] or {}).get("clip"), s.get("triW"))


def parse_topt(o):
    """Blur flash, as measured from a reference (or set by hand): how hard it blurs, how white it goes, how far it pushes in,
    how far it twists, and whether the picture mirrors at the peak."""
    o = o if isinstance(o, dict) else {}
    return {"blur": _fnum(o.get("blur"), 100, 0, 200) / 100, "white": _fnum(o.get("white"), 100, 0, 100) / 100,
            "zoom": _fnum(o.get("zoom"), 22, 0, 80) / 100, "spin": _fnum(o.get("spin"), 0, -90, 90),
            "mirror": o.get("mirror") if o.get("mirror") in ("v", "h") else None, "smear": bool(o.get("smear"))}


BFLASH_ZOOM = 0.22                         # Blur flash: how far the picture pushes in at the peak (the page uses the same number)


OV_SHADOW_PAD, OV_SHADOW_SIGMA, OV_SHADOW_DX, OV_SHADOW_DY = 80, 22.0, 26, 30     # floating-layer drop shadow (px at 1920 wide; the page uses the same)


def bflash_white(k, T):
    """Blur flash: how white frame k of T is (0-1): up to full white at the cut, back down after it."""
    N = T / 2
    return k / N if k < N else 1 - (k - N) / N


def bflash_sigma(k, T):
    """Blur flash: blur (px at 1920 wide) on frame k of T - a peak in the middle. The page uses the same curve."""
    q = 1 - abs((k + 0.5) / T * 2 - 1)
    return 46 * q * q


MULTI = ("tri", "duo", "split")
SLIDES = {"left": "slideleft", "right": "slideright", "up": "slideup", "down": "slidedown"}
MOTION = ("spin", "zoomin", "zoomout")    # both clips are scaled/rotated inside the window, then blended
XFADE = dict(SLIDES, slowmo="fade", slowin="fade", slowout="fade", spin="fade", zoomin="fade", zoomout="fade",   # types that overlap two clips
             circle="circleopen", pixel="pixelize",
             fade="fade", dip="fadeblack", flashw="fadewhite", bflash="fadewhite", wipel="smoothleft", wiper="smoothright",   # plain xfade looks
             cube="fade", flip="fade", squeeze="fade", radial="fade", star="fade", diamond="fade", mgspark="fade", mgstar="fade", mgleak="fade")   # (built by tr3_graph)
POST_ONLY = ("glitch", "punch", "zsync")  # hard cut + effect frames around the cut
PUNCH_ZOOM = 0.10                         # Zoom Punch (CapCut style): 100% -> 110% into the cut, back out after it
FLICKER_ALPHA = (0.85, 0.55, 0.25)        # Brightness Flicker thump: white on the beat frame and the 2 after
FADE_ALPHA = {-2: 0.25, -1: 0.6, 0: 0.9, 1: 0.6, 2: 0.3, 3: 0.1}   # Fade Out thump: soft dip to black around the beat


TR3 = ("cube", "flip", "squeeze", "radial", "star", "diamond", "mgspark", "mgstar", "mgleak")   # 3D / shape / motion-graphic transitions
TR3_PERSP = 2.4                           # camera distance of the 3D ones, in picture widths (the page uses the same)
TR3_STAR_K = 0.5                          # star: inner corner radius / tip radius
TR3_SPARK = ((8, 0.55, 0.0, 0.030), (13, 0.85, 0.7, 0.022), (21, 1.15, 1.9, 0.016))   # sparkle rings: how many, how fast, turned by, dot size


def tr3_ease(q):
    q = max(0.0, min(1.0, q))
    return 4 * q ** 3 if q < 0.5 else 1 - 4 * (1 - q) ** 3


def tr3_ease_expr(q):
    return f"if(lt({q},0.5),4*pow({q},3),1-4*pow(1-({q}),3))"


def tr3_q_expr(q, ez):
    """Motion-graphic easing: 0 = the effect runs at an even pace; 1 = it starts and ends slowly and rushes through the middle
    (ease-in-out, power 1..5). The page has the same sum (tr3Q)."""
    n = 1 + 4 * max(0.0, min(1.0, ez or 0))
    if n < 1.001:
        return q
    k = 2 ** (n - 1)
    return f"if(lt({q},0.5),{k:.6f}*pow({q},{n:.4f}),1-{k:.6f}*pow(1-({q}),{n:.4f}))"


def tr3_faces(typ, j, T, W, H):
    """The flat pieces of a 3D transition on frame j of T: which picture, where its left / right edge lands (px), how tall each
    edge is (1 = full height) and how opaque. Same numbers as tr3Faces() in the page."""
    e = tr3_ease((j + 0.5) / T)
    w = cx = W / 2
    P = TR3_PERSP * W
    out = []
    if typ == "cube":
        th = e * _math.pi / 2
        c, s = _math.cos(th), _math.sin(th)
        out.append(("A", cx - w * (c + s) * P / (P + 2 * w * s), cx + w * (c - s), P / (P + 2 * w * s), 1.0, 1 - j / (2 * T)))
        out.append(("B", cx + w * (c - s), cx + w * (c + s) * P / (P + 2 * w * c), 1.0, P / (P + 2 * w * c), 1 - (T - 1 - j) / (2 * T)))
    elif typ == "flip":
        first = e < 0.5
        th = (e if first else e - 1) * _math.pi
        c, s = _math.cos(th), _math.sin(th)
        out.append(("A" if first else "B", cx - w * c * P / (P + w * s), cx + w * c * P / (P - w * s), P / (P + w * s), P / (P - w * s),
                    1 - j / T if first else 1 - (T - 1 - j) / T))
    else:
        out.append(("B", 0.0, float(W), 1.0, 1.0, 1.0))
        out.append(("A", cx - w * (1 - e), cx + w * (1 - e), 1.0, 1.0, 1.0))
    return [f for f in out if f[2] - f[1] > 0.5]


def tr3_when(frames):
    """enable= expression that is true on exactly these frames (streams are timed 1 frame = 1/FPS s)."""
    runs, frames = [], sorted(frames)
    for k in frames:
        if runs and runs[-1][1] == k - 1:
            runs[-1][1] = k
        else:
            runs.append([k, k])
    return "+".join(f"between(t,{(a - 0.5) / FPS:.5f},{(b + 0.5) / FPS:.5f})" for a, b in runs) or "0"


def tr3_graph(typ, A, B, T, W, H, chains, key, opaque, ez=0):
    """One 3D / shape / motion-graphic transition. A and B are RGBA streams of exactly T frames (frame k at k/FPS s);
    the answer is the label of an RGBA stream of T frames. opaque: on black (Beat Sync) instead of see-through (Timeline)."""
    tb = f"settb=1/{FPS},setpts=N"
    N = T // 2
    mw, mh = max(2, W // 8 * 2), max(2, H // 8 * 2)

    def gray(expr, lab, extra=""):
        chains.append(f"color=c=black:s={mw}x{mh}:r={FPS}:d={T / FPS + 0.5:.4f},trim=end_frame={T},format=gray,"
                      f"geq=lum='{expr}'{extra},scale={W}:{H}:flags=bilinear,setsar=1,{tb}[{lab}]")

    def hard_cut(lab):
        chains.append(f"{A}trim=end_frame={N},{tb}[{key}ha]")
        chains.append(f"{B}trim=start_frame={N},setpts=PTS-STARTPTS,{tb}[{key}hb]")
        chains.append(f"[{key}ha][{key}hb]concat=n=2:v=1:a=0,{tb}[{lab}]")

    q = tr3_q_expr(f"((N+0.5)/{T})", ez if typ in ("mgspark", "mgstar", "mgleak") else 0)
    q = f"({q})"
    star = (f"st(0,hypot(X-W/2,Y-H/2))*0+st(1,abs(mod(atan2(Y-H/2,X-W/2)+PI/2+PI/5+2*PI,2*PI/5)-PI/5))*0+"
            f"255*lte(ld(0),(%s)*hypot(W/2,H/2)*1.03*{TR3_STAR_K * _math.sin(_math.pi / 5):.6f}/"
            f"({TR3_STAR_K * _math.sin(_math.pi / 5):.6f}*cos(ld(1))+{1 - TR3_STAR_K * _math.cos(_math.pi / 5):.6f}*sin(ld(1))))")
    if typ in ("cube", "flip", "squeeze"):
        cx = w = W / 2
        P = TR3_PERSP * W
        b = 4
        e = tr3_ease_expr(f"((on-0.5)/{T})")               # (the perspective filter counts its frames from 1)
        vis = {"A": [], "B": []}
        for j in range(T):
            for f in tr3_faces(typ, j, T, W, H):
                vis[f[0]].append(j)

        def face(src, xl, xr, sl, sr, fade, lab):
            xr = f"max({xr},({xl})+2)"
            wd = f"(({xr})-({xl}))"
            x0, x1 = f"{b}+({xl})-{b}*{wd}/{W}", f"{b}+({xr})+{b}*{wd}/{W}"
            chains.append(f"{src}format=rgba,pad=iw+{2 * b}:ih+{2 * b}:{b}:{b}:color=black@0,"
                          f"perspective=x0='{x0}':y0='{b + H / 2}-{H / 2 + b}*({sl})':x1='{x1}':y1='{b + H / 2}-{H / 2 + b}*({sr})':"
                          f"x2='{x0}':y2='{b + H / 2}+{H / 2 + b}*({sl})':x3='{x1}':y3='{b + H / 2}+{H / 2 + b}*({sr})':"
                          f"sense=destination:eval=frame:interpolation=linear,crop={W}:{H}:{b}:{b},{tb}" + (f"[{lab}]" if not fade else f",split[{lab}c][{lab}k]"))
            if fade:                                       # turning away from the light: the piece gets darker (its own black shape under a fading copy)
                chains.append(f"[{lab}k]colorchannelmixer=rr=0:gg=0:bb=0[{lab}s]")
                chains.append(f"[{lab}c]{fade.lstrip(',')},{tb}[{lab}d]")
                chains.append(f"[{lab}s][{lab}d]overlay=format=rgb:eof_action=pass,format=rgba,{tb}[{lab}]")

        def dim_out(K):                                    # opacity 1 -> 1 - j/K
            return f",fade=t=out:alpha=1:start_frame=0:nb_frames={K}"

        def dim_in(K):                                     # opacity 1 - (T-1-j)/K
            p = K - (T - 1)
            return (f",tpad=start_mode=clone:start={p},fade=t=in:alpha=1:start_frame=0:nb_frames={K},"
                    f"trim=start_frame={p},setpts=PTS-STARTPTS")

        if typ == "cube":
            th = f"(({e})*PI/2)"
            c, s = f"cos({th})", f"sin({th})"
            edge = f"({cx}+{w}*({c}-{s}))"
            face(A, f"({cx}-{w}*({c}+{s})*{P}/({P}+{2 * w}*{s}))", edge, f"({P}/({P}+{2 * w}*{s}))", "1", dim_out(2 * T), key + "fa")
            face(B, edge, f"({cx}+{w}*({c}+{s})*{P}/({P}+{2 * w}*{c}))", "1", f"({P}/({P}+{2 * w}*{c}))", dim_in(2 * T), key + "fb")
        elif typ == "flip":
            for src, th, fade, lab in ((A, f"(({e})*PI)", dim_out(T), key + "fa"), (B, f"((({e})-1)*PI)", dim_in(T), key + "fb")):
                c, s = f"cos({th})", f"sin({th})"
                face(src, f"({cx}-{w}*{c}*{P}/({P}+{w}*{s}))", f"({cx}+{w}*{c}*{P}/({P}-{w}*{s}))", f"({P}/({P}+{w}*{s}))", f"({P}/({P}-{w}*{s}))", fade, lab)
        else:
            chains.append(f"{B}format=rgba,{tb}[{key}fb]")
            face(A, f"({cx}-{w}*(1-({e})))", f"({cx}+{w}*(1-({e})))", "1", "1", "", key + "fa")
        chains.append(f"color=c=black{'' if opaque else '@0'}:s={W}x{H}:r={FPS}:d={T / FPS + 0.5:.4f},trim=end_frame={T},format=rgba,{tb}[{key}bg]")
        order = ("fb", "fa") if typ == "squeeze" else ("fa", "fb")
        chains.append(f"[{key}bg][{key}{order[0]}]overlay=format=rgb:eof_action=pass:enable='{tr3_when(vis['B' if order[0] == 'fb' else 'A'])}'[{key}o1]")
        chains.append(f"[{key}o1][{key}{order[1]}]overlay=format=rgb:eof_action=pass:enable='{tr3_when(vis['B' if order[1] == 'fb' else 'A'])}',format=rgba,{tb}[{key}out]")
    elif typ in ("radial", "star", "diamond"):
        p = tr3_ease_expr(q)
        if typ == "radial":
            gray(f"255*lte(mod(atan2(X-W/2,H/2-Y)+2*PI,2*PI),2*PI*1.02*({p}))", key + "m")
        elif typ == "diamond":
            gray(f"255*lte(abs(X-W/2)/(W/2)+abs(Y-H/2)/(H/2),2*1.03*({p}))", key + "m")
        else:
            gray(star % f"({p})/{TR3_STAR_K}", key + "m")
        chains.append(f"{B}format=rgba,split[{key}b1][{key}b2]")
        chains.append(f"[{key}b2]alphaextract,format=gray[{key}ba]")
        chains.append(f"[{key}ba][{key}m]blend=all_mode=multiply[{key}bm]")
        chains.append(f"[{key}b1][{key}bm]alphamerge[{key}bx]")
        chains.append(f"{A}[{key}bx]overlay=format=rgb:eof_action=pass,format=rgba,{tb}[{key}out]")
    elif typ == "mgstar":
        hard_cut(key + "base")
        gray(star % f"pow(min(1,1.1*(1-abs(2*{q}-1))),1.6)/{TR3_STAR_K}", key + "m")
        chains.append(f"color=c=white:s={W}x{H}:r={FPS}:d={T / FPS + 0.5:.4f},trim=end_frame={T},format=rgba,{tb}[{key}w]")
        chains.append(f"[{key}w][{key}m]alphamerge[{key}st]")
        chains.append(f"[{key}base][{key}st]overlay=format=rgb:eof_action=pass,format=rgba,{tb}[{key}out]")
    else:
        if typ == "mgspark":
            hard_cut(key + "base")
            rings = "+".join(f"exp(-(pow(ld(0)-{v}*ld(2),2)+pow((mod(ld(1)+{ph}+PI/{K}+2*PI,2*PI/{K})-PI/{K})*ld(0),2))/(2*pow({sg}*H,2)))"
                             for K, v, ph, sg in TR3_SPARK)
            expr = (f"st(0,hypot(X-W/2,Y-H/2))*0+st(1,atan2(Y-H/2,X-W/2))*0+st(2,hypot(W/2,H/2)*(1-pow(1-{q},2)))*0+"
                    f"255*min(1,pow(sin(PI*{q}),0.8)*({rings})+0.85*pow(1-abs(2*{q}-1),2)*exp(-pow(ld(0),2)/(2*pow(0.22*H,2))))")
            tint = ",format=rgb24,lutrgb=g='255*pow(val/255,1.2)':b='255*pow(val/255,1.9)'"
        else:                                              # mgleak: a warm glow sweeps across while the two shots dissolve
            chains.append(f"{B}format=rgba,fade=t=in:alpha=1:start_frame=0:nb_frames={T},{tb}[{key}xb]")     # B fades in OVER A (right for see-through layers too)
            chains.append(f"{A}[{key}xb]overlay=format=rgb:eof_action=pass,format=rgba,{tb}[{key}base]")
            expr = (f"255*0.82*sin(PI*{q})*exp(-(pow(X-W*(-0.25+1.5*{q}),2)/(2*pow(0.26*W,2))+pow(Y-0.42*H,2)/(2*pow(0.75*H,2))))")
            tint = ",format=rgb24,lutrgb=g='255*pow(val/255,1.5)':b='255*pow(val/255,3)'"
        gray(expr, key + "g", tint)
        chains.append(f"[{key}g]format=gbrap[{key}gl]")
        chains.append(f"[{key}base]format=gbrap[{key}bb]")
        chains.append(f"[{key}bb][{key}gl]blend=c0_mode=screen:c1_mode=screen:c2_mode=screen:c3_mode=normal,format=rgba,{tb}[{key}out]")
    return f"[{key}out]"


def punch_len(T):
    """Zoom Punch length: 4-8 frames, following the Fast / Normal / Slow transition speed."""
    return max(4, min(8, round(4 + (T - 4) * 0.4)))
ZSYNC_ZOOM = 1.0                          # Zoom Punch Sync: deep zoom into the cut (200%), incoming zooms out from 200%
IMAGE_EXT = (".jpg", ".jpeg", ".png", ".webp", ".bmp")
PHOTO_SECONDS = 10.0                      # a photo becomes a 10 s looping clip
# output shapes: 16:9, 9:16, 1:1, 4:5, 21:9 (the keys are what the page sends as plan.orient)
ORIENTS = {"landscape": (1920, 1080), "portrait": (1080, 1920), "square": (1080, 1080), "tall": (1080, 1350), "wide": (2560, 1080)}
RENDER_LOCK = threading.Lock()
TLEN_DEFAULT = 4                          # transition length in frames ("Fast" = 0.13 s)
SLOW_T = ("slowmo", "slowin", "slowout")   # Slow-mo zoom (in + out), Slow-mo zoom in (only the outgoing clip pushes in), Slow-mo zoom out (only the incoming one lands)
SLOWMO_RATE = 0.4      # both clips play at 0.4x of their own speed inside a Slow-mo window
SLOWMO_ZOOM = 0.30     # Slow-mo: outgoing zooms 1.0 -> 1.3, incoming 1.3 -> 1.0
# whip blur on slides = how far the picture moves in that frame (quantised to a few levels)
SLIDE_SIG_K, SLIDE_SIG_MAX = 0.22, 110.0
SLIDE_LEVELS = (4, 8, 14, 22, 34, 50, 70, 90, 110)
MOTION_SIG_K, MOTION_SIG_MAX = 60.0, 30.0        # spin / zoom blur
MOTION_LEVELS = (3, 6, 10, 15, 21, 28)
THUMP_BLUR_K = 0.06                              # thump zoom blur: 6% of the radius at 100% / 100%
THUMP_BLUR_W = (1.0, 0.45, 0.2)                  # beat frame, +1, +2
THUMP_LEVELS = (0.012, 0.02, 0.03, 0.042, 0.056, 0.072, 0.09, 0.11, 0.14, 0.18)
INTRO_SIG = 50.0                                 # Blur Intro: sigma at frame 0 (amount 100%)
INTRO_LEVELS = (1.5, 2.5, 4, 6, 9, 13, 18, 24, 31, 40, 50, 62, 76, 100)
TITLE_IN, TITLE_OUT = 0.6, 0.8                   # title fade in / out (s)
TITLE_FONTS = {   # key -> font files to look for (Windows names first)
    "impact": ("impact.ttf",), "arialblack": ("ariblk.ttf", "Arial Black.ttf"),
    "arialbold": ("arialbd.ttf", "Arial Bold.ttf"), "georgia": ("georgiab.ttf", "Georgia Bold.ttf"),
    "verdana": ("verdanab.ttf", "Verdana Bold.ttf"), "segoeblack": ("seguibl.ttf",),
    "segoesemi": ("seguisb.ttf", "segoeuib.ttf", "arialbd.ttf", "Arial Bold.ttf"),
}
WM_POS = ("tl", "tc", "tr", "ml", "mc", "mr", "bl", "bc", "br")
WM_FONT = ("seguisb.ttf", "segoeuib.ttf", "arialbd.ttf", "Arial Bold.ttf")
FALLBACK_FONTS = ("DejaVuSans-Bold.ttf", "LiberationSans-Bold.ttf", "arial.ttf", "Arial.ttf", "DejaVuSans.ttf")
def flash_frames(T):
    """Flash modifier: white frames centred on the cut, 100% in the middle, ~70% at the edges."""
    h = max(1, T // 4)
    return [(d, round(1.0 - 0.3 * abs(d) / h, 2)) for d in range(-h, h + 1)]


def glitch_half(T):
    return max(2, T // 2)


_font_index = None
_filters = {}


def has_filter(name):
    """Does this FFmpeg build have the filter? (some minimal builds have no text support)"""
    if name not in _filters:
        try:
            r = run(["ffmpeg", "-hide_banner", "-h", f"filter={name}"], timeout=15)
            _filters[name] = r.returncode == 0 and "Unknown filter" not in (r.stdout or "") + (r.stderr or "")
        except Exception:
            _filters[name] = False
    return _filters[name]


def find_font(names):
    """Path of the first font file found (Windows, macOS or Linux font folders), or None."""
    global _font_index
    if _font_index is None:
        _font_index = {}
        dirs = [os.path.join(os.environ.get("WINDIR", r"C:\Windows"), "Fonts"),
                os.path.join(os.environ.get("LOCALAPPDATA", ""), "Microsoft", "Windows", "Fonts"),
                "/Library/Fonts", "/System/Library/Fonts", "/System/Library/Fonts/Supplemental",
                os.path.expanduser("~/Library/Fonts"), "/usr/share/fonts", "/usr/local/share/fonts",
                os.path.expanduser("~/.fonts")]
        for d in dirs:
            if not d or not os.path.isdir(d):
                continue
            for root, _, files in os.walk(d):
                for f in files:
                    _font_index.setdefault(f.lower(), os.path.join(root, f))
    for nm in list(names) + list(FALLBACK_FONTS):
        hit = _font_index.get(nm.lower())
        if hit:
            return hit
    return None


class RenderError(Exception):
    pass


class Cancelled(Exception):
    pass


def parse_tf(tfp):
    """Transform of a cut or of one pane: zoom 100-300 % (or width / height with the lock off), pan, Ken Burns."""
    tfp = tfp or {}
    zz = lambda k: min(3.0, max(1.0, float(tfp.get(k, 100) or 100) / 100.0))
    return {"zoom": zz("zoom"), "lock": tfp.get("lock", True) is not False, "zx": zz("zx"), "zy": zz("zy"),
            "x": min(1.0, max(-1.0, float(tfp.get("x", 0) or 0) / 100.0)),
            "y": min(1.0, max(-1.0, float(tfp.get("y", 0) or 0) / 100.0)),
            "kb": bool(tfp.get("kb")), "dir": "out" if tfp.get("dir") == "out" else "in",
            "amt": min(0.8, max(0.05, float(tfp.get("amt", 20) or 20) / 100.0))}


def validate_plan(plan):
    """Check the plan sent by the page and normalise it. Raises ValueError."""
    song = SONGS.get(plan.get("song"))
    if not song:
        raise ValueError("Song not found - load it again.")
    secs = plan.get("sections") or []
    if not secs:
        raise ValueError("No sections to render.")
    start = float(plan["start"])
    total = int(plan["totalFrames"])
    out_secs = []
    for i, s in enumerate(secs):
        clip = CLIPS.get(s.get("clip"))
        if not clip or clip.get("status") != "ready":
            raise ValueError(f"Section {i + 1} has no video.")
        f0, f1 = int(s["f0"]), int(s["f1"])
        if f1 - f0 < 2:
            raise ValueError(f"Section {i + 1} is too short.")
        if i == 0 and f0 != 0:
            raise ValueError("First section must start at frame 0.")
        if i > 0 and f0 != out_secs[-1]["f1"]:
            raise ValueError("Sections are not continuous.")
        fill = s.get("fill", "crop")
        if fill not in FILL_FILTERS:
            fill = "crop"
        beats = [(int(b["k"]), bool(b.get("h")),
                  b.get("kind") if b.get("kind") in ("zoom", "flicker", "fade", "shake", "spark") else "zoom",
                  min(1.0, max(0.0, float(b.get("str", 100) if b.get("str") is not None else 100) / 100.0)))
                 for b in (s.get("beats") or [])]
        speed = min(MAX_SPEED, max(MIN_SPEED, float(s.get("speed", 1) or 1)))
        sec = {"clip": clip, "f0": f0, "f1": f1, "fill": fill,
               "clipStart": max(0.0, float(s.get("clipStart", 0))),
               "speed": speed, "beats": beats, "layout": "single",
               "vol": min(2.0, max(0.0, float(s.get("vol", 100) if s.get("vol") is not None else 100) / 100.0)), "mute": bool(s.get("mute"))}
        sec["tf"] = parse_tf(s.get("tf"))
        sec["off"] = parse_off(s.get("off"))
        sec["mo"] = parse_mo(s.get("mo"), 100000)       # the cut's own Animation (in / out)
        ovs = []
        for o in (s.get("ovs") or [])[:3]:              # floating layers baked into this cut
            oc = CLIPS.get((o or {}).get("clip"))
            if not oc or oc.get("status") != "ready":
                continue
            ovs.append({"clip": oc, "x": _fnum(o.get("x"), OUTPUT_W / 2, -10000, 10000), "y": _fnum(o.get("y"), OUTPUT_H / 2, -10000, 10000),
                        "scale": _fnum(o.get("scale"), 30, 1, 400) / 100.0, "opacity": _fnum(o.get("opacity"), 100, 0, 100) / 100.0, "t0": 0,
                        "shadow": _fnum(o.get("shadow"), 0, 0, 100) / 100.0, "fade": int(_fnum(o.get("fade"), 0, 0, 60)),
                        "mo": parse_mo(o.get("mo"), 100000)})
            ob = parse_bgr(o.get("bgr"))                 # AI background removal on the overlay itself
            if ob:
                ob["matte"] = bgr_matte_clip(o.get("clip"), ob, f"an overlay of cut {i + 1}")
                ovs[-1]["bgr"] = ob
        if ovs:
            sec["ovs"] = ovs
        cvp = s.get("curve") or {}
        if cvp.get("on"):
            raw = list(cvp.get("v") or [])[:12]
            vv = [min(10.0, max(0.1, float(x))) for x in (raw if len(raw) >= 2 else raw + [1, 1, 1, 1])[:12]]
            sec["curve"] = {"v": vv, "u": curve_nodes(cvp.get("u"), len(vv)), "ease": bool(cvp.get("ease", True))}
        fx = parse_fx(s.get("fx"))
        if fx:
            sec["fx"] = fx
        lfx = {k: v for k, v in tl_parse_fx(s.get("lfx")).items() if k in BS_LFX}        # the Timeline's looks, on a Beat Sync cut
        if lfx:
            sec["lfx"] = lfx
        bgr = parse_bgr(s.get("bgr"))
        if bgr and s.get("layout") in (None, "single"):
            bgr["matte"] = bgr_matte_clip(s.get("clip"), bgr, f"cut {i + 1}")
            sec["bgr"] = bgr
        lay = s.get("layout")
        _ow, _oh = ORIENTS.get(plan.get("orient"), ORIENTS["landscape"])
        if lay in MULTI:                               # (every layout works in every shape: side by side, or stacked)
            panes = []
            npn = 3 if lay == "tri" else 2
            for pn in (list(s.get("panes") or []) + [None, None, None])[:npn]:
                pc = CLIPS.get((pn or {}).get("clip"))
                if pn and (not pc or pc.get("status") != "ready"):
                    raise ValueError(f"Section {i + 1}: a triptych video is not ready yet.")
                pf = (pn or {}).get("fill", "crop")
                pst = (pn or {}).get("clipStart")
                panes.append({"clip": pc, "fill": pf if pf in FILL_FILTERS else "crop",
                              "mirror": bool((pn or {}).get("mirror")),
                              "clipStart": max(0.0, float(pst)) if pst is not None else sec["clipStart"],
                              "vol": min(2.0, max(0.0, float(pn.get("vol", 100) if pn.get("vol") is not None else 100) / 100.0)), "mute": bool(pn.get("mute")),
                              "tf": parse_tf(pn.get("tf")) if pn.get("tf") else None, "off": parse_off(pn.get("off"))} if pc else None)
                if pc and pn.get("speed") is not None:            # this pane has its own speed (and maybe its own speed graph)
                    pv = pn.get("curve") or {}
                    panes[-1].update(own=True, speed=min(MAX_SPEED, max(MIN_SPEED, float(pn.get("speed") or 1))))
                    if pv.get("on"):
                        raw = list(pv.get("v") or [])[:12]
                        vv = [min(10.0, max(0.1, float(x))) for x in (raw if len(raw) >= 2 else raw + [1, 1, 1, 1])[:12]]
                        panes[-1]["curve"] = {"v": vv, "u": curve_nodes(pv.get("u"), len(vv)), "ease": bool(pv.get("ease", True))}
            if lay == "split":
                sec.update(layout="split", panes=panes, splitH=min(80.0, max(20.0, float(s.get("splitH", 50) or 50))))
                out_secs.append(sec)
                continue
            if lay == "duo":
                df = s.get("duoFit")
                sec.update(layout="duo", panes=panes, duoFit=df if df in DUO_FITS else "gaps",
                           duoW=min(80.0, max(20.0, float(s.get("duoW", 50) or 50))))
                out_secs.append(sec)
                continue
            tf = s.get("triFit")
            sec.update(layout="tri", panes=panes, triFit=tf if tf in TRI_FITS else "gaps")
            tw = s.get("triW")
            if tf == "custom" and isinstance(tw, list) and len(tw) == 3:
                w3 = [min(80.0, max(10.0, float(x))) for x in tw]
                tot = sum(w3)
                sec["triW"] = [x * 100 / tot for x in w3]
            elif tf == "custom":
                sec["triFit"] = "all"
        out_secs.append(sec)
    if out_secs[-1]["f1"] != total:
        raise ValueError("Sections don't cover the selection.")

    raw = plan.get("transitions") or []
    trans = []
    for i in range(len(out_secs) - 1):
        t = (raw[i] if i < len(raw) else None) or {}
        typ = t.get("type", "none")
        flash = bool(t.get("flash"))
        if typ == "flash":                 # older plans: Flash used to be its own type
            typ, flash = "none", True
        if typ not in XFADE and typ not in POST_ONLY:
            typ = "none"
        tf = int(t.get("tf", 0)) if typ in XFADE else 0
        la = out_secs[i]["f1"] - out_secs[i]["f0"]
        lb = out_secs[i + 1]["f1"] - out_secs[i + 1]["f0"]
        tf = min(tf, la, lb)
        tf -= tf % 2            # even, so each side extends by exactly tf/2 frames
        if tf < 2 and typ in XFADE:
            typ, tf = "none", 0
        trans.append({"type": typ, "tf": tf, "flash": flash, "opt": parse_topt(t.get("opt")) if typ == "bflash" else None,
                      "ez": _fnum(t.get("ez"), 0, 0, 100) / 100})

    p = plan.get("pulse") or {}
    pulse = {"on": bool(p.get("on")),
             "intensity": min(3.0, max(0.0, float(p.get("intensity", 100)) / 100.0)),
             "heavy": bool(p.get("heavy")),
             "blur": bool(plan.get("blur", True)),      # whip blur on slides
             "tlen": max(2, min(30, int(plan.get("tlen", TLEN_DEFAULT)) // 2 * 2)),   # transition length (frames)
             "mblur": bool(p.get("mblur")),
             "orient": plan.get("orient") if plan.get("orient") in ORIENTS else "landscape",
             "smooth": bool(plan.get("smoothSlow", True)),           # blend frames for slow motion                                         # zoom blur on thumps
             "mblurAmt": min(2.0, max(0.1, float(p.get("mblurAmt", 100)) / 100.0))}
    pulse["polish"] = validate_polish(plan.get("polish") or {}, total)
    pulse["look"] = parse_look((plan.get("polish") or {}).get("look"))
    pulse["look_segs"] = parse_look_segs((plan.get("polish") or {}).get("look"), total) if ((plan.get("polish") or {}).get("look") or {}).get("on") else []
    pulse["feel"] = plan.get("feel") if plan.get("feel") in EASE_FEEL else "smooth"
    pulse["govs"] = parse_govs(plan.get("overlays"), total)
    pulse["vis"] = parse_vis(plan.get("vis"), (SONGS.get(plan.get("song")) or {}).get("path"), plan.get("start"), total)
    au = plan.get("audio") or {}
    pulse["audio"] = {"song": min(2.0, max(0.0, float(au.get("song", 100)) / 100.0)),
                      "clips": min(2.0, max(0.0, float(au.get("clips", 100)) / 100.0)),
                      "fadeIn": min(30.0, max(0.02, float(au.get("fadeIn", 0.02) or 0.02), _fnum(au.get("fin"), 0, 0, 10))),   # Intro Sequence ease-in / song fade in
                      "fadeOut": _fnum(au.get("fout"), 0.25, 0.02, 15),           # song fade out at the end (s)
                      "xf": _fnum(au.get("xf"), 30, 0, 250) / 1000.0}             # clip sound: fade at each hard cut (s)
    pulse["export"] = parse_export(plan.get("export"))
    return song, start, total, out_secs, trans, pulse


def validate_polish(po, total):
    f = lambda v, d, lo, hi: min(hi, max(lo, float(v if v is not None else d)))
    color = lambda v, d: v if isinstance(v, str) and re.fullmatch(r"#[0-9a-fA-F]{6}", v) else d
    it, tt, wm = po.get("intro") or {}, po.get("title") or {}, po.get("wm") or {}
    title_text = str(tt.get("text") or "").replace("\r", " ").replace("\n", " ").strip()[:120]
    wm_text = str(wm.get("text") or "").replace("\r", " ").replace("\n", " ").strip()[:60]
    sq = po.get("seq") or {}
    nseq = max(0, min(total, int(sq.get("frames", 0))))
    fade = f(sq.get("fade"), 2.0, 0.2, 30.0)

    def style(d, outline_on, out_w, shadow_on, sx, sy, sblur, sop):
        ol, sh = d.get("outline") or {}, d.get("shadow") or {}
        return {"outline": {"on": bool(ol.get("on", outline_on)), "w": f(ol.get("w"), out_w, 0, 30),
                            "color": color(ol.get("color"), "#000000")},
                "shadow": {"on": bool(sh.get("on", shadow_on)), "x": f(sh.get("x"), sx, -60, 60), "y": f(sh.get("y"), sy, -60, 60),
                           "blur": f(sh.get("blur"), sblur, 0, 60), "color": color(sh.get("color"), "#000000"),
                           "op": f(sh.get("op"), sop, 0, 100) / 100.0}}
    title = {"on": bool(tt.get("on")) and bool(title_text), "text": title_text,
             "size": int(f(tt.get("size"), 120, 24, 300)), "color": color(tt.get("color"), "#ffd34d"),
             "font": tt.get("font") if tt.get("font") in TITLE_FONTS else "impact",
             "pos": tt.get("pos") if tt.get("pos") in ("center", "top", "lower") else "center",
             "start": f(tt.get("start"), 0.3, 0.0, total / FPS - 0.2),
             "dur": f(tt.get("dur"), 3.5, 0.8, 30.0), "glow": f(tt.get("glow"), 100, 0, 200) / 100.0}
    title.update(style(tt, False, 4, False, 6, 6, 10, 70))
    title["glowColor"] = color(tt.get("glowColor"), title["color"])
    wmg = wm.get("glow") or {}
    wmark = {"on": bool(wm.get("on")) and bool(wm_text), "text": wm_text,
             "size": int(f(wm.get("size"), 30, 12, 200)), "opacity": f(wm.get("opacity"), 55, 10, 100) / 100.0,
             "pos": wm.get("pos") if wm.get("pos") in WM_POS else "bc",
             "dx": f(wm.get("dx"), 0, -1000, 1000), "dy": f(wm.get("dy"), 0, -1000, 1000),
             "font": wm.get("font") if wm.get("font") in TITLE_FONTS else "segoesemi",
             "color": color(wm.get("color"), "#ffffff"),
             "glow": {"amt": f(wmg.get("amt"), 0, 0, 200) / 100.0, "color": color(wmg.get("color"), "#ffffff")}}
    wmark.update(style(wm, False, 2, True, 2, 2, 0, 55))
    ov = po.get("ov") or {}
    oc = CLIPS.get(ov.get("clip"))
    ovl = {"on": bool(ov.get("on")) and bool(oc and oc.get("image") and oc.get("status") == "ready"),
           "image": oc.get("image") if oc else None, "iw": (oc or {}).get("width") or 0, "ih": (oc or {}).get("height") or 0,
           "size": f(ov.get("size"), 30, 2, 100) / 100.0, "opacity": f(ov.get("opacity"), 100, 0, 100) / 100.0,
           "pos": ov.get("pos") if ov.get("pos") in WM_POS else "tr",
           "dx": f(ov.get("dx"), 0, -2000, 2000), "dy": f(ov.get("dy"), 0, -2000, 2000),
           "start": f(ov.get("start"), 0, 0, total / FPS), "dur": f(ov.get("dur"), 0, 0, total / FPS)}
    return {
        "total": total, "ov": ovl,
        "seq": {"on": bool(sq.get("on")) and nseq >= FPS // 2, "frames": nseq,
                "blur": f(sq.get("blur"), 100, 0, 200) / 100.0, "fade": fade,
                # Unblur start (s into the intro) + how long it takes to clear (can run on into the main edit)
                "ustart": f(sq.get("ustart"), max(0.0, nseq / FPS - fade), 0.0, nseq / FPS),
                "udur": f(sq.get("udur"), fade, 0.1, 30.0)},
        "intro": {"on": bool(it.get("on")), "dur": f(it.get("dur"), 2.5, 0.5, 6.0),
                  "amt": f(it.get("amt"), 100, 20, 200) / 100.0},
        "title": title,
        "wm": wmark,
    }


# ----- clip time: speed, plus Slow-mo windows at either end ---------------------
def time_map(sp, L, tin, tout, slow_in, slow_out):
    """Piecewise clip speed in clip seconds: (t1, t2, a1, b, a3).
    [0, t1) plays at a1, [t1, t2) at b (the cut's speed), [t2, ...) at a3."""
    t1 = tin / FPS if slow_in else 0.0
    t2 = (L - tout) / FPS if slow_out else L / FPS + 3600.0
    a1 = sp * SLOWMO_RATE if slow_in else sp
    a3 = sp * SLOWMO_RATE if slow_out else sp
    return t1, t2, a1, sp, a3


def clip_offset(tm, tau):
    """Seconds of source footage used after `tau` seconds of on-screen clip time."""
    t1, t2, a1, b, a3 = tm
    if tau < t1:
        return a1 * tau
    if tau < t2:
        return a1 * t1 + b * (tau - t1)
    return a1 * t1 + b * (t2 - t1) + a3 * (tau - t2)


def curve_nodes(u, n):
    """Keyframe positions (0..1) of a Speed Graph with n keyframes: the plan's own if they are sane, else evenly spaced."""
    try:
        uu = [float(x) for x in (u or [])]
    except (TypeError, ValueError):
        uu = []
    if len(uu) == n and n >= 2 and all(uu[i + 1] - uu[i] > 1e-4 for i in range(n - 1)):
        lo, hi = uu[0], uu[-1]
        return [0.0] + [min(1.0, max(0.0, (x - lo) / (hi - lo))) for x in uu[1:-1]] + [1.0]
    return [i / (n - 1) for i in range(n)]


def curve_speed(cv, u):
    """Speed Graph: keyframes (position u 0..1 of the cut, speed v); interpolated in log space (eased or straight)."""
    import math
    v = cv["v"]
    U = cv.get("u") or [i / (len(v) - 1) for i in range(len(v))]
    u = min(1.0, max(0.0, u))
    seg = 0
    while seg < len(v) - 2 and u >= U[seg + 1]:
        seg += 1
    x = min(1.0, max(0.0, (u - U[seg]) / max(1e-9, U[seg + 1] - U[seg])))
    w = x * x * (3 - 2 * x) if cv.get("ease", True) else x
    a, b = math.log2(v[seg]), math.log2(v[seg + 1])
    return 2 ** (a + (b - a) * w)


def curve_table(cv, n):
    """Per-output-frame speeds r[k] and cumulative source seconds O[k] (k = 0..n) for this
    (possibly chunk-sliced) cut. Frame k of the slice is frame k0+k of the whole cut."""
    L, k0 = cv["L"], cv.get("k0", 0)
    r = [curve_speed(cv, (k0 + k + 0.5) / L) for k in range(n)]
    O = [0.0]
    for x in r:
        O.append(O[-1] + x / FPS)
    return r, O


def pane_timing(s, pp):
    """The cut as one of its panes times it: the pane's own speed / speed graph if it has one, else the cut's."""
    if pp and pp.get("own"):
        return dict(s, speed=pp["speed"], curve=pp.get("curve"), blend=pp.get("blend", False))
    return s


def prep_pane_timing(s, L):
    """Before a render: which own-speed panes glide (frame blending) + the length their speed graph runs over."""
    for pp in (s.get("panes") or []) if s.get("layout") in MULTI else []:
        if pp and pp.get("own"):
            pcv = pp.get("curve")
            pp["blend"] = pp["speed"] < 0.99 or bool(pcv and min(pcv["v"]) < 0.99)
            if pcv:
                pcv.update(L=L, k0=0)


def offset_fn(s, L, tin, tout, slow_in, slow_out):
    """tau (s on screen) -> seconds of source used. Speed Graph cuts follow their curve, others time_map."""
    cv = s.get("curve")
    if cv:
        cvl = dict(cv, L=cv.get("L", L))
        r, O = curve_table(cvl, L)

        def f(tau):
            k = tau * FPS
            if k <= 0:
                return tau * r[0]
            i = min(L - 1, int(k))
            return O[i] + (k - i) * r[i] / FPS
        return f
    tm = time_map(s.get("speed", 1.0), L, tin, tout, slow_in, slow_out)
    return lambda tau: clip_offset(tm, tau)


def section_windows(secs, trans, i):
    n = len(secs)
    tin = trans[i - 1]["tf"] if i > 0 else 0
    tout = trans[i]["tf"] if i < n - 1 else 0
    slow_in = i > 0 and trans[i - 1]["type"] in SLOW_T and tin > 0
    slow_out = i < n - 1 and trans[i]["type"] in SLOW_T and tout > 0
    return tin, tout, slow_in, slow_out


# ----- chunking --------------------------------------------------------------
def post_half(t, T):
    """How many frames an effect reaches either side of its cut (flash / glitch)."""
    h = 0
    if t.get("flash"):
        h = max(h, max(1, T // 4) + 1)
    if t["type"] == "glitch":
        h = max(h, glitch_half(T) + 1)
    if t["type"] in ("punch", "zsync"):
        h = max(h, max(T, punch_len(T)) + 1)
    return h


def pick_cuts(secs, trans, chunk=None, T=TLEN_DEFAULT):
    """Global frames where the render can be split. A cut is only legal where
    no transition is running, and never leaves a slice shorter than 2 frames."""
    chunk = chunk or CHUNK_SECTIONS
    n = len(secs)
    if n <= chunk:
        return _time_cuts(secs, trans, [], T)

    def cand(i):
        s = secs[i]
        tin = trans[i - 1]["tf"] if i > 0 else 0
        tout = trans[i]["tf"] if i < n - 1 else 0
        ph_in = post_half(trans[i - 1], T) if i > 0 else 0
        ph_out = post_half(trans[i], T) if i < n - 1 else 0
        if tin == 0 and ph_in == 0:
            return s["f0"]                       # clean hard cut
        lo = max(s["f0"] + tin // 2, s["f0"] + 2, s["f0"] + ph_in)
        hi = min(s["f1"] - tout // 2, s["f1"] - 2, s["f1"] - ph_out)
        return (lo + hi) // 2 if lo <= hi else None

    cuts, last_i, j = [], 0, chunk
    while j < n:
        best = None
        for d in range(chunk // 2):
            for i in (j - d, j + d):
                if last_i < i < n and cand(i) is not None:
                    best = i
                    break
            if best is not None:
                break
        if best is None:
            j += chunk
            continue
        w = cand(best)
        if not cuts or w > cuts[-1]:
            cuts.append(w)
        last_i = best
        j = best + chunk
    return _time_cuts(secs, trans, cuts, T)


def _time_cuts(secs, trans, cuts, T):
    """Extra split points so that no piece is longer than CHUNK_SECONDS (a few long cuts can be many minutes).
    A split may sit in the middle of a cut, but never where a transition is running."""
    n, total, lim = len(secs), secs[-1]["f1"] if secs else 0, int(CHUNK_SECONDS * FPS)
    if total <= lim * 1.5:
        return cuts

    def zone(i):
        s = secs[i]
        tin = trans[i - 1]["tf"] if i > 0 else 0
        tout = trans[i]["tf"] if i < n - 1 else 0
        ph_in = post_half(trans[i - 1], T) if i > 0 else 0
        ph_out = post_half(trans[i], T) if i < n - 1 else 0
        return max(s["f0"] + tin // 2, s["f0"] + 2, s["f0"] + ph_in), min(s["f1"] - tout // 2, s["f1"] - 2, s["f1"] - ph_out)

    out, bounds = [], [0] + list(cuts) + [total]
    for a, b in zip(bounds, bounds[1:]):
        pos = a
        while b - pos > lim * 1.5:
            tgt, best = pos + lim, None
            for i in range(n):
                if secs[i]["f1"] <= pos + 5 * FPS or secs[i]["f0"] >= b - 5 * FPS:
                    continue
                lo, hi = zone(i)
                lo, hi = max(lo, pos + 5 * FPS), min(hi, b - 5 * FPS)
                if lo > hi:
                    continue
                w = min(max(tgt, lo), hi)
                if best is None or abs(w - tgt) < abs(best - tgt):
                    best = w
            if best is None or best <= pos:
                break
            out.append(best)
            pos = best
        if b < total:
            out.append(b)
    return sorted(set(out))


def slice_plan(secs, trans, w0, w1):
    """The part of the edit between global frames [w0, w1), re-based to frame 0.
    Sections cut by the window keep their exact clip timing and pulse beats."""
    n = len(secs)
    out_s, idx = [], []
    for i, s in enumerate(secs):
        if s["f1"] <= w0 or s["f0"] >= w1:
            continue
        tin = trans[i - 1]["tf"] if i > 0 else 0
        tout = trans[i]["tf"] if i < n - 1 else 0
        clip_f0 = s["f0"] - tin // 2                 # global frame of clip frame 0
        nf0, nf1 = max(s["f0"], w0), min(s["f1"], w1)
        _, _, slow_in, slow_out = section_windows(secs, trans, i)
        Lfull = (s["f1"] - s["f0"]) + tin // 2 + tout // 2
        off_full = offset_fn(s, Lfull, tin, tout, slow_in, slow_out)
        ntin = tin if s["f0"] >= w0 else 0
        ntout = tout if s["f1"] <= w1 else 0
        delta = (nf0 - ntin // 2) - clip_f0          # clip frames skipped
        L = (nf1 - nf0) + ntin // 2 + ntout // 2
        beats = [(b[0] - delta,) + tuple(b[1:]) for b in s["beats"]
                 if -PULSE_FRAMES < b[0] - delta < L]   # keep tails of beats just before the cut
        shift = off_full(delta / FPS)
        ns = dict(s, f0=nf0 - w0, f1=nf1 - w0, clipStart=s["clipStart"] + shift, beats=beats)
        if s.get("curve"):
            cv = s["curve"]
            ns["curve"] = dict(cv, L=cv.get("L", Lfull), k0=cv.get("k0", 0) + delta)
        if s.get("layout") in MULTI:
            def _pane(pp):
                if not pp or not pp.get("own"):
                    return dict(pp, clipStart=pp["clipStart"] + shift) if pp else None
                np_ = dict(pp, clipStart=pp["clipStart"] + offset_fn(pane_timing(s, pp), Lfull, tin, tout, slow_in, slow_out)(delta / FPS))
                if pp.get("curve"):
                    np_["curve"] = dict(pp["curve"], L=pp["curve"].get("L", Lfull), k0=pp["curve"].get("k0", 0) + delta)
                return np_
            ns["panes"] = [_pane(pp) for pp in s["panes"]]
        if s.get("ovs"):                               # overlays keep running from where the cut is
            ns["ovs"] = [dict(o, t0=o.get("t0", 0) + delta) for o in s["ovs"]]
        if s.get("fx"):                                # effects + tracked censor keep the cut's own clock
            ns["fxoff"] = s.get("fxoff", 0) + delta
        ns["kof"] = s.get("kof", 0) + delta            # (clip frames already played: the cut's Animation keeps its own clock too)
        out_s.append(ns)
        idx.append(i)
    out_t = [trans[i] for i in idx[:-1]]
    return out_s, out_t


# ----- filtergraph -------------------------------------------------------------
# ---------------------------------------------------------------------------
# Beat Sync: cut Effects (applied to the cut BEFORE the thumps), the censor box (static or tracked)
# and the song-wide Overlay layers (after the cuts + transitions, before the thumps).
# ---------------------------------------------------------------------------
BS_LFX = ("vhs", "rgb", "chroma", "bloom", "vig", "bars", "mirror", "flipv", "kmirror")     # (all the same on every frame: safe when a render is split in parts)


def parse_fx(fx):
    fx = fx or {}
    f = lambda d, k, dv, lo, hi: _fnum((d or {}).get(k), dv, lo, hi)
    on = lambda d: bool((d or {}).get("on"))
    out = {}
    b = fx.get("bright")
    if on(b):
        out["bright"] = {"hz": f(b, "hz", 2, 0.1, 12), "amt": f(b, "amt", 10, 0, 40) / 100}
    b = fx.get("shake")
    if on(b):
        out["shake"] = {"amt": f(b, "amt", 10, 1, 60), "hz": f(b, "hz", 8, 0.5, 25)}
    b = fx.get("glitch")
    if on(b):
        out["glitch"] = {"dur": f(b, "dur", 0.3, 0.05, 2), "amt": int(f(b, "amt", 10, 1, 60))}
    b = fx.get("zblur")
    if on(b):
        out["zblur"] = {"amt": f(b, "amt", 100, 10, 300) / 100}
    b = fx.get("leak")
    if on(b):
        out["leak"] = {"amt": f(b, "amt", 60, 5, 100) / 100, "period": f(b, "period", 3, 0.5, 12)}
    b = fx.get("censor")
    if on(b):
        cz = {"mode": "black" if b.get("mode") == "black" else "blur", "blur": f(b, "blur", 20, 2, 80),
              "x": f(b, "x", 0, -4000, 8000), "y": f(b, "y", 0, -4000, 8000),
              "w": max(4.0, f(b, "w", 200, 4, 8000)), "h": max(4.0, f(b, "h", 200, 4, 8000))}
        tr = b.get("track") or {}
        boxes = tr.get("boxes") if isinstance(tr.get("boxes"), list) else None
        if boxes:
            bb = []
            for v in boxes[:20000]:
                try:
                    bb.append([float(v[0]), float(v[1]), float(v[2]), float(v[3])])
                except (TypeError, ValueError, IndexError):
                    bb.append(bb[-1] if bb else [cz["x"], cz["y"], cz["w"], cz["h"]])
            cz["track"] = bb
        out["censor"] = cz
    return out


_leak_cache = {}


def leak_png(w, h):
    """Warm light-leak gradient (RGBA, w x h). The preview loads the very same picture from /api/leak."""
    key = (w, h)
    p = _leak_cache.get(key)
    if p and os.path.exists(p):
        return p
    import numpy as np
    from PIL import Image
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    d = max(w, h)
    r1 = np.hypot(xx - 0.12 * w, yy - 0.08 * h) / (0.95 * d)          # main glow from the top-left corner
    r2 = np.hypot(xx - 0.95 * w, yy - 0.9 * h) / (0.55 * d)           # a softer one bottom-right
    a1 = np.clip(1 - r1, 0, 1) ** 2.2
    a2 = np.clip(1 - r2, 0, 1) ** 2.6 * 0.6
    a = np.clip(a1 + a2, 0, 1)
    k = np.clip(xx / w, 0, 1)
    col = np.stack([np.full_like(k, 255), 150 - 70 * k, 40 + 70 * k], -1)          # orange -> pink across
    img = np.concatenate([col, (a * 235)[..., None]], -1).astype(np.uint8)
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    p = os.path.join(UPLOAD_DIR, f"_leak_{w}x{h}.png")
    Image.fromarray(img, "RGBA").save(p)
    _leak_cache[key] = p
    return p


def leak_alpha(fx, u):
    """Light leak opacity at clip-local time u (s): fades in and out once per cycle."""
    return fx["amt"] * (0.5 - 0.5 * _math.cos(2 * _math.pi * u / fx["period"]))


def censor_box(cz, k):
    """Censor box (x, y, w, h, output px) on clip-local frame k: tracked boxes keep the first box's size."""
    tr = cz.get("track")
    if not tr:
        return cz["x"], cz["y"], cz["w"], cz["h"]
    b = tr[min(max(0, k), len(tr) - 1)]
    cx, cy = b[0] + b[2] / 2, b[1] + b[3] / 2
    return cx - cz["w"] / 2, cy - cz["h"] / 2, cz["w"], cz["h"]


def cut_fx_chain(c, s, i, L, inputs, n_in, chains, tag, pulse):
    """The cut's own effects, in order: censor -> brightness pulse -> shake -> glitch -> light leak -> zoom blur.
    `c` is the cut's filter list so far (L frames, OUTPUT size); returns the new one."""
    fx = s.get("fx") or {}
    if not fx:
        return c
    off = s.get("fxoff", 0)                         # clip frames skipped (when the render is split in parts)
    W, H = OUTPUT_W, OUTPUT_H
    rel = lambda p: os.path.relpath(p, UPLOAD_DIR).replace(chr(92), "/")
    U = f"(t+{off / FPS:.6f})"                       # clip-local seconds
    chains.append(",".join(c) + f",format=yuv420p,settb=1/{FPS},setpts=N[fx{i}_0]")
    cur, step = f"[fx{i}_0]", [0]

    def nxt():
        step[0] += 1
        return f"[fx{i}_{step[0]}]"
    cz = fx.get("censor")
    if cz:
        boxes = [censor_box(cz, k + off) for k in range(L)]
        moving = len({tuple(round(v) for v in b) for b in boxes}) > 1
        cmd = f"{tag}_cz{i}.txt"
        if moving:
            nm = f"czb{i}" if cz["mode"] == "black" else f"czm{i}"
            with open(cmd, "w", encoding="utf-8") as fh:
                last = None
                for k, b in enumerate(boxes):
                    r = tuple(int(round(v)) for v in b)
                    if r != last:
                        fh.write(f"{k / FPS:.6f} drawbox@{nm} x {r[0]}, drawbox@{nm} y {r[1]}, drawbox@{nm} w {r[2]}, drawbox@{nm} h {r[3]};\n")
                        last = r
        x0, y0, w0, h0 = (int(round(v)) for v in boxes[0])
        sc = f"sendcmd=f='{rel(cmd)}'," if moving else ""
        o = nxt()
        if cz["mode"] == "black":
            chains.append(f"{cur}{sc}drawbox@czb{i}=x={x0}:y={y0}:w={w0}:h={h0}:color=black:t=fill{o}")
        else:
            chains.append(f"{cur}{sc}format=gbrp,split=3[czo{i}][czs{i}][czk{i}]")
            chains.append(f"[czs{i}]gblur=sigma={cz['blur']:.2f}:steps=3[czl{i}]")
            chains.append(f"[czk{i}]drawbox=x=0:y=0:w=iw:h=ih:color=black:t=fill,"
                          f"drawbox@czm{i}=x={x0}:y={y0}:w={w0}:h={h0}:color=white:t=fill[czq{i}]")
            chains.append(f"[czo{i}][czl{i}][czq{i}]maskedmerge,format=yuv420p{o}")
        cur = o
    post = []
    b = fx.get("bright")
    if b and b["amt"] > 0:                          # brightness rides a sine the whole time the cut is on screen
        post.append(f"eq=brightness='{b['amt']:.4f}*sin(2*PI*{U}*{b['hz']:.4f})':eval=frame")
    b = fx.get("shake")
    if b:                                           # random-looking shake: crop window wanders, scaled back to full frame
        m = int(_math.ceil(b["amt"] / 2) * 2)
        hz = b["hz"]
        xs = f"{m}+{m}*(0.6*sin(2*PI*{hz:.4f}*{U})+0.4*sin(2*PI*{hz * 1.7:.4f}*{U}+1.3))"
        ys = f"{m}+{m}*(0.6*cos(2*PI*{hz * 1.3:.4f}*{U}+0.7)+0.4*cos(2*PI*{hz * 2.1:.4f}*{U}))"
        post.append(f"crop=w={W - 2 * m}:h={H - 2 * m}:x='{xs}':y='{ys}':exact=1,scale={W}:{H}:flags=bicubic,setsar=1")
    b = fx.get("glitch")
    if b:                                           # RGB split burst at the start of the cut (where it comes on screen)
        tin = s.get("_tin", 0)
        a, e = tin // 2 - off, tin // 2 + max(1, round(b["dur"] * FPS)) - off
        a, e = max(0, a), min(L, e)
        if e > a:
            A, A2 = b["amt"], max(1, b["amt"] // 2)
            post.append(f"format=gbrp,rgbashift=rh={-A}:bh={A}:enable='between(n,{a},{e - 1})*eq(mod(n+{off},2),0)',"
                        f"rgbashift=rh={A2}:bh={-A2}:gv={max(1, A2 // 2)}:enable='between(n,{a},{e - 1})*eq(mod(n+{off},2),1)',format=yuv420p")
    if post:
        o = nxt()
        chains.append(cur + ",".join(post) + o)
        cur = o
    b = fx.get("leak")
    if b:                                           # warm gradient laid on top, fading in and out
        cmd = f"{tag}_lk{i}.txt"
        with open(cmd, "w", encoding="utf-8") as fh:
            last = None
            for k in range(L):
                v = round(leak_alpha(b, (k + off) / FPS), 4)
                if v != last:
                    fh.write(f"{k / FPS:.6f} colorchannelmixer@lk{i} aa {v:.4f};\n")
                    last = v
        inputs.extend(["-loop", "1", "-framerate", str(FPS), "-t", f"{L / FPS + 1:.4f}", "-i", rel(leak_png(W, H))])
        idx = n_in[0]
        n_in[0] += 1
        chains.append(f"[{idx}:v]format=rgba,trim=end_frame={L + 1},setpts=PTS-STARTPTS,sendcmd=f='{rel(cmd)}',"
                      f"colorchannelmixer@lk{i}=aa={leak_alpha(b, off / FPS):.4f},settb=1/{FPS},setpts=N[lki{i}]")
        o = nxt()
        chains.append(f"{cur}[lki{i}]overlay=0:0:eof_action=repeat:format=auto,format=yuv420p{o}")
        cur = o
    b = fx.get("zblur")
    if b and s.get("beats"):                        # zoom blur on this cut's thump points
        lv = {}
        for k, heavy, kind, st in s["beats"]:
            if st <= 0:
                continue
            big = heavy and pulse.get("heavy")
            for d, w in enumerate(THUMP_BLUR_W):
                kk = k + d
                if 0 <= kk < L:
                    a = THUMP_BLUR_K * ((HEAVY_ZOOM if big else PULSE_ZOOM) / PULSE_ZOOM) * st * b["amt"] * w
                    if a >= THUMP_LEVELS[0] * 0.75:
                        lv[kk] = max(lv.get(kk, 0), a)
        if lv:
            groups = {}
            for f_, a in lv.items():
                groups.setdefault(min(THUMP_LEVELS, key=lambda v: abs(v - a)), []).append(f_)
            fxs = [f"geq={radial_expr(a)}:enable='{frame_ranges(fr)}'" for a, fr in sorted(groups.items())]
            chains.append(f"{cur}split[zbm{i}][zbb{i}]")
            chains.append(f"[zbb{i}]scale={W // 2}:{H // 2}," + ",".join(fxs) + f",scale={W}:{H}[zbz{i}]")
            o = nxt()
            chains.append(f"[zbm{i}][zbz{i}]overlay=enable='{frame_ranges(list(lv))}',format=yuv420p{o}")
            cur = o
    return [f"{cur}trim=end_frame={L},setpts=PTS-STARTPTS"]


def tl_parse_kfs(raw, props=("pos", "scale", "rot", "opacity")):
    """Keyframes sent by the page ({prop: [[frame, value], ...]}) -> {prop: [(frame, value), ...]}, sorted, one per frame."""
    kf = {}
    for k, lst in (raw.items() if isinstance(raw, dict) else []):
        if k not in props or not isinstance(lst, list):
            continue
        pts = {}
        for e in lst[:3000]:
            try:
                pts[int(e[0])] = [float(e[1][0]), float(e[1][1])] if k == "pos" else float(e[1])
            except (TypeError, ValueError, IndexError):
                continue
        if pts:
            kf[k] = sorted(pts.items())
    return kf


def parse_govs(raw, total):
    """Song-wide Overlay layers (Text / PNG) from the page: each is a picture + in/out + place + animation."""
    out = []
    for o in (raw or [])[:24]:
        if not isinstance(o, dict):
            continue
        vc = CLIPS.get(o.get("clip")) if isinstance(o.get("clip"), str) else None
        if vc and (vc.get("status") != "ready" or vc.get("kind", "video") not in ("video", "gif")):
            vc = None
        if not vc and not (isinstance(o.get("img"), str) and o["img"].startswith("data:image/png;base64,")):
            continue
        f0 = int(_fnum(o.get("f0"), 0, 0, total))
        f1 = int(_fnum(o.get("f1"), total, 0, total))
        if f1 - f0 < 2:
            continue
        box = o.get("box") or [1, 1]
        out.append({"img": None if vc else o["img"], "video": {"path": vc["path"], "v0": vc.get("v0", 0), "dur": float(vc.get("duration") or 0)} if vc else None,
                    "w": int(_fnum(o.get("w"), 2, 2, 8000)), "h": int(_fnum(o.get("h"), 2, 2, 8000)),
                    "f0": f0, "f1": f1, "x": _fnum(o.get("x"), OUTPUT_W / 2, -8000, 8000), "y": _fnum(o.get("y"), OUTPUT_H / 2, -8000, 8000),
                    "scale": _fnum(o.get("scale"), 100, 1, 2000), "opacity": _fnum(o.get("opacity"), 100, 0, 100),
                    "size": _fnum(o.get("size"), 100, 1, 2000), "box": [_fnum(box[0], 1, 1, 8000), _fnum(box[1], 1, 1, 8000)],
                    "kf": tl_parse_kfs(o.get("kf")), "anim": txa_norm(o.get("anim")), "tw": [u_ for u_ in (o.get("tw") if isinstance(o.get("tw"), list) else [])[:400] if isinstance(u_, str)],
                    "two": [u_ for u_ in (o.get("two") if isinstance(o.get("two"), list) else [])[:60] if isinstance(u_, str)],
                    "n": int(_fnum(o.get("n"), 0, 0, 400))})
    return out


def gov_layers(cur, chains, inputs, n_in, govs, frame0, total, tag):
    """Lay the song-wide overlays over the finished cuts + transitions (this part's frames)."""
    for li, o in enumerate(govs):
        a, b = o["f0"] - frame0, o["f1"] - frame0
        if b <= 0 or a >= total:
            continue
        N = o["f1"] - o["f0"]
        skip = max(0, -a)
        if o.get("video") and all(o["anim"][k_]["type"] == "none" for k_ in ("in", "out", "loop")) and not any((o.get("kf") or {}).values()):
            # a video layer that only sits there (a nested project as an overlay): scaled once to its size on the frame and laid on,
            # instead of warping a full-frame picture on every frame. A layer with an animation takes the general way below.
            v = o["video"]
            w = max(2, int(round(o["w"] * o["scale"] / 100 / 2)) * 2)
            h = max(2, int(round(o["h"] * o["scale"] / 100 / 2)) * 2)
            st, en = max(0, a), min(total, b)
            src = os.path.basename(v["path"]) if os.path.dirname(os.path.abspath(v["path"])) == os.path.abspath(UPLOAD_DIR) else os.path.abspath(v["path"])
            inputs.extend(["-ss", f"{v.get('v0', 0) + skip / FPS:.4f}", "-t", f"{(en - st) / FPS + 1:.4f}", "-i", src])
            idx = n_in[0]
            n_in[0] += 1
            op = o["opacity"] / 100
            chains.append(f"[{idx}:v]fps={FPS},scale={w}:{h}:flags=bicubic,setsar=1,format=yuva420p"
                          + (f",colorchannelmixer=aa={op:.4f}" if op < 0.999 else "") + f",setpts=PTS-STARTPTS+{st}/{FPS}/TB[gv{li}]")
            chains.append(f"{cur}[gv{li}]overlay=x={int(round(o['x'] - w / 2))}:y={int(round(o['y'] - h / 2))}:eof_action=pass:format=auto:"
                          f"enable='between(n,{st},{en - 1})',format=yuv420p,settb=1/{FPS},setpts=N[go{li}]")
            cur = f"[go{li}]"
            continue
        c = {"media": {"kind": "text", "w": o["w"], "h": o["h"], "audio": False,
                       "text": {"img": o["img"], "video": o.get("video"), "tw": o.get("tw") or [], "two": o.get("two") or [], "n": o.get("n") or 0, "size": o["size"], "box": o["box"], "anim": o["anim"]}},
             "dur": N, "start": max(0, a), "p": {"pos": [o["x"], o["y"]], "scale": o["scale"], "rot": 0.0, "opacity": o["opacity"]}, "kf": o.get("kf") or {}}
        lab, _, _ = tl_text_layer(c, OUTPUT_W, OUTPUT_H, inputs, n_in, chains, f"g{li}", f"{tag}_f{frame0}", skip=skip)
        st, en = max(0, a), min(total, b)
        chains.append(f"{cur}{lab}overlay=x=0:y=0:eof_action=pass:format=auto:"
                      f"enable='between(n,{st},{en - 1})',format=yuv420p,settb=1/{FPS},setpts=N[go{li}]")
        cur = f"[go{li}]"
    return cur


SHAKE_FRAMES = 10        # a Screen Shake thump lasts this long
SPARK_N = 12             # a Sparkle Burst thump lasts this long
SPARK_RINGS = ((10, 0.55, 0.0), (14, 0.85, 0.7), (18, 1.15, 1.9))      # dots, how far they fly, turned by


def spark_dots(f, W, H):
    """The dots of a Sparkle Burst on its frame f (0..SPARK_N-1): (x, y, radius, alpha). The page draws the same ones."""
    q = (f + 1) / SPARK_N
    m, out = min(W, H), []
    for cnt, sp, turn in SPARK_RINGS:
        r = m * 0.48 * sp * (1 - (1 - q) ** 2)
        for i in range(cnt):
            a = 2 * _math.pi * i / cnt + turn
            out.append((W / 2 + r * _math.cos(a), H / 2 + r * _math.sin(a), max(1.5, m * 0.016 * (1 - q) + 1.5), (1 - q) ** 1.2))
    return out


def spark_pngs():
    """The frames of one Sparkle Burst as transparent PNGs at the size of the output (made once per size)."""
    import cv2
    import numpy as np
    d = os.path.join(WORK_DIR, f"spark_{OUTPUT_W}x{OUTPUT_H}")
    pat = os.path.join(d, "s%02d.png")
    if not os.path.exists(pat % (SPARK_N - 1)):
        os.makedirs(d, exist_ok=True)
        for f in range(SPARK_N):
            im = np.zeros((OUTPUT_H, OUTPUT_W, 4), np.uint8)
            for x, y, r, a in spark_dots(f, OUTPUT_W, OUTPUT_H):
                cv2.circle(im, (int(round(x)), int(round(y))), int(round(r * 2.4)), (255, 244, 214, int(255 * a * 0.28)), -1, cv2.LINE_AA)
            for x, y, r, a in spark_dots(f, OUTPUT_W, OUTPUT_H):
                cv2.circle(im, (int(round(x)), int(round(y))), int(round(r)), (255, 255, 255, int(255 * a)), -1, cv2.LINE_AA)
            cv2.imwrite(pat % f, im)
    return pat


def spark_layers(cur, chains, inputs, n_in, frames, total):
    """Sparkle Burst thumps: the burst laid over the finished picture at each of its frames."""
    frames = sorted(set(int(f) for f in frames if 0 <= f < total))[:80]
    if not frames:
        return cur
    inputs.extend(["-framerate", str(FPS), "-i", spark_pngs()])
    idx = n_in[0]
    n_in[0] += 1
    chains.append(f"[{idx}:v]format=rgba,split={len(frames)}" + "".join(f"[skr{j}]" for j in range(len(frames))))
    for j, G in enumerate(frames):
        chains.append(f"[skr{j}]setpts=PTS-STARTPTS+{G}/{FPS}/TB[sks{j}]")
        chains.append(f"{cur}[sks{j}]overlay=x=0:y=0:eof_action=pass:format=auto:enable='between(n,{G},{G + SPARK_N - 1})',"
                      f"format=yuv420p,settb=1/{FPS},setpts=N[sko{j}]")
        cur = f"[sko{j}]"
    return cur


# ---------------------------------------------------------------------------
# Audio Visualizer overlay: the song's spectrum, worked out once per frame; the page draws it live from these numbers and
# the render draws the same shapes into a transparent video that is laid over the edit.
# ---------------------------------------------------------------------------
VIS_BANDS, VIS_WAVE = 48, 96
_VIS_DATA, _VIS_FILES = {}, {}


def vis_data(path, start, frames):
    """(bands [frames x VIS_BANDS], wave [frames x VIS_WAVE]) as uint8 for the song from `start` seconds on, one row per frame."""
    import numpy as np
    key = (path, round(float(start), 3), int(frames))
    if key in _VIS_DATA:
        return _VIS_DATA[key]
    sr, win = 22050, 2048
    p = subprocess.run(["ffmpeg", "-v", "error", "-ss", f"{max(0.0, start):.4f}", "-t", f"{frames / FPS + 0.2:.4f}", "-i", path, "-vn", "-ac", "1",
                        "-ar", str(sr), "-f", "f32le", "-"], stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, creationflags=NO_WINDOW)
    y = np.frombuffer(p.stdout, dtype=np.float32)
    if len(y) < win:
        y = np.concatenate([y, np.zeros(win - len(y), np.float32)])
    y = np.concatenate([np.zeros(win // 2, np.float32), y, np.zeros(win, np.float32)])
    edges = np.geomspace(50, 9000, VIS_BANDS + 1) * win / sr
    lo, hi = np.floor(edges[:-1]).astype(int), np.maximum(np.floor(edges[:-1]).astype(int) + 1, np.ceil(edges[1:]).astype(int))
    hann = np.hanning(win).astype(np.float32)
    B, Wv = np.zeros((frames, VIS_BANDS), np.float32), np.zeros((frames, VIS_WAVE), np.float32)
    pick = np.linspace(win // 2 - 512, win // 2 + 511, VIS_WAVE).astype(int)
    for n in range(frames):
        seg = y[int(round(n * sr / FPS)):][:win]
        if len(seg) < win:
            break
        mag = np.abs(np.fft.rfft(seg * hann))
        B[n] = [float(np.sqrt(np.mean(mag[a:b] ** 2))) for a, b in zip(lo, hi)]
        Wv[n] = seg[pick]
    B *= np.linspace(0.6, 2.4, VIS_BANDS, dtype=np.float32)            # (the top of the spectrum is always quieter: lifted so it moves too)
    ref = float(np.percentile(B, 97)) or 1.0
    B = np.clip(B / ref, 0, 1) ** 0.75
    for n in range(1, frames):                                        # bars fall back slowly instead of flickering
        B[n] = np.maximum(B[n], B[n - 1] * 0.80)
    pk = float(np.percentile(np.abs(Wv), 99.5)) or 1.0
    Wv = np.clip(Wv / pk * 0.5 + 0.5, 0, 1)
    out = (np.round(B * 255).astype(np.uint8), np.round(Wv * 255).astype(np.uint8))
    if len(_VIS_DATA) > 6:
        _VIS_DATA.clear()
    _VIS_DATA[key] = out
    return out


def parse_vis(v, song_path, start, total):
    if not isinstance(v, dict) or not v.get("on") or not song_path or total < 2:
        return None
    col = v.get("color") if isinstance(v.get("color"), str) and re.fullmatch(r"#[0-9a-fA-F]{6}", v.get("color")) else "#ffffff"
    return {"style": v.get("style") if v.get("style") in ("bars", "wave", "circle") else "bars", "color": col, "y": _fnum(v.get("y"), 0.82, 0.05, 0.95),
            "size": _fnum(v.get("size"), 0.22, 0.05, 0.6), "op": _fnum(v.get("op"), 90, 5, 100), "song": song_path, "start": _fnum(start, 0, 0, 1e6), "total": int(total)}


def vis_box(v, W, H):
    """Where the visualizer sits on a W x H frame: (x0, y0, w, h) of the box it is drawn in. The page uses the same numbers."""
    hm = v["size"] * H
    if v["style"] == "circle":
        side = int(_math.ceil((hm * 0.45 + hm * 0.55) * 2 + 8) // 2 * 2)
        return int(round(W / 2 - side / 2)), int(round(v["y"] * H - side / 2)), side, side
    w, h = int(round(W * 0.8 / 2) * 2), int(_math.ceil(hm + 8) // 2 * 2)
    return int(round(W / 2 - w / 2)), int(round(v["y"] * H - h / 2)), w, h


def vis_draw(im, v, bands, wave, H):
    """One frame of the visualizer into the BGRA picture `im` (the size of its box)."""
    import cv2
    import numpy as np
    h, w = im.shape[:2]
    hm = v["size"] * H
    c = v["color"]
    col = (int(c[5:7], 16), int(c[3:5], 16), int(c[1:3], 16), 255)
    if v["style"] == "bars":
        pitch = w / VIS_BANDS
        for i in range(VIS_BANDS):
            bh = max(2.0, bands[i] / 255 * hm)
            cv2.rectangle(im, (int(round(i * pitch + pitch * 0.16)), int(round(h - 4 - bh))), (int(round(i * pitch + pitch * 0.84)), h - 4), col, -1)
    elif v["style"] == "wave":
        pts = np.array([[w * i / (VIS_WAVE - 1), h / 2 + (wave[i] / 255 - 0.5) * hm] for i in range(VIS_WAVE)], np.float32)
        cv2.polylines(im, [np.round(pts * 16).astype(np.int32)], False, col, max(2, int(round(H / 270))), cv2.LINE_AA, 4)
    else:
        r0, n = hm * 0.45, VIS_BANDS * 2
        lw = max(2, int(round(2 * _math.pi * r0 / n * 0.6)))
        for j in range(n):
            b = bands[j if j < VIS_BANDS else n - 1 - j]
            a = -_math.pi / 2 + 2 * _math.pi * j / n
            r1 = r0 + max(2.0, b / 255 * hm * 0.55)
            cv2.line(im, (int(round((w / 2 + r0 * _math.cos(a)) * 16)), int(round((h / 2 + r0 * _math.sin(a)) * 16))),
                     (int(round((w / 2 + r1 * _math.cos(a)) * 16)), int(round((h / 2 + r1 * _math.sin(a)) * 16))), col, lw, cv2.LINE_AA, 4)


def vis_gov(v):
    """The visualizer as a transparent video for the whole edit (made once per setting) -> a song-wide video layer."""
    import numpy as np
    x0, y0, w, h = vis_box(v, OUTPUT_W, OUTPUT_H)
    key = (v["song"], round(v["start"], 3), v["total"], v["style"], v["color"], round(v["y"], 4), round(v["size"], 4), OUTPUT_W, OUTPUT_H)
    path = _VIS_FILES.get(key)
    if not path or not os.path.exists(path):
        bands, wave = vis_data(v["song"], v["start"], v["total"])
        os.makedirs(WORK_DIR, exist_ok=True)
        path = os.path.join(WORK_DIR, f"vis_{uuid.uuid4().hex[:10]}.mov")
        proc = subprocess.Popen(["ffmpeg", "-v", "error", "-y", "-f", "rawvideo", "-pix_fmt", "bgra", "-s", f"{w}x{h}", "-r", str(FPS), "-i", "-",
                                 "-c:v", "qtrle", "-pix_fmt", "argb", path], stdin=subprocess.PIPE, stderr=subprocess.DEVNULL, creationflags=NO_WINDOW)
        try:
            for n in range(v["total"]):
                im = np.zeros((h, w, 4), np.uint8)
                vis_draw(im, v, bands[n], wave[n], OUTPUT_H)
                proc.stdin.write(im.tobytes())
        finally:
            proc.stdin.close()
            proc.wait()
        if proc.returncode:
            raise RuntimeError("the visualizer video could not be written")
        _VIS_FILES[key] = path
    return {"img": None, "video": {"path": path, "v0": 0, "dur": v["total"] / FPS}, "w": w, "h": h, "f0": 0, "f1": v["total"],
            "x": x0 + w / 2, "y": y0 + h / 2, "scale": 100, "opacity": v["op"], "size": 100, "box": [w, h], "kf": {},
            "anim": txa_norm(None), "tw": [], "two": [], "n": 0}


@app.get("/api/song/<sid>/spectrum")
def api_song_spectrum(sid):
    """The numbers the page draws the Audio Visualizer from: the song's spectrum and waveform, one row per frame of the edit."""
    s = SONGS.get(sid)
    if not s:
        return err("That song is not loaded any more.", 404)
    start, frames = _fnum(request.args.get("start"), 0, 0, 1e6), int(_fnum(request.args.get("frames"), 0, 0, 30 * 60 * FPS))
    if frames < 2:
        return err("Nothing to analyse.")
    try:
        bands, wave = vis_data(s["path"], start, frames)
    except Exception as e:
        return err(str(e))
    import base64
    return jsonify({"frames": frames, "bands": VIS_BANDS, "wave": VIS_WAVE, "b": base64.b64encode(bands.tobytes()).decode(), "w": base64.b64encode(wave.tobytes()).decode()})


def beat_thumps(secs, trans, pulse, total):
    """The thumps on the finished edit (cuts + transitions + overlays): zoom terms, Flicker / Fade Out shades,
    heavy-beat flash frames. Each beat belongs to one cut and only acts while that cut is on screen."""
    terms, shade, flashes = [], {}, []
    pulse["_shx"], pulse["_shy"], pulse["_spark"] = [], [], []          # Screen Shake (shift terms) and Sparkle Burst (frames) of this graph
    if not (pulse["on"] and pulse["intensity"] > 0):
        return terms, shade, flashes
    I = pulse["intensity"]
    for i, s in enumerate(secs):
        tin, tout, _, _ = section_windows(secs, trans, i)
        L = (s["f1"] - s["f0"]) + tin // 2 + tout // 2
        cf0 = s["f0"] - tin // 2
        inside = lambda k: 0 <= k < L and 0 <= cf0 + k < total
        for k, heavy, kind, st in s["beats"]:
            if k <= -PULSE_FRAMES or k >= L or st <= 0:
                continue
            if kind == "spark":
                if inside(k):
                    pulse["_spark"].append(cf0 + k)
                continue
            if kind == "shake":                         # a short, dying shake: the picture is pushed in a little so its edges stay out of sight
                G = cf0 + k
                on = f"between(in-({G}),0,{SHAKE_FRAMES - 1})*between(in,{max(0, cf0)},{cf0 + L - 1})"
                terms.append(f"{0.05 * I * st:.4f}*{on}")
                pulse["_shx"].append(f"{0.018 * I * st:.4f}*iw*sin((in-({G}))*2.9)*(1-(in-({G}))/{SHAKE_FRAMES})*{on}")
                pulse["_shy"].append(f"{0.014 * I * st:.4f}*ih*cos((in-({G}))*3.7)*(1-(in-({G}))/{SHAKE_FRAMES})*{on}")
                continue
            if kind in ("flicker", "fade"):
                tab = enumerate(FLICKER_ALPHA) if kind == "flicker" else FADE_ALPHA.items()
                col = "white" if kind == "flicker" else "black"
                for d, a in tab:
                    if inside(k + d):
                        shade.setdefault((col, round(min(1.0, a * st * I), 2)), []).append(cf0 + k + d)
                continue
            big = heavy and pulse["heavy"]
            amp = (HEAVY_ZOOM if big else PULSE_ZOOM) * I * st
            G = cf0 + k
            terms.append(f"{amp:.4f}*between(in-({G}),0,{PULSE_FRAMES - 1})*pow(1-(in-({G}))/{PULSE_FRAMES},2)"
                         f"*between(in,{max(0, cf0)},{cf0 + L - 1})")
            if big:
                flashes += [cf0 + k + d for d in range(FLASH_FRAMES) if inside(k + d)]
    return terms, shade, flashes


def build_video_graph(secs, trans, pulse, frame0=0):
    """Inputs (relative to UPLOAD_DIR) + filter chains ending in [vout].

    Every clip becomes [head][body][tail]: the head/tail are the frames it spends
    inside a transition. Each transition is built from (tail of A, head of B) as
    its own little segment, and the whole edit is ONE concat of
    body0, trans0, body1, trans1, ... so the frame count is exact."""
    inputs, chains = [], []
    n = len(secs)
    n_in = [0]
    polish = pulse.get("polish") or {}

    def source(clip, cs_global, sp, L, tin, tout, slow_in, slow_out, own=None):
        """[k:v] -> setpts/fps/trim so output frame j = source frame at cs + offset(j/FPS).
        own = a pane with its own timing: its speed graph + frame blending are used instead of the cut's."""
        cs = cs_global
        cv, blend = (own.get("curve"), own.get("blend", False)) if own else (_cv, _blend)
        if clip["duration"] > 0.1:
            cs = cs % clip["duration"]               # clips loop when they run out
        s0 = max(0.0, cs - SEEK_MARGIN)
        ctab = curve_table(dict(cv, L=cv.get("L", L)), L) if cv else None
        need = ctab[1][-1] if ctab else L * sp / FPS
        inputs.extend(["-threads", DECODER_THREADS, "-ss", f"{s0 + clip.get('v0', 0):.6f}", "-stream_loop", "-1",
                       "-t", f"{cs - s0 + need + 1.0:.6f}", "-i", os.path.basename(clip["path"])])
        idx = n_in[0]
        n_in[0] += 1
        off = cs - s0 + 0.001        # +1 ms: a frame landing exactly on a sample time counts as "at or before"
        if ctab:
            # Speed Graph: exact per-frame mapping. Source time O[k] is on screen at output frame k;
            # between frames it is linear, so output frame k shows the latest source frame <= O[k].
            r, O = ctab
            u = f"(PTS*TB-{off:.6f})"
            terms = [f"lt({u},{O[1]:.6f})*({u}/{r[0]:.6f})"]
            for k in range(1, L - 1):
                terms.append(f"gte({u},{O[k]:.6f})*lt({u},{O[k + 1]:.6f})*({k / FPS:.6f}+({u}-{O[k]:.6f})/{r[k]:.6f})")
            terms.append(f"gte({u},{O[L - 1]:.6f})*({(L - 1) / FPS:.6f}+({u}-{O[L - 1]:.6f})/{r[L - 1]:.6f})")
            shift = "setpts='(" + "+".join(terms) + ")/TB'"
        elif slow_in or slow_out:
            t1, t2, a1, b, a3 = time_map(sp, L, tin, tout, slow_in, slow_out)
            u1 = a1 * t1
            u2 = u1 + b * (t2 - t1)
            u = f"(PTS*TB-{off:.6f})"
            shift = (f"setpts='(if(lt({u},{u1:.6f}),{u}/{a1:.6f},if(lt({u},{u2:.6f}),"
                     f"{t1:.6f}+({u}-{u1:.6f})/{b:.6f},{t2:.6f}+({u}-{u2:.6f})/{a3:.6f})))/TB'")
        elif sp == 1.0:
            shift = f"setpts=PTS-{off:.6f}/TB"
        else:
            shift = f"setpts=(PTS-{off:.6f}/TB)/{sp:.6f}"
        # slow motion (speed < 1 or a Slow-mo window): blend neighbouring frames instead of repeating them
        slow = pulse.get("smooth", True) and blend
        # (framerate's output frame n is the blend at input time (n+1)/fps, so delay its input by one frame:
        #  blended frames then sit exactly where the frame-picking rule puts them)
        pick = f"setpts=PTS+{1 / FPS:.9f}/TB,framerate=fps={FPS}" if slow else f"fps={FPS}:round=up"
        return f"[{idx}:v]{shift},{pick},trim=start=0,setpts=PTS-STARTPTS"

    hold = lambda L: f"setsar=1,tpad=stop_mode=clone:stop_duration=2,trim=end_frame={L},setpts=PTS-STARTPTS"

    for i, s in enumerate(secs):
        tin, tout, slow_in, slow_out = section_windows(secs, trans, i)
        # clip covers its section plus half of each neighbouring transition
        L = (s["f1"] - s["f0"]) + tin // 2 + tout // 2
        sp = s.get("speed", 1.0)                     # manual speed / Sync to cut
        tm = (sp, L, tin, tout, slow_in, slow_out)
        cv = _cv = s.get("curve")
        # decided on the WHOLE edit (before chunking), so a chunk that starts mid-cut blends the same way
        _blend = s.get("blend", sp < 0.99 or bool(cv and min(cv["v"]) < 0.99))
        multi = s.get("layout") in MULTI
        if multi:
            # Triptych / Duo: panes side by side; Split (9:16): top + bottom. Each pane has its own fill, mirror,
            # zoom/pan, start and sound; ONE clip from here on
            widths, gap = pane_geometry(s)
            vert = s.get("layout") == "split"
            npn = len(s["panes"])
            for k, p in enumerate(s["panes"]):
                pw, ph = (OUTPUT_W, widths[k]) if vert else (widths[k], OUTPUT_H)
                if p:
                    ptm = (p["speed"],) + tm[1:] if p.get("own") else tm
                    ch = (source(p["clip"], p.get("clipStart", s["clipStart"]), *ptm, own=p if p.get("own") else None) + "," + fill_filter(p["fill"], pw, ph, p.get("off"))
                          + (",hflip" if p.get("mirror") else "") + "," + hold(L))
                    ptf = transform_fx(p.get("tf"), L, pw, ph)             # zoom / pan inside this pane only
                    if ptf:
                        ch += "," + ptf + f",trim=end_frame={L},setpts=PTS-STARTPTS"
                else:
                    ch = (f"color=c=black:s={pw}x{ph}:r={FPS}:d={L / FPS + 0.5:.4f},"
                          f"trim=end_frame={L},setpts=PTS-STARTPTS")
                if gap and k < npn - 1 and not vert:    # gap to the right of every pane but the last
                    ch += f",pad={pw + gap}:{ph}:0:0:black"
                chains.append(ch + f",format=yuv420p,settb=1/{FPS},setpts=N[p{i}_{k}]")
            chains.append("".join(f"[p{i}_{k}]" for k in range(npn)) + f"{'vstack' if vert else 'hstack'}=inputs={npn},setsar=1,"     # (re-stamp: fps right after a stack drops the last frame)
                          f"setpts=N/{FPS}/TB,fps={FPS}[c{i}]")
            c = [f"[c{i}]setpts=PTS-STARTPTS"]
        elif s.get("bgr"):
            # AI background removal: the clip and its matte with the same timing -> alpha -> fill / zoom ->
            # over the chosen background (before the effects, overlays and thumps)
            bgr = s["bgr"]
            chains.append(source(s["clip"], s["clipStart"], *tm) + f"[bgs{i}]")
            chains.append(source(bgr["matte"], s["clipStart"], *tm) + "," + bgr_matte_filters(bgr) + f"[bgm{i}]")
            chains.append(f"[bgm{i}][bgs{i}]scale2ref=w=iw:h=ih[bgm2{i}][bgs2{i}]")
            ff = fill_filter(s["fill"], OUTPUT_W, OUTPUT_H, s.get("off")).replace("color=black", "color=black@0")
            ch = f"[bgs2{i}][bgm2{i}]alphamerge,format=rgba,{ff},format=rgba,{hold(L)}"
            chains.append(ch + f",settb=1/{FPS},setpts=N[bgf{i}]")
            bg = bgr_background(dict(bgr, bg="black" if bgr["bg"] == "transparent" else bgr["bg"]), OUTPUT_W, OUTPUT_H, L, inputs, n_in, chains, f"bgb{i}")
            chains.append(f"{bg}settb=1/{FPS},setpts=N[bgb2{i}]")
            chains.append(f"[bgb2{i}][bgf{i}]overlay=format=auto,format=yuv420p,trim=end_frame={L},setpts=PTS-STARTPTS[bgo{i}]")
            c = [f"[bgo{i}]setpts=PTS-STARTPTS"]
            ttf = transform_fx(s.get("tf"), L)            # zoom / pan: the whole cut (subject + background), like any cut
            if ttf:
                c += [ttf, f"trim=end_frame={L}", "setpts=PTS-STARTPTS"]
        else:
            c = [source(s["clip"], s["clipStart"], *tm), fill_filter(s["fill"], OUTPUT_W, OUTPUT_H, s.get("off")), hold(L)]

        tfx = None if multi or s.get("bgr") else transform_fx(s.get("tf"), L)
        if tfx:
            c.append(tfx)
        if s.get("mo"):
            # Animation of the cut's own picture: it slides / scales / turns / fades over black (its overlays stay put)
            mf, mx, my, men = mo_filters(s["mo"], OUTPUT_W, OUTPUT_H, s.get("kof", 0), L)
            chains.append(",".join(c) + f",format=rgba,settb=1/{FPS},setpts=N{mf}[mv{i}]")
            chains.append(f"color=c=black:s={OUTPUT_W}x{OUTPUT_H}:r={FPS}:d={L / FPS + 1:.4f},trim=end_frame={L},settb=1/{FPS},setpts=N[mb{i}]")
            chains.append(f"[mb{i}][mv{i}]overlay=x='{OUTPUT_W // 2}+({mx})-overlay_w/2':y='{OUTPUT_H // 2}+({my})-overlay_h/2':"
                          f"enable='{men}':eof_action=pass:format=auto,format=yuv420p[mo{i}]")
            c = [f"[mo{i}]trim=end_frame={L},setpts=PTS-STARTPTS"]
            if s["mo"].get("blur"):                     # Motion Blur on a recorded / animated move: neighbouring frames are mixed, so only what moves smears
                c.append("tmix=frames=3:weights='1 2 1'")
        if s.get("ovs"):
            # Overlays: pictures / GIFs / videos composited onto the cut HERE, before the pulse zoom and the
            # transitions, so the whole composite thumps, slides and spins as one picture
            chains.append(",".join(c) + f",format=yuv420p,settb=1/{FPS},setpts=N[op{i}]")
            cur = f"[op{i}]"
            for j, o in enumerate(s["ovs"]):
                oc = o["clip"]
                mw, mh = max(2, oc.get("width") or 2), max(2, oc.get("height") or 2)
                ow = max(2, round(OUTPUT_W * o["scale"] / 2) * 2)
                oh = max(2, round(ow * mh / mw / 2) * 2)
                ox, oy = round(o["x"] - ow / 2), round(o["y"] - oh / 2)
                if oc.get("kind") == "photo":
                    inputs.extend(["-loop", "1", "-framerate", str(FPS), "-t", f"{L / FPS + 1:.4f}", "-i", os.path.basename(oc.get("image") or oc["path"])])
                    pick = f"trim=end_frame={L + 1}"
                else:
                    dur = oc.get("duration") or 1
                    t0 = (o.get("t0", 0) / FPS) % dur if dur > 0.1 else 0
                    inputs.extend(["-stream_loop", "-1", "-ss", f"{t0 + oc.get('v0', 0):.4f}", "-t", f"{L / FPS + 1:.4f}", "-i", os.path.basename(oc["path"])])
                    pick = f"setpts=PTS-STARTPTS,fps={FPS}:round=up,trim=end_frame={L + 1}"
                idx = n_in[0]
                n_in[0] += 1
                alpha = f",colorchannelmixer=aa={o['opacity']:.4f}" if o["opacity"] < 0.999 else ""
                fadein = f",fade=t=in:st=0:d={o['fade'] / FPS:.4f}:alpha=1" if o.get("fade") else ""
                osrc = f"[{idx}:v]{pick},setpts=PTS-STARTPTS"
                if o.get("bgr"):                       # the overlay's own background removed: its matte, with the same timing, becomes its alpha
                    ob = o["bgr"]
                    om = ob["matte"]
                    if oc.get("kind") == "photo":
                        inputs.extend(["-stream_loop", "-1", "-t", f"{L / FPS + 1:.4f}", "-i", os.path.basename(om["path"])])
                    else:
                        inputs.extend(["-stream_loop", "-1", "-ss", f"{t0 + om.get('v0', 0):.4f}", "-t", f"{L / FPS + 1:.4f}", "-i", os.path.basename(om["path"])])
                    midx = n_in[0]
                    n_in[0] += 1
                    mpick = f"setpts=PTS-STARTPTS,fps={FPS}:round=up,trim=end_frame={L + 1}"
                    chains.append(f"{osrc}[obs{i}_{j}]")
                    chains.append(f"[{midx}:v]{mpick},setpts=PTS-STARTPTS,{bgr_matte_filters(ob)}[obm{i}_{j}]")
                    chains.append(f"[obm{i}_{j}][obs{i}_{j}]scale2ref=w=iw:h=ih[obm2{i}_{j}][obs2{i}_{j}]")
                    chains.append(f"[obs2{i}_{j}][obm2{i}_{j}]alphamerge,format=rgba[oba{i}_{j}]")
                    osrc = f"[oba{i}_{j}]setpts=PTS-STARTPTS"
                omo = o.get("mo")
                mof, mxe, mye, men = mo_filters(omo, ow, oh, o.get("t0", 0), L) if omo else ("", "0", "0", "")
                chains.append(f"{osrc},scale={ow}:{oh}:flags=bicubic,setsar=1,format=rgba{alpha}{fadein},"
                              f"settb=1/{FPS},setpts=N{mof}[oi{i}_{j}]")
                if omo:                                # animated: the layer's centre moves, so it is placed by its centre
                    ocx, ocy = ox + ow / 2, oy + oh / 2
                    chains.append(f"{cur}[oi{i}_{j}]overlay=x='{ocx:.1f}+({mxe})-overlay_w/2':y='{ocy:.1f}+({mye})-overlay_h/2':enable='{men}':"
                                  f"eof_action=repeat:format=auto,format=yuv420p[oo{i}_{j}]")
                    cur = f"[oo{i}_{j}]"
                    continue
                if o.get("shadow"):                    # soft drop shadow: the layer's own shape, black, blurred, a little down-right
                    pad, sig = OV_SHADOW_PAD, OV_SHADOW_SIGMA * OUTPUT_W / 1920
                    dx_, dy_ = round(OV_SHADOW_DX * OUTPUT_W / 1920), round(OV_SHADOW_DY * OUTPUT_W / 1920)
                    chains.append(f"[oi{i}_{j}]split[oj{i}_{j}][ok{i}_{j}]")
                    chains.append(f"[ok{i}_{j}]pad=iw+{2 * pad}:ih+{2 * pad}:{pad}:{pad}:color=black@0,colorchannelmixer=rr=0:gg=0:bb=0:aa={o['shadow']:.3f},"
                                  f"gblur=sigma={sig:.2f}:steps=2[os{i}_{j}]")
                    chains.append(f"{cur}[os{i}_{j}]overlay=x={ox - pad + dx_}:y={oy - pad + dy_}:eof_action=repeat:format=auto[ot{i}_{j}]")
                    chains.append(f"[ot{i}_{j}][oj{i}_{j}]overlay=x={ox}:y={oy}:eof_action=repeat:format=auto,format=yuv420p[oo{i}_{j}]")
                else:
                    chains.append(f"{cur}[oi{i}_{j}]overlay=x={ox}:y={oy}:eof_action=repeat:format=auto,format=yuv420p[oo{i}_{j}]")
                cur = f"[oo{i}_{j}]"
            c = [f"{cur}trim=end_frame={L},setpts=PTS-STARTPTS"]
        if s.get("lfx"):
            # Looks from the Timeline's effect library (VHS, RGB split, bloom...): the same filters, on the finished cut picture
            lch = tl_fx_source(s["lfx"], ",".join(c) + ",format=rgba", OUTPUT_W, OUTPUT_H, L, inputs, n_in, chains, f"L{i}",
                               pulse.get("tag") or os.path.join(WORK_DIR, "x"))
            chains.append(lch + f",format=yuv420p,settb=1/{FPS},setpts=N[lfx{i}]")
            c = [f"[lfx{i}]trim=end_frame={L},setpts=PTS-STARTPTS"]
        # the cut's own Effects (before the thumps, which now act on the finished edit)
        s["_tin"] = tin
        c = cut_fx_chain(c, s, i, L, inputs, n_in, chains, pulse.get("tag") or os.path.join(WORK_DIR, "x"), pulse)
        terms = []
        # Zoom Punch: the outgoing clip accelerates into a zoom right up to the hard cut,
        # the incoming one lands slightly zoomed and settles
        Tp = pulse.get("tlen", TLEN_DEFAULT)
        if i < n - 1 and trans[i]["type"] == "punch":           # punch in: 100% -> 110% into the hard cut
            tp = max(2, min(punch_len(Tp), L - 1))
            x = f"((in-{L - tp}+1)/{tp})"
            terms.append(f"{PUNCH_ZOOM}*if(gte(in,{L - tp}),{x}*{x}*(3-2*{x}),0)")
        if i > 0 and trans[i - 1]["type"] == "punch":           # ...and the next clip punches back out from 110%
            hh = max(2, min(punch_len(Tp), L - 1))
            x = f"(in/{hh})"
            terms.append(f"{PUNCH_ZOOM}*if(lt(in,{hh}),1-{x}*{x}*(3-2*{x}),0)")
        # Zoom Punch Sync: deep zoom into the beat, hard cut, the next clip snaps back out of the zoom
        if i < n - 1 and trans[i]["type"] == "zsync":
            tp = max(2, min(Tp, L - 1))
            x = f"((in-{L - tp}+1)/{tp})"
            terms.append(f"{ZSYNC_ZOOM}*if(gte(in,{L - tp}),pow({x},3),0)")
        if i > 0 and trans[i - 1]["type"] == "zsync":
            hh = max(2, min(Tp, L - 1))
            terms.append(f"{ZSYNC_ZOOM}*if(lt(in,{hh}),pow(1-in/{hh},3),0)")
        # Slow-mo transition: zoom in at the end of the outgoing clip, out at the start of the incoming one
        if slow_out and trans[i]["type"] != "slowout":
            A = L - tout
            x = f"((in-{A})/{tout})"
            terms.append(f"{SLOWMO_ZOOM}*if(gte(in,{A}),{x}*{x}*(3-2*{x}),0)")
        if slow_in and trans[i - 1]["type"] != "slowin":
            x = f"(in/{tin})"
            terms.append(f"{SLOWMO_ZOOM}*if(lt(in,{tin}),1-{x}*{x}*(3-2*{x}),0)")
        if terms:
            z = "1+" + "+".join(terms)
            c.append(f"zoompan=z='{z}':x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)'"
                     f":d=1:s={OUTPUT_W}x{OUTPUT_H}:fps={FPS}")
            c.append("setpts=PTS-STARTPTS")
        # end on fps=30 so every stream carries a constant-rate tag (FFmpeg 7+ needs it)
        c += ["format=yuv420p", f"settb=1/{FPS}", "setpts=N", f"fps={FPS}"]

        # [head][body][tail]: only frames inside a transition window go to the transition
        typ_in = trans[i - 1]["type"] if i > 0 and tin else None
        typ_out = trans[i]["type"] if i < n - 1 and tout else None
        segs = []
        if typ_in:
            segs.append((f"h{i}", 0, tin, window_fx(typ_in, "in", tin) if typ_in in MOTION else None))
        m0, m1 = tin, L - tout
        if m1 > m0:
            segs.append((f"b{i}", m0, m1, None))
        if typ_out:
            segs.append((f"t{i}", L - tout, L, window_fx(typ_out, "out", tout) if typ_out in MOTION else None))
        if len(segs) == 1 and segs[0][0] == f"b{i}":
            chains.append(",".join(c) + f"[b{i}]")
        else:
            chains.append(",".join(c) + f",split={len(segs)}" + "".join(f"[s{i}_{k}]" for k in range(len(segs))))
            for k, (lab, a, b, fx) in enumerate(segs):
                chains.append(f"[s{i}_{k}]trim=start_frame={a}:end_frame={b},setpts=PTS-STARTPTS"
                              + (f",{fx}" if fx else "") + f",format=yuv420p,settb=1/{FPS},setpts=N,fps={FPS}[{lab}]")

    # transitions: each is one T-frame segment built from (tail of A, head of B)
    blur_on = pulse.get("blur", True)
    for i in range(n - 1):
        t, T = trans[i], trans[i]["tf"]
        if not T:
            continue
        A, B = f"[t{i}]", f"[h{i + 1}]"
        typ = t["type"]
        if typ in SLIDES:
            # eased slide: both shots sit side by side, a window moves across with ease-in-out
            E = ease_expr(f"((n+0.5)/{T})")
            if typ == "left":
                g = f"{A}{B}hstack=inputs=2,crop={OUTPUT_W}:{OUTPUT_H}:x='{OUTPUT_W}*{E}':y=0:exact=1"
            elif typ == "right":
                g = f"{B}{A}hstack=inputs=2,crop={OUTPUT_W}:{OUTPUT_H}:x='{OUTPUT_W}*(1-{E})':y=0:exact=1"
            elif typ == "up":
                g = f"{A}{B}vstack=inputs=2,crop={OUTPUT_W}:{OUTPUT_H}:x=0:y='{OUTPUT_H}*{E}':exact=1"
            else:
                g = f"{B}{A}vstack=inputs=2,crop={OUTPUT_W}:{OUTPUT_H}:x=0:y='{OUTPUT_H}*(1-{E})':exact=1"
            fx = []
            if blur_on:
                horiz = typ in ("left", "right")
                for lvl, frames in sorted(blur_levels(slide_blur(T, OUTPUT_W if horiz else OUTPUT_H), SLIDE_LEVELS).items()):
                    sig = f"sigma={lvl}:sigmaV=0" if horiz else f"sigma=0.01:sigmaV={lvl}"
                    fx.append(f"gblur={sig}:steps=2:enable='{frame_ranges(frames)}'")
            # (stacking can drop the last frame - pad + trim keeps the window exactly T frames)
            chains.append(",".join([g, f"setpts=N/{FPS}/TB"] + fx + ["format=yuv420p", "tpad=stop_mode=clone:stop=2", f"trim=end_frame={T}",
                                               f"settb=1/{FPS}", "setpts=N", f"fps={FPS}"]) + f"[x{i}]")
        elif typ in ("dip", "flashw", "bflash"):
            # Dip to black / Flash white: A fades out over the first half of the window, B fades in over the second
            # (the fade filter, not xfade=fadeblack: its black / white are right for every pixel range)
            N, col = T // 2, ("black" if typ == "dip" else "white")
            if typ == "bflash":
                # Blur flash: hard cut in the middle; around it the picture blurs, pushes in, twists, mirrors and whites out.
                # Every amount is a function of the frame (peak in the middle), the same numbers the page's preview uses.
                o = t.get("opt") or parse_topt(None)
                Q = f"pow(1-abs((n+0.5)/{T}*2-1),2)"
                chains.append(f"{A}trim=end_frame={N},settb=1/{FPS},setpts=N[da{i}]")
                chains.append(f"{B}trim=start_frame={N},setpts=PTS-STARTPTS,settb=1/{FPS},setpts=N[db{i}]")
                ch = f"[da{i}][db{i}]concat=n=2:v=1:a=0,settb=1/{FPS},setpts=N,format=yuv420p"
                peak = [k_ for k_ in range(T) if (1 - abs((k_ + 0.5) / T * 2 - 1)) ** 2 >= 0.3]
                if o["mirror"] and peak:
                    chains.append(ch + f",split[bm{i}][bn{i}]")
                    if o["mirror"] == "v":
                        chains.append(f"[bn{i}]crop=iw:ih/2:0:0,split[bt{i}][bu{i}];[bu{i}]vflip[bv{i}];[bt{i}][bv{i}]vstack[bw{i}]")
                    else:
                        chains.append(f"[bn{i}]crop=iw/2:ih:0:0,split[bt{i}][bu{i}];[bu{i}]hflip[bv{i}];[bt{i}][bv{i}]hstack[bw{i}]")
                    ch = f"[bm{i}][bw{i}]overlay=0:0:enable='{frame_ranges(peak)}'"
                sgn = f"if(lt(n,{N}),1,-1)"
                ANG = f"({o['spin'] * _math.pi / 180:.5f}*{Q}*{sgn})"
                cover = max(OUTPUT_W / OUTPUT_H, OUTPUT_H / OUTPUT_W)
                Z = f"((1+{o['zoom']:.4f}*{Q})*(abs(cos({ANG}))+abs(sin({ANG}))*{cover:.4f}))" if o["spin"] else f"(1+{o['zoom']:.4f}*{Q})"
                if o["spin"]:
                    ch += f",rotate=a='{ANG}':ow=iw:oh=ih:fillcolor=white:bilinear=1"
                if o["zoom"] or o["spin"]:
                    ch += f",scale=w='trunc({OUTPUT_W}*{Z}/2)*2':h='trunc({OUTPUT_H}*{Z}/2)*2':eval=frame:flags=bilinear,crop={OUTPUT_W}:{OUTPUT_H},setsar=1"
                lv, wh = {}, {}
                for k_ in range(T):
                    sg = round(bflash_sigma(k_, T) * o["blur"] * OUTPUT_W / 1920, 1)
                    if sg >= 0.6:
                        lv.setdefault(sg, []).append(k_)
                    al = round(o["white"] * bflash_white(k_, T), 2)
                    if al > 0.005:
                        wh.setdefault(al, []).append(k_)
                for sg, fr in sorted(lv.items()):
                    # Mirror smear: the blur runs sideways only, so the picture streaks across instead of going soft all round
                    ch += (f",gblur=sigma={sg * 2.4:.1f}:sigmaV=0.4:steps=2:enable='{frame_ranges(fr)}'" if o.get("smear")
                           else f",gblur=sigma={sg}:steps=2:enable='{frame_ranges(fr)}'")
                for al, fr in sorted(wh.items()):
                    ch += f",drawbox=x=0:y=0:w=iw:h=ih:color=white@{al:.2f}:t=fill:enable='{frame_ranges(fr)}'"
                chains.append(ch + f",format=yuv420p,tpad=stop_mode=clone:stop=2,trim=end_frame={T},settb=1/{FPS},setpts=N,fps={FPS}[x{i}]")
                continue_bflash = True
            else:
                continue_bflash = False
            if not continue_bflash:
                chains.append(f"{A}fade=type=out:start_frame=0:nb_frames={N}:color={col},trim=end_frame={N},settb=1/{FPS},setpts=N[da{i}]")
                chains.append(f"{B}fade=type=in:start_frame={N}:nb_frames={N}:color={col},trim=start_frame={N},setpts=PTS-STARTPTS,settb=1/{FPS},setpts=N[db{i}]")
                chains.append(f"[da{i}][db{i}]concat=n=2:v=1:a=0,format=yuv420p,tpad=stop_mode=clone:stop=2,trim=end_frame={T},"
                              f"settb=1/{FPS},setpts=N,fps={FPS}[x{i}]")
        elif typ in TR3:
            chains.append(f"{A}format=rgba,settb=1/{FPS},setpts=N[q{i}a]")
            chains.append(f"{B}format=rgba,settb=1/{FPS},setpts=N[q{i}b]")
            out3 = tr3_graph(typ, f"[q{i}a]", f"[q{i}b]", T, OUTPUT_W, OUTPUT_H, chains, f"q{i}", True, t.get("ez") or 0)
            chains.append(f"{out3}format=yuv420p,tpad=stop_mode=clone:stop=2,trim=end_frame={T},settb=1/{FPS},setpts=N,fps={FPS}[x{i}]")
        elif typ == "circle":
            # Circle Open: a crisp, eased, anti-aliased circle grows from the centre and reveals B.
            # The mask is drawn small (cheap) and scaled up, which also softens its edge by a few px.
            mw, mh = OUTPUT_W // 4, OUTPUT_H // 4
            r = f"(({ease_expr(f'((N+0.5)/{T})')})*hypot(W/2,H/2)*1.03)"
            m = f"255*lte(hypot(X-W/2,Y-H/2),{r})"
            chains.append(f"color=c=black:s={mw}x{mh}:r={FPS}:d={T / FPS + 0.5:.4f},trim=end_frame={T},format=yuv420p,"
                          f"geq=lum='{m}':cb='{m}':cr='{m}',scale={OUTPUT_W}:{OUTPUT_H}:flags=bilinear,setsar=1,"
                          f"settb=1/{FPS},setpts=N[cm{i}]")
            chains.append(f"{A}settb=1/{FPS},setpts=N[ca{i}]")
            chains.append(f"{B}settb=1/{FPS},setpts=N[cb{i}]")
            chains.append(f"[ca{i}][cb{i}][cm{i}]maskedmerge,format=yuv420p,tpad=stop_mode=clone:stop=2,trim=end_frame={T},"
                          f"settb=1/{FPS},setpts=N,fps={FPS}[x{i}]")
        else:
            # Slow-mo / Spin / Zoom: the (already transformed) windows are blended
            fx = []
            if blur_on and typ in MOTION:
                for lvl, frames in sorted(blur_levels(motion_blur(T), MOTION_LEVELS).items()):
                    fx.append(f"gblur=sigma={lvl}:enable='{frame_ranges(frames)}'")
            chains.append(",".join([f"{A}{B}xfade=transition={XFADE[typ]}:duration={T / FPS:.6f}:offset=0"] + fx
                                   + ["format=yuv420p", "tpad=stop_mode=clone:stop=2", f"trim=end_frame={T}",
                                      f"settb=1/{FPS}", "setpts=N", f"fps={FPS}"]) + f"[x{i}]")

    order = []
    for i in range(n):
        tin, tout, _, _ = section_windows(secs, trans, i)
        L = (secs[i]["f1"] - secs[i]["f0"]) + tin // 2 + tout // 2
        if L - tout > tin:
            order.append(f"[b{i}]")
        if i < n - 1 and trans[i]["tf"]:
            order.append(f"[x{i}]")
    chains.append("".join(order) + f"concat=n={len(order)}:v=1:a=0,settb=1/{FPS},setpts=N,fps={FPS}[joined]")
    cur = "[joined]"

    # effects on the finished timeline (frame numbers = this graph's output frames)
    total = secs[-1]["f1"]
    T = pulse.get("tlen", TLEN_DEFAULT)
    # song-wide Overlays: on top of the cuts + transitions...
    govs_ = list(pulse.get("govs") or [])
    if pulse.get("vis"):                                # the Audio Visualizer: a video of its own (drawn from the song), laid on like any video layer
        try:
            vg = vis_gov(pulse["vis"])
            if vg:
                govs_.append(vg)
        except Exception as e:
            log.info(f"[visualizer] left out of this render: {e}")
    if govs_:
        cur = gov_layers(cur, chains, inputs, n_in, govs_, frame0, total, pulse.get("tag") or os.path.join(WORK_DIR, "x"))
    # ...then the thumps act on everything, overlays included (zoom, Flicker / Fade Out, heavy flash)
    zt, shade, flashes = beat_thumps(secs, trans, pulse, total)
    if pulse.get("_spark"):
        cur = spark_layers(cur, chains, inputs, n_in, pulse["_spark"], total)
    th = []
    if zt:
        shx = "+(" + "+".join(pulse["_shx"]) + ")" if pulse.get("_shx") else ""
        shy = "+(" + "+".join(pulse["_shy"]) + ")" if pulse.get("_shy") else ""
        th += [f"zoompan=z='1+{'+'.join(zt)}':x='iw/2-(iw/zoom/2){shx}':y='ih/2-(ih/zoom/2){shy}':d=1:s={OUTPUT_W}x{OUTPUT_H}:fps={FPS}",
               "setpts=PTS-STARTPTS"]
    if shade:                                   # (drawbox blends colour correctly only in 4:4:4)
        th.append("format=yuv444p," + ",".join(
            f"drawbox=x=0:y=0:w=iw:h=ih:color={col}@{a:.2f}:t=fill:enable='{frame_ranges(fr)}'"
            for (col, a), fr in sorted(shade.items()) if a > 0))
    if flashes:
        th.append(f"format=yuv444p,drawbox=x=0:y=0:w=iw:h=ih:color=white@{min(1.0, 0.85 * pulse['intensity']):.2f}:t=fill"
                  f":enable='{frame_ranges(sorted(set(flashes)))}'")
    if th:
        chains.append(cur + ",".join(th + ["format=yuv420p", f"settb=1/{FPS}", "setpts=N", f"fps={FPS}"]) + "[thz]")
        cur = "[thz]"

    # motion blur on the thumps: a zoom (radial) blur on the beat frame and the 2 after it
    lv = {}
    if blur_on:                                          # ...and on the last frames of a Zoom Punch
        for i in range(n - 1):
            if trans[i]["type"] != "zsync":                 # (Zoom Punch is one clean motion: no blur)
                continue
            for f, a in punch_blur(secs, trans, i, T).items():
                if 0 <= f < total:
                    lv[f] = max(lv.get(f, 0), a)
    if (pulse["on"] and pulse["intensity"] > 0 and pulse.get("mblur")) or lv:
        for i, s in enumerate(secs):
            tin, tout, _, _ = section_windows(secs, trans, i)
            L = (s["f1"] - s["f0"]) + tin // 2 + tout // 2
            cf0 = s["f0"] - tin // 2
            for k, heavy, kind, st in (s["beats"] if pulse["on"] and pulse.get("mblur") else []):
                if kind != "zoom" or st <= 0:
                    continue
                amp = (HEAVY_ZOOM if (heavy and pulse["heavy"]) else PULSE_ZOOM) * st
                for d, w in enumerate(THUMP_BLUR_W):
                    kk = k + d
                    if not (0 <= kk < L) or not (0 <= cf0 + kk < total):
                        continue
                    a = thump_blur_amount(amp, pulse["intensity"], pulse["mblurAmt"], w)
                    if a >= THUMP_LEVELS[0] * 0.75:
                        f = cf0 + kk
                        lv[f] = max(lv.get(f, 0), a)
        if lv:
            groups = {}
            for f, a in lv.items():
                groups.setdefault(min(THUMP_LEVELS, key=lambda v: abs(v - a)), []).append(f)
            hw, hh = OUTPUT_W // 2, OUTPUT_H // 2
            fx = [f"geq={radial_expr(a)}:enable='{frame_ranges(fr)}'" for a, fr in sorted(groups.items())]
            chains.append(f"{cur}split[tbm][tbb]")
            chains.append(f"[tbb]scale={hw}:{hh}," + ",".join(fx) + f",scale={OUTPUT_W}:{OUTPUT_H}[tbz]")
            chains.append(f"[tbm][tbz]overlay=enable='{frame_ranges(list(lv))}',format=yuv420p,settb=1/{FPS},setpts=N[thumped]")
            cur = "[thumped]"

    post = []
    # Glitch: colour split + horizontal band jitter on the frames around a hard cut
    gl_even, gl_odd = [], []
    for i in range(n - 1):
        if trans[i]["type"] == "glitch":
            gh, f1 = glitch_half(T), secs[i]["f1"]
            for f in range(f1 - gh, f1 + gh):
                if 0 <= f < total:
                    (gl_even if (f + frame0) % 2 == 0 else gl_odd).append(f)
    if gl_even or gl_odd:
        allg = frame_ranges(gl_even + gl_odd)
        G = f"(N+{frame0})"
        post.append(f"geq=lum='p(X+(mod(floor(Y/37)+{G},3)-1)*28*gt(mod(floor(Y/37)*7+{G}*3,5),2),Y)'"
                    f":cb='p(X+(mod(floor(Y/18)+{G},3)-1)*14,Y)':cr='p(X-(mod(floor(Y/18)+{G},3)-1)*14,Y)'"
                    f":enable='{allg}'")
        if gl_even:
            post.append(f"chromashift=cbh=24:crh=-24:enable='{frame_ranges(gl_even)}'")
        if gl_odd:
            post.append(f"chromashift=cbh=-16:crh=16:cbv=6:enable='{frame_ranges(gl_odd)}'")
    # Flash modifier: stacks on any transition, centred on the cut
    flash = {}
    for i in range(n - 1):
        if trans[i].get("flash"):
            for d, a in flash_frames(T):
                f = secs[i]["f1"] + d
                if 0 <= f < total:
                    flash.setdefault(a, []).append(f)
    if flash:
        post.append("format=yuv444p")          # drawbox blends colour correctly only in 4:4:4
    for a, frames in sorted(flash.items()):
        post.append(f"drawbox=x=0:y=0:w=iw:h=ih:color=white@{a:.2f}:t=fill:enable='{frame_ranges(frames)}'")
    # Polish: blurred intro that clears as the song comes in (global frame numbers)
    intro = polish.get("intro") or {}
    seq = polish.get("seq") or {}
    if intro.get("on") or seq.get("on"):
        lv = {}
        prof = (seq_blur(seq["frames"], seq["blur"], seq["ustart"], seq["udur"], polish.get("total"))
                if seq.get("on") else intro_blur(intro["dur"], intro["amt"]))
        for f, sig in prof.items():
            if 0 <= f - frame0 < total:
                lv.setdefault(sig, []).append(f - frame0)
        for sig, frames in sorted(lv.items()):
            post.append(f"gblur=sigma={sig}:steps=2:enable='{frame_ranges(frames)}'")
    chains.append(cur + ",".join(post + ["format=yuv420p"]) + "[pol]")
    cur = "[pol]"

    # Polish: glowing 3D title + living watermark
    tt = polish.get("title") or {}
    if tt.get("on") and tt.get("file"):
        cur = title_graph(chains, cur, tt, frame0, total)
    wm = polish.get("wm") or {}
    last = []
    if wm.get("on") and wm.get("png"):
        # styled watermark image, looped; its opacity breathes on the whole video's clock (geq on the small image only)
        idx = n_in[0]
        n_in[0] += 1
        inputs.extend(["-loop", "1", "-framerate", str(FPS), "-t", f"{total / FPS + 1:.4f}", "-i", wm["png"]])
        G = f"(T+{frame0 / FPS:.4f})"
        al = watermark_alpha(wm, G, polish.get("total", total) / FPS)
        chains.append(f"[{idx}:v]format=rgba,geq=r='r(X,Y)':g='g(X,Y)':b='b(X,Y)':a='alpha(X,Y)*{al}',"
                      f"settb=1/{FPS},setpts=N[wmi]")
        chains.append(f"{cur}settb=1/{FPS},setpts=N[wmb]")
        chains.append(f"[wmb][wmi]overlay=x={wm['px']}:y={wm['py']}:eof_action=repeat:shortest=0,format=yuv420p[wmo]")
        cur = "[wmo]"
    elif wm.get("on") and wm.get("file"):
        last.append(watermark_filter(wm, frame0, polish.get("total", total)))
    ov = polish.get("ov") or {}
    if ov.get("on") and ov.get("ow"):
        # Image layer (logo / sticker / Image Editor picture), with its transparency, on top of everything
        TOT = polish.get("total", total) / FPS
        a = ov["start"]
        b = TOT if ov["dur"] <= 0 else min(TOT, a + ov["dur"])
        if b > frame0 / FPS and a < (frame0 + total) / FPS:
            idx = n_in[0]
            n_in[0] += 1
            inputs.extend(["-loop", "1", "-framerate", str(FPS), "-t", f"{total / FPS + 1:.4f}", "-i", os.path.basename(ov["image"])])
            chains.append(f"[{idx}:v]format=rgba,scale={ov['ow']}:{ov['oh']}:flags=lanczos,"
                          f"colorchannelmixer=aa={ov['opacity']:.3f},settb=1/{FPS},setpts=N[ovi]")
            if last:
                chains.append(cur + ",".join(last) + "[ovpre]")
                cur, last = "[ovpre]", []
            chains.append(f"{cur}settb=1/{FPS},setpts=N[ovb]")
            en = f"enable='between(t+{frame0 / FPS:.4f},{a:.4f},{b - 0.5 / FPS:.4f})'"
            chains.append(f"[ovb][ovi]overlay=x={ov['px']}:y={ov['py']}:eof_action=repeat:{en},format=yuv420p[ovo]")
            cur = "[ovo]"
    if pulse.get("look") or pulse.get("look_segs"):
        if last:                                       # (the look counts frames: start it on a clean, frame-numbered stream)
            chains.append(cur + ",".join(last + [f"settb=1/{FPS}", "setpts=N"]) + "[lkin]")
            cur, last = "[lkin]", []
        cur, last = look_graph(cur, last, chains, pulse.get("look"), pulse.get("look_segs"), frame0, total)
    chains.append(cur + ",".join(last + [f"scale={OUTPUT_W}:{OUTPUT_H}", "setsar=1", f"settb=1/{FPS}", "setpts=N",
                                         f"fps={FPS}", "format=yuv420p"]) + "[vout]")
    return inputs, chains


# ----- easing + blur profiles (the browser preview uses the same numbers) ----------
EASE_POW = 3                                  # transition feel: 3 = smooth (cubic), 5 = snappy, 7 = punchy (set per render)
EASE_FEEL = {"smooth": 3, "snappy": 5, "punchy": 7}


def ease(q):
    """ease-in-out of power EASE_POW: slow start, fast middle, slow landing (higher power = snappier)."""
    q = min(1.0, max(0.0, q))
    k = 2 ** (EASE_POW - 1)
    return k * q ** EASE_POW if q < 0.5 else 1 - k * (1 - q) ** EASE_POW


def ease_expr(q):
    k = 2 ** (EASE_POW - 1)
    return f"if(lt({q},0.5),{k}*pow({q},{EASE_POW}),1-{k}*pow(1-{q},{EASE_POW}))"


# ---------------------------------------------------------------------------
# Image Editor: AI cut-outs (rembg / GrabCut), all on this PC
# ---------------------------------------------------------------------------
_REMBG = {"session": None, "lock": threading.Lock(), "fine": None, "fine_failed": False}


def _still_mask(img):
    """Subject mask for ONE picture (Image Editor, templates), 0-255 at the picture's size. Better than the video one:
    1. the sharper model (isnet-general-use, 1024 px; a one-time 180 MB download) when it can be had, else the usual u2net;
    2. the AI's soft, low-resolution edge is then snapped to the picture's real edges (a guided filter: where the picture
       has an edge near the mask's edge, the mask's edge moves onto it), so hair and shoulders are crisp instead of a halo.
    Call with _REMBG["lock"] held."""
    import numpy as np
    from rembg import new_session, remove
    def make(name):
        try:
            return new_session(name, providers=ai_providers())
        except TypeError:                                   # older rembg: no providers argument
            return new_session(name)
    sess = None
    if _REMBG["fine"] is None and not _REMBG["fine_failed"]:
        try:
            _REMBG["fine"] = make("isnet-general-use")
        except Exception:
            _REMBG["fine_failed"] = True                      # offline / old rembg: the usual model does it
    sess = _REMBG["fine"]
    _REMBG["used"] = time.time()
    rgb = img.convert("RGB")
    m = None
    if sess is not None:
        try:
            m = remove(rgb, session=sess, only_mask=True)
        except Exception:
            _REMBG["fine"], _REMBG["fine_failed"] = None, True
    if m is None:
        if _REMBG["session"] is None:
            _REMBG["session"] = make("u2net")
        m = remove(rgb, session=_REMBG["session"], only_mask=True)
    a = np.array(m.convert("L").resize(img.size))
    try:
        import cv2
        g = cv2.cvtColor(np.array(rgb), cv2.COLOR_RGB2GRAY).astype(np.float32) / 255
        p_ = a.astype(np.float32) / 255
        r = max(2, int(max(img.size) / 220))
        box = lambda x: cv2.boxFilter(x, -1, (2 * r + 1, 2 * r + 1))
        mI, mp = box(g), box(p_)
        ka = (box(g * p_) - mI * mp) / (box(g * g) - mI * mI + 1e-4)
        q = np.clip(box(ka) * g + box(mp - ka * mI), 0, 1)
        q = np.clip((q - 0.08) / 0.84, 0, 1)
        unsure = cv2.dilate(((p_ > 0.04) & (p_ < 0.96)).astype(np.uint8), np.ones((2 * r + 1, 2 * r + 1), np.uint8)) > 0
        a = (np.where(unsure, q, p_) * 255 + 0.5).astype(np.uint8)       # (only the edge band changes; solid inside / outside stay as the AI said)
    except Exception:
        pass
    return a


def ai_model_ready():
    for _dp, _dn, files in os.walk(os.environ.get("U2NET_HOME", "")):
        if "u2net.onnx" in files:
            return True
    return False


def _data_url(img):
    import base64
    import io
    buf = io.BytesIO()
    img.save(buf, "PNG")
    return "data:image/png;base64," + base64.b64encode(buf.getvalue()).decode("ascii")


def _cutout_result(img, a, outline):
    """(mask, cut-out) data URLs for the Image Editor; outline = 1-3 px white sticker edge on the cut-out."""
    import numpy as np
    from PIL import Image, ImageFilter
    rgba = np.array(img)
    cut = rgba.copy()
    cut[:, :, 3] = a
    out = Image.fromarray(cut, "RGBA")
    if outline:
        try:
            import cv2
            k = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (2 * outline + 1, 2 * outline + 1))
            solid = np.where(a >= 96, 255, 0).astype(np.uint8)
            grown = cv2.GaussianBlur(cv2.dilate(solid, k), (3, 3), 0.6)
        except ImportError:
            grown = np.array(Image.fromarray(np.where(a >= 96, 255, 0).astype(np.uint8)).filter(ImageFilter.MaxFilter(2 * outline + 1)))
        under = np.zeros_like(rgba)
        under[:, :, :3] = 255
        under[:, :, 3] = grown
        out = Image.alpha_composite(Image.fromarray(under, "RGBA"), out)
    m = np.zeros_like(rgba)
    m[:, :, :3] = 255
    m[:, :, 3] = a
    return jsonify(mask=_data_url(Image.fromarray(m, "RGBA")), cutout=_data_url(out), outline=outline,
                   width=img.size[0], height=img.size[1])


@app.post("/api/img/decode")
def api_img_decode():
    """Image mode: a picture the browser can't open (TIFF, HEIC, ...) or a still from a video (MKV, HEVC, ProRes...)
    -> PNG (transparency kept)."""
    f = request.files.get("file")
    if not f or not f.filename:
        return err("No file received.")
    _uid, path = save_upload(f, WORK_DIR)
    out = path + ".png"
    try:
        try:                                            # plain pictures first: Pillow keeps 16-bit / alpha best
            from PIL import Image
            with Image.open(path) as im:
                if getattr(im, "n_frames", 1) == 1 or im.format in ("TIFF", "GIF", "WEBP", "PNG"):
                    im.seek(0)
                    im = im.convert("RGBA" if ("A" in im.getbands() or im.mode == "P") else "RGB")
                    return jsonify({"png": _data_url(im), "w": im.width, "h": im.height, "video": False, "t": 0})
        except Exception:
            pass
        info = probe(path)
        vs = [st for st in info.get("streams", []) if st.get("codec_type") == "video"]
        if not vs:
            raise RuntimeError("That file has no picture in it.")
        dur = float(info.get("format", {}).get("duration") or 0)
        fmt_name = info.get("format", {}).get("format_name", "")
        video = dur > 0.2 and not fmt_name.endswith("_pipe") and fmt_name != "image2"
        t = min(1.0, dur / 3) if video else 0.0
        for tt in (t, 0.0):
            r = run(["ffmpeg", "-v", "error", "-y", "-ss", f"{tt:.3f}", "-i", path, "-map", "0:v:0", "-frames:v", "1",
                     "-c:v", "png", "-f", "image2", out], timeout=120)
            if r.returncode == 0 and os.path.exists(out) and os.path.getsize(out) > 0:
                t = tt
                break
        else:
            raise RuntimeError((r.stderr or "FFmpeg could not read it.").strip()[-200:])
        from PIL import Image
        with Image.open(out) as im:
            im.load()
            return jsonify({"png": _data_url(im), "w": im.width, "h": im.height, "video": video, "t": round(t, 3)})
    except Exception as e:
        return err(str(e))
    finally:
        _rm(path)
        _rm(out)


@app.post("/api/img/grabcut")
def api_img_grabcut():
    """Image Editor 'Mark Object': a rough loop drawn around something -> OpenCV GrabCut snaps
    the exact outline (inside the loop = probably the object, outside = background)."""
    f = request.files.get("file")
    if not f:
        return err("No image.")
    try:
        pts = json.loads(request.form.get("poly") or "[]")
        outline = max(0, min(3, int(request.form.get("outline", 0) or 0)))
    except (ValueError, TypeError):
        return err("Bad mark.")
    if len(pts) < 3:
        return err("Draw a loop around the object.")
    try:
        import cv2
        import numpy as np
        from PIL import Image
    except ImportError:
        return err("OpenCV is not installed. Close the editor and double-click Start_Tool.bat again: it installs it.", 500)
    try:
        img = Image.open(f.stream).convert("RGBA")
    except Exception:
        return err("Could not read that picture.")
    rgba = np.array(img)
    H, W = rgba.shape[:2]
    k = min(1.0, 900.0 / max(H, W))                       # GrabCut on a smaller copy: fast, then scaled back up
    sw, sh = max(8, round(W * k)), max(8, round(H * k))
    small = cv2.resize(cv2.cvtColor(rgba[:, :, :3], cv2.COLOR_RGB2BGR), (sw, sh), interpolation=cv2.INTER_AREA)
    poly = np.array([[float(x) * k, float(y) * k] for x, y in pts], np.float32).round().astype(np.int32)
    mask = np.full((sh, sw), cv2.GC_BGD, np.uint8)
    cv2.fillPoly(mask, [poly], cv2.GC_PR_FGD)
    inside = int((mask == cv2.GC_PR_FGD).sum())
    if inside < 64:
        return err("That mark is too small - draw a loop around the whole object.")
    if inside > sw * sh * 0.97:
        cv2.rectangle(mask, (0, 0), (sw - 1, sh - 1), cv2.GC_BGD, 2)    # (loop covers everything: the border is background)
    band = max(2, round(min(sw, sh) / 150))
    cv2.polylines(mask, [poly], True, cv2.GC_PR_BGD, band)               # the loop itself: probably background
    bgd, fgd = np.zeros((1, 65), np.float64), np.zeros((1, 65), np.float64)
    try:
        cv2.grabCut(small, mask, None, bgd, fgd, 6, cv2.GC_INIT_WITH_MASK)
    except cv2.error as e:
        return err(f"Could not separate the object: {e}", 500)
    m = np.where((mask == cv2.GC_FGD) | (mask == cv2.GC_PR_FGD), 255, 0).astype(np.uint8)
    m = cv2.morphologyEx(m, cv2.MORPH_OPEN, np.ones((3, 3), np.uint8))
    m = cv2.morphologyEx(m, cv2.MORPH_CLOSE, np.ones((5, 5), np.uint8))
    n, lab, stats, _ = cv2.connectedComponentsWithStats(m, 8)              # drop specks: keep the big pieces
    if n > 2:
        keep = [i for i in range(1, n) if stats[i, cv2.CC_STAT_AREA] >= stats[1:, cv2.CC_STAT_AREA].max() * 0.08]
        m = np.where(np.isin(lab, keep), 255, 0).astype(np.uint8)
    if not m.any():
        return err("No object found inside that mark - try a slightly bigger loop.")
    m = cv2.resize(m, (W, H), interpolation=cv2.INTER_LINEAR)
    m = cv2.GaussianBlur(m, (3, 3), 0.8)                                  # soft anti-aliased edge
    a = np.minimum(m, rgba[:, :, 3])
    return _cutout_result(img, a, outline)


_REFINE_AI = {}          # md5 of the layer picture -> the AI subject mask (so every scribble doesn't re-run the AI)


def _ai_subject_mask(img, key):
    """The rembg subject mask (0-255, full size) or None if the AI cut-out isn't installed / downloaded."""
    if key in _REFINE_AI:
        return _REFINE_AI[key]
    try:
        from rembg import new_session, remove  # noqa: F401  (only checks that it is installed)
    except Exception:
        return None
    if not ai_model_ready():
        return None
    try:
        with _REMBG["lock"]:
            a = _still_mask(img)
    except Exception:
        return None
    if len(_REFINE_AI) > 6:
        _REFINE_AI.pop(next(iter(_REFINE_AI)))
    _REFINE_AI[key] = a
    return a


@app.post("/api/img/refine")
def api_img_refine():
    """Image Editor 'Refine Edge': green scribbles = keep (subject), red = remove (background), an optional box =
    the subject is somewhere inside. OpenCV GrabCut, seeded with the AI subject mask, snaps to the real edges;
    the AI's soft edge (hair) is kept wherever GrabCut agrees with it."""
    import hashlib
    f = request.files.get("file")
    if not f:
        return err("No image.")
    try:
        strokes = json.loads(request.form.get("strokes") or "[]")
        box = json.loads(request.form.get("box") or "null")
        outline = max(0, min(3, int(request.form.get("outline", 0) or 0)))
        use_ai = request.form.get("ai", "1") != "0"
    except (ValueError, TypeError):
        return err("Bad scribbles.")
    if not strokes and not box:
        return err("Scribble green over what to keep, red over what to remove (or drag a box around the subject).")
    try:
        import cv2
        import numpy as np
        from PIL import Image
    except ImportError:
        return err("OpenCV is not installed. Close the editor and double-click Start_Tool.bat again: it installs it.", 500)
    raw = f.read()
    try:
        import io
        img = Image.open(io.BytesIO(raw)).convert("RGBA")
    except Exception:
        return err("Could not read that picture.")
    rgba = np.array(img)
    H, W = rgba.shape[:2]
    ai = _ai_subject_mask(img, hashlib.md5(raw).hexdigest()) if use_ai else None
    k = min(1.0, 900.0 / max(H, W))
    sw, sh = max(8, round(W * k)), max(8, round(H * k))
    small = cv2.resize(cv2.cvtColor(rgba[:, :, :3], cv2.COLOR_RGB2BGR), (sw, sh), interpolation=cv2.INTER_AREA)

    def paint(target, scale, kinds):
        """Draw the scribbles of the given kinds onto target (value per kind) at this scale."""
        for st in strokes:
            kind = st.get("kind")
            if kind not in kinds:
                continue
            pts = np.array([[float(x) * scale, float(y) * scale] for x, y in st.get("pts", [])], np.float32).round().astype(np.int32)
            r = max(1, int(round(float(st.get("r", 8)) * scale)))
            if len(pts) == 1:
                cv2.circle(target, tuple(int(v) for v in pts[0]), r, kinds[kind], -1)
            elif len(pts) > 1:
                cv2.polylines(target, [pts], False, kinds[kind], 2 * r + 1, lineType=cv2.LINE_8)
                for q in (pts[0], pts[-1]):
                    cv2.circle(target, tuple(int(v) for v in q), r, kinds[kind], -1)

    # 1. the starting guess: the AI mask as *probable* subject / background (GrabCut may overrule it)
    mask = np.full((sh, sw), cv2.GC_PR_BGD, np.uint8)
    allowed = np.zeros((sh, sw), np.uint8)                       # where the subject may be at all
    if ai is not None:
        a_s = cv2.resize(ai, (sw, sh), interpolation=cv2.INTER_AREA)
        mask[a_s >= 128] = cv2.GC_PR_FGD
        if (a_s >= 128).any():
            rr = max(4, round(min(sw, sh) * 0.08))
            allowed = cv2.dilate(np.uint8(a_s >= 128) * 255, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (2 * rr + 1, 2 * rr + 1)))
    if box:
        x0, y0, x1, y1 = [float(v) * k for v in box]
        x0, x1 = sorted((max(0, x0), min(sw - 1, x1)))
        y0, y1 = sorted((max(0, y0), min(sh - 1, y1)))
        bm = np.zeros((sh, sw), np.uint8)
        cv2.rectangle(bm, (int(x0), int(y0)), (int(x1), int(y1)), 255, -1)
        if ai is None or not (mask == cv2.GC_PR_FGD).any():
            mask[bm > 0] = cv2.GC_PR_FGD
        allowed = bm                                             # a box is the hard limit: nothing outside it
    else:
        grow = np.zeros((sh, sw), np.uint8)
        paint(grow, k, {"fg": 255})
        if grow.any():
            rr = max(6, round(min(sw, sh) * 0.06))
            allowed = np.maximum(allowed, cv2.dilate(grow, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (2 * rr + 1, 2 * rr + 1))))
            if ai is None:                                       # no AI: the area around the green strokes may be subject
                ys, xs = np.nonzero(grow)
                pad = max(8, round(min(sw, sh) * 0.12))
                yy0, yy1, xx0, xx1 = max(0, ys.min() - pad), min(sh, ys.max() + pad), max(0, xs.min() - pad), min(sw, xs.max() + pad)
                allowed[yy0:yy1, xx0:xx1] = 255
    if allowed.any():
        mask[allowed == 0] = cv2.GC_BGD
    # 2. the scribbles are certain
    paint(mask, k, {"fg": int(cv2.GC_FGD), "bg": int(cv2.GC_BGD)})
    if not (mask == cv2.GC_FGD).any() and not (mask == cv2.GC_PR_FGD).any():
        return err("Nothing marked as the subject yet - scribble green over it or drag a box around it.")
    if not ((mask == cv2.GC_BGD) | (mask == cv2.GC_PR_BGD)).any():
        cv2.rectangle(mask, (0, 0), (sw - 1, sh - 1), cv2.GC_BGD, 1)
    bgd, fgd = np.zeros((1, 65), np.float64), np.zeros((1, 65), np.float64)
    try:
        cv2.grabCut(small, mask, None, bgd, fgd, 5, cv2.GC_INIT_WITH_MASK)
    except cv2.error as e:
        return err(f"Could not refine: {e}", 500)
    m = np.where((mask == cv2.GC_FGD) | (mask == cv2.GC_PR_FGD), 255, 0).astype(np.uint8)
    m = cv2.morphologyEx(m, cv2.MORPH_OPEN, np.ones((3, 3), np.uint8))
    # drop specks that no green scribble asked for
    n, lab, stats, _ = cv2.connectedComponentsWithStats(m, 8)
    if n > 2:
        green = np.zeros((sh, sw), np.uint8)
        paint(green, k, {"fg": 255})
        big = stats[1:, cv2.CC_STAT_AREA].max()
        keep = [i for i in range(1, n) if stats[i, cv2.CC_STAT_AREA] >= big * 0.03 or green[lab == i].any()]
        m = np.where(np.isin(lab, keep), 255, 0).astype(np.uint8)
    # 3. back to full size; keep the AI's soft edge where it agrees, GrabCut's edge where it doesn't
    up = cv2.GaussianBlur(cv2.resize(m, (W, H), interpolation=cv2.INTER_LINEAR), (3, 3), 0.8)
    if ai is not None:
        hard = up >= 128
        agree = hard == (ai >= 128)
        a = np.where(agree, ai, up).astype(np.uint8)
        a = np.where(hard & (ai < 128), np.maximum(up, 0), a)
    else:
        a = up
    # the scribbles win at full resolution too (exactly where you drew)
    full = np.full((H, W), 128, np.uint8)
    paint(full, 1.0, {"fg": 255, "bg": 0})
    a = np.where(full == 255, 255, np.where(full == 0, 0, a)).astype(np.uint8)
    if not (a >= 128).any():
        return err("Everything ended up as background - add a green scribble over the subject.")
    a = np.minimum(a, rgba[:, :, 3])
    res = _cutout_result(img, a, outline)
    return res


@app.post("/api/img/manga_cut")
def api_img_manga_cut():
    """Image Editor: Manga Cutout. A manga panel -> its foreground figure and the panel behind it, with OpenCV only (no AI
    model): the part of the page where the drawing is densest gives a first guess, GrabCut snaps that guess to the lines,
    and the hole the figure leaves is painted in so the background can move behind it."""
    f = request.files.get("file")
    if not f:
        return err("No image.")
    try:
        import cv2
        import numpy as np
        from PIL import Image
    except ImportError:
        return err("OpenCV / Pillow are not installed. Close Kiru and start it again with Start_Tool.bat: it installs them.", 500)
    try:
        im = Image.open(f.stream).convert("RGBA")
    except Exception:
        return err("That picture could not be read.")
    rgba = np.array(im)
    rgb, alpha0 = np.ascontiguousarray(rgba[:, :, :3]), rgba[:, :, 3]
    H, W = rgb.shape[:2]
    k = min(1.0, 640 / max(W, H))
    small = cv2.resize(rgb, (max(16, round(W * k)), max(16, round(H * k))), interpolation=cv2.INTER_AREA)
    h, w = small.shape[:2]
    g = cv2.cvtColor(small, cv2.COLOR_RGB2GRAY)
    edge = cv2.magnitude(cv2.Sobel(g, cv2.CV_32F, 1, 0), cv2.Sobel(g, cv2.CV_32F, 0, 1))
    dens = cv2.GaussianBlur(edge, (0, 0), max(3.0, w / 40))
    dens /= float(dens.max()) + 1e-6
    yy, xx = np.mgrid[0:h, 0:w]
    centre = np.exp(-(((xx - w / 2) / (0.45 * w)) ** 2 + ((yy - h * 0.55) / (0.5 * h)) ** 2))      # a figure is rarely pressed into a corner
    sal = dens * (0.4 + 0.6 * centre)
    thr = max(0.18, cv2.threshold((sal * 255).astype(np.uint8), 0, 255, cv2.THRESH_BINARY + cv2.THRESH_OTSU)[0] / 255)
    blob = cv2.morphologyEx((sal > thr).astype(np.uint8), cv2.MORPH_CLOSE, np.ones((9, 9), np.uint8))
    n, lab, stats, _ = cv2.connectedComponentsWithStats(blob)
    if n <= 1:
        return err("Kiru could not find a figure in this panel. Select it by hand (Selection Brush or Lasso) and use Copy to new layer.")
    core = (lab == 1 + int(np.argmax(stats[1:, cv2.CC_STAT_AREA]))).astype(np.uint8)
    mask = np.full((h, w), cv2.GC_PR_BGD, np.uint8)
    mask[cv2.dilate(core, np.ones((15, 15), np.uint8)) > 0] = cv2.GC_PR_FGD
    mask[cv2.erode(core, np.ones((11, 11), np.uint8)) > 0] = cv2.GC_FGD
    b = max(2, int(0.02 * min(w, h)))
    mask[:b] = mask[-b:] = cv2.GC_BGD
    mask[:, :b] = mask[:, -b:] = cv2.GC_BGD
    engine = "OpenCV GrabCut"
    try:
        cv2.grabCut(small, mask, None, np.zeros((1, 65), np.float64), np.zeros((1, 65), np.float64), 4, cv2.GC_INIT_WITH_MASK)
        fg = ((mask == cv2.GC_FGD) | (mask == cv2.GC_PR_FGD)).astype(np.uint8)
    except cv2.error:
        fg = np.zeros((h, w), np.uint8)
    fg = cv2.morphologyEx(fg, cv2.MORPH_OPEN, np.ones((3, 3), np.uint8))
    n2, lab2, st2, _ = cv2.connectedComponentsWithStats(fg)
    if n2 > 1:
        fg = (lab2 == 1 + int(np.argmax(st2[1:, cv2.CC_STAT_AREA]))).astype(np.uint8)
    cover = float(fg.mean())
    if cover < 0.02 or cover > 0.9:                       # GrabCut gave up (flat page, or it took everything): the dense area itself
        fg, engine = cv2.dilate(core, np.ones((7, 7), np.uint8)), "OpenCV threshold"
        cover = float(fg.mean())
    cnt, _ = cv2.findContours(fg, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    cv2.drawContours(fg, cnt, -1, 1, -1)                  # (holes inside the figure belong to it)
    a_full = cv2.GaussianBlur(cv2.resize(fg * 255, (W, H), interpolation=cv2.INTER_LINEAR), (0, 0), 1.2)
    character = np.dstack([rgb, np.minimum(a_full, alpha0)])
    hole = cv2.dilate(fg * 255, np.ones((9, 9), np.uint8))
    filled = cv2.resize(cv2.inpaint(small, hole, 5, cv2.INPAINT_TELEA), (W, H), interpolation=cv2.INTER_CUBIC)
    hm = (cv2.GaussianBlur(cv2.resize(hole, (W, H), interpolation=cv2.INTER_LINEAR), (0, 0), 3)[..., None] / 255.0)
    background = np.dstack([(rgb * (1 - hm) + filled * hm).astype(np.uint8), alpha0])
    return jsonify({"character": _data_url(Image.fromarray(character, "RGBA")), "background": _data_url(Image.fromarray(background, "RGBA")),
                    "cover": round(cover, 3), "engine": engine})


@app.post("/api/img/subject")
def api_img_subject():
    """Image Editor: 'Select Subject' / 'Cut out'. Returns the subject mask and the cut-out
    (optionally with a 1-3 px white outline). Runs fully on this PC."""
    f = request.files.get("file")
    if not f:
        return err("No image.")
    try:
        outline = max(0, min(3, int(request.form.get("outline", 0) or 0)))
    except ValueError:
        outline = 0
    try:
        import numpy as np
        from PIL import Image, ImageFilter
    except ImportError:
        return err("Pillow / numpy are not installed. Close the editor and double-click Start_Tool.bat again: it installs them.", 500)
    try:
        from rembg import new_session, remove  # noqa: F401  (only checks that it is installed)
    except Exception:
        return err("The AI cut-out (rembg) is not installed. Close the editor and double-click Start_Tool.bat again: it installs it.", 500)
    if not ai_model_ready():
        return err("The AI model is not downloaded yet. Close the editor and double-click Start_Tool.bat again "
                   "(a one-time 176 MB download), then try again.", 500)
    try:
        img = Image.open(f.stream).convert("RGBA")
    except Exception:
        return err("Could not read that picture.")
    try:
        with _REMBG["lock"]:
            mask_a = _still_mask(img)
    except Exception as e:
        return err(f"The AI cut-out failed: {e}", 500)
    rgba = np.array(img)
    a = np.minimum(mask_a, rgba[:, :, 3])    # keep any transparency the layer had
    cut = rgba.copy()
    cut[:, :, 3] = a
    out = Image.fromarray(cut, "RGBA")
    if outline:
        try:
            import cv2
            k = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (2 * outline + 1, 2 * outline + 1))
            solid = np.where(a >= 96, 255, 0).astype(np.uint8)          # a crisp sticker edge, not the soft mask fringe
            grown = cv2.GaussianBlur(cv2.dilate(solid, k), (3, 3), 0.6)
        except ImportError:
            solid = Image.fromarray(np.where(a >= 96, 255, 0).astype(np.uint8))
            grown = np.array(solid.filter(ImageFilter.MaxFilter(2 * outline + 1)))
        under = np.zeros_like(rgba)
        under[:, :, :3] = 255
        under[:, :, 3] = grown
        out = Image.alpha_composite(Image.fromarray(under, "RGBA"), out)
    m = np.zeros_like(rgba)
    m[:, :, :3] = 255
    m[:, :, 3] = a
    return jsonify(mask=_data_url(Image.fromarray(m, "RGBA")), cutout=_data_url(out), outline=outline,
                   width=img.size[0], height=img.size[1])





# ---------------------------------------------------------------------------
# Fonts + Image templates (Image Editor: "Create Template from Reference")
#   fonts/            free fonts Kiru downloaded for you (Google Fonts) - the page loads every file in here
#   font matching     the text cut out of the reference is compared with the same words drawn in every font on this PC
#   image template    a poster / graphic -> Background (text + subject painted out), Shapes, Subject spot, Text layers
# ---------------------------------------------------------------------------
FONT_DIR = os.path.join(BASE_DIR, "fonts")
_FONTS = {"scan": None}
# free Google Fonts by look - what Kiru offers when the right font is not on the PC
FONT_FAMILIES = {
    "condensed": ["Bebas Neue", "Anton", "Oswald", "League Gothic", "Fjalla One"],
    "bold-sans": ["Montserrat", "Poppins", "Archivo Black", "Rubik", "Inter"],
    "sans": ["Roboto", "Inter", "Open Sans", "Lato", "Nunito"],
    "serif": ["Playfair Display", "Merriweather", "Cinzel", "Abril Fatface", "Lora"],
    "slab": ["Rye", "Alfa Slab One", "Special Elite", "Roboto Slab", "Black Ops One"],
    "script": ["Pacifico", "Dancing Script", "Great Vibes", "Satisfy", "Kaushan Script"],
    "marker": ["Permanent Marker", "Bangers", "Luckiest Guy", "Caveat", "Creepster"],
    "tech": ["Orbitron", "Russo One", "Press Start 2P", "Staatliches", "Righteous"],
}
FONT_OK_EXT = (".ttf", ".otf", ".woff2", ".woff")


def font_scan():
    """Every font file Kiru can draw with: fonts/ first, then the system's. [{family, path, local(bool: in fonts/)}]"""
    if _FONTS["scan"] is not None:
        return _FONTS["scan"]
    from PIL import ImageFont
    dirs = [(FONT_DIR, True)]
    if os.name == "nt":
        dirs += [(os.path.join(os.environ.get("WINDIR", r"C:\Windows"), "Fonts"), False),
                 (os.path.join(os.environ.get("LOCALAPPDATA", ""), "Microsoft", "Windows", "Fonts"), False)]
    else:
        dirs += [(d, False) for d in ("/usr/share/fonts", "/usr/local/share/fonts", os.path.expanduser("~/.fonts"), "/Library/Fonts", "/System/Library/Fonts")]
    out, seen = [], set()
    for d, local in dirs:
        if not d or not os.path.isdir(d):
            continue
        for dp, _dn, files in os.walk(d):
            for fn in sorted(files):
                if not fn.lower().endswith((".ttf", ".otf")) or len(out) >= 900:
                    continue
                pth = os.path.join(dp, fn)
                try:
                    fam, style = ImageFont.truetype(pth, 20).getname()
                except Exception:
                    continue
                key = (fam, style)
                if key in seen or re.search(r"unifont|symbol|math|emoji|dingbat|wingding|webding|marlett|icons|fallback", fam, re.I):
                    continue                                  # (not for words: symbol sets, and fonts that draw empty boxes)
                seen.add(key)
                out.append({"family": fam, "style": style, "path": pth, "local": local, "file": fn})
    _FONTS["scan"] = out
    return out


def font_features(mask):
    """Rough look of a piece of text (binary: True = ink): how heavy, how narrow, how slanted, how much the stroke width varies."""
    import cv2
    import numpy as np
    m = mask.astype(np.uint8)
    ys, xs = np.nonzero(m)
    if len(xs) < 30:
        return None
    m = m[ys.min():ys.max() + 1, xs.min():xs.max() + 1]
    h, w = m.shape
    dist = cv2.distanceTransform(m, cv2.DIST_L2, 3)
    core = dist[dist > 0.5]
    stroke = float(np.percentile(core, 85)) * 2 if len(core) else 1.0
    cols = m.any(axis=0)
    letters = max(1, int(np.sum(cols[1:] & ~cols[:-1])) + int(cols[0]))
    d5 = cv2.distanceTransform(m, cv2.DIST_L2, 5)        # the middle line of every stroke: thick-and-thin (serif, script) or even (sans)?
    rid = d5[(d5 >= cv2.dilate(d5, np.ones((3, 3), np.uint8))) & (d5 > 1.2)]
    vary = float(np.percentile(rid, 90) / max(0.5, np.percentile(rid, 25))) if len(rid) > 12 else 1.0
    return {"weight": stroke / max(1.0, h), "letter_w": w / letters / max(1.0, h), "ink": float(m.mean()), "vary": vary,
            "contrast": float(np.std(core) / max(0.5, np.mean(core))) if len(core) else 0.0, "h": h, "w": w, "letters": letters}


def font_category(f, text):
    """Which family of looks a text belongs to (see FONT_FAMILIES)."""
    if not f:
        return "sans"
    caps = re.sub(r"[^A-Za-z]", "", text).isupper()
    nch = len(re.sub(r"\s", "", text.split("\n")[0]))
    if not caps and nch >= 4 and f["letters"] < nch * 0.6:
        return "script"                                   # the letters join up
    if f["letter_w"] < (0.58 if caps else 0.44) and f["weight"] > 0.1:
        return "condensed"
    if f.get("vary", 1.0) > 1.52:
        return "serif"
    if f["weight"] > 0.15:
        return "bold-sans"
    return "sans"


def font_match(mask, text, limit=260):
    """The font on this PC that draws `text` most like `mask` (binary ink, cropped): each font draws the words, both pictures are
    squeezed to the same box and compared pixel by pixel. -> [(score 0-1, family, style, local)] best first."""
    import numpy as np
    from PIL import Image, ImageDraw, ImageFont
    import cv2
    ys, xs = np.nonzero(mask)
    if len(xs) < 30 or not text.strip():
        return []
    ref = mask[ys.min():ys.max() + 1, xs.min():xs.max() + 1].astype(np.uint8)
    BW, BH = 240, max(16, min(120, int(round(240 * ref.shape[0] / max(1, ref.shape[1])))))
    ref_s = cv2.resize(ref * 255, (BW, BH), interpolation=cv2.INTER_AREA) > 96
    ar_ref = ref.shape[1] / max(1, ref.shape[0])
    line = text.split("\n")[0]
    res = []
    for fnt in font_scan()[:limit]:
        try:
            F = ImageFont.truetype(fnt["path"], 64)
            x0, y0, x1, y1 = F.getbbox(line)
            if x1 - x0 < 8 or y1 - y0 < 8:
                continue
            im = Image.new("L", (x1 - x0 + 8, y1 - y0 + 8), 0)
            ImageDraw.Draw(im).text((4 - x0, 4 - y0), line, font=F, fill=255)
            a = np.array(im) > 96
            ys2, xs2 = np.nonzero(a)
            if len(xs2) < 20:
                continue
            a = a[ys2.min():ys2.max() + 1, xs2.min():xs2.max() + 1]
            ar = a.shape[1] / max(1, a.shape[0])
            cand = cv2.resize(a.astype(np.uint8) * 255, (BW, BH), interpolation=cv2.INTER_AREA) > 96
            iou = float((cand & ref_s).sum()) / max(1.0, float((cand | ref_s).sum()))
            shape = min(ar, ar_ref) / max(ar, ar_ref)          # how much it had to be squeezed to fit (a wide font is not a narrow one)
            res.append((round(iou * (0.55 + 0.45 * shape), 4), fnt["family"], fnt["style"], fnt["local"]))
        except Exception:
            continue
    res.sort(reverse=True)
    best, seen = [], set()
    for r in res:
        if r[1] not in seen:
            seen.add(r[1])
            best.append(r)
    return best[:6]


@app.get("/api/fonts")
def api_fonts():
    """The fonts in the fonts/ folder (the page loads each one), plus the names of the looks Kiru can fetch."""
    os.makedirs(FONT_DIR, exist_ok=True)
    out = []
    for fn in sorted(os.listdir(FONT_DIR)):
        if fn.lower().endswith(FONT_OK_EXT):
            fam = re.sub(r"[-_ ](Regular|Bold|Italic|var|\d{3})$", "", os.path.splitext(fn)[0]).replace("_", " ")
            out.append({"family": fam, "file": fn, "url": "/fonts/" + fn, "weight": "100 900" if "-var." in fn else "700" if re.search(r"(Bold|700|800|900)", fn) else "400"})
    return jsonify(fonts=out, families=FONT_FAMILIES, folder=FONT_DIR)


@app.get("/fonts/<path:fn>")
def api_font_file(fn):
    p = os.path.join(FONT_DIR, os.path.basename(fn))
    if not os.path.isfile(p) or not p.lower().endswith(FONT_OK_EXT):
        return err("Not found.", 404)
    return send_file(p, max_age=3600)


def font_css_urls(css):
    """Google Fonts CSS -> [(weight, url)] of the latin faces (the last @font-face of each weight is the latin subset)."""
    out = {}
    for blk in re.findall(r"@font-face\s*{[^}]*}", css or ""):
        w = re.search(r"font-weight:\s*(\d+)", blk)
        u = re.search(r"url\((https://[^)]+)\)", blk)
        if u:
            out[int(w.group(1)) if w else 400] = u.group(1)
    return sorted(out.items())


@app.post("/api/fonts/install")
def api_font_install():
    """The one place Kiru goes on the internet for you: fetch a FREE Google Font (regular + bold) into fonts/.
    Only when you click Download. Nothing about your project is sent - just the font's name in the address."""
    import urllib.request
    import urllib.parse
    fam = re.sub(r"[^A-Za-z0-9 ]", "", str((request.get_json(force=True) or {}).get("family") or ""))[:48].strip()
    if not fam:
        return err("Which font?")
    os.makedirs(FONT_DIR, exist_ok=True)
    got = []
    try:
        for spec in (f"{fam}:wght@400;700", fam):
            url = "https://fonts.googleapis.com/css2?family=" + urllib.parse.quote(spec).replace("%3A", ":").replace("%40", "@").replace("%3B", ";") + "&display=swap"
            try:
                req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 (Windows NT 6.1) Kiru"})     # (an old browser gets .ttf files)
                css = urllib.request.urlopen(req, timeout=20).read().decode("utf-8", "replace")
            except Exception as e:
                last = e
                continue
            for w, u in font_css_urls(css):
                ext = os.path.splitext(urllib.parse.urlparse(u).path)[1].lower() or ".ttf"
                if ext not in FONT_OK_EXT:
                    continue
                fn = f"{fam.replace(' ', '_')}-{w}{ext}"
                data = urllib.request.urlopen(urllib.request.Request(u, headers={"User-Agent": "Mozilla/5.0 Kiru"}), timeout=30).read()
                if len(data) > 2000:
                    with open(os.path.join(FONT_DIR, fn), "wb") as fh:
                        fh.write(data)
                    got.append(fn)
            if got:
                break
        if not got:                                      # second door: the same free fonts, from the Google Fonts project's files
            import json as _json
            slug = fam.replace(" ", "").lower()
            for lic in ("ofl", "apache", "ufl"):
                try:
                    lst = _json.loads(urllib.request.urlopen(urllib.request.Request(f"https://api.github.com/repos/google/fonts/contents/{lic}/{slug}", headers={"User-Agent": "Kiru"}), timeout=20).read().decode("utf-8"))
                except Exception as e:                    # (the list could not be read: try the usual file names)
                    last = e
                    camel = fam.replace(" ", "")
                    base = f"https://raw.githubusercontent.com/google/fonts/main/{lic}/{slug}/"
                    lst = [{"name": n_, "download_url": base + urllib.parse.quote(n_)} for n_ in (camel + "-Regular.ttf", camel + "-Bold.ttf", camel + "[wght].ttf")]
                ttf = [x for x in lst if isinstance(x, dict) and str(x.get("name", "")).lower().endswith((".ttf", ".otf")) and "italic" not in str(x.get("name", "")).lower()]
                pick = [x for x in ttf if re.search(r"-(Regular|Bold)\.", x["name"])] or ttf[:1]
                if len(lst) == 3 and "[wght]" in lst[2]["name"]:
                    pick = ttf
                for x in pick[:3]:
                    try:
                        data = urllib.request.urlopen(urllib.request.Request(x["download_url"], headers={"User-Agent": "Kiru"}), timeout=40).read()
                    except Exception as e:
                        last = e
                        continue
                    if "[wght]" in x["name"] and got:
                        continue                              # (already have the fixed weights)
                    if len(data) > 2000:
                        fn = f"{fam.replace(' ', '_')}-{'var' if '[wght]' in x['name'] else '700' if '-Bold.' in x['name'] else '400'}{os.path.splitext(x['name'])[1].lower()}"
                        with open(os.path.join(FONT_DIR, fn), "wb") as fh:
                            fh.write(data)
                        got.append(fn)
                if got:
                    break
        if not got:
            raise RuntimeError(f"Google Fonts could not be reached, or it has no free font called \"{fam}\" ({locals().get('last', 'no answer')})")
    except Exception as e:
        return err(f"Could not download {fam}: {e}. Check the internet connection, or put a .ttf / .otf into the fonts folder yourself.", 502)
    _FONTS["scan"] = None
    return jsonify(ok=True, family=fam, files=got, fonts=[{"family": fam, "file": fn, "url": "/fonts/" + fn, "weight": "100 900" if "-var." in fn else "700" if "-700" in fn else "400"} for fn in got])


@app.post("/api/img/separate")
def api_img_separate():
    """The Separate Layer brush: a rough line drawn INSIDE a shape (a paper scrap, a letter tile, a sticker) -> that shape as its own
    cut-out. The line's colours grow out to everything alike that touches it; GrabCut then snaps the edge. Runs on this PC."""
    f = request.files.get("file")
    if not f:
        return err("No image.")
    try:
        import cv2
        import numpy as np
        from PIL import Image
        pts = json.loads(request.form.get("pts") or "[]")
        rad = float(request.form.get("r") or 6)
        pil = Image.open(f.stream).convert("RGBA")
    except Exception:
        return err("Could not read that picture.")
    if len(pts) < 1:
        return err("Draw a line inside the shape.")
    rgba = np.array(pil)
    H, W = rgba.shape[:2]
    k = min(1.0, 900.0 / max(H, W))
    sw, sh = max(8, round(W * k)), max(8, round(H * k))
    small = cv2.resize(cv2.cvtColor(rgba[:, :, :3], cv2.COLOR_RGB2BGR), (sw, sh), interpolation=cv2.INTER_AREA)
    S = np.zeros((sh, sw), np.uint8)
    pp = np.array([[float(x) * k, float(y) * k] for x, y in pts], np.float32).round().astype(np.int32)
    r = max(2, int(round(rad * k)))
    if len(pp) == 1:
        cv2.circle(S, tuple(int(v) for v in pp[0]), r, 255, -1)
    else:
        cv2.polylines(S, [pp], False, 255, 2 * r + 1)
    if not S.any():
        return err("The line is outside the picture.")
    lab = cv2.cvtColor(cv2.bilateralFilter(small, 7, 40, 7), cv2.COLOR_BGR2LAB).astype(np.float32)
    seeds = lab[S > 0]
    kk = int(min(4, max(1, len(seeds) // 40)))
    if kk > 1:
        _, _lb, cen = cv2.kmeans(seeds, kk, None, (cv2.TERM_CRITERIA_EPS + cv2.TERM_CRITERIA_MAX_ITER, 10, 1.0), 2, cv2.KMEANS_PP_CENTERS)
    else:
        cen = seeds.mean(axis=0, keepdims=True)
    spread = float(np.mean(np.min(np.linalg.norm(seeds[:, None, :] - cen[None], axis=2), axis=1)))
    dist = np.min(np.linalg.norm(lab[:, :, None, :] - cen[None, None], axis=3), axis=2)
    edges = cv2.dilate(cv2.Canny(cv2.cvtColor(small, cv2.COLOR_BGR2GRAY), 50, 130), np.ones((2, 2), np.uint8)) > 0      # a clear edge is a wall the shape does not cross
    tol = min(24.0, 10 + 1.4 * spread)
    for _try in range(5):                                # a piece of a collage is a part of the picture: if it swallows a third of it, be stricter
        cand = ((dist < tol) & ~edges).astype(np.uint8)
        cand = cv2.morphologyEx(cand, cv2.MORPH_OPEN, np.ones((3, 3), np.uint8))
        cand[S > 0] = 1
        nl, lb = cv2.connectedComponents(cand, connectivity=4)
        grow = np.isin(lb, np.unique(lb[S > 0])) & (cand > 0)
        if grow.mean() <= 0.3:
            break
        tol *= 0.72
    grow = cv2.morphologyEx(grow.astype(np.uint8), cv2.MORPH_CLOSE, np.ones((5, 5), np.uint8)) > 0
    ys, xs = np.nonzero(grow)
    mx, my = int((xs.max() - xs.min()) * 0.15 + 10), int((ys.max() - ys.min()) * 0.15 + 10)
    X0, X1, Y0, Y1 = max(0, xs.min() - mx), min(sw, xs.max() + mx), max(0, ys.min() - my), min(sh, ys.max() + my)
    mask = np.full((sh, sw), cv2.GC_BGD, np.uint8)
    mask[Y0:Y1, X0:X1] = cv2.GC_PR_BGD
    mask[grow] = cv2.GC_PR_FGD
    mask[S > 0] = cv2.GC_FGD
    fg = grow
    try:
        if 0.002 < grow.mean() < 0.9:
            bgd, fgd = np.zeros((1, 65), np.float64), np.zeros((1, 65), np.float64)
            cv2.grabCut(small, mask, None, bgd, fgd, 4, cv2.GC_INIT_WITH_MASK)
            g2 = ((mask == cv2.GC_FGD) | (mask == cv2.GC_PR_FGD)).astype(np.uint8)
            nl2, lb2 = cv2.connectedComponents(g2, connectivity=8)
            g2 = np.isin(lb2, np.unique(lb2[S > 0])) & (g2 > 0)
            if grow.sum() * 0.4 < g2.sum() < grow.sum() * 2.5:          # (GrabCut may tidy the edge, not change what the shape is)
                fg = g2
    except Exception:
        pass
    fg = cv2.morphologyEx(fg.astype(np.uint8), cv2.MORPH_CLOSE, np.ones((5, 5), np.uint8))
    cnts, _h = cv2.findContours(fg, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)       # holes inside (print on the paper, letters on a tile) belong to the shape
    full = np.zeros((sh, sw), np.uint8)
    cv2.drawContours(full, cnts, -1, 255, -1)
    if full.sum() > 2.2 * 255 * max(1, int(fg.sum())):   # (unless "the holes" are most of it: then it is a ring round other things, keep it as found)
        full = fg * 255
    a = cv2.GaussianBlur(cv2.resize(full, (W, H), interpolation=cv2.INTER_LINEAR), (0, 0), max(0.8, 0.6 / k))
    a = np.clip((a.astype(np.float32) - 96) * (255 / 64), 0, 255).astype(np.uint8)
    a = np.minimum(a, rgba[:, :, 3])
    ys, xs = np.nonzero(a > 8)
    if len(xs) < 30:
        return err("No shape was found under that line. Draw a longer line well inside it.")
    x0, x1, y0, y1 = int(xs.min()), int(xs.max()) + 1, int(ys.min()), int(ys.max()) + 1
    cut = np.dstack([cv2.cvtColor(rgba[:, :, :3], cv2.COLOR_RGB2BGR), a])[y0:y1, x0:x1]
    return jsonify(png=_png_url(cut), x=x0, y=y0, w=x1 - x0, h=y1 - y0, share=round(float((a > 128).mean()), 4))


@app.post("/api/img/rematch")
def api_img_rematch():
    """Compare one line of a poster (its ink picture) with every font Kiru can draw with - again, after new fonts arrived."""
    import base64
    import cv2
    import numpy as np
    j = request.get_json(force=True) or {}
    try:
        raw = base64.b64decode(str(j.get("ink", "")).split(",", 1)[1])
        ink = cv2.imdecode(np.frombuffer(raw, np.uint8), cv2.IMREAD_GRAYSCALE) > 127
    except Exception:
        return err("Bad picture.")
    m = font_match(ink, str(j.get("text") or "")[:80])
    return jsonify(match=[{"score": m_[0], "family": m_[1], "style": m_[2], "local": m_[3]} for m_ in m])


@app.post("/api/img/inpaint")
def api_img_inpaint():
    """Paint something out of a picture (a logo, a word, a watermark): the masked area is filled in from what surrounds it."""
    f, m = request.files.get("file"), request.files.get("mask")
    if not f or not m:
        return err("No image.")
    try:
        import cv2
        import numpy as np
        from PIL import Image
        pil = Image.open(f.stream).convert("RGBA")
        mk = np.array(Image.open(m.stream).convert("RGBA").resize(pil.size))[:, :, 3]
    except Exception:
        return err("Could not read that picture.")
    rgba = np.array(pil)
    img = cv2.cvtColor(rgba[:, :, :3], cv2.COLOR_RGB2BGR)
    hole = cv2.dilate((mk > 40).astype(np.uint8) * 255, np.ones((7, 7), np.uint8))
    if not hole.any():
        return err("Nothing is selected.")
    H, W = hole.shape
    sc_ = min(1.0, 1400 / max(W, H))
    sm = cv2.resize(img, None, fx=sc_, fy=sc_, interpolation=cv2.INTER_AREA)
    hm = cv2.resize(hole, (sm.shape[1], sm.shape[0]), interpolation=cv2.INTER_NEAREST)
    fill = cv2.resize(cv2.inpaint(sm, (hm > 0).astype(np.uint8), 6, cv2.INPAINT_TELEA), (W, H), interpolation=cv2.INTER_CUBIC)
    soft = cv2.GaussianBlur(hole, (0, 0), 2.0).astype(np.float32)[..., None] / 255
    out = (img * (1 - soft) + fill * soft).astype(np.uint8)
    return jsonify(png=_png_url(np.dstack([out, rgba[:, :, 3]])))


FONT_PACK = ["Bebas Neue", "Anton", "Oswald", "Roboto Condensed", "Montserrat", "Poppins", "Archivo Black", "Playfair Display",
             "Abril Fatface", "DM Serif Display", "Roboto Slab", "Space Mono", "Pacifico", "Permanent Marker"]


@app.post("/api/fonts/pack")
def api_font_pack():
    """One click: a starter set of free Google Fonts covering every look (condensed, heavy sans, didone serif, slab, mono, script,
    marker), so the font matcher has something close to offer for most posters. Skips the ones already in fonts/."""
    have = {f["family"].lower() for f in font_scan()}
    got, failed, fonts = [], [], []
    for fam in FONT_PACK:
        if fam.lower() in have:
            continue
        with app.test_request_context(json={"family": fam}):
            r = api_font_install()
        resp = r[0] if isinstance(r, tuple) else r
        code = r[1] if isinstance(r, tuple) else 200
        if code == 200:
            got.append(fam)
            fonts += resp.get_json().get("fonts", [])
        else:
            failed.append(fam)
    if not got and failed:
        return err("The font pack could not be downloaded. Check the internet connection.", 502)
    return jsonify(ok=True, installed=got, failed=failed, fonts=fonts)


def _png_url(arr_bgra):
    import cv2
    import base64
    ok, buf = cv2.imencode(".png", arr_bgra)
    return "data:image/png;base64," + base64.b64encode(buf.tobytes()).decode("ascii")


_POCR = {"eng": None, "failed": False}


def _poster_ocr(img_bgr):
    """Text finder for posters: RapidOCR (the PaddleOCR detector + reader, run by onnxruntime - small, offline, good at big display
    type, slanted lines and text on pictures). -> [{quad: 4 corner points clockwise from top-left, text, conf 0-100}] or None."""
    if _POCR["failed"]:
        return None
    try:
        if _POCR["eng"] is None:
            from rapidocr_onnxruntime import RapidOCR
            _POCR["eng"] = RapidOCR()
        res, _ = _POCR["eng"](img_bgr)
    except Exception:
        _POCR["failed"] = True
        return None
    out = []
    for box, txt, cf in res or []:
        txt = (txt or "").strip()
        if txt:
            out.append({"quad": [[float(a), float(b)] for a, b in box], "text": txt, "conf": float(cf) * 100})
    return out


def _poster_spaces(text, ink):
    """The reader drops the gaps between words ("LOADINGNOW"): put them back where the letters stand clearly apart."""
    import numpy as np
    if " " in text or len(text) < 4:
        return text
    cols = ink.any(axis=0)
    xs = np.nonzero(cols)[0]
    if len(xs) < 4:
        return text
    x0, x1 = xs[0], xs[-1]
    gaps, start = [], None
    for x in range(x0, x1 + 1):
        if not cols[x] and start is None:
            start = x
        elif cols[x] and start is not None:
            gaps.append((start, x - start))
            start = None
    if len(gaps) < 2:
        return text
    med = float(np.median([g[1] for g in gaps]))
    big = [g for g in gaps if g[1] > max(2.4 * med, 0.22 * ink.shape[0])]
    if not big or len(big) > len(text) // 2:
        return text
    runs_before = lambda gx: int(np.sum(cols[x0 + 1:gx + 1] & ~cols[x0:gx])) + 1          # letters standing left of the gap
    total_runs = runs_before(x1)
    if total_runs == len(text):                           # one run of ink per letter: the gap is after exactly that many letters
        cut = sorted({runs_before(g[0]) for g in big})
    else:
        cut = sorted({int(round((g[0] + g[1] / 2 - x0) / max(1, x1 - x0) * len(text))) for g in big})
    out, last = [], 0
    for c_ in cut:
        if 0 < c_ < len(text) and c_ > last:
            out.append(text[last:c_])
            last = c_
    out.append(text[last:])
    return " ".join(out)


def _poster_look(img, mask):
    """How the subject of a poster was treated, measured on its own pixels: a small colour palette (duotone / screen-print),
    film grain, a dither / halftone stipple, how colourful it is. The page applies the same recipe to the picture you drop in."""
    import cv2
    import numpy as np
    m = mask > 128
    if m.sum() < 2000:
        return None
    px = img[m].astype(np.float32)
    lab = cv2.cvtColor(img, cv2.COLOR_BGR2LAB)[m].astype(np.float32)
    if len(px) > 60000:
        sel = np.random.RandomState(1).choice(len(px), 60000, replace=False)
        px, lab = px[sel], lab[sel]
    K = 6
    _, lbl, cen = cv2.kmeans(lab, K, None, (cv2.TERM_CRITERIA_EPS + cv2.TERM_CRITERIA_MAX_ITER, 12, 1.0), 2, cv2.KMEANS_PP_CENTERS)
    lbl = lbl.ravel()
    resid = float(np.mean(np.linalg.norm(lab - cen[lbl], axis=1)))          # how far pixels sit from their palette colour (small = flat print colours)
    share = np.bincount(lbl, minlength=K) / len(lbl)
    order = np.argsort(cen[:, 0])
    pal = []
    for k_ in order:
        if share[k_] < 0.03:
            continue
        c_ = np.median(px[lbl == k_], axis=0)
        pal.append({"color": "#%02x%02x%02x" % (int(c_[2]), int(c_[1]), int(c_[0])), "l": round(float(cen[k_, 0]) / 255, 3), "share": round(float(share[k_]), 3)})
    hsv = cv2.cvtColor(img, cv2.COLOR_BGR2HSV)[m]
    satd = hsv[hsv[:, 1] > 60]
    hue_spread = 0.0
    if len(satd) > 500:
        ang = satd[:, 0].astype(np.float32) * (np.pi / 90)
        hue_spread = float(1 - np.hypot(np.cos(ang).mean(), np.sin(ang).mean()))   # 0 = one hue, 1 = every hue
    gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY).astype(np.float32)
    hp = gray - cv2.GaussianBlur(gray, (0, 0), 1.2)
    edge = cv2.dilate((cv2.Canny(gray.astype(np.uint8), 60, 140) > 0).astype(np.uint8), np.ones((5, 5), np.uint8)) > 0
    calm = m & ~edge
    grain = float(np.std(hp[calm])) if calm.sum() > 800 else 0.0
    dots = float(edge[m].mean())
    g8 = gray.astype(np.uint8)
    speck = float((np.abs(gray - cv2.medianBlur(g8, 3).astype(np.float32))[m] > 18).mean())     # single pixels that jump out of their neighbourhood: stipple, dither, heavy noise
    grain = max(grain, 1.6 + speck * 40)
    limited = resid < 9.5 or hue_spread < 0.16 or speck > 0.15
    return {"palette": pal if limited else None, "limited": bool(limited), "resid": round(resid, 2), "hue_spread": round(hue_spread, 3),
            "grain": round(min(1.0, max(0.0, (grain - 1.6) / 9.0)), 3), "dither": bool(speck > 0.15), "speck": round(speck, 3), "dots": round(dots, 3),
            "sat": round(float(hsv[:, 1].mean()) / 255, 3), "luma": round(float(gray[m].mean()) / 255, 3)}


@app.post("/api/img/template")
def api_img_template():
    """A poster / thumbnail / graphic -> a layer stack to rebuild it: Background (the words and the subject painted out),
    flat Shapes, a Subject spot (cut out by the AI when it is installed), and one Text layer per line with its colour, size
    and the font on this PC that draws it most alike (plus free fonts of the same look to download)."""
    f = request.files.get("file")
    if not f:
        return err("No image.")
    try:
        import cv2
        import numpy as np
        from PIL import Image
    except ImportError:
        return err("OpenCV / Pillow are not installed. Close Kiru and run Start_Tool.bat again.", 500)
    try:
        pil = Image.open(f.stream).convert("RGB")
    except Exception:
        return err("Could not read that picture.")
    if max(pil.size) > 2600:
        k = 2600 / max(pil.size)
        pil = pil.resize((int(pil.size[0] * k), int(pil.size[1] * k)), Image.LANCZOS)
    W, H = pil.size
    img = cv2.cvtColor(np.array(pil), cv2.COLOR_RGB2BGR)
    gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
    notes = []
    text_only = request.form.get("mode") == "text"       # "Edit text in a picture": only the words become layers, the rest stays one picture
    # ---- manual labels: what you painted in the Labeling Interface. Text = read words only there; Logo = keep that exact area as a
    #      picture of its own; Subject = cut that exact area out and leave a "drop image here" spot. Everything else stays untouched.
    lab_m = {}
    for key_ in ("text", "logo", "subject"):
        fm = request.files.get("m_" + key_)
        if fm:
            try:
                mm_ = np.array(Image.open(fm.stream).convert("RGBA").resize((W, H), Image.BILINEAR))[..., 3]
                if int((mm_ > 40).sum()) > 30:
                    lab_m[key_] = (mm_ > 40).astype(np.uint8) * 255
            except Exception:
                pass
    manual = request.form.get("manual") == "1"
    logos = []
    # ---- 0. shapes: big flat rectangles (banners, boxes, bars) - found first: words often sit on them
    shapes = []
    q = (img // 24).astype(np.int32)
    code = q[..., 0] * 400 + q[..., 1] * 20 + q[..., 2]
    small = cv2.resize(code.astype(np.float32), (W // 4, H // 4), interpolation=cv2.INTER_NEAREST).astype(np.int32)
    vals, counts = np.unique(small, return_counts=True)
    for v in vals[np.argsort(-counts)][:10]:
        mm = (small == v).astype(np.uint8)
        mm = cv2.morphologyEx(mm, cv2.MORPH_CLOSE, np.ones((5, 5), np.uint8))
        nlab, lab, st, _ = cv2.connectedComponentsWithStats(mm, 8)
        for j in range(1, nlab):
            x0, y0, bw, bh, area = st[j]
            if area < small.size * 0.006 or area > small.size * 0.45 or bw < 10 or bh < 5:
                continue
            if area / float(bw * bh) < 0.86 or (x0 <= 1 and y0 <= 1 and x0 + bw >= small.shape[1] - 1) or bw * bh > small.size * 0.6:
                continue
            X0, Y0, BW, BH = x0 * 4, y0 * 4, bw * 4, bh * 4
            ring_ = img[max(0, Y0 - 12):Y0 + BH + 12, max(0, X0 - 12):X0 + BW + 12]
            inner = img[Y0:Y0 + BH, X0:X0 + BW]
            col = np.median(inner.reshape(-1, 3), axis=0)
            if np.abs(np.median(ring_.reshape(-1, 3), axis=0) - col).sum() < 12 and area > small.size * 0.2:
                continue                                  # (that is the background itself)
            if X0 <= 4 or Y0 <= 4 or X0 + BW >= W - 4 or Y0 + BH >= H - 4:
                continue                                  # runs off the picture: a band of the background, not a box
            shapes.append({"x": int(X0 + BW / 2), "y": int(Y0 + BH / 2), "w": int(BW), "h": int(BH), "color": "#%02x%02x%02x" % (int(col[2]), int(col[1]), int(col[0]))})
    shapes = [] if text_only else sorted(shapes, key=lambda s_: -s_["w"] * s_["h"])[:6]
    # ---- 1. text: RapidOCR finds and reads the lines (any size, slanted too); Tesseract is the fallback
    lines, kept_bg = [], 0
    ocr_src = img
    if manual:                                           # read only inside the Text marks (everything else is painted flat for the reader)
        tm_ = lab_m.get("text")
        if tm_ is None:
            ocr_src = None
        else:
            tm_ = cv2.dilate(tm_, np.ones((9, 9), np.uint8))
            if "logo" in lab_m:
                tm_[lab_m["logo"] > 0] = 0
            ocr_src = img.copy()
            flat = cv2.blur(img, (31, 31))
            ocr_src[tm_ == 0] = flat[tm_ == 0]
    found_ = _poster_ocr(ocr_src) if ocr_src is not None else []
    if manual and found_ is None:
        found_ = []
    if manual:
        tm0 = lab_m.get("text")
        for e_ in found_:
            q_ = np.array(e_["quad"], np.float32)
            cx_, cy_ = int(np.clip(q_[:, 0].mean(), 0, W - 1)), int(np.clip(q_[:, 1].mean(), 0, H - 1))
            if tm0 is not None and tm_[cy_, cx_] and len(re.sub(r"\s", "", e_["text"])) >= 1 and e_["conf"] >= 25:
                lines.append({"quad": e_["quad"], "text": e_["text"], "conf": e_["conf"]})
        if tm0 is not None:                              # a Text mark where nothing could be read still becomes a text layer: "Edit this text"
            got = np.zeros((H, W), np.uint8)
            for ln_ in lines:
                cv2.fillPoly(got, [np.array(ln_["quad"], np.int32)], 255)
            nl_, lb_, st_, _c = cv2.connectedComponentsWithStats((tm0 > 0).astype(np.uint8), 8)
            for j_ in range(1, nl_):
                x0, y0, bw, bh, ar_ = st_[j_]
                if ar_ < 150 or bw < 12 or bh < 8 or int((got[lb_ == j_] > 0).sum()) > 0.15 * ar_:
                    continue
                lines.append({"quad": [[int(x0), int(y0)], [int(x0 + bw), int(y0)], [int(x0 + bw), int(y0 + bh)], [int(x0), int(y0 + bh)]], "text": "Edit this text", "conf": 0, "blank": True})
    elif found_ is not None:
        for e_ in found_:
            q_ = np.array(e_["quad"], np.float32)
            wq, hq = float(np.linalg.norm(q_[1] - q_[0])), float(np.linalg.norm(q_[3] - q_[0]))
            ascii_ = sum(1 for ch_ in e_["text"] if ch_.isascii()) / max(1, len(e_["text"]))
            okc = len(re.sub(r"[^A-Za-z0-9]", "", e_["text"]))
            if e_["conf"] < (72 if okc < 5 else 62) or ascii_ < 0.8 or okc < 2 or hq < 7 or (hq > 1.6 * wq and okc >= 3):
                kept_bg += 1                              # other scripts, upright columns, unsure readings: stay in the picture
                continue
            lines.append({"quad": e_["quad"], "text": e_["text"], "conf": e_["conf"]})
    else:
        pass
    region_ = None
    try:
        region_ = [float(v) for v in (request.form.get("region") or "").split(",")] if request.form.get("region") else None
    except ValueError:
        region_ = None
    if region_ and len(region_) == 4 and found_ is not None:        # "this is text": only what lies in the marked area, and all of it (no second-guessing)
        lines, kept_bg = [], 0
        for e_ in found_:
            cx_, cy_ = sum(p_[0] for p_ in e_["quad"]) / 4, sum(p_[1] for p_ in e_["quad"]) / 4
            if region_[0] <= cx_ <= region_[2] and region_[1] <= cy_ <= region_[3] and len(re.sub(r"[^A-Za-z0-9]", "", e_["text"])) >= 1:
                lines.append({"quad": e_["quad"], "text": e_["text"], "conf": e_["conf"]})
    if found_ is None:
        try:
            import pytesseract
            _tess_setup(pytesseract)
            pytesseract.get_tesseract_version()
            found = {}
            for pol, src in enumerate((gray, 255 - gray)):
                for psm in (11, 3):
                    try:
                        d = pytesseract.image_to_data(src, config=f"--psm {psm} --oem 1", output_type=pytesseract.Output.DICT, timeout=40)
                    except Exception:
                        continue
                    for j, tx in enumerate(d["text"]):
                        tx = (tx or "").strip()
                        try:
                            cf = float(d["conf"][j])
                        except (TypeError, ValueError):
                            cf = -1
                        if cf < 55 or len(re.sub(r"[^A-Za-z0-9]", "", tx)) < 2 or d["height"][j] < H * 0.012:
                            continue
                        key = (pol, psm, d["block_num"][j], d["par_num"][j], d["line_num"][j])
                        L = found.setdefault(key, {"words": [], "x0": 1e9, "y0": 1e9, "x1": 0, "y1": 0, "conf": []})
                        L["words"].append(tx)
                        L["conf"].append(cf)
                        L["x0"], L["y0"] = min(L["x0"], d["left"][j]), min(L["y0"], d["top"][j])
                        L["x1"], L["y1"] = max(L["x1"], d["left"][j] + d["width"][j]), max(L["y1"], d["top"][j] + d["height"][j])
            cand = sorted(found.values(), key=lambda L: -(np.mean(L["conf"]) * len(" ".join(L["words"]))))
            for L in cand:                                   # keep the best reading of each place
                bx = (L["x0"], L["y0"], L["x1"], L["y1"])
                if (bx[2] - bx[0]) < 8 or (bx[3] - bx[1]) < 6:
                    continue
                def ov(a, b):
                    ix = max(0, min(a[2], b[2]) - max(a[0], b[0])) * max(0, min(a[3], b[3]) - max(a[1], b[1]))
                    return ix / max(1.0, min((a[2] - a[0]) * (a[3] - a[1]), (b[2] - b[0]) * (b[3] - b[1])))
                if any(ov(bx, k_["box"]) > 0.4 for k_ in lines):
                    continue
                lines.append({"box": bx, "text": " ".join(L["words"]), "conf": float(np.mean(L["conf"]))})
            lines = [L for L in lines if L["conf"] >= (72 if len(re.sub(r"[^A-Za-z0-9]", "", L["text"])) < 4 else 55)]
            for sh_ in shapes:                               # a banner nobody read yet: read what is written on it
                bx = (sh_["x"] - sh_["w"] / 2, sh_["y"] - sh_["h"] / 2, sh_["x"] + sh_["w"] / 2, sh_["y"] + sh_["h"] / 2)
                if any(bx[0] <= (k_["box"][0] + k_["box"][2]) / 2 <= bx[2] and bx[1] <= (k_["box"][1] + k_["box"][3]) / 2 <= bx[3] for k_ in lines):
                    continue
                txt, cf = _tpl_read_crop(img, sh_["x"] / W, sh_["y"] / H, sh_["w"] * 0.9 / W, sh_["h"] * 0.55 / H)
                if txt and cf >= 60 and len(re.sub(r"[^A-Za-z0-9]", "", txt)) >= 3:
                    in_ = 8
                    bx = (bx[0] + in_, bx[1] + in_, bx[2] - in_, bx[3] - in_)
                    crop = gray[int(bx[1]):int(bx[3]), int(bx[0]):int(bx[2])]
                    _, mk_ = cv2.threshold(crop, 0, 255, cv2.THRESH_BINARY + cv2.THRESH_OTSU)
                    ink_ = mk_ > 0
                    if ink_.mean() > 0.5:
                        ink_ = ~ink_
                    nl_, lb_ = cv2.connectedComponents(ink_.astype(np.uint8), connectivity=8)
                    edge_ = set(np.unique(lb_[0])) | set(np.unique(lb_[-1])) | set(np.unique(lb_[:, 0])) | set(np.unique(lb_[:, -1]))
                    ink_ &= ~np.isin(lb_, [e_ for e_ in edge_ if e_])
                    ys_, xs_ = np.nonzero(ink_)
                    if len(xs_) > 20:
                        lines.append({"box": (bx[0] + xs_.min(), bx[1] + ys_.min(), bx[0] + xs_.max() + 1, bx[1] + ys_.max() + 1), "text": txt.split("\n")[0], "conf": cf, "sure": True})
            for L in lines:
                if L.get("sure"):
                    continue
                x0, y0, x1, y1 = L["box"]
                txt, cf = _tpl_read_crop(img, (x0 + x1) / 2 / W, (y0 + y1) / 2 / H, (x1 - x0) / W, (y1 - y0) / H)
                if txt and cf >= L["conf"] - 6 and len(re.sub(r"[^A-Za-z0-9]", "", txt)) >= len(re.sub(r"[^A-Za-z0-9]", "", L["text"])) * 0.7:
                    L["text"], L["conf"] = txt.split("\n")[0], cf
        except Exception:
            notes.append("Tesseract OCR is not installed, so the words could not be read. (winget install UB-Mannheim.TesseractOCR)")
        for L in lines:
            x0, y0, x1, y1 = L["box"]
            L["quad"] = [[x0, y0], [x1, y0], [x1, y1], [x0, y1]]
    if kept_bg:
        notes.append(f"{kept_bg} piece{'s' if kept_bg != 1 else ''} of lettering (other scripts, upright columns, or too unclear to read) stayed in the Background layer.")
    # ---- 2. each line: straighten it, find the ink, its colour, outline and font
    texts, text_mask = [], np.zeros((H, W), np.uint8)
    for L in sorted(lines, key=lambda L: (min(p_[1] for p_ in L["quad"]), min(p_[0] for p_ in L["quad"]))):
        q_ = np.array(L["quad"], np.float32)
        wq, hq = int(max(np.linalg.norm(q_[1] - q_[0]), np.linalg.norm(q_[2] - q_[3]))), int(max(np.linalg.norm(q_[3] - q_[0]), np.linalg.norm(q_[2] - q_[1])))
        if wq < 6 or hq < 5:
            continue
        pad = max(6, int(hq * 0.45))                      # (room to see an outline, a shadow and the real background behind the line)
        dst = np.array([[pad, pad], [pad + wq, pad], [pad + wq, pad + hq], [pad, pad + hq]], np.float32)
        Mq = cv2.getPerspectiveTransform(q_, dst)
        patch = cv2.warpPerspective(img, Mq, (wq + 2 * pad, hq + 2 * pad), flags=cv2.INTER_LINEAR, borderMode=cv2.BORDER_REPLICATE)
        pg = cv2.cvtColor(patch, cv2.COLOR_BGR2GRAY)
        _, mk = cv2.threshold(pg, 0, 255, cv2.THRESH_BINARY + cv2.THRESH_OTSU)
        ink = mk > 0
        rim = np.concatenate([ink[:max(1, pad // 2)].ravel(), ink[-max(1, pad // 2):].ravel(), ink[:, :max(1, pad // 2)].ravel(), ink[:, -max(1, pad // 2):].ravel()])
        if rim.mean() > 0.5:                              # (what lies around the line is the page, not the ink)
            ink = ~ink
        nl_, lb_ = cv2.connectedComponents(ink.astype(np.uint8), connectivity=8)
        edge_ = set(np.unique(lb_[0])) | set(np.unique(lb_[-1])) | set(np.unique(lb_[:, 0])) | set(np.unique(lb_[:, -1]))
        clean_ = ink & ~np.isin(lb_, [e_ for e_ in edge_ if e_])       # (whatever touches the edge of the cut-out is not a letter)
        if clean_.sum() > max(20, ink.sum() * 0.4):
            ink = clean_
        mg_ = max(1, int(hq * 0.06))                       # only what lies inside the line's own box is its ink (not artwork that pokes into the margin)
        inner_ = np.zeros_like(ink)
        inner_[pad - mg_:pad + hq + mg_, pad - mg_:pad + wq + mg_] = True
        if (ink & inner_).sum() >= 20:
            ink = ink & inner_
        if ink.sum() < 20:
            continue
        ys_, xs_ = np.nonzero(ink)
        ix0, ix1, iy0, iy1 = xs_.min(), xs_.max() + 1, ys_.min(), ys_.max() + 1
        cen = cv2.perspectiveTransform(np.array([[[(ix0 + ix1) / 2, (iy0 + iy1) / 2]]], np.float32), np.linalg.inv(Mq))[0][0]
        ang = float(np.degrees(np.arctan2(q_[1][1] - q_[0][1], q_[1][0] - q_[0][0])))
        if abs(ang) < 1.2 or (abs(ang) < 14 and (hq < 22 or wq < 5 * hq)):
            ang = 0.0                                      # (the corners of a short or small line are too rough to trust a few degrees)
        col = np.median(patch[ink], axis=0)
        ring = cv2.dilate(ink.astype(np.uint8), np.ones((5, 5), np.uint8)).astype(bool) & ~cv2.dilate(ink.astype(np.uint8), np.ones((3, 3), np.uint8)).astype(bool)   # (2 px out: past the blended edge pixel)
        kf_ = 2 * max(4, int(hq * 0.32)) + 1
        far = ~cv2.dilate(ink.astype(np.uint8), np.ones((kf_, kf_), np.uint8)).astype(bool)
        outline = None
        if ring.sum() > 20 and far.sum() > 20:
            rc, fc_ = np.median(patch[ring], axis=0).astype(np.float32), np.median(patch[far], axis=0).astype(np.float32)
            rs_, fs_ = float(patch[ring].astype(np.float32).std(axis=0).mean()), float(patch[far].astype(np.float32).std(axis=0).mean())
            # an outline: one even colour hugging the letters that is not the letters' colour, and either differs from the page
            # or is far more even than the (busy) picture behind
            if np.abs(rc - col).sum() > 90 and (np.abs(rc - fc_).sum() > 90 or (rs_ < 30 and fs_ > 2.0 * rs_ + 14 and np.abs(rc - fc_).sum() > 30)):
                outline = "#%02x%02x%02x" % (int(rc[2]), int(rc[1]), int(rc[0]))
        inkd = ink.astype(np.uint8)
        ol_w = 0
        if outline:                                      # how thick: grow the letters a pixel at a time while the new band is still outline-coloured
            prev_ = cv2.dilate(inkd, np.ones((3, 3), np.uint8))
            ol_w = 1
            for k_ in range(2, max(3, pad)):
                cur_ = cv2.dilate(inkd, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (2 * k_ + 1, 2 * k_ + 1)))
                band_ = (cur_ > 0) & ~(prev_ > 0)
                prev_ = cur_
                if band_.sum() < 10 or float((np.abs(patch[band_].astype(np.float32) - rc).sum(axis=1) < 90).mean()) < 0.55:
                    break
                ol_w = k_
            if (ol_w < 2 and hq > 30) or ol_w > max(3, 0.3 * hq):
                ol_w = 0                                  # (as thick as the letters = the page itself)
            if False:
                ol_w = 0                                  # (a hair of edge colour on big type is not an outline)
            if ol_w == 0:
                outline = None
        shadow, glow = None, None
        R_ = max(3, min(pad - 1, int(hq * 0.3)))
        body_ = cv2.dilate(inkd, np.ones((2 * ol_w + 3, 2 * ol_w + 3), np.uint8)) > 0
        near_ = cv2.dilate(inkd, np.ones((2 * R_ + 1, 2 * R_ + 1), np.uint8)) > 0
        zone_ = near_ & ~body_
        if zone_.sum() > 30 and (~near_).sum() > 30:
            bgc_ = np.median(patch[~near_], axis=0).astype(np.float32)
            dif_ = np.abs(patch.astype(np.float32) - bgc_).sum(axis=2)
            S_ = zone_ & (dif_ > 55)
            if S_.sum() > 0.12 * ink.sum():
                sy_, sx_ = np.nonzero(S_)
                ddx, ddy = float(sx_.mean() - xs_.mean()) if False else 0.0, 0.0
                iy_, ix_ = np.nonzero(ink)
                ddx, ddy = float(sx_.mean() - ix_.mean()), float(sy_.mean() - iy_.mean())
                scol = np.median(patch[S_], axis=0)
                shex = "#%02x%02x%02x" % (int(scol[2]), int(scol[1]), int(scol[0]))
                cover = S_.sum() / max(1, zone_.sum())
                if np.hypot(ddx, ddy) < max(0.7, 0.03 * hq):
                    if cover > 0.55:                       # the same colour all round the letters, fading out: a glow
                        glow = {"size": int(R_ * 1.4), "color": shex}
                else:
                    ox_, oy_ = int(round(ddx * 2.2)) or (1 if ddx > 0.3 else -1 if ddx < -0.3 else 0), int(round(ddy * 2.2)) or (1 if ddy > 0.3 else -1 if ddy < -0.3 else 0)
                    shifted = np.roll(np.roll(body_, oy_, axis=0), ox_, axis=1) & zone_
                    if max(abs(ox_), abs(oy_)) <= R_ and shifted.sum() > 20 and (S_ & shifted).sum() / S_.sum() > 0.5 and (S_ & shifted).sum() / shifted.sum() > 0.45:
                        hard = float(np.percentile(dif_[S_], 30)) > 110
                        shadow = {"x": ox_, "y": oy_, "blur": 0 if hard else int(max(2, R_ * 0.7)), "color": shex, "op": 100 if hard else 75}
        txt = _poster_spaces(L["text"], ink)
        feats = font_features(ink)
        cat = font_category(feats, txt)
        match = font_match(ink, txt)
        dil_ = max(3, int(hq * 0.18)) + ol_w + (max(abs(shadow["x"]), abs(shadow["y"])) + shadow["blur"] if shadow else 0) + (glow["size"] if glow else 0)
        back = cv2.warpPerspective(cv2.dilate(ink.astype(np.uint8), np.ones((2 * dil_ + 1, 2 * dil_ + 1), np.uint8)) * 255, Mq, (W, H), flags=cv2.INTER_NEAREST | cv2.WARP_INVERSE_MAP)
        text_mask |= back
        texts.append({"text": txt, "x": round(float(cen[0])), "y": round(float(cen[1])), "w": int(ix1 - ix0), "h": int(iy1 - iy0), "rot": round(ang, 1),
                      "color": "#%02x%02x%02x" % (int(col[2]), int(col[1]), int(col[0])), "outline": outline, "ol_w": int(ol_w), "shadow": shadow, "glow": glow,
                      "crop": _png_url(cv2.cvtColor(patch if patch.shape[1] <= 420 else cv2.resize(patch, (420, max(8, int(patch.shape[0] * 420 / patch.shape[1]))), interpolation=cv2.INTER_AREA), cv2.COLOR_BGR2BGRA)),
                      "ink": _png_url(cv2.cvtColor(inkd[iy0:iy1, ix0:ix1] * 255, cv2.COLOR_GRAY2BGRA)),
                      "ink_std": round(float(patch[cv2.erode(inkd, np.ones((3, 3), np.uint8)) > 0].astype(np.float32).std(axis=0).mean()) if cv2.erode(inkd, np.ones((3, 3), np.uint8)).sum() > 30 else 0.0, 1),
                      "bold": bool(feats and feats["weight"] > 0.16),
                      "caps": re.sub(r"[^A-Za-z]", "", txt).isupper(), "spacing": round(float(feats["letter_w"]), 3) if feats else None,
                      "confidence": round(L["conf"] / 100, 2), "look": cat, "match": [{"score": m_[0], "family": m_[1], "style": m_[2], "local": m_[3]} for m_ in match],
                      "suggest": FONT_FAMILIES.get(cat, FONT_FAMILIES["sans"])})
    # a flat box that is really a line of heavy type (the reader found words filling it) is not a shape
    def _is_text_box(sh_):
        for t_ in texts:
            if abs(t_["x"] - sh_["x"]) < sh_["w"] / 2 and abs(t_["y"] - sh_["y"]) < sh_["h"] / 2 and t_["w"] > 0.6 * sh_["w"] and t_["h"] > 0.5 * sh_["h"]:
                return True
        return False
    shapes = [sh_ for sh_ in shapes if not _is_text_box(sh_)]
    # ---- 3. subject: the AI cut-out (when installed); else nothing
    subj = None
    try:
        import hashlib
        if manual:                                       # the Subject mark IS the cut-out (soft edge of 1-2 px), no guessing
            a = cv2.GaussianBlur(lab_m["subject"], (0, 0), 1.2) if "subject" in lab_m and not text_only else None
        else:
            a = None if text_only else _ai_subject_mask(pil, "tpl" + hashlib.md5(pil.tobytes()[:200000]).hexdigest())
    except Exception:
        a = None
    if manual:
        shapes = []                                      # (nothing is taken apart that you did not mark)
    if text_only:
        pass
    elif a is not None:
        m = (a > 110).astype(np.uint8)
        m[text_mask > 0] = 0
        for sh_ in shapes:                               # a banner lying over the person is not part of the person
            m[int(sh_["y"] - sh_["h"] / 2) - 2:int(sh_["y"] + sh_["h"] / 2) + 2, int(sh_["x"] - sh_["w"] / 2) - 2:int(sh_["x"] + sh_["w"] / 2) + 2] = 0
        nlab, lab, st, _ = cv2.connectedComponentsWithStats(m, 8)
        if nlab > 1:
            k = 1 + int(np.argmax(st[1:, cv2.CC_STAT_AREA]))
            if st[k, cv2.CC_STAT_AREA] > W * H * (0.001 if manual else 0.03):
                x0, y0, bw, bh = st[k, cv2.CC_STAT_LEFT], st[k, cv2.CC_STAT_TOP], st[k, cv2.CC_STAT_WIDTH], st[k, cv2.CC_STAT_HEIGHT]
                alpha = np.where(lab == k, a, 0).astype(np.uint8)
                cut = np.dstack([img, alpha])[y0:y0 + bh, x0:x0 + bw]
                subj = {"x": int(x0 + bw / 2), "y": int(y0 + bh / 2), "w": int(bw), "h": int(bh), "png": _png_url(cut)}
                look = _poster_look(img, np.where(lab == k, a, 0).astype(np.uint8))
                subj["look"] = look
                ringm = cv2.dilate((lab == k).astype(np.uint8), np.ones((25, 25), np.uint8)).astype(bool) & ~cv2.dilate((lab == k).astype(np.uint8), np.ones((7, 7), np.uint8)).astype(bool)
                around = img[ringm].astype(np.float32) if ringm.sum() > 200 else None

                medc = np.median(around, axis=0) if around is not None else None
                flat_bg = around is not None and float((np.abs(around - medc).sum(axis=1) < 40).mean()) > 0.7
                # a dark, flat-coloured figure on a plain light page with a picture inside it = a silhouette used as a window ("fill the shape")
                subj["mode"] = "clip" if (look and look["limited"] and look["luma"] < 0.36 and flat_bg and float(medc.mean()) > 190) else "cut"
                subj_mask = cv2.dilate((lab == k).astype(np.uint8) * 255, np.ones((15, 15), np.uint8))
    else:
        notes.append("The AI cut-out is not installed, so no subject was separated: the whole picture stays in the Background layer.")
    # ---- 4b. Logo marks: each one becomes a picture layer of its own, cut exactly as marked
    if "logo" in lab_m:
        lm_ = lab_m["logo"]
        nl_, lb_, st_, _c = cv2.connectedComponentsWithStats((lm_ > 0).astype(np.uint8), 8)
        for j_ in range(1, nl_):
            x0, y0, bw, bh, ar_ = st_[j_]
            if ar_ < 80:
                continue
            al_ = cv2.GaussianBlur(((lb_ == j_).astype(np.uint8) * 255), (0, 0), 0.8)
            logos.append({"x": int(x0 + bw / 2), "y": int(y0 + bh / 2), "w": int(bw), "h": int(bh), "png": _png_url(np.dstack([img, al_])[y0:y0 + bh, x0:x0 + bw])})
    # ---- 5. background: paint the words and the subject out
    hole = text_mask.copy()
    if logos:
        hole |= cv2.dilate(lab_m["logo"], np.ones((7, 7), np.uint8))
    if subj:
        hole |= subj_mask
    for sh_ in shapes:                                   # the shapes become their own layers: paint them out of the background too
        hole[max(0, int(sh_["y"] - sh_["h"] / 2) - 6):int(sh_["y"] + sh_["h"] / 2) + 6, max(0, int(sh_["x"] - sh_["w"] / 2) - 6):int(sh_["x"] + sh_["w"] / 2) + 6] = 255
    bg = img
    if hole.any():
        sc_ = min(1.0, 900 / max(W, H))                    # (inpainting is slow on big pictures: do it small, put only the holes back)
        sm = cv2.resize(img, None, fx=sc_, fy=sc_, interpolation=cv2.INTER_AREA)
        hm = cv2.resize(hole, (sm.shape[1], sm.shape[0]), interpolation=cv2.INTER_NEAREST)
        fill = cv2.inpaint(sm, (hm > 0).astype(np.uint8), 7, cv2.INPAINT_TELEA)
        fill = cv2.GaussianBlur(cv2.resize(fill, (W, H), interpolation=cv2.INTER_CUBIC), (0, 0), 2.0)
        soft = cv2.GaussianBlur(hole, (0, 0), 3.0).astype(np.float32)[..., None] / 255
        bg = (img * (1 - soft) + fill * soft).astype(np.uint8)
    fonts = {}
    for t_ in texts:
        best = t_["match"][0] if t_["match"] else None
        t_["font"] = best["family"] if best and best["score"] >= 0.3 else None
        t_["font_sure"] = bool(best and best["score"] >= 0.52)
        for fam in t_["suggest"][:3]:
            fonts.setdefault(fam, {"family": fam, "look": t_["look"], "have": any(fn["family"].lower() == fam.lower() for fn in font_scan())})
    return jsonify(width=W, height=H, background=_png_url(np.dstack([bg, np.full((H, W), 255, np.uint8)])), shapes=shapes, subject=subj, texts=texts, logos=logos, manual=manual, engine="rapidocr" if found_ is not None else "tesseract",
                   fonts=list(fonts.values()), notes=notes, reference=_png_url(np.dstack([img, np.full((H, W), 255, np.uint8)])))


# ---------------------------------------------------------------------------
# Look: one colour grade over the whole edit (under the title / watermark). The page previews it with an SVG
# filter that is the same maths: contrast + brightness per channel, then one saturation x white-balance matrix.
# ---------------------------------------------------------------------------
def parse_look(g):
    if not isinstance(g, dict) or not g.get("on"):
        return None
    lk = {"contrast": _fnum(g.get("contrast"), 100, 40, 200) / 100, "bright": _fnum(g.get("bright"), 0, -40, 40) / 100,
          "sat": _fnum(g.get("sat"), 100, 0, 250) / 100, "temp": _fnum(g.get("temp"), 0, -100, 100) / 100,
          "tint": _fnum(g.get("tint"), 0, -100, 100) / 100, "vig": _fnum(g.get("vig"), 0, 0, 100) / 100,
          "sharp": round(_fnum(g.get("sharp"), 0, 0, 100) / 100 * 20), "glow": round(_fnum(g.get("glow"), 0, 0, 100) / 100, 3)}
    if lk == {"contrast": 1, "bright": 0, "sat": 1, "temp": 0, "tint": 0, "vig": 0, "sharp": 0, "glow": 0}:
        return None
    return lk


def look_matrix(lk):
    """Rows of the 3x3 matrix: saturation (Rec.709 weights, like CSS saturate) then per-channel white-balance gains."""
    s, t, n = lk["sat"], lk["temp"], lk["tint"]
    m = [[.213 + .787 * s, .715 - .715 * s, .072 - .072 * s],
         [.213 - .213 * s, .715 + .285 * s, .072 - .072 * s],
         [.213 - .213 * s, .715 - .715 * s, .072 + .928 * s]]
    gain = [1 + .12 * t + .05 * n, 1 - .10 * n, 1 - .12 * t + .05 * n]
    return [[m[r][c] * gain[r] for c in range(3)] for r in range(3)]


def parse_look_segs(g, total):
    """Looks for parts of the edit (a template's dark half and bright half): [(first frame, end frame, look)]."""
    out = []
    for sg in ((g or {}).get("segs") or [])[:12] if isinstance(g, dict) else []:
        if not isinstance(sg, dict):
            continue
        a = int(round(_fnum(sg.get("a"), 0, 0, 1e6) * FPS))
        b = int(round(_fnum(sg.get("b"), 0, 0, 1e6) * FPS))
        lk = parse_look(dict(sg.get("look") or {}, on=True))
        if b - a >= 2 and lk:
            out.append((a, min(b, total), lk))
    return out


def look_graph(cur, last, chains, look, segs, frame0, total, tag="lk"):
    """Add the Look to the end of the picture chain: the whole-edit look, or one look per part of the edit (each switched on
    only for its frames), each with its optional glow. Returns (cur, last)."""
    jobs = [(a, b, lk) for a, b, lk in segs if b > frame0 and a < frame0 + total] if segs else ([(None, None, look)] if look else [])
    for j, (a, b, lk) in enumerate(jobs):
        en = "" if a is None else f":enable='between(n,{a - frame0},{b - frame0 - 1})'"
        fl = look_filters(lk)
        last = last + [fl[0]] + [f + en for f in fl[1:]]
        if lk.get("glow"):                              # glow: the bright parts, blurred, screened back over the picture
            chains.append(cur + ",".join(last + ["format=gbrp"]) + f",split[{tag}a{j}][{tag}b{j}]")
            chains.append(f"[{tag}b{j}]lutrgb=r='val*val/255':g='val*val/255':b='val*val/255',gblur=sigma={GLOW_SIGMA * OUTPUT_W / 1920:.2f}:steps=2[{tag}c{j}]")
            chains.append(f"[{tag}a{j}][{tag}c{j}]blend=all_mode=screen:all_opacity={GLOW_GAIN * lk['glow']:.4f}{en}[{tag}d{j}]")
            cur, last = f"[{tag}d{j}]", []
    return cur, last


GLOW_SIGMA, GLOW_GAIN = 26.0, 0.85          # Look glow: blur (px at 1920 wide) and strength at 100 % (the page uses the same numbers)


def look_filters(lk):
    c, b = lk["contrast"], lk["bright"]
    out = ["format=gbrp"]
    if lk.get("sharp"):                                 # the "4K / HD" sharpen: the same 3x3 kernel the page's preview uses
        k = int(lk["sharp"])
        m = f"0 -{k} 0 -{k} {20 + 4 * k} -{k} 0 -{k} 0"
        out.append(f"convolution=0m='{m}':1m='{m}':2m='{m}':0rdiv=0.05:1rdiv=0.05:2rdiv=0.05")
    if c != 1 or b != 0:
        e = f"clip((val/255-0.5)*{c:.4f}+{0.5 + b:.4f},0,1)*255"
        out.append(f"lutrgb=r='{e}':g='{e}':b='{e}'")
    if lk["sat"] != 1 or lk["temp"] or lk["tint"]:
        m = look_matrix(lk)
        out.append("colorchannelmixer=" + ":".join(f"{a}{b_}={m[i][j]:.5f}" for i, a in enumerate("rgb") for j, b_ in enumerate("rgb")))
    if lk["vig"] > 0:
        out.append(f"vignette=angle={lk['vig'] * 0.95:.4f}")
    return out


def slide_blur(T, span):
    """Per-frame whip blur (sigma, px) = how far the picture moves during that frame."""
    return [min(SLIDE_SIG_MAX, SLIDE_SIG_K * span * (ease((j + 1) / T) - ease(j / T)) * 1920 / OUTPUT_W)
            for j in range(T)]


def motion_blur(T):
    return [min(MOTION_SIG_MAX, MOTION_SIG_K * (ease((j + 1) / T) - ease(j / T))) for j in range(T)]


def blur_levels(sigmas, levels):
    out = {}
    for j, sig in enumerate(sigmas):
        if sig < levels[0] * 0.6:
            continue
        out.setdefault(min(levels, key=lambda v: abs(v - sig)), []).append(j)
    return out


def punch_blur(secs, trans, i, T):
    """global frame -> zoom-blur amount on a Zoom Punch (end of cut i) / Zoom Punch Sync (both sides)."""
    s = secs[i]
    kind = trans[i]["type"]
    amp = ZSYNC_ZOOM
    tin = trans[i - 1]["tf"] if i > 0 else 0
    L = (s["f1"] - s["f0"]) + tin // 2
    tp = max(2, min(T, L - 1))
    cf0 = s["f0"] - tin // 2
    out, prev = {}, 0.0
    for j in range(tp):
        z = amp * ((j + 1) / tp) ** 3
        a = min(0.18, 0.35 * (z - prev))
        prev = z
        if a >= THUMP_LEVELS[0] * 0.75:
            out[cf0 + L - tp + j] = a
    if kind == "zsync" and i + 1 < len(secs):               # the incoming clip zooming back out
        b = secs[i + 1]
        tout_b = trans[i + 1]["tf"] if i + 1 < len(trans) else 0
        Lb = (b["f1"] - b["f0"]) + tout_b // 2
        hh = max(2, min(T, Lb - 1))
        for j in range(hh):
            z0, z1 = amp * (1 - j / hh) ** 3, amp * (1 - (j + 1) / hh) ** 3
            a = min(0.18, 0.35 * (z0 - z1))
            if a >= THUMP_LEVELS[0] * 0.75:
                out[b["f0"] + j] = a
    return out


def transform_fx(tf, L, w=None, h=None):
    """Transform (zoom 100-300% + pan) and Ken Burns (slow zoom in/out across the cut) as one zoompan.
    Ken Burns runs on a 2x upscale so the slow move stays smooth (zoompan positions are whole pixels).
    w x h = the box it works in (the whole frame, or one Triptych / Duo pane)."""
    if not tf:
        return None
    OW_, OH_ = (w or OUTPUT_W), (h or OUTPUT_H)
    lock = tf.get("lock", True)
    zx, zy = (tf["zoom"], tf["zoom"]) if lock else (tf.get("zx", 1.0), tf.get("zy", 1.0))
    if max(zx, zy) <= 1.001 and not tf["kb"]:
        return None
    zm = min(zx, zy)                      # uniform part (zoompan never distorts) ...
    z0 = z1 = zm
    if tf["kb"]:
        if tf["dir"] == "in":
            z1 = z0 * (1 + tf["amt"])
        else:
            z0 = z0 * (1 + tf["amt"])
    q = f"(in/{max(1, L - 1)})"
    Z = f"({z0:.5f}+({z1 - z0:.5f})*{q})"
    X = f"(iw-iw/zoom)*{0.5 + tf['x'] / 2:.5f}"
    Y = f"(ih-ih/zoom)*{0.5 + tf['y'] / 2:.5f}"
    pre = f"scale={2 * OW_}:{2 * OH_}:flags=bicubic," if tf["kb"] else ""
    out = (pre + f"zoompan=z='{Z}':x='{X}':y='{Y}':d=1:s={OW_}x{OH_}:fps={FPS},"
           "setsar=1,setpts=PTS-STARTPTS")
    # ... and with the aspect lock off, the extra zoom on one axis is a stretch + crop of that axis only
    if zx > zm + 1e-3:
        out += (f",scale={round(OW_ * zx / zm / 2) * 2}:{OH_}:flags=bicubic,"
                f"crop={OW_}:{OH_}:(iw-{OW_})*{0.5 + tf['x'] / 2:.5f}:0,setsar=1")
    elif zy > zm + 1e-3:
        out += (f",scale={OW_}:{round(OH_ * zy / zm / 2) * 2}:flags=bicubic,"
                f"crop={OW_}:{OH_}:0:(ih-{OH_})*{0.5 + tf['y'] / 2:.5f},setsar=1")
    return out


def thump_blur_amount(amp, intensity, amt, w):
    """Fraction of the radius a thump streaks inward (0.07 = 7%)."""
    return THUMP_BLUR_K * (amp / PULSE_ZOOM) * intensity * amt * w


def radial_expr(a):
    """geq zoom blur: average of 8 samples along the line to the centre."""
    K = 7
    parts = "+".join(f"p(W/2+(X-W/2)*{1 - a * j / K:.5f},H/2+(Y-H/2)*{1 - a * j / K:.5f})" for j in range(1, K + 1))
    e = f"(p(X,Y)+{parts})/{K + 1}"
    return f"lum='{e}':cb='{e}':cr='{e}'"


def intro_blur(dur, amt):
    """global frame -> quantised blur sigma, heavy at frame 0, clear after `dur` seconds."""
    N = max(1, round(dur * FPS))
    out = {}
    for g in range(N):
        q = (g + 0.5) / N
        sig = INTRO_SIG * amt * (1 - q * q * (3 - 2 * q))
        if sig >= INTRO_LEVELS[0] * 0.75:
            out[g] = min(INTRO_LEVELS, key=lambda v: abs(v - sig))
    return out


def seq_blur(N, amt, ustart, udur, total=None):
    """Intro Sequence: heavy blur held until `ustart` s, then clearing over `udur` s
    (it may carry on a little into the main edit)."""
    g0 = max(0, min(N, round(ustart * FPS)))
    F = max(1, round(udur * FPS))
    end = min(g0 + F, total if total else g0 + F)
    out = {}
    for g in range(end):
        q = 0.0 if g < g0 else (g - g0 + 0.5) / F
        sig = INTRO_SIG * amt * (1 - q * q * (3 - 2 * q))
        if sig >= INTRO_LEVELS[0] * 0.75:
            out[g] = min(INTRO_LEVELS, key=lambda v: abs(v - sig))
    return out


def _hex(c):
    c = c.lstrip("#")
    return int(c[0:2], 16), int(c[2:4], 16), int(c[4:6], 16)


def _mix(c, d, k):
    a, b = _hex(c), _hex(d)
    return "0x" + "".join(f"{round(x + (y - x) * k):02x}" for x, y in zip(a, b))


def title_layout(tt):
    """x / y expressions and the 3D extrusion offsets for drawtext."""
    size = tt["size"]
    y0 = {"center": "(h-text_h)/2", "top": f"{round(OUTPUT_H * 0.12)}", "lower": f"{round(OUTPUT_H * 0.66)}"}[tt["pos"]]
    depth = max(3, round(size / 16))
    step = max(1.0, size / 70)
    return "(w-text_w)/2", y0, depth, step


def title_graph(chains, cur, tt, frame0, nloc):
    """Glow layer (blurred copy on a transparent canvas, overlaid twice) + 3D extrusion + face."""
    ts = round(tt["start"] * FPS)
    te = ts + max(2, round(tt["dur"] * FPS))
    a, b = max(ts, frame0), min(te, frame0 + nloc)
    if b <= a:
        return cur
    D = (te - ts) / FPS
    x0, y0, depth, step = title_layout(tt)
    size, col = tt["size"], tt["color"]
    font = f"fontfile='{tt['font_file']}':" if tt.get("font_file") else ""
    base = f"drawtext={font}textfile='{tt['file']}':expansion=none:fontsize={size}"

    def tau(off):          # title-local time for a stream whose t=0 is `off` seconds into the title
        return f"(t+{off:.4f})"

    def alpha(tv):
        return f"clip(min({tv}/{TITLE_IN},({D:.4f}-{tv})/{TITLE_OUT}),0,1)"

    def rise(tv):
        return f"{round(size * 0.22)}*pow(1-clip({tv}/{TITLE_IN},0,1),3)"

    # glow canvas: transparent, as long as this render window, so it lines up frame for frame
    # with the video (its filters only do work while the title is on screen)
    mt = tau((frame0 - ts) / FPS)
    en = f"enable='between(t,{(a - frame0) / FPS:.4f},{(b - frame0) / FPS:.4f})'"
    gk = tt["glow"]
    canvas = (f"color=c=0x{col.lstrip('#')}@0:s={OUTPUT_W}x{OUTPUT_H}:r={FPS}:d={nloc / FPS + 1:.4f},"
              f"trim=end_frame={nloc},format=rgba")
    glow_txt = (f"{base}:fontcolor=0x{col.lstrip('#')}:borderw={max(2, round(size / 22))}:bordercolor=0x{col.lstrip('#')}"
                f":x={x0}:y='{y0}+{rise(mt)}':alpha='{alpha(mt)}*(0.85+0.15*sin(2*PI*{mt}/1.6))':{en}")
    sh = tt.get("shadow") or {}
    if sh.get("on") and sh.get("op", 0) > 0:          # drop shadow: soft copy behind everything
        sc = sh["color"].lstrip("#")
        canvas_s = (f"color=c=0x{sc}@0:s={OUTPUT_W}x{OUTPUT_H}:r={FPS}:d={nloc / FPS + 1:.4f},"
                    f"trim=end_frame={nloc},format=rgba")
        stx = (f"{base}:fontcolor=0x{sc}:x={x0}+{sh['x']:.1f}+{depth * step:.1f}:y='{y0}+{rise(mt)}+{sh['y']:.1f}+{depth * step:.1f}'"
               f":alpha='{alpha(mt)}':{en}")
        bl = f",gblur=sigma={sh['blur'] / 2:.1f}:{en}" if sh["blur"] >= 1 else ""
        chains.append(f"{canvas_s},{stx}{bl},colorchannelmixer=aa={sh['op']:.2f}:{en}[tsh]")
        chains.append(f"{cur}[tsh]overlay={en}[tsh2]")
        cur = "[tsh2]"
    gc = (tt.get("glowColor") or col).lstrip("#")
    glow_txt = glow_txt.replace(f"fontcolor=0x{col.lstrip('#')}:borderw={max(2, round(size / 22))}:bordercolor=0x{col.lstrip('#')}",
                                f"fontcolor=0x{gc}:borderw={max(2, round(size / 22))}:bordercolor=0x{gc}")
    chains.append(f"{canvas},{glow_txt},split[tg1][tg2]")
    chains.append(f"[tg1]gblur=sigma={max(2, size * 0.07 * gk):.1f}:{en},colorchannelmixer=aa={min(3, 1.3 * gk + 0.2):.2f}:{en}[tgs]")
    chains.append(f"[tg2]gblur=sigma={max(4, size * 0.22 * gk):.1f}:{en},colorchannelmixer=aa={min(3, 1.6 * gk + 0.2):.2f}:{en}[tgw]")
    if gk > 0:
        chains.append(f"{cur}[tgw]overlay={en}[tov1]")
        chains.append(f"[tov1][tgs]overlay={en}[tov2]")
    else:
        chains.append("[tgw]nullsink")
        chains.append("[tgs]nullsink")
        chains.append(f"{cur}null[tov2]")
    # 3D extrusion + face drawn straight onto the video (t = this window's time)
    layers = []
    for d in range(depth, 0, -1):
        shade = _mix(col, "#000000", 0.78 - 0.33 * (depth - d) / max(1, depth - 1))
        layers.append(f"{base}:fontcolor={shade}:x={x0}+{d * step:.1f}:y='{y0}+{rise(mt)}+{d * step:.1f}'"
                      f":alpha='{alpha(mt)}':{en}")
    ol = tt.get("outline") or {}
    if ol.get("on") and ol.get("w", 0) >= 1:          # your outline replaces the thin highlight edge
        bw, bc = max(1, round(ol["w"])), "0x" + ol["color"].lstrip("#")
    else:
        bw, bc = max(1, round(size / 70)), _mix(col, '#ffffff', 0.65)
    layers.append(f"{base}:fontcolor=0x{col.lstrip('#')}:borderw={bw}:bordercolor={bc}"
                  f":x={x0}:y='{y0}+{rise(mt)}':alpha='{alpha(mt)}':{en}")
    chains.append(f"[tov2]settb=1/{FPS},setpts=N,format=yuv444p," + ",".join(layers) + ",format=yuv420p[titled]")
    return "[titled]"


def text_image(text, font_file, size, color, outline=None, shadow=None, glow=None):
    """Styled text as an RGBA image (Pillow): glow + drop shadow + outline (outside) + face.
    Returns (image, (x, y) of the text box inside the image, (w, h) of the text box)."""
    from PIL import Image, ImageDraw, ImageFont, ImageFilter
    try:
        font = ImageFont.truetype(font_file, size) if font_file else ImageFont.load_default(size)
    except Exception:
        font = ImageFont.load_default(size)
    ow = int(round(outline["w"])) if outline and outline.get("on") else 0
    l, t, r, b = ImageDraw.Draw(Image.new("L", (1, 1))).textbbox((0, 0), text, font=font, stroke_width=ow)
    tw, th = r - l, b - t
    gs = (max(2.0, size * 0.12 * glow["amt"]) if glow and glow.get("amt", 0) > 0 else 0)
    sh = shadow if shadow and shadow.get("on") and shadow.get("op", 0) > 0 else None
    sb = sh["blur"] / 2 if sh else 0
    pad = int(max(ow, 3 * gs, (abs(sh["x"]) + abs(sh["y"]) + 3 * sb) if sh else 0)) + 4
    W_, H_ = tw + 2 * pad, th + 2 * pad
    org = (pad - l, pad - t)

    def mask(dx=0.0, dy=0.0):
        m = Image.new("L", (W_, H_), 0)
        ImageDraw.Draw(m).text((org[0] + dx, org[1] + dy), text, font=font, fill=255, stroke_width=ow, stroke_fill=255)
        return m

    def tinted(alpha, col, k):
        layer = Image.new("RGBA", (W_, H_), _hex(col) + (0,))
        layer.putalpha(alpha.point(lambda v: min(255, int(v * k))))
        return layer

    out = Image.new("RGBA", (W_, H_), (0, 0, 0, 0))
    if gs:
        m = mask()
        for sig, k in ((gs, 1.6 * glow["amt"] + 0.2), (gs * 0.35, 1.3 * glow["amt"] + 0.2)):
            out = Image.alpha_composite(out, tinted(m.filter(ImageFilter.GaussianBlur(sig)), glow["color"], min(3.0, k)))
    if sh:
        m = mask(sh["x"], sh["y"])
        if sb >= 0.5:
            m = m.filter(ImageFilter.GaussianBlur(sb))
        out = Image.alpha_composite(out, tinted(m, sh["color"], sh["op"]))
    face = Image.new("RGBA", (W_, H_), (0, 0, 0, 0))
    ImageDraw.Draw(face).text(org, text, font=font, fill=_hex(color) + (255,), stroke_width=ow,
                              stroke_fill=(_hex(outline["color"]) + (255,)) if ow else None)
    out = Image.alpha_composite(out, face)
    return out, (pad, pad), (tw, th)


WM_MARGIN = 56


def wm_place(wm, tw, th):
    """Top-left of the watermark's text box on the frame (9-grid + your X / Y nudge)."""
    v, hz = wm["pos"][0], wm["pos"][1]
    x = {"l": WM_MARGIN, "c": (OUTPUT_W - tw) / 2, "r": OUTPUT_W - tw - WM_MARGIN}[hz]
    y = {"t": round(WM_MARGIN * 0.8), "m": (OUTPUT_H - th) / 2, "b": OUTPUT_H - th - round(WM_MARGIN * 0.8)}[v]
    return round(x + wm.get("dx", 0)), round(y + wm.get("dy", 0))


def watermark_alpha(wm, G, TOT):
    return (f"{wm['opacity']:.3f}*(0.78+0.22*sin(2*PI*{G}/4))*clip({G}/1.5,0,1)"
            f"*clip(({TOT:.4f}-{G})/1.0,0,1)")


def watermark_filter(wm, frame0, total_global):
    G = f"(t+{frame0 / FPS:.4f})"
    TOT = total_global / FPS
    al = (f"{wm['opacity']:.3f}*(0.78+0.22*sin(2*PI*{G}/4))*clip({G}/1.5,0,1)"
          f"*clip(({TOT:.4f}-{G})/1.0,0,1)")
    # (fallback when Pillow is missing: plain drawtext with outline + hard shadow)
    m = WM_MARGIN
    x = {"l": f"{m}", "c": "(w-text_w)/2", "r": f"w-text_w-{m}"}[wm["pos"][1]] + f"+{wm.get('dx', 0):.0f}"
    y = {"t": f"{round(m * 0.8)}", "m": "(h-text_h)/2", "b": f"h-text_h-{round(m * 0.8)}"}[wm["pos"][0]] + f"+{wm.get('dy', 0):.0f}"
    font = f"fontfile='{wm['font_file']}':" if wm.get("font_file") else ""
    ol, sh = wm.get("outline") or {}, wm.get("shadow") or {}
    extra = (f":borderw={max(1, round(ol['w']))}:bordercolor=0x{ol['color'].lstrip('#')}" if ol.get("on") and ol.get("w", 0) >= 1 else "")
    if sh.get("on"):
        extra += f":shadowcolor=0x{sh['color'].lstrip('#')}@{sh['op']:.2f}:shadowx={sh['x']:.0f}:shadowy={sh['y']:.0f}"
    return (f"drawtext={font}textfile='{wm['file']}':expansion=none:fontsize={wm['size']}:fontcolor=0x{wm.get('color', '#ffffff').lstrip('#')}"
            f"{extra}:x={x}:y={y}:alpha='{al}'")


def window_fx(kind, role, T):
    """Spin / Zoom on the frames a clip spends inside its transition window.
    role 'out' = the clip leaving, 'in' = the clip arriving; progress is eased 0 -> 1
    (ease-in-out cubic, sampled at the middle of each frame).
    Zoom < 1 is done by zooming a 2x black-padded frame (zoompan can't go below 1)."""
    e = ease_expr(f"((in+0.5)/{T})")
    sc = {("zoomin", "out"): f"(1+1.5*{e})", ("zoomin", "in"): f"(0.5+0.5*{e})",
          ("zoomout", "out"): f"(1-0.5*{e})", ("zoomout", "in"): f"(2.5-1.5*{e})",
          ("spin", "out"): f"(1-0.5*{e})", ("spin", "in"): f"(0.5+0.5*{e})"}[(kind, role)]
    f = (f"pad={2 * OUTPUT_W}:{2 * OUTPUT_H}:{OUTPUT_W // 2}:{OUTPUT_H // 2}:black,"
         f"zoompan=z='2*{sc}':x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':d=1:s={OUTPUT_W}x{OUTPUT_H}:fps={FPS}")
    if kind == "spin":
        en = ease_expr(f"((n+0.5)/{T})")
        ang = f"PI*{en}" if role == "out" else f"PI*({en}-1)"
        f += f",rotate=a='{ang}':fillcolor=black"
    return f


def frame_ranges(frames):
    """[3,4,5,9] -> 'between(n,3,5)+between(n,9,9)' for a filter's enable option."""
    frames = sorted(set(frames))
    out, a = [], None
    for k, f in enumerate(frames):
        if a is None:
            a = f
        if k + 1 == len(frames) or frames[k + 1] != f + 1:
            out.append(f"between(n,{a},{f})")
            a = None
    return "+".join(out) or "0"


# Export formats. The edit is always built as H.264 first (exact frames, fast); any other choice is one more
# FFmpeg pass over that file. key -> (label, extension, mimetype)
EXPORT_FORMATS = {"h264": ("MP4 (H.264)", ".mp4", "video/mp4"), "hevc": ("MP4 (HEVC / H.265)", ".mp4", "video/mp4"),
                  "prores": ("MOV (ProRes 422)", ".mov", "video/quicktime"), "webm": ("WebM (VP9)", ".webm", "video/webm")}
EXPORT_Q = ("high", "balanced", "small")


def parse_export(e):
    e = e if isinstance(e, dict) else {}
    return {"fmt": e.get("fmt") if e.get("fmt") in EXPORT_FORMATS else "h264", "q": e.get("q") if e.get("q") in EXPORT_Q else "high",
            "scale": 1.0 if _fnum(e.get("scale"), 1, 0.25, 1) > 0.99 else _fnum(e.get("scale"), 1, 0.25, 1)}


def export_args(ex):
    """FFmpeg output arguments for the chosen format + quality (None = the H.264 master is the export as it is)."""
    fmt, q, k = ex["fmt"], EXPORT_Q.index(ex["q"]), ex["scale"]
    if fmt == "h264" and q == 0 and k == 1.0:
        return None
    vf = ["-vf", f"scale=trunc(iw*{k:.4f}/2)*2:trunc(ih*{k:.4f}/2)*2:flags=lanczos"] if k < 1 else []
    if fmt == "h264":
        return vf + ["-c:v", "libx264", "-preset", "medium", "-crf", str((17, 21, 26)[q]), "-pix_fmt", "yuv420p",
                     "-c:a", "aac", "-b:a", ("256k", "192k", "128k")[q], "-movflags", "+faststart"]
    if fmt == "hevc":
        return vf + ["-c:v", "libx265", "-preset", "medium", "-crf", str((20, 24, 29)[q]), "-pix_fmt", "yuv420p", "-tag:v", "hvc1",
                     "-x265-params", "log-level=error", "-c:a", "aac", "-b:a", ("256k", "192k", "128k")[q], "-movflags", "+faststart"]
    if fmt == "prores":
        return vf + ["-c:v", "prores_ks", "-profile:v", str((3, 2, 1)[q]), "-pix_fmt", "yuv422p10le", "-vendor", "apl0", "-c:a", "pcm_s16le"]
    return vf + ["-c:v", "libvpx-vp9", "-crf", str((26, 32, 38)[q]), "-b:v", "0", "-row-mt", "1", "-cpu-used", "3", "-pix_fmt", "yuv420p",
                 "-c:a", "libopus", "-b:a", ("192k", "128k", "96k")[q]]


def export_finish(job, master, ex, total_frames):
    """Turn the finished H.264 master into the chosen export format. Returns the path of the file to hand over."""
    args = export_args(ex)
    label, ext, mime = EXPORT_FORMATS[ex["fmt"]]
    job["mime"] = mime
    job["name"] = os.path.splitext(job.get("name") or "kiru.mp4")[0] + ext
    if not args:
        return master
    out = os.path.splitext(master)[0] + "_x" + ext
    job["encoder"] = (job.get("encoder") or "") + f" -> {label}"
    cmd = ["ffmpeg", "-hide_banner", "-y", "-v", "error", "-i", os.path.abspath(master)] + args + ["-progress", "pipe:1", "-nostats", os.path.abspath(out)]
    log_path = os.path.join(WORK_DIR, os.path.basename(master) + "_export.log")
    with open(log_path, "w", encoding="utf-8") as log:
        proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=log, text=True, cwd=UPLOAD_DIR, creationflags=NO_WINDOW)
        job["proc"] = proc
        for line in proc.stdout:
            if job.get("cancel"):
                proc.kill()
                break
            key, _, val = line.strip().partition("=")
            if key in ("out_time_us", "out_time_ms") and val.isdigit():
                job["progress"] = min(0.999, 0.98 + 0.019 * (int(val) / 1e6 * FPS) / max(1, total_frames))
        proc.wait()
    job["proc"] = None
    if job.get("cancel"):
        _rm(out)
        raise Cancelled()
    if proc.returncode != 0 or not os.path.exists(out):
        with open(log_path, encoding="utf-8", errors="replace") as fh:
            msg = fh.read()[-1500:]
        _rm(out)
        _rm(log_path)
        raise RenderError(f"The edit rendered, but converting it to {label} failed (your FFmpeg may not have that encoder).\n" + msg)
    _rm(log_path)
    _rm(master)
    job["path"] = out
    return out


def audio_chain(idx, total_s, fade_in=0.02, fade_out=0.25):
    fade_out = min(fade_out, total_s / 2)
    return (f"[{idx}:a]aresample=48000,aformat=channel_layouts=stereo,"
            f"atrim=end={total_s:.4f},asetpts=PTS-STARTPTS,"
            f"afade=t=in:st=0:d={fade_in:.4f}:curve=qsin,"
            f"afade=t=out:st={total_s - fade_out:.4f}:d={fade_out:.4f}[aout]")


def atempo_chain(r):
    """atempo takes 0.5 .. 100 per stage, so chain stages for anything outside that."""
    parts = []
    while r > 100.0:
        parts.append(100.0)
        r /= 100.0
    while r < 0.5:
        parts.append(0.5)
        r /= 0.5
    parts.append(r)
    return ",".join(f"atempo={x:.6f}" for x in parts)


def clip_audio_graph(secs, trans, aud, total, first_idx):
    """Original sound of the clips, following each cut's speed / Slow-mo exactly.
    Cuts go on two lanes (even / odd), so the overlapping halves of a transition
    crossfade instead of colliding. Returns (inputs, chains, [lane labels])."""
    gv = aud["clips"]
    inputs, chains, lanes = [], [], {0: [], 1: []}
    if gv <= 0:
        return inputs, chains, []
    idx = first_idx
    AF = "aresample=48000,aformat=sample_fmts=fltp:sample_rates=48000:channel_layouts=stereo"
    for i, s in enumerate(secs):
        tin, tout, slow_in, slow_out = section_windows(secs, trans, i)
        L = (s["f1"] - s["f0"]) + tin // 2 + tout // 2
        Ls = L / FPS
        srcs = []
        cands = s["panes"] if s.get("layout") in MULTI else [{"clip": s["clip"], "clipStart": s["clipStart"],
                                                              "vol": s.get("vol", 1.0), "mute": s.get("mute")}]
        for pp in cands:
            if pp and pp["clip"].get("audio") and not pp.get("mute") and pp.get("vol", 1.0) > 0:
                srcs.append(pp)
        if not srcs:
            continue
        def timing(ps):
            tm = time_map(ps.get("speed", 1.0), L, tin, tout, slow_in, slow_out)
            t1, t2 = tm[0], tm[1]
            cuts = sorted({0.0, Ls} | {x for x in (t1, t2) if 0 < x < Ls})
            if ps.get("curve"):                                  # speed graph: pieces of 6 frames
                cuts = sorted({min(Ls, k / FPS) for k in range(0, L, 6)} | {Ls})
            return offset_fn(ps, L, tin, tout, slow_in, slow_out), [(a, b) for a, b in zip(cuts, cuts[1:]) if b - a > 1e-6]
        offf, pieces = timing(s)
        offf0, pieces0 = offf, pieces
        outs = []
        for j, pp in enumerate(srcs):
            offf, pieces = timing(pane_timing(s, pp)) if pp.get("own") else (offf0, pieces0)      # a pane with its own speed: its sound follows it
            clip = pp["clip"]
            cs = pp["clipStart"] % clip["duration"] if clip["duration"] > 0.1 else pp["clipStart"]
            need = offf(Ls)
            inputs += ["-ss", f"{cs + clip.get('v0', 0):.6f}", "-stream_loop", "-1", "-t", f"{need + 1.0:.6f}", "-vn",
                       "-i", os.path.basename(clip["path"])]
            k = idx
            idx += 1
            labs = [f"[{k}:a]"]
            if len(pieces) > 1:
                labs = [f"[as{i}_{j}_{m}]" for m in range(len(pieces))]
                chains.append(f"[{k}:a]{AF},asplit={len(pieces)}" + "".join(labs))
            pl = []
            for m, (a, b) in enumerate(pieces):
                ua, ub = offf(a), offf(b)
                rate = (ub - ua) / (b - a)
                pre = AF + "," if len(pieces) == 1 else ""
                chains.append(f"{labs[m]}{pre}atrim=start={ua:.6f}:end={ub:.6f},asetpts=PTS-STARTPTS,{atempo_chain(rate)},"
                              f"apad=whole_dur={b - a:.6f},atrim=end={b - a:.6f},asetpts=PTS-STARTPTS[ap{i}_{j}_{m}]")
                pl.append(f"[ap{i}_{j}_{m}]")
            chains.append("".join(pl) + (f"concat=n={len(pl)}:v=0:a=1," if len(pl) > 1 else "anull,")
                          + f"volume={pp.get('vol', 1.0) * gv:.4f}[av{i}_{j}]")
            outs.append(f"[av{i}_{j}]")
        mix = "".join(outs) + (f"amix=inputs={len(outs)}:normalize=0:duration=longest," if len(outs) > 1 else "anull,")
        xf = max(0.004, min(aud.get("xf", 0.006), Ls / 2.5))    # hard cut: a short fade so two sounds never click together
        fi = tin / FPS if tin else xf             # crossfade over the transition, else the hard-cut fade
        fo = tout / FPS if tout else xf
        chains.append(mix + f"afade=t=in:st=0:d={fi:.4f},afade=t=out:st={max(0.0, Ls - fo):.4f}:d={fo:.4f},"
                      f"apad=whole_dur={Ls:.6f},atrim=end={Ls:.6f},asetpts=PTS-STARTPTS[sa{i}]")
        lanes[i % 2].append((s["f0"] - tin // 2, f"[sa{i}]", L))
    out = []
    for ln, items in lanes.items():
        if not items:
            continue
        seq, cur = [], 0
        for g, (f, lab, L) in enumerate(items):
            if f > cur:
                chains.append(f"anullsrc=r=48000:cl=stereo,atrim=end={(f - cur) / FPS:.6f},{AF}[gap{ln}_{g}]")
                seq.append(f"[gap{ln}_{g}]")
            seq.append(lab)
            cur = f + L
        chains.append("".join(seq) + f"concat=n={len(seq)}:v=0:a=1,apad=whole_dur={total / FPS:.6f},"
                      f"atrim=end={total / FPS:.6f}[lane{ln}]")
        out.append(f"[lane{ln}]")
    return inputs, chains, out


def mixed_audio(song_idx, total_s, aud, lanes):
    """Song (at its volume) + clip lanes, summed without normalising, then a
    limiter so 200% clips + song can't clip or crackle."""
    sv = aud["song"]
    fi = min(aud.get("fadeIn", 0.02), total_s / 2)
    if not lanes and abs(sv - 1.0) < 1e-6:
        return [audio_chain(song_idx, total_s, fi, aud.get("fadeOut", 0.25))]
    fade_out = min(aud.get("fadeOut", 0.25), total_s / 2)
    ch = [f"[{song_idx}:a]aresample=48000,aformat=sample_fmts=fltp:sample_rates=48000:channel_layouts=stereo,"
          f"atrim=end={total_s:.4f},asetpts=PTS-STARTPTS,volume={sv:.4f}[songv]"]
    ch.append("[songv]" + "".join(lanes) + (f"amix=inputs={1 + len(lanes)}:normalize=0:duration=first," if lanes else "")
              + "alimiter=limit=0.89:attack=5:release=80:level=0,"
              + f"afade=t=in:st=0:d={fi:.4f}:curve=qsin,afade=t=out:st={total_s - fade_out:.4f}:d={fade_out:.4f}[aout]")
    return ch


def song_input(song, start, total_s):
    return ["-ss", f"{start:.4f}", "-t", f"{total_s + 0.5:.4f}",
            "-i", os.path.basename(song["path"])]


# ----- running FFmpeg ----------------------------------------------------------
def run_ffmpeg(job, cmd, log_path, frames_before, frames_this, total_frames, base=0.0, span=0.98):
    """Run one FFmpeg command (cwd = uploads, so inputs are short relative names).
    The bar goes from base to base + span over total_frames."""
    with open(log_path, "w", encoding="utf-8") as log:
        proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=log, text=True,
                                cwd=UPLOAD_DIR, creationflags=NO_WINDOW)
        job["proc"] = proc
        for line in proc.stdout:
            if job.get("cancel"):
                proc.kill()
                break
            key, _, val = line.strip().partition("=")
            if key in ("out_time_us", "out_time_ms") and val.isdigit():
                done = min(frames_this, int(val) / 1e6 * FPS)
                job["progress"] = min(0.995, base + (frames_before + done) / max(1, total_frames) * span)
        proc.wait()
    job["proc"] = None
    if job.get("cancel"):
        raise Cancelled()
    if proc.returncode != 0:
        with open(log_path, encoding="utf-8", errors="replace") as fh:
            raise RenderError(fh.read()[-3000:] or "FFmpeg failed.")


def run_render(jid):
    """Renders are serialised: the output size (16:9 or 9:16) is set for the whole job."""
    global OUTPUT_W, OUTPUT_H, EASE_POW
    with RENDER_LOCK:
        keep = OUTPUT_W, OUTPUT_H, EASE_POW
        OUTPUT_W, OUTPUT_H = ORIENTS[JOBS[jid]["plan"][5].get("orient", "landscape")]
        EASE_POW = EASE_FEEL[JOBS[jid]["plan"][5].get("feel", "smooth")]
        try:
            _run_render(jid)
        finally:
            OUTPUT_W, OUTPUT_H, EASE_POW = keep
            job_release(jid)


def _run_render(jid):
    job = JOBS[jid]
    song, start, total, secs, trans, pulse = job["plan"]
    out_path = os.path.join(EXPORT_DIR, jid + ".mp4")
    job["path"] = out_path
    total_s = total / FPS
    tag = os.path.join(WORK_DIR, jid)
    keep_debug = False
    try:
        prepare_polish(pulse["polish"], tag)
        pulse["tag"] = tag
        for i, s in enumerate(secs):
            cv = s.get("curve")
            s["blend"] = s.get("speed", 1.0) < 0.99 or bool(cv and min(cv["v"]) < 0.99)   # slowed cuts glide
            tin, tout, _, _ = section_windows(secs, trans, i)
            if cv:
                cv.update(L=(s["f1"] - s["f0"]) + tin // 2 + tout // 2, k0=0)
            prep_pane_timing(s, (s["f1"] - s["f0"]) + tin // 2 + tout // 2)
        cuts = pick_cuts(secs, trans, T=pulse["tlen"])
        windows = list(zip([0] + cuts, cuts + [total]))
        job["chunks"] = len(windows)
        encoders = ["nvenc", "x264"] if nvenc_available() else ["x264"]
        last_err = ""
        for enc in encoders:
            enc_args = NVENC_ARGS if enc == "nvenc" else X264_ARGS
            job.update(status="rendering", progress=0.0,
                       encoder="NVENC (GPU)" if enc == "nvenc" else "libx264 (CPU)")
            try:
                if len(windows) == 1:
                    # small edit: ONE FFmpeg command for everything
                    inputs, chains = build_video_graph(secs, trans, pulse)
                    n_inputs = inputs.count("-i")
                    inputs += song_input(song, start, total_s)
                    ai, ac, lanes = clip_audio_graph(secs, trans, pulse["audio"], total, n_inputs + 1)
                    inputs += ai
                    chains += ac + mixed_audio(n_inputs, total_s, pulse["audio"], lanes)
                    with open(tag + "_graph.txt", "w", encoding="utf-8") as fh:
                        fh.write(";\n".join(chains))
                    cmd = (["ffmpeg", "-hide_banner", "-y", "-v", "error"] + inputs
                           + filter_script_args(tag + "_graph.txt")
                           + ["-map", "[vout]", "-map", "[aout]", "-t", f"{total_s:.4f}",
                              "-r", str(FPS)] + enc_args
                           + ["-c:a", "aac", "-b:a", "256k", "-movflags", "+faststart",
                              "-progress", "pipe:1", "-nostats", out_path])
                    run_ffmpeg(job, cmd, tag + "_ffmpeg.log", 0, total, total)
                else:
                    # big edit: render chunks (video only), then join + add song
                    done = 0
                    lst = []
                    for ci, (w0, w1) in enumerate(windows):
                        job["chunk"] = ci + 1
                        csecs, ctrans = slice_plan(secs, trans, w0, w1)
                        inputs, chains = build_video_graph(csecs, ctrans, pulse, frame0=w0)
                        graph = f"{tag}_g{ci:03d}.txt"
                        with open(graph, "w", encoding="utf-8") as fh:
                            fh.write(";\n".join(chains))
                        part = f"{tag}_part{ci:03d}.mp4"
                        nf = w1 - w0
                        cmd = (["ffmpeg", "-hide_banner", "-y", "-v", "error"] + inputs
                               + filter_script_args(graph)
                               + ["-map", "[vout]", "-an", "-frames:v", str(nf),
                                  "-r", str(FPS)] + enc_args
                               + ["-f", "mp4", "-progress", "pipe:1", "-nostats", part])
                        run_ffmpeg(job, cmd, tag + "_ffmpeg.log", done, nf, total, span=JOIN_AT)
                        lst.append(f"file '{os.path.basename(part)}'\nduration {nf / FPS:.6f}\n")
                        done += nf
                        _rm(graph)
                    job["chunk"] = "join"
                    with open(tag + "_list.txt", "w", encoding="utf-8") as fh:
                        fh.write("".join(lst))
                    ai, ac, lanes = clip_audio_graph(secs, trans, pulse["audio"], total, 2)
                    with open(tag + "_agraph.txt", "w", encoding="utf-8") as fh:
                        fh.write(";\n".join(ac + mixed_audio(1, total_s, pulse["audio"], lanes)))
                    cmd = (["ffmpeg", "-hide_banner", "-y", "-v", "error",
                            "-f", "concat", "-safe", "0", "-i", os.path.abspath(tag + "_list.txt")]
                           + song_input(song, start, total_s) + ai
                           + filter_script_args(tag + "_agraph.txt")
                           + ["-map", "0:v", "-map", "[aout]", "-c:v", "copy",
                              "-c:a", "aac", "-b:a", "256k", "-t", f"{total_s:.4f}",
                              "-movflags", "+faststart",
                              "-progress", "pipe:1", "-nostats", out_path])
                    run_ffmpeg(job, cmd, tag + "_ffmpeg.log", 0, total, total, base=JOIN_AT, span=0.98 - JOIN_AT)
                    for name in os.listdir(WORK_DIR):          # joined: the pieces go at once (a long edit is gigabytes of them)
                        if name.startswith(jid + "_part"):
                            _rm(os.path.join(WORK_DIR, name))
                export_finish(job, out_path, pulse.get("export") or parse_export(None), total)
                job.update(status="done", progress=1.0, finished=time.time())
                return
            except RenderError as e:
                last_err = str(e)
                _rm(out_path)
                if enc == "nvenc":
                    log.info("[render] NVENC failed, falling back to libx264.")
        job.update(status="error", error=last_err or "FFmpeg failed.")
        keep_debug = True
    except Cancelled:
        job["status"] = "cancelled"
        _rm(out_path)
    except Exception as e:
        job.update(status="error", error=str(e))
        keep_debug = True
    finally:
        job["proc"] = None
        for name in os.listdir(WORK_DIR):
            if name.startswith(jid) and not (keep_debug and name.endswith((".txt", ".log"))):
                _rm(os.path.join(WORK_DIR, name))


def prepare_polish(po, tag):
    """Title / watermark text go to files (no escaping problems) and the font is
    copied next to them; both are referenced relative to the uploads folder."""
    import shutil
    ov = po.get("ov") or {}
    if ov.get("on"):                           # Image layer: its size on the frame + where it goes
        iw, ih = ov.get("iw") or 0, ov.get("ih") or 0
        try:
            from PIL import Image
            with Image.open(ov["image"]) as im:
                iw, ih = im.size
        except Exception:
            pass
        if iw and ih:
            ow = max(2, round(OUTPUT_W * ov["size"] / 2) * 2)
            oh = max(2, round(ow * ih / iw / 2) * 2)
            x, y = wm_place(ov, ow, oh)
            ov.update(ow=ow, oh=oh, px=x, py=y)
    if not has_filter("drawtext"):            # FFmpeg without text support: render everything else
        for key in ("title", "wm"):
            if (po.get(key) or {}).get("on"):
                log.info(f"[render] this FFmpeg has no drawtext filter - skipping the {key}.")
                po[key]["on"] = False
    rel = lambda path: os.path.relpath(path, UPLOAD_DIR).replace("\\", "/")
    for key, fonts in (("title", None), ("wm", WM_FONT)):
        d = po.get(key) or {}
        if not d.get("on"):
            continue
        txt = tag + f"_{key}.txt"
        with open(txt, "w", encoding="utf-8") as fh:
            fh.write(d["text"])
        d["file"] = rel(txt)
        src = find_font(TITLE_FONTS[d.get("font") or "segoesemi"] if d.get("font") else fonts)
        if src:
            dst = tag + f"_{key}font" + os.path.splitext(src)[1].lower()
            shutil.copyfile(src, dst)
            d["font_file"] = rel(dst)
        if key == "wm":
            try:                                   # styled watermark as one PNG (outline, shadow, glow)
                img, (bx, by), (tw, th) = text_image(d["text"], src, d["size"], d.get("color", "#ffffff"),
                                                     d.get("outline"), d.get("shadow"), d.get("glow"))
                png = tag + "_wm.png"
                img.save(png)
                x, y = wm_place(d, tw, th)
                d.update(png=rel(png), px=x - bx, py=y - by)
            except ImportError:
                log.info("[render] Pillow is not installed - plain watermark (no glow).")


def _rm(path):
    try:
        if path and os.path.exists(path):
            os.remove(path)
    except OSError:
        pass


# ---------------------------------------------------------------------------
# Routes
# ---------------------------------------------------------------------------
SETTINGS_FILE = os.path.join(BASE_DIR, "settings.json")       # theme, language, devices...: survives a cleared browser store


AUTOSAVE_FILE = os.path.join(BASE_DIR, "project.kiru_autosave" + INSTANCE)   # the whole session, every 2 minutes while there are unsaved changes
RECENT_DIR = os.path.join(BASE_DIR, "recent_projects")              # Kiru's own copy of the last 5 projects saved / opened (for the start screen)
RECENT_MAX = 5


def autosave_clear():
    """A clean exit (or a saved project): nothing to recover next time."""
    _rm(AUTOSAVE_FILE)


def autosave_path():
    """This window's auto-save file; a browser tab on the same engine (?slot=...) has its own."""
    slot = re.sub(r"[^a-z0-9]", "", str(request.args.get("slot") or "").lower())[:16]
    return AUTOSAVE_FILE + ("_tab" + slot if slot else "")


def recent_index():
    try:
        with open(os.path.join(RECENT_DIR, "index.json"), encoding="utf-8") as fh:
            lst = json.load(fh)
        return [e for e in lst if isinstance(e, dict) and os.path.isfile(os.path.join(RECENT_DIR, str(e.get("file"))))][:RECENT_MAX]
    except (OSError, ValueError):
        return []


def settings_load():
    try:
        with open(SETTINGS_FILE, encoding="utf-8") as fh:
            d = json.load(fh)
        return d if isinstance(d, dict) else {}
    except (OSError, ValueError):
        return {}


def locale_dirs():
    """Where translation files live: next to the program (yours win), then the ones that ship inside the app."""
    here = os.path.dirname(os.path.abspath(__file__))
    out = []
    exe = os.path.dirname(os.path.abspath(sys.executable))
    for d in (os.path.join(BASE_DIR, "locales"), os.path.join(here, "locales"), os.path.join(exe, "locales"),
              os.path.join(exe, "..", "Resources", "locales"), os.path.join(getattr(sys, "_MEIPASS", here), "locales")):
        if os.path.isdir(d) and d not in out:
            out.append(d)
    return out


def locale_read(code):
    if not re.fullmatch(r"[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})?", code or ""):
        return None
    for d in locale_dirs():
        try:
            with open(os.path.join(d, code + ".json"), encoding="utf-8") as fh:
                j = json.load(fh)
            if isinstance(j, dict) and isinstance(j.get("strings"), dict):
                return j
        except (OSError, ValueError):
            continue
    return None


