SCRUB_H = (540, 270)
SCRUB_SEM = threading.Semaphore(1)       # one at a time, so editing stays responsive


def make_scrub(cid, h):
    """Low-res, every-frame-a-keyframe copy for smooth scrubbing in the Timeline (½ / ¼ playback).
    Same frame timing and start as the normal preview, so it shows the same frames."""
    c = CLIPS.get(cid)
    if not c:
        return
    st = c.setdefault("scrub", {})[h]
    out = os.path.join(UPLOAD_DIR, f"{cid}_s{h}.mp4")
    with SCRUB_SEM:
        if cid not in CLIPS:
            return
        vf = f"scale=-2:'min({h},ih)':flags=bilinear,scale=trunc(iw/2)*2:trunc(ih/2)*2"
        cmd = ["ffmpeg", "-v", "error", "-y", "-ss", f"{c.get('v0', 0):.6f}", "-i", c["path"], "-map", "0:v:0", "-map", "0:a:0?",
               "-vf", vf, "-c:v", "libx264", "-preset", "ultrafast", "-tune", "fastdecode", "-crf", "27" if h > 300 else "25",
               "-g", "1", "-pix_fmt", "yuv420p", "-c:a", "aac", "-b:a", "128k", "-ac", "2", "-movflags", "+faststart",
               "-progress", "pipe:1", "-nostats", out]
        dur = max(0.1, float(c.get("duration") or 0))
        try:
            proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True,
                                    creationflags=NO_WINDOW, encoding="utf-8", errors="replace")
            st["proc"] = proc
            for line in proc.stdout:
                key, _, val = line.strip().partition("=")
                if key == "out_time_us" and val.isdigit():
                    st["pct"] = min(99, int(int(val) / 1e6 / dur * 100))
            proc.wait()
            rc = proc.returncode
        except Exception:
            rc = 1
        st.pop("proc", None)
    if cid not in CLIPS:
        _rm(out)
        return
    if rc == 0 and os.path.exists(out):
        st.update(status="ready", path=out, pct=100)
    else:
        _rm(out)
        st.update(status="error")


@app.post("/api/clip/<cid>/scrub/<int:h>")
def api_clip_scrub(cid, h):
    c = CLIPS.get(cid)
    if not c or h not in SCRUB_H:
        return err("Unknown clip.", 404)
    if c.get("kind", "video") not in ("video", "gif") or c.get("status") != "ready":
        return jsonify({"status": "none"})
    if (c.get("height") or 0) <= h * 1.15 and not c.get("play_path") != c.get("path"):
        return jsonify({"status": "same"})                 # already small: the normal preview is the scrub copy
    st = c.setdefault("scrub", {}).get(h)
    if not st or st.get("status") == "error":
        c["scrub"][h] = {"status": "processing", "pct": 0}
        threading.Thread(target=make_scrub, args=(cid, h), daemon=True).start()
        st = c["scrub"][h]
    return jsonify({"status": st["status"], "pct": st.get("pct", 0), "url": f"/media/scrub/{cid}/{h}"})


@app.get("/media/scrub/<cid>/<int:h>")
def media_scrub(cid, h):
    st = (CLIPS.get(cid) or {}).get("scrub", {}).get(h)
    if st and st.get("status") == "ready":
        return send_file(st["path"], mimetype="video/mp4", conditional=True)
    return err("Not found.", 404)


@app.get("/media/<kind>/<mid>")
def media(kind, mid):
    if kind == "song" and mid in SONGS:
        return send_file(SONGS[mid]["play_path"], conditional=True)
    if kind == "thumb" and mid in CLIPS and CLIPS[mid].get("thumb"):
        return send_file(CLIPS[mid]["thumb"], mimetype="image/jpeg", conditional=True)
    if kind == "image" and mid in CLIPS and CLIPS[mid].get("image"):          # a photo's original (keeps transparency)
        return send_file(CLIPS[mid]["image"], conditional=True)
    if kind == "clip" and mid in CLIPS and CLIPS[mid]["status"] == "ready":
        c = CLIPS[mid]
        return send_file(c["play_path"], mimetype=c["play_mime"], conditional=True)
    return err("Not found.", 404)


def _fnum(v, d, lo, hi):
    try:
        v = float(v)
    except (TypeError, ValueError):
        return d
    if v != v:  # NaN
        return d
    return min(hi, max(lo, v))


# ---------------------------------------------------------------------------
# AI background removal: Robust Video Matting (RVM, ONNX) on this PC. CUDA (RTX) when onnxruntime-gpu is
# installed, else the CPU. One grayscale matte video per clip (same frames as the clip), cached; the
# Expand / Edge clean refinements (OpenCV) are cached per setting; Feather + Threshold are done in FFmpeg.
# ---------------------------------------------------------------------------
AI_DIR = os.path.join(BASE_DIR, "ai_models")
RVM_FILE = "rvm_mobilenetv3_fp32.onnx"
RVM_URL = "https://github.com/PeterL1n/RobustVideoMatting/releases/download/v1.0.0/" + RVM_FILE
MATTE_SEM = threading.Semaphore(1)
_rvm = {}
BGR_MODES = ("transparent", "black", "white", "bin", "color")


def rvm_model():
    """Path of the RVM model; downloaded once into ai_models/ (15 MB) if it isn't there yet."""
    p = os.path.join(AI_DIR, RVM_FILE)
    if os.path.exists(p) and os.path.getsize(p) > 1_000_000:
        return p
    os.makedirs(AI_DIR, exist_ok=True)
    import urllib.request
    tmp = p + ".part"
    urllib.request.urlretrieve(RVM_URL, tmp)
    os.replace(tmp, p)
    return p


_GPU_LIBS = {"done": False}
AI_STATE = {"provider": None, "fallback": False, "reason": "", "probing": False}
AI_LOCK = threading.Lock()


_CU13 = re.compile(r"[\\/](cu13|cuda_?13)[\\/]|-cu13", re.I)


def _nvidia_dirs():
    """site-packages/nvidia/*/bin (Windows) or /lib - the pip CUDA 12 / cuDNN 9 DLLs. CUDA 13 leftovers are skipped:
    their cudnn64_9.dll has the same name as the CUDA 12 one and loading the wrong one crashes."""
    import glob
    import site
    roots = list(getattr(site, "getsitepackages", lambda: [])()) + [site.getusersitepackages()]
    roots += [p for p in sys.path if p.endswith("site-packages")]
    dirs = []
    for r in dict.fromkeys(roots):
        for sub in ("bin", "lib"):
            for d in glob.glob(os.path.join(r, "nvidia", "*", sub)):
                if os.path.isdir(d) and d not in dirs and not _CU13.search(d.replace(r, "")):
                    dirs.append(d)
    return dirs


def setup_gpu_libs():
    """Put the pip NVIDIA DLL folders on the DLL search path *before* onnxruntime loads its CUDA provider."""
    if _GPU_LIBS["done"]:
        return
    _GPU_LIBS["done"] = True
    try:
        dirs = _nvidia_dirs()
        for d in dirs:
            if hasattr(os, "add_dll_directory"):
                try:
                    os.add_dll_directory(d)
                except OSError:
                    pass
        if dirs:
            os.environ["PATH"] = os.pathsep.join(dirs) + os.pathsep + os.environ.get("PATH", "")
    except Exception:
        pass


def _import_ort(verbose=False):
    setup_gpu_libs()
    import onnxruntime as ort
    if hasattr(ort, "preload_dlls"):                       # ORT >= 1.21: loads CUDA / cuDNN from the pip nvidia-* packages
        try:
            ort.preload_dlls(cuda=True, cudnn=True, msvc=True, verbose=verbose)
        except TypeError:
            ort.preload_dlls()
        except Exception as e:
            if verbose:
                print("        preload_dlls failed:", e, flush=True)
    return ort


def _probe_model():
    try:
        return rvm_model()
    except Exception:
        for dp, _dn, files in os.walk(os.environ.get("U2NET_HOME", "")):
            if "u2net.onnx" in files:
                return os.path.join(dp, "u2net.onnx")
    return None


# Windows crash codes -> what they mean for the GPU stack
_CRASH = {3221225501: "0xC000001D illegal instruction - a DLL built for something else was loaded (CUDA 13 ONNX Runtime with CUDA 12 libraries, or two cuDNN copies)",
          3221225477: "0xC0000005 access violation - mismatched CUDA / cuDNN / driver versions",
          3221225781: "0xC0000135 a required DLL was not found",
          3221225785: "0xC0000139 a DLL is the wrong version (entry point not found)",
          3221226505: "0xC0000409 stack buffer overrun / fast-fail inside a native library",
          3221225725: "0xC00000FD stack overflow inside a native library"}
_CU12_DLLS = ["cudart64_12.dll", "cublas64_12.dll", "cublasLt64_12.dll", "cufft64_11.dll", "curand64_10.dll", "cudnn64_9.dll"]


GPU_OPTS_FILE = os.path.join(AI_DIR, "gpu_options.json")
# CUDA provider settings tried in order when the first inference crashes. The default (EXHAUSTIVE) makes cuDNN
# benchmark every convolution kernel on the first run - the most code that runs exactly where the crash happens.
GPU_VARIANTS = [{}, {"cudnn_conv_algo_search": "HEURISTIC"}, {"cudnn_conv_algo_search": "DEFAULT"},
                {"cudnn_conv_algo_search": "DEFAULT", "cudnn_conv_use_max_workspace": "0", "use_tf32": "0",
                 "arena_extend_strategy": "kSameAsRequested"}]


def gpu_options():
    """The CUDA provider options the GPU test found working for this onnxruntime version ({} = defaults)."""
    try:
        with open(GPU_OPTS_FILE, encoding="utf-8") as fh:
            j = json.load(fh)
        import onnxruntime as _o
        return j.get("options", {}) if (not j.get("ort") or j.get("ort") == _o.__version__) else {}
    except Exception:
        return {}


def _gpu_stages(model=None):
    """`app.py --gpu-check --stages`: the GPU test step by step, printing as it goes (flushed), so if a native library
    crashes the process, the last line printed + the faulthandler traceback show exactly where."""
    import faulthandler
    import platform
    faulthandler.enable(file=sys.stderr, all_threads=True)
    P = lambda *a: print(*a, flush=True)
    P(f"[1/8] Python {platform.python_version()} ({sys.executable}) on {platform.platform()}")
    try:
        smi = subprocess.run(["nvidia-smi", "--query-gpu=name,driver_version,memory.total", "--format=csv,noheader"],
                             capture_output=True, text=True, timeout=20, creationflags=NO_WINDOW)
        P("[2/8] NVIDIA:", (smi.stdout or smi.stderr).strip() or "nvidia-smi gave nothing")
        try:
            drv = float((smi.stdout.split(",")[1]).strip().split(".")[0])
            if drv < 528:
                P(f"        !! driver {drv:.0f} is too old for CUDA 12 - update the NVIDIA driver (550 or newer)")
        except Exception:
            pass
    except Exception as e:
        P("[2/8] NVIDIA: nvidia-smi not available -", e)
    import importlib.metadata as md
    pk = {}
    for d in md.distributions():
        n = (d.metadata["Name"] or "").lower().replace("_", "-")
        if n.startswith("onnxruntime") or n.startswith("nvidia-"):
            pk[n] = d.version
    P("[3/8] Packages:", ", ".join(f"{k} {v}" for k, v in sorted(pk.items())) or "none")
    if "onnxruntime" in pk and "onnxruntime-gpu" in pk:
        P("        !! CONFLICT: the CPU 'onnxruntime' and 'onnxruntime-gpu' are both installed (they overwrite each other)")
    g = pk.get("onnxruntime-gpu")
    if g:
        try:
            mm = tuple(int(x) for x in g.split(".")[:2])
            if mm >= (1, 27):
                P(f"        !! onnxruntime-gpu {g} is built for CUDA 13 (Start_Tool.bat installs a CUDA 12 / 11 build)")
        except ValueError:
            pass
    c13 = [k for k in pk if "cu13" in k or k in ("nvidia-cuda-runtime", "nvidia-cudnn", "nvidia-cublas", "nvidia-cufft", "nvidia-curand", "nvidia-cuda-nvrtc")]
    if c13:
        P("        !! CUDA 13 packages present:", ", ".join(c13))
    dirs = _nvidia_dirs()
    P(f"[4/8] NVIDIA DLL folders ({len(dirs)}):")
    for d in dirs:
        P("        " + d)
    if sys.platform == "win32":
        have = {f.lower() for d in dirs for f in os.listdir(d)}
        miss = [f for f in _CU12_DLLS if f.lower() not in have]
        P("        CUDA 12 / cuDNN 9 DLLs:", "all there" if not miss else "MISSING " + ", ".join(miss))
    P("[5/8] import onnxruntime ...")
    import numpy as np
    ort = _import_ort(verbose=False)
    capi = os.path.join(os.path.dirname(ort.__file__), "capi")
    P(f"        onnxruntime {ort.__version__} from {os.path.dirname(ort.__file__)}")
    try:
        from onnxruntime.capi import version_info as _vi
        cv = getattr(_vi, "cuda_version", "")
        P(f"        built for CUDA {cv or '?'} / cuDNN {getattr(_vi, 'cudnn_version', '?')}")
        if sys.platform == "win32" and cv.startswith("11."):
            have = {f.lower() for d in dirs for f in os.listdir(d)}
            need = ["cudart64_110.dll", "cublas64_11.dll", "cublasLt64_11.dll", "cufft64_10.dll", "cudnn64_8.dll"]
            miss = [f for f in need if f.lower() not in have]
            P("        CUDA 11 / cuDNN 8 DLLs:", "all there" if not miss else "MISSING " + ", ".join(miss))
    except Exception:
        pass
    P("        providers built in:", ", ".join(ort.get_available_providers()))
    if sys.platform == "win32":
        P("        onnxruntime_providers_cuda.dll:", "found" if os.path.isfile(os.path.join(capi, "onnxruntime_providers_cuda.dll")) else "MISSING (this is not the GPU build)")
    if os.environ.get("VE_TEST_GPU_CRASH") == "1":           # test hook: simulate a native crash in a DLL
        faulthandler._sigsegv()
    P("[6/8] preload_dlls (CUDA + cuDNN) ...")
    if hasattr(ort, "preload_dlls"):
        try:
            ort.preload_dlls(cuda=True, cudnn=True, msvc=True, verbose=True)
        except TypeError:
            ort.preload_dlls()
        P("        ok")
    else:
        P("        (this onnxruntime has no preload_dlls - using the DLL folders above)")
    model = model or _probe_model()
    if not model:
        raise RuntimeError("no AI model downloaded yet (ai_models\\rvm_mobilenetv3_fp32.onnx)")
    fake = os.environ.get("VE_TEST_FAKE_CUDA") == "1"          # test hook: CPU stands in for CUDA
    if "CUDAExecutionProvider" not in ort.get_available_providers() and not fake:
        raise RuntimeError("this onnxruntime has no CUDA provider (CPU build installed)")
    P(f"[7/8] CUDA session on {os.path.basename(model)} ...")
    so_opt = ort.SessionOptions()
    so_opt.log_severity_level = 1
    try:
        cuda_opts = json.loads(os.environ.get("VE_CUDA_OPTS") or "{}")
    except ValueError:
        cuda_opts = {}
    P("        CUDA provider options:", cuda_opts or "defaults")
    so = ort.InferenceSession(model, so_opt, providers=["CPUExecutionProvider"] if fake else [("CUDAExecutionProvider", cuda_opts), "CPUExecutionProvider"])
    P("        session providers:", so.get_providers())
    if so.get_providers()[0] != "CUDAExecutionProvider" and not fake:
        raise RuntimeError("CUDAExecutionProvider did not load (see the messages above for the DLL)")
    P("[8/8] one inference on the GPU ...")
    feeds = {}
    for i in so.get_inputs():
        shp = [d if isinstance(d, int) and d > 0 else 1 for d in i.shape]
        if i.name == "src" or len(shp) == 4 and shp[1] == 3:
            shp = [1, 3, 256, 256]
        feeds[i.name] = np.array([1.0], np.float32) if i.name == "downsample_ratio" else np.zeros(shp, np.float32)
    if fake and os.environ.get("VE_TEST_INFER_CRASH") and cuda_opts.get("cudnn_conv_algo_search") != os.environ["VE_TEST_INFER_CRASH"]:
        faulthandler._sigsegv()
    so.run(None, feeds)
    P("        GPU OK")
    print("GPUCHECK " + json.dumps({"provider": "CUDAExecutionProvider", "error": ""}), flush=True)
    return 0


def gpu_check_main():
    """`python app.py --gpu-check [--verbose]`: test the GPU for real in a child process (a broken CUDA / cuDNN can
    hard-crash the process that loads it). Exit 0 = the GPU works. --verbose prints the whole step-by-step report;
    the report is always saved to ai_models\\gpu_check.log."""
    if "--stages" in sys.argv:
        try:
            return _gpu_stages()
        except Exception:
            import traceback
            traceback.print_exc()
            sys.stdout.flush()
            return 2
    verbose = "--verbose" in sys.argv

    def attempt(opts):
        env = dict(os.environ, PYTHONUNBUFFERED="1", PYTHONIOENCODING="utf-8", VE_CUDA_OPTS=json.dumps(opts))
        try:
            r = subprocess.run(self_cmd("--gpu-check", "--stages") if FROZEN else [sys.executable, "-X", "faulthandler", os.path.abspath(__file__), "--gpu-check", "--stages"],
                               capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=300,
                               creationflags=NO_WINDOW, cwd=BASE_DIR, env=env)
            return (r.stdout or "") + (("\n" + r.stderr) if r.stderr.strip() else ""), r.returncode
        except subprocess.TimeoutExpired:
            return "the GPU test hung for 5 minutes", -1

    tries = []
    for k, opts in enumerate(GPU_VARIANTS):
        out, rc = attempt(opts)
        tries.append((opts, out, rc))
        if rc == 0 and "GPU OK" in out:
            break
        if "[8/8]" not in out:                  # it didn't even reach the inference: other settings won't help
            break
    ok = rc == 0 and "GPU OK" in out
    if ok:
        try:
            import importlib.metadata as md
            ver = md.version("onnxruntime-gpu")
        except Exception:
            ver = ""
        try:
            os.makedirs(AI_DIR, exist_ok=True)
            with open(GPU_OPTS_FILE, "w", encoding="utf-8") as fh:
                json.dump({"ort": ver, "options": opts}, fh)
        except OSError:
            pass
    if len(tries) > 1:                          # report every attempt, the last one in full
        head = []
        for o, ot, rcx in tries[:-1]:
            fat = next((l.strip() for l in ot.splitlines() if l.startswith(("Windows fatal exception", "Fatal Python error"))), "")
            head.append(f"--- attempt with CUDA options {o or 'defaults'}: exit code {rcx} {fat}")
        out = "\n".join(head) + f"\n--- attempt with CUDA options {opts or 'defaults'}:\n" + out
    lines = [l for l in out.splitlines() if not l.startswith("GPUCHECK ")]
    last = next((l.strip() for l in reversed(lines) if re.match(r"\[\d/8\]", l.strip())), "")
    if ok:
        res = {"provider": "CUDAExecutionProvider", "error": "", "options": opts}
    else:
        if rc in _CRASH or (rc < 0 and (rc & 0xFFFFFFFF) in _CRASH):
            why = f"the GPU test CRASHED with exit code {rc} = {_CRASH.get(rc) or _CRASH.get(rc & 0xFFFFFFFF)}, during: {last}"
        else:
            fatal = next((l.strip() for l in lines if l.startswith(("Fatal Python error", "Windows fatal exception"))), "")
            tb = [l for l in lines if l.strip() and not l.startswith("Extension modules")]
            why = (f"the GPU test CRASHED ({fatal}, exit code {rc})" if fatal else (tb[-1].strip() if tb else f"exit code {rc}")) + (f"  (during: {last})" if last else "")
        dll = next((l.strip() for l in lines if "Error loading" in l or ("LoadLibrary" in l and ".dll" in l)), "")
        if dll:
            why += "  |  " + dll[dll.find("Error loading"):] if "Error loading" in dll else "  |  " + dll
        res = {"provider": "CPUExecutionProvider", "error": why, "exit": rc}
    report = "\n".join(lines).rstrip() + f"\n\nexit code: {rc}" + ("" if ok else f"\nRESULT: {res['error']}")
    try:
        os.makedirs(AI_DIR, exist_ok=True)
        with open(os.path.join(AI_DIR, "gpu_check.log"), "w", encoding="utf-8") as fh:
            fh.write(time.strftime("%Y-%m-%d %H:%M:%S") + "  GPU check\n\n" + report + "\n")
    except Exception:
        pass
    if verbose:
        print(report, flush=True)
        print(("\n  [ok] The GPU works." if ok else f"\n  [!] {res['error']}\n  (saved to {os.path.join(AI_DIR, 'gpu_check.log')})"), flush=True)
    print("GPUCHECK " + json.dumps(res), flush=True)
    return 0 if ok else 2


_PROV_NAME = {"CUDAExecutionProvider": "GPU (CUDA)", "DmlExecutionProvider": "GPU (DirectML)", "CPUExecutionProvider": "CPU"}


def _cpu_fallback(reason, report=None):
    AI_STATE.update(provider="CPUExecutionProvider", fallback=True, reason=reason)
    log.info("\n  [!] ============================================================")
    log.info("  [!] The GPU AI could not start - AI is running on the CPU (slow).")
    log.info(f"  [!] Reason: {reason[:600]}")
    if report:
        log.info("  [!] ---- GPU test report ----")
        for l in report.splitlines()[-40:]:
            log.info("  [!] " + l)
    log.info(f"  [!] Full report: {os.path.join(AI_DIR, 'gpu_check.log')}")
    log.info("  [!] Fix: close the editor and run Start_Tool.bat (or Start_Tool.bat --repair-gpu),")
    log.info("  [!]      and keep the NVIDIA driver up to date.")
    print("  [!] ============================================================\n", flush=True)


def ai_provider():
    """The onnxruntime provider for every AI model in this run, decided once. The GPU is tested in a child process
    first (a CUDA / cuDNN mix-up can hard-crash the process that loads it), so the editor never dies."""
    with AI_LOCK:
        if AI_STATE["provider"]:
            return AI_STATE["provider"]
        if os.environ.get("VE_FORCE_CPU") == "1":
            _cpu_fallback("VE_FORCE_CPU=1 (testing)")
            return AI_STATE["provider"]
        fc = os.path.join(AI_DIR, "gpu_force_cpu.txt")
        if os.path.isfile(fc):                              # Start_Tool.bat switched the GPU off after its test crashed
            AI_STATE.update(provider="CPUExecutionProvider", fallback=True, forced=True,
                            reason="GPU switched off by Start_Tool.bat after the GPU test crashed (ai_models\\gpu_force_cpu.txt)")
            log.info("  [i] AI background removal runs on the CPU: the GPU was switched off after its test crashed with every ONNX Runtime version.")
            print("      Start_Tool.bat --repair-gpu tries the GPU again.", flush=True)
            return AI_STATE["provider"]
        try:
            ort = _import_ort()
            have = ort.get_available_providers()
        except Exception as e:
            AI_STATE.update(provider="CPUExecutionProvider", reason=f"onnxruntime: {e}")
            return AI_STATE["provider"]
        if not any(p in have for p in ("CUDAExecutionProvider", "DmlExecutionProvider")):
            AI_STATE.update(provider="CPUExecutionProvider", fallback=False, reason="no GPU version of onnxruntime")
            return AI_STATE["provider"]
        AI_STATE["probing"] = True
        try:
            r = subprocess.run(self_cmd("--gpu-check"), capture_output=True, text=True,
                               timeout=400, creationflags=NO_WINDOW, cwd=BASE_DIR, env=os.environ.copy())
            line = next((l for l in (r.stdout or "").splitlines()[::-1] if l.startswith("GPUCHECK ")), None)
            res = json.loads(line[9:]) if line else {}
            if r.returncode == 0 and res.get("provider") == "CUDAExecutionProvider":
                AI_STATE.update(provider="CUDAExecutionProvider", fallback=False, reason="")
            elif "DmlExecutionProvider" in have and "CUDAExecutionProvider" not in have:
                AI_STATE.update(provider="DmlExecutionProvider", fallback=False, reason="")
            else:
                rep = None
                try:
                    with open(os.path.join(AI_DIR, "gpu_check.log"), encoding="utf-8") as fh:
                        rep = fh.read()
                except OSError:
                    pass
                _cpu_fallback(res.get("error") or f"the GPU test failed (exit code {r.returncode})", rep)
        except subprocess.TimeoutExpired:
            _cpu_fallback("the GPU test timed out")
        except Exception as e:
            _cpu_fallback(str(e))
        finally:
            AI_STATE["probing"] = False
        return AI_STATE["provider"]


def ai_providers():
    p = ai_provider()
    if p == "CUDAExecutionProvider":
        o = gpu_options()
        return [("CUDAExecutionProvider", o) if o else p, "CPUExecutionProvider"]
    return [p, "CPUExecutionProvider"] if p != "CPUExecutionProvider" else ["CPUExecutionProvider"]


def ai_label():
    p = AI_STATE.get("provider")
    if not p:
        return None
    if p == "CPUExecutionProvider":
        return ("CPU (slow, GPU off)" if AI_STATE.get("forced") else "CPU (slow)") if AI_STATE.get("fallback") else "CPU"
    return _PROV_NAME.get(p, p)


def rvm_session():
    """(session, provider label). The GPU (CUDA / DirectML) when it really works, else the CPU - never a crash."""
    if "s" in _rvm:
        return _rvm["s"], _rvm["prov"]
    ort = _import_ort()
    prov = ai_provider()
    model = rvm_model()
    try:
        so = ort.InferenceSession(model, providers=ai_providers())
        if so.get_providers()[0] != prov:
            raise RuntimeError(f"{_PROV_NAME.get(prov, prov)} did not load")
    except Exception as e:
        if prov == "CPUExecutionProvider":
            raise RuntimeError(f"The AI model couldn't start: {e}")
        _cpu_fallback(str(e))
        so = ort.InferenceSession(model, providers=["CPUExecutionProvider"])
    _rvm.update(s=so, prov=ai_label())
    return _rvm["s"], _rvm["prov"]


def ai_selftest_main():
    """Child process (python app.py --ai-selftest): load the background-removal model on the CPU and push one frame through it.
    If anything here crashes, only this child dies - the editor then hides the feature instead of showing a broken button."""
    try:
        import numpy as np
        ort = _import_ort()
        so = ort.InferenceSession(rvm_model(), providers=["CPUExecutionProvider"])
        feeds = {}
        for i in so.get_inputs():
            shp = [d if isinstance(d, int) and d > 0 else 1 for d in i.shape]
            if i.name == "src" or len(shp) == 4 and shp[1] == 3:
                shp = [1, 3, 192, 192]
            feeds[i.name] = np.array([1.0], np.float32) if i.name == "downsample_ratio" else np.zeros(shp, np.float32)
        out = so.run(None, feeds)
        if not out or out[0] is None:
            raise RuntimeError("the model returned nothing")
        print("AISELFTEST ok", flush=True)
        return 0
    except Exception as e:
        print("AISELFTEST fail " + str(e).replace("\n", " ")[:300], flush=True)
        return 3


def ai_boot():
    """Once, right after the editor starts (in the background): does the video AI cut-out work on this PC at all?
    1. the model on the CPU, in a child process   -> if that fails the feature is switched off for this run (the page hides it)
    2. the GPU, also in a child process           -> GPU when it really works, otherwise the CPU, quietly"""
    try:
        r = subprocess.run(self_cmd("--ai-selftest"), capture_output=True, text=True, timeout=300,
                           creationflags=NO_WINDOW, cwd=BASE_DIR, env=os.environ.copy())
        line = next((l for l in (r.stdout or "").splitlines()[::-1] if l.startswith("AISELFTEST ")), "")
        if r.returncode != 0 or not line.startswith("AISELFTEST ok"):
            why = line[16:] if line.startswith("AISELFTEST fail") else f"the test stopped (exit code {r.returncode})"
            AI_STATE.update(dead=True, reason=why)
            print("  [i] AI background removal is switched off for this run: its self-test failed (" + why[:160] + ").", flush=True)
            print("      Everything else works. Start_Tool.bat --repair-gpu reinstalls the AI parts.", flush=True)
        else:
            ai_provider()                                 # GPU test (child process) -> GPU or a quiet CPU fallback
            print(f"  [ok] AI background removal self-test passed - running on {ai_label() or 'CPU'}", flush=True)
    except subprocess.TimeoutExpired:
        AI_STATE.update(dead=True, reason="the self-test timed out")
    except Exception as e:
        AI_STATE.update(dead=True, reason=str(e))
    try:
        import importlib.util as _iu
        AI_STATE["rembg"] = bool(_iu.find_spec("rembg"))
    except Exception:
        AI_STATE["rembg"] = False
    AI_STATE["tested"] = True


@app.get("/api/ai/status")
def api_ai_status():
    return jsonify(provider=AI_STATE.get("provider"), label=ai_label(), fallback=bool(AI_STATE.get("fallback")),
                   reason=AI_STATE.get("reason", ""), probing=bool(AI_STATE.get("probing")),
                   tested=bool(AI_STATE.get("tested")), usable=not AI_STATE.get("dead"), cpu=AI_STATE.get("provider") == "CPUExecutionProvider",
                   rembg=AI_STATE.get("rembg", True))


def rvm_run(sess, feeds):
    """One RVM step; if the GPU fails mid-run, switch to the CPU and carry on (same recurrent state)."""
    try:
        return sess, sess.run(None, feeds)
    except Exception as e:
        if AI_STATE.get("provider") == "CPUExecutionProvider":
            raise
        _cpu_fallback(f"GPU run failed: {e}")
        _rvm.clear()
        sess, _ = rvm_session()
        return sess, sess.run(None, feeds)


def _video_info(path):
    info = probe(path)
    v = next((x for x in info.get("streams", []) if x.get("codec_type") == "video"), {})
    num, _, den = (v.get("avg_frame_rate") if v.get("avg_frame_rate") not in (None, "0/0") else v.get("r_frame_rate") or "30/1").partition("/")
    fps = float(num) / float(den or 1) if float(den or 1) else 30.0
    vst = float(v.get("start_time") or 0)
    fst = float(info.get("format", {}).get("start_time") or 0)
    return int(v.get("width") or 0), int(v.get("height") or 0), (fps if 1 < fps < 241 else 30.0), max(0.0, vst - fst), \
        f"{num}/{den or 1}" if 1 < fps < 241 else "30"


def make_matte(cid):
    """The raw matte (white = the person / subject) for the whole clip, at its own frame rate."""
    import numpy as np
    c = CLIPS.get(cid)
    st = c["matte"]
    try:
        with MATTE_SEM:
            if cid not in CLIPS:
                return
            st.update(stage="Loading the AI model", pct=0)
            sess, prov = rvm_session()
            st["provider"] = prov
            src = c["path"]
            w, h, fps, vd, rate = _video_info(src)
            if not w or not h:
                raise RuntimeError("This clip has no picture.")
            k = min(1.0, 1280 / max(w, h))
            pw, ph = max(2, int(round(w * k / 2)) * 2), max(2, int(round(h * k / 2)) * 2)
            ds = np.array([min(1.0, 384 / min(pw, ph))], np.float32)
            out = os.path.join(UPLOAD_DIR, f"{cid}_matte.mp4")
            dec = subprocess.Popen(["ffmpeg", "-v", "error", "-i", src, "-map", "0:v:0", "-vf", f"scale={pw}:{ph}:flags=bilinear",
                                    "-fps_mode", "passthrough", "-f", "rawvideo", "-pix_fmt", "rgb24", "-"],
                                   stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, creationflags=NO_WINDOW)
            enc = subprocess.Popen(["ffmpeg", "-v", "error", "-y", "-f", "rawvideo", "-pix_fmt", "gray", "-s", f"{pw}x{ph}", "-r", rate, "-i", "-",
                                    "-c:v", "libx264", "-preset", "veryfast", "-crf", "8", "-pix_fmt", "yuv420p", "-g", str(max(1, int(fps))), out],
                                   stdin=subprocess.PIPE, stderr=subprocess.DEVNULL, creationflags=NO_WINDOW)
            st.update(proc=dec, proc2=enc, stage="Finding the subject")
            total = max(1, int(round((c.get("duration") or 1) * fps)))
            rec = [np.zeros((1, 1, 1, 1), np.float32)] * 4
            n = 0
            fb = pw * ph * 3
            while True:
                buf = dec.stdout.read(fb)
                if len(buf) < fb or st.get("cancel"):
                    break
                x = np.frombuffer(buf, np.uint8).reshape(ph, pw, 3).transpose(2, 0, 1)[None].astype(np.float32) / 255
                sess, (_, pha, *rec) = rvm_run(sess, {"src": x, "r1i": rec[0], "r2i": rec[1], "r3i": rec[2], "r4i": rec[3], "downsample_ratio": ds})
                st["provider"] = ai_label()
                enc.stdin.write((pha[0, 0] * 255 + 0.5).clip(0, 255).astype(np.uint8).tobytes())
                n += 1
                st["pct"] = min(99, int(n / total * 100))
            enc.stdin.close()
            enc.wait()
            dec.kill()
            if st.get("cancel") or cid not in CLIPS:
                _rm(out)
                st["status"] = "cancelled"
                return
            if enc.returncode != 0 or n == 0:
                raise RuntimeError("Couldn't write the matte.")
            st.update(status="ready", path=out, pct=100, vd=vd, w=pw, h=ph, frames=n, stage="Done")
    except Exception as e:
        st.update(status="error", error=str(e))
    finally:
        st.pop("proc", None)
        st.pop("proc2", None)


def matte_key(expand, clean):
    return f"e{int(expand)}c{int(clean)}"


def refine_matte(cid, expand, clean):
    """Expand (+) / Contract (-) and Edge clean (open + close) with OpenCV; cached per setting."""
    import numpy as np
    import cv2
    c = CLIPS[cid]
    m = c["matte"]
    key = matte_key(expand, clean)
    ref = c.setdefault("mref", {})
    if key == "e0c0":
        ref[key] = {"status": "ready", "path": m["path"]}
        return
    st = ref[key]
    try:
        out = os.path.join(UPLOAD_DIR, f"{cid}_matte_{key}.mp4")
        w, h, fps, _, rate = _video_info(m["path"])
        k = w / max(1, c.get("width") or w)                        # settings are in clip pixels; the matte may be smaller
        cap = cv2.VideoCapture(m["path"])
        enc = subprocess.Popen(["ffmpeg", "-v", "error", "-y", "-f", "rawvideo", "-pix_fmt", "gray", "-s", f"{w}x{h}", "-r", rate, "-i", "-",
                                "-c:v", "libx264", "-preset", "veryfast", "-crf", "8", "-pix_fmt", "yuv420p", "-g", str(max(1, int(fps))), out],
                               stdin=subprocess.PIPE, stderr=subprocess.DEVNULL, creationflags=NO_WINDOW)
        ker = lambda r: cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (2 * r + 1, 2 * r + 1))
        rc = max(1, round(clean * k)) if clean else 0
        re_ = max(1, round(abs(expand) * k)) if expand else 0
        n, tot = 0, max(1, m.get("frames") or 1)
        while True:
            ok, fr = cap.read()
            if not ok:
                break
            g = fr[:, :, 0]
            if rc:
                g = cv2.morphologyEx(g, cv2.MORPH_OPEN, ker(rc))
                g = cv2.morphologyEx(g, cv2.MORPH_CLOSE, ker(rc))
            if re_:
                g = (cv2.dilate if expand > 0 else cv2.erode)(g, ker(re_))
            enc.stdin.write(np.ascontiguousarray(g).tobytes())
            n += 1
            st["pct"] = min(99, int(n / tot * 100))
        cap.release()
        enc.stdin.close()
        enc.wait()
        if enc.returncode != 0 or not n:
            raise RuntimeError("Couldn't refine the matte.")
        st.update(status="ready", path=out, pct=100)
    except Exception as e:
        st.update(status="error", error=str(e))


def matte_job(cid, expand, clean):
    c = CLIPS.get(cid)
    if not c:
        return
    if c["matte"].get("status") == "processing" and "path" not in c["matte"]:
        make_matte(cid)
    if c["matte"].get("status") == "ready" and cid in CLIPS:
        refine_matte(cid, expand, clean)


def matte_state(cid, expand=0, clean=0, start=True):
    """Where the matte for this clip + refinement is: {status, pct, stage, url, provider, error}."""
    c = CLIPS.get(cid)
    if not c:
        return {"status": "error", "error": "Unknown clip."}
    key = matte_key(expand, clean)
    m = c.setdefault("matte", {})
    if not m or m.get("status") in ("error", "cancelled"):
        if not start:
            return {"status": "none"}
        c["matte"] = m = {"status": "processing", "pct": 0, "stage": "Waiting"}
        ref = c.setdefault("mref", {})
        ref[key] = {"status": "processing", "pct": 0}
        threading.Thread(target=matte_job, args=(cid, expand, clean), daemon=True).start()
    elif m.get("status") == "ready":
        ref = c.setdefault("mref", {})
        r = ref.get(key)
        if not r or r.get("status") == "error":
            if not start:
                return {"status": "none"}
            ref[key] = {"status": "processing", "pct": 0}
            if key == "e0c0":
                refine_matte(cid, expand, clean)
            else:
                threading.Thread(target=refine_matte, args=(cid, expand, clean), daemon=True).start()
    r = (c.get("mref") or {}).get(key) or {}
    if m.get("status") == "error":
        return {"status": "error", "error": m.get("error")}
    if m.get("status") != "ready":
        return {"status": "processing", "pct": m.get("pct", 0), "stage": m.get("stage", "Finding the subject"), "provider": m.get("provider")}
    if r.get("status") == "error":
        return {"status": "error", "error": r.get("error")}
    if r.get("status") != "ready":
        return {"status": "processing", "pct": r.get("pct", 0), "stage": "Refining the edges", "provider": m.get("provider")}
    return {"status": "ready", "url": f"/media/matte/{cid}/{key}", "provider": m.get("provider"), "vd": m.get("vd", 0)}


def parse_bgr(b):
    """Background removal settings from the page (None = off)."""
    if not isinstance(b, dict) or not b.get("on"):
        return None
    mode = b.get("bg") if b.get("bg") in BGR_MODES else "transparent"
    bc = CLIPS.get(b.get("bgClip")) if mode == "bin" else None
    if mode == "bin" and not (bc and bc.get("status") == "ready"):
        mode = "black"
    col = str(b.get("color") or "")
    if not re.fullmatch(r"#[0-9a-fA-F]{6}", col):
        col = "#000000"
    return {"bg": mode, "bgClip": bc, "color": col, "feather": _fnum(b.get("feather"), 2, 0, 50), "expand": int(_fnum(b.get("expand"), 0, -20, 20)),
            "thresh": _fnum(b.get("thresh"), 0, 0, 100), "clean": int(_fnum(b.get("clean"), 0, 0, 10))}


def bgr_matte_clip(cid, bgr, what):
    """A clip-like record for the refined matte (same timing as the clip), or ValueError if it isn't ready."""
    clip = CLIPS[cid]
    st = matte_state(cid, bgr["expand"], bgr["clean"], start=False)
    if st.get("status") != "ready":
        raise ValueError(f"Background removal for {what} isn't ready yet. Wait for it to finish (the Effects panel shows the progress), then render.")
    path = CLIPS[cid]["mref"][matte_key(bgr["expand"], bgr["clean"])]["path"]
    return {"path": path, "duration": clip.get("duration") or 0, "v0": max(0.0, clip.get("v0", 0) - st.get("vd", 0)), "kind": "video"}


def bgr_matte_filters(bgr):
    """Threshold (lut) then Feather (gblur) on the matte."""
    f = ["format=gray"]
    t = bgr["thresh"] / 100 * 0.98
    if t > 0.001:
        f.append(f"lut=y='clip((val-{t * 255:.3f})/{1 - t:.5f},0,255)'")
    if bgr["feather"] >= 0.3:
        f.append(f"gblur=sigma={bgr['feather'] / 2:.3f}:steps=3")
    return ",".join(f)


def bgr_background(bgr, w, h, L, inputs, n_in, chains, lab):
    """Background behind the cut-out subject, w x h for L frames -> [lab]. None for Transparent."""
    if bgr["bg"] == "transparent":
        return None
    if bgr["bg"] in ("black", "white", "color"):
        col = "0x" + bgr.get("color", "#000000")[1:] if bgr["bg"] == "color" else bgr["bg"]
        chains.append(f"color=c={col}:s={w}x{h}:r={FPS}:d={L / FPS + 1:.4f},trim=end_frame={L + 1},setpts=PTS-STARTPTS,format=rgba[{lab}]")
        return f"[{lab}]"
    bc = bgr["bgClip"]
    if bc.get("kind") == "photo":
        inputs.extend(["-loop", "1", "-framerate", str(FPS), "-t", f"{L / FPS + 1:.4f}", "-i", os.path.basename(bc.get("image") or bc["path"])])
        pick = f"trim=end_frame={L + 1}"
    else:
        inputs.extend(["-stream_loop", "-1", "-ss", f"{bc.get('v0', 0):.4f}", "-t", f"{L / FPS + 1:.4f}", "-i", os.path.basename(bc["path"])])
        pick = f"setpts=PTS-STARTPTS,fps={FPS}:round=up,trim=end_frame={L + 1}"
    idx = n_in[0]
    n_in[0] += 1
    chains.append(f"[{idx}:v]{pick},setpts=PTS-STARTPTS,{fill_filter('crop', w, h)},format=rgba[{lab}]")
    return f"[{lab}]"


# ---------------------------------------------------------------------------
# Timeline colour: Lift / Gamma / Gain (per R, G, B) + a .cube LUT (FFmpeg lut3d)
# ---------------------------------------------------------------------------
LUTS = {}


def parse_grade(g):
    if not isinstance(g, dict):
        return None
    ch = lambda k, d, lo, hi: [_fnum((g.get(k) or [d, d, d])[i] if isinstance(g.get(k), list) and len(g.get(k)) == 3 else d, d, lo, hi) for i in range(3)]
    lift, gamma, gain = ch("lift", 0, -0.5, 0.5), ch("gamma", 1, 0.2, 5), ch("gain", 1, 0, 4)
    lut = LUTS.get(g.get("lut")) if g.get("lut") else None
    amt = _fnum(g.get("lutAmt"), 100, 0, 100) / 100
    if lift == [0, 0, 0] and gamma == [1, 1, 1] and gain == [1, 1, 1] and not lut:
        return None
    return {"lift": lift, "gamma": gamma, "gain": gain, "lut": lut, "lutAmt": amt}


def grade_filters(gr):
    """Lift / Gamma / Gain: x' = (lift + x * (gain - lift)) ^ (1 / gamma), per channel (= the preview's SVG filter)."""
    out = []
    if gr["lift"] != [0, 0, 0] or gr["gamma"] != [1, 1, 1] or gr["gain"] != [1, 1, 1]:
        ex = [f"255*pow(clip({gr['lift'][i]:.5f}+val/255*{gr['gain'][i] - gr['lift'][i]:.5f},0,1),{1 / gr['gamma'][i]:.5f})" for i in range(3)]
        out.append(f"lutrgb=r='{ex[0]}':g='{ex[1]}':b='{ex[2]}'")
    if gr["lut"]:
        rel = os.path.relpath(gr["lut"]["path"], UPLOAD_DIR).replace(chr(92), "/")
        out.append(f"lut3d=file='{rel}':interp=tetrahedral")
    return out



DUCK_THRESHOLD, DUCK_RATIO, DUCK_ATTACK_MS, DUCK_RELEASE_MS = 0.012, 16, 20, 500     # Auto-duck (music under the video's sound)
DUCK_GAIN = 0.18                                     # what the page's preview turns the music down to (about -15 dB)


def kf_ease(c, prop, k0, k1):
    """How the stretch between two keyframes moves: 'lin', 'in' (slow arrival), 'out' (slow start) or 'io' (both = an S curve).
    A keyframe's own setting is Ease Out (leaving it slowly), Ease In (arriving slowly) or Ease In-Out."""
    ke = (c.get("ke") or {}).get(prop) or {}
    out0, in1 = ke.get(k0) in ("out", "io"), ke.get(k1) in ("in", "io")
    return "io" if out0 and in1 else "out" if out0 else "in" if in1 else "lin"


def kf_curve(mode, q):
    return q * q * (3 - 2 * q) if mode == "io" else q * q if mode == "out" else q * (2 - q) if mode == "in" else q


def kf_value(c, prop, k):
    """Value of a (maybe keyframed) property at clip-local frame k: between keyframes it follows their easing, held outside."""
    ks = c["kf"].get(prop)
    if not ks:
        return c["p"][prop]
    if k <= ks[0][0]:
        return ks[0][1]
    if k >= ks[-1][0]:
        return ks[-1][1]
    for (k0, v0), (k1, v1) in zip(ks, ks[1:]):
        if k0 <= k <= k1:
            q = kf_curve(kf_ease(c, prop, k0, k1), (k - k0) / (k1 - k0))
            return [v0[0] + (v1[0] - v0[0]) * q, v0[1] + (v1[1] - v0[1]) * q] if prop == "pos" else v0 + (v1 - v0) * q
    return ks[-1][1]


def kf_expr(c, prop, T, comp=None):
    """The same piecewise-linear curve as an FFmpeg expression of T (clip-local seconds):
    v0 + sum((v[i+1]-v[i]) * clip((T - t[i]) / (t[i+1]-t[i]), 0, 1))."""
    ks = c["kf"].get(prop)
    val = (lambda v: v[comp]) if comp is not None else (lambda v: v)
    if not ks:
        return f"{val(c['p'][prop]):.6f}"
    terms = [f"{val(ks[0][1]):.6f}"]
    for (k0, v0), (k1, v1) in zip(ks, ks[1:]):
        dv = val(v1) - val(v0)
        if abs(dv) < 1e-9:
            continue
        q = f"clip(({T}-{k0 / FPS:.6f})/{(k1 - k0) / FPS:.6f},0,1)"
        mode = kf_ease(c, prop, k0, k1)                  # (the same curves as kf_curve, written out for FFmpeg)
        q = f"({q}*{q}*(3-2*{q}))" if mode == "io" else f"({q}*{q})" if mode == "out" else f"({q}*(2-{q}))" if mode == "in" else q
        terms.append(f"{dv:.6f}*{q}")
    return "(" + "+".join(terms) + ")"


# ---------------------------------------------------------------------------
# Timeline text layers: CapCut-style In / Out / Loop animations.
# The maths is written once (txa_motion / txa_look) and run two ways: with plain numbers
# (per-frame opacity, blur, typewriter, motion blur -> sendcmd) and with FFmpeg expression
# objects (position, scale, rotation, 3D flip -> the perspective filter's corner expressions).
# The browser preview (txaMotion / txaLook in the page) is the same formulas line for line.
# ---------------------------------------------------------------------------
import math as _math

TXA_IN = ("none", "typewriter", "fade", "slideup", "pop", "blurin", "flipup", "bounce", "glitch", "scatter")
TXA_OUT = ("none", "fadeout", "slidedown", "shrink", "blurout", "scatterout")
TXA_LOOP = ("none", "pulse", "flicker", "wave", "glitch", "neon")
TXA_SLIDE = 160.0          # Slide Up / Slide Down travel (px)
TXA_BLUR = 24.0            # Blur In / Blur Out: starting / ending blur (sigma, px)
TXA_PERSP = 1400.0         # Flip Up: camera distance for the 3D tilt (px)
TXA_SIGMAX = 30.0          # blur cap in the text picture's own pixels
TXA_EO = 1 - _math.exp(-6)                       # ease-out 1-exp(-6t), scaled to land exactly on 1
TXA_S0, TXA_S1 = 1 / (1 + _math.exp(5)), 1 / (1 + _math.exp(-5))   # sigmoid ends (ease-in-out)


class FX:
    """A tiny FFmpeg-expression builder: arithmetic on FX objects makes expression text."""
    __slots__ = ("e",)

    def __init__(self, e):
        self.e = e

    @staticmethod
    def s(v):
        return v.e if isinstance(v, FX) else f"({float(v):.9g})"

    def _b(self, o, op, rev=False):
        a, b = (FX.s(o), self.e) if rev else (self.e, FX.s(o))
        return FX(f"({a}{op}{b})")

    def __add__(self, o): return self._b(o, "+")
    def __radd__(self, o): return self._b(o, "+", True)
    def __sub__(self, o): return self._b(o, "-")
    def __rsub__(self, o): return self._b(o, "-", True)
    def __mul__(self, o): return self._b(o, "*")
    def __rmul__(self, o): return self._b(o, "*", True)
    def __truediv__(self, o): return self._b(o, "/")
    def __rtruediv__(self, o): return self._b(o, "/", True)
    def __neg__(self): return FX(f"(-{self.e})")


class _MNum:
    exp, sin, cos, floor = staticmethod(_math.exp), staticmethod(_math.sin), staticmethod(_math.cos), staticmethod(_math.floor)
    abs = staticmethod(abs)

    @staticmethod
    def clip(x, a, b):
        return min(b, max(a, x))


class _MExpr:
    exp = staticmethod(lambda x: FX(f"exp({FX.s(x)})"))
    sin = staticmethod(lambda x: FX(f"sin({FX.s(x)})"))
    cos = staticmethod(lambda x: FX(f"cos({FX.s(x)})"))
    abs = staticmethod(lambda x: FX(f"abs({FX.s(x)})"))
    floor = staticmethod(lambda x: FX(f"floor({FX.s(x)})"))
    clip = staticmethod(lambda x, a, b: FX(f"clip({FX.s(x)},{FX.s(a)},{FX.s(b)})"))


def txa_eo(M, q):
    """Ease-out: 1 - exp(-6t) (normalised so it ends exactly on 1)."""
    return (1 - M.exp(-6 * q)) / TXA_EO


def txa_eio(M, q):
    """Ease-in-out: the sigmoid 1 / (1 + exp(-10 (t - 0.5))) (normalised to 0..1)."""
    return (1 / (1 + M.exp(-10 * (q - 0.5))) - TXA_S0) / (TXA_S1 - TXA_S0)


def txa_spring(M, q):
    """Bounce / Pop: ease-out + a damped spring, amplitude * exp(-decay t) * sin(frequency t)."""
    return txa_eo(M, q) + 0.9 * M.exp(-4 * q) * M.sin(2 * _math.pi * q)


def txa_hash(M, s):
    """A repeatable 0..1 'random' number for step s (the same in the page)."""
    r = M.sin(s * 12.9898 + 78.233) * 43758.5453
    return r - M.floor(r)


def txa_norm(a):
    """Clean an animation dict from the page: {in: {type, dur}, out: {...}, loop: {...}}."""
    a = a or {}
    out = {}
    for slot, names, dflt in (("in", TXA_IN, 0.4), ("out", TXA_OUT, 0.4), ("loop", TXA_LOOP, 0.5)):
        v = a.get(slot) or {}
        t = v.get("type") if v.get("type") in names else "none"
        out[slot] = {"type": t, "dur": _fnum(v.get("dur"), dflt, 0.1, 2.0)}
    return out


def txa_durs(a, L):
    """Effective In / Out lengths (s): squeezed together when the clip is shorter than both."""
    din = a["in"]["dur"] if a["in"]["type"] != "none" else 0.0
    dout = a["out"]["dur"] if a["out"]["type"] != "none" else 0.0
    if din + dout > L > 0:
        k = L / (din + dout)
        din, dout = din * k, dout * k
    return din, dout


def txa_motion(M, a, u, L, size):
    """Movement channels at clip-local time u (s): dx, dy (px), sc (scale x), fa (3D flip, degrees)."""
    din, dout = txa_durs(a, L)
    dx, dy, sc, fa = 0.0, 0.0, 1.0, 0.0
    ti, to, tl = a["in"]["type"], a["out"]["type"], a["loop"]["type"]
    if din > 0:
        qi = M.clip(u / din, 0, 1)
        if ti == "slideup":
            dy = dy + TXA_SLIDE * (1 - txa_eo(M, qi))
        elif ti == "pop":
            sc = sc * txa_spring(M, qi)
        elif ti == "flipup":
            fa = fa + 90 * (1 - txa_eo(M, qi))
        elif ti == "bounce":                     # drops in from above and bounces to rest
            dy = dy - 1.4 * TXA_SLIDE * M.abs(M.cos(3 * _math.pi * qi)) * (1 - qi) * (1 - qi)
        elif ti == "glitch":                     # jitters sideways, settling as it lands (a new offset every 2 frames)
            dx = dx + 0.35 * size * (1 - qi) * (2 * txa_hash(M, M.floor(u * 15 + 1e-6)) - 1)
    if dout > 0:
        vo = M.clip((u + 1.0 / FPS - (L - dout)) / dout, 0, 1)
        if to == "slidedown":
            dy = dy + TXA_SLIDE * txa_eio(M, vo)
        elif to == "shrink":
            sc = sc * (1 - txa_eio(M, vo))
    P = a["loop"]["dur"]
    if tl == "pulse":
        sc = sc * (1 + 0.05 * (0.5 - 0.5 * M.cos(2 * _math.pi * u / P)))
    elif tl == "wave":
        dy = dy - 0.12 * size * M.sin(2 * _math.pi * u / P)
    elif tl == "glitch":                         # a short sideways burst at the start of every cycle
        ph = u / P - M.floor(u / P)
        dx = dx + 0.3 * size * M.clip((0.18 - ph) * 1e6, 0, 1) * (2 * txa_hash(M, M.floor(u * 15 + 1e-6)) - 1)
    return dx, dy, sc, fa


def txa_flicker(u, P):
    s = _math.floor(u / (P / 6) + 1e-9)
    r = _math.sin(s * 12.9898 + 78.233) * 43758.5453
    r -= _math.floor(r)
    return 0.12 if r < 0.2 else 0.55 if r < 0.32 else 1.0


def txa_look(a, u, L):
    """Opacity multiplier + blur (sigma px) at time u (numbers only)."""
    din, dout = txa_durs(a, L)
    al, bl = 1.0, 0.0
    M = _MNum
    ti, to = a["in"]["type"], a["out"]["type"]
    if din > 0:
        qi = M.clip(u / din, 0, 1)
        if ti == "fade":
            al *= txa_eo(M, qi)
        elif ti in ("slideup", "flipup"):
            al *= txa_eo(M, M.clip(2 * qi, 0, 1))
        elif ti == "pop":
            al *= txa_eo(M, M.clip(3 * qi, 0, 1))
        elif ti == "blurin":
            al *= txa_eo(M, qi)
            bl += TXA_BLUR * (1 - txa_eo(M, qi))
        elif ti == "bounce":
            al *= txa_eo(M, M.clip(4 * qi, 0, 1))
        elif ti == "glitch" and qi < 1:
            al *= 0.35 if txa_hash(M, _math.floor(u * 15 + 1e-6) + 7) < 0.3 else 1.0
    if dout > 0:
        vo = M.clip((u + 1.0 / FPS - (L - dout)) / dout, 0, 1)
        if to == "fadeout":
            al *= 1 - txa_eio(M, vo)
        elif to in ("slidedown", "shrink"):
            al *= 1 - txa_eio(M, M.clip(2 * vo - 1, 0, 1))
        elif to == "blurout":
            al *= 1 - txa_eio(M, vo)
            bl += TXA_BLUR * txa_eio(M, vo)
    if a["loop"]["type"] == "flicker":
        al *= txa_flicker(u, a["loop"]["dur"])
    elif a["loop"]["type"] == "neon":            # a neon tube: breathes, with the odd dropout
        P = a["loop"]["dur"]
        al *= 0.86 + 0.14 * _math.sin(2 * _math.pi * u / P)
        if txa_hash(M, _math.floor(u / (P / 8) + 1e-9) + 3) < 0.07:
            al *= 0.35
    return al, bl


def txa_mb(v):
    """Motion blur (sigma px) for an edge moving v px per frame: slow = sharp, fast = smeared."""
    return 0.0 if v < 4 else min(24.0, 0.22 * (v - 4))


def txa_pad(sig):
    """Clear margin (px) added round the text picture for a blur of this sigma."""
    return int(_math.ceil(3 * sig)) + 2 if sig > 0 else 0


def txa_chars(a, k, L, n):
    """Typewriter: how many characters show on clip-local frame k."""
    din, _ = txa_durs(a, L)
    if a["in"]["type"] == "scatter" and din > 0 and n > 0:        # Letter Scatter: n pictures of the letters settling, spread over the In time
        nin = max(1, int(_math.floor(din * FPS + 0.5)))
        return n if k >= nin else min(n - 1, int(k * n // nin))
    if a["in"]["type"] != "typewriter" or din <= 0 or n <= 0:
        return n
    nin = max(1, int(_math.floor(din * FPS + 0.5)))
    return n if k >= nin else min(n, int(_math.floor((k + 1) * n / nin)))


def txa_frame(c, k):
    """Everything the text render needs for frame k: opacity, blur sigma X / Y in image px."""
    t, N = c["media"]["text"], c["dur"]
    a, L, size = t["anim"], N / FPS, t["size"]
    bw, bh = t["box"]
    u = k / FPS
    m = txa_motion(_MNum, a, u, L, size)
    m2 = txa_motion(_MNum, a, (k - 1 if k > 0 else k + 1) / FPS, L, size)
    us = kf_value(c, "scale", k) / 100
    S = us * m[2]
    al, bl = txa_look(a, u, L)
    rad = lambda d: d * _math.pi / 180
    vy = abs(m[1] - m2[1]) + abs(_math.cos(rad(m[3])) - _math.cos(rad(m2[3]))) * bh / 2 * S
    vs = abs(m[2] - m2[2]) * us * max(bw, bh) / 2
    iso = (bl ** 2 + txa_mb(vs) ** 2) ** 0.5
    sy = (iso ** 2 + txa_mb(vy) ** 2) ** 0.5
    Sx = max(0.05, S)
    Sy = max(0.05, S * max(0.2, _math.cos(rad(m[3]))))
    sgx, sgy = min(TXA_SIGMAX, iso / Sx), min(TXA_SIGMAX, sy / Sy)
    op = kf_value(c, "opacity", k) / 100 * al
    return max(0.0, min(1.0, op)), (sgx if sgx >= 0.3 else 0.0), (sgy if sgy >= 0.3 else 0.0)


def _png_from_data_url(url, path):
    import base64
    if not isinstance(url, str) or not url.startswith("data:image/png;base64,"):
        raise ValueError("A text layer's picture is missing - select it and try again.")
    with open(path, "wb") as fh:
        fh.write(base64.b64decode(url.split(",", 1)[1]))


def _link(src, dst):
    try:
        os.link(src, dst)
    except OSError:
        shutil.copyfile(src, dst)


def tl_text_layer(c, W, H, inputs, n_in, chains, li, tag, skip=0):
    """A text clip -> a full-frame RGBA layer at (0, 0). The browser drew the styled text (same
    code as the Image Editor) into a PNG; FFmpeg animates it: typewriter frames, opacity + blur
    per frame (sendcmd), then position / scale / rotation / 3D flip via perspective expressions."""
    m, N = c["media"], c["dur"]
    t = m["text"]
    W0, H0 = int(m["w"]), int(m["h"])
    rel = lambda p: os.path.relpath(p, UPLOAD_DIR).replace(chr(92), "/")
    full = f"{tag}_tx{li}.png"
    vid = t.get("video")
    if not vid:
        _png_from_data_url(t["img"], full)
    a, L = t["anim"], N / FPS
    ss = float(t.get("ss") or 1)          # the page draws the text at this many times its size (supersampled): finer edges once it is placed
    # animations made of pictures (Typewriter, Letter Scatter in / out): one linked picture per frame of the clip
    din, dout = txa_durs(a, L)
    nin = min(N, max(1, int(_math.floor(din * FPS + 0.5)))) if a["in"]["type"] in ("typewriter", "scatter") and t["tw"] and din > 0 else 0
    nout = min(N - nin, max(1, int(_math.floor(dout * FPS + 0.5)))) if a["out"]["type"] == "scatterout" and t.get("two") and dout > 0 else 0
    if vid:
        # a video layer: the file is read from where this part starts (never decoded from its beginning for every part of a long
        # render); empty frames stand in for what was skipped, so the animation still counts its frames from the layer's start
        inputs.extend(["-ss", f"{vid.get('v0', 0) + skip / FPS:.4f}", "-t", f"{max(1, N - skip) / FPS + 1:.4f}", "-i", os.path.basename(vid["path"])
                       if os.path.dirname(os.path.abspath(vid["path"])) == os.path.abspath(UPLOAD_DIR) else os.path.abspath(vid["path"])])
        idx = n_in[0]
        n_in[0] += 1
        src = f"[{idx}:v]fps={FPS},scale={W0}:{H0}:flags=bilinear,setsar=1,format=rgba,setpts=PTS-STARTPTS"
        if skip:
            chains.append(f"color=c=black@0:s={W0}x{H0}:r={FPS},format=rgba,trim=end_frame={skip},setpts=PTS-STARTPTS[tvp{li}]")
            chains.append(src + f"[tvv{li}]")
            ch = f"[tvp{li}][tvv{li}]concat=n=2:v=1:a=0,trim=end_frame={N + 1},setpts=PTS-STARTPTS"
        else:
            ch = src + f",trim=end_frame={N + 1},setpts=PTS-STARTPTS"
    elif nin or nout:
        def _pics(urls, tg):
            out_ = []
            for i, url in enumerate(urls):
                p_ = f"{tag}_tx{li}_{tg}{i}.png"
                _png_from_data_url(url, p_)
                out_.append(p_)
            return out_
        pre, post = (_pics(t["tw"], "c") if nin else []), (_pics(t["two"], "o") if nout else [])
        for k in range(N + 1):
            if k < nin:
                cnt = txa_chars(a, k, L, t["n"])
                src_ = pre[cnt] if cnt < len(pre) else full
            elif nout and k >= N - nout:
                src_ = post[min(len(post) - 1, int((k - (N - nout)) * len(post) // nout))]
            else:
                src_ = full
            _link(src_, f"{tag}_tx{li}_f{k:05d}.png")
        inputs.extend(["-framerate", str(FPS), "-start_number", "0", "-i", rel(f"{tag}_tx{li}_f%05d.png")])
        i0 = n_in[0]
        n_in[0] += 1
        ch = f"[{i0}:v]format=rgba,trim=end_frame={N + 1},setpts=PTS-STARTPTS"
    else:
        inputs.extend(["-loop", "1", "-framerate", str(FPS), "-t", f"{N / FPS + 1:.4f}", "-i", rel(full)])
        idx = n_in[0]
        n_in[0] += 1
        ch = f"[{idx}:v]format=rgba,trim=end_frame={N + 1},setpts=PTS-STARTPTS"
    # per-frame opacity + blur (only written when they change)
    frames = [txa_frame(c, k) for k in range(N)]
    blur = any(f[1] or f[2] for f in frames)
    cmd = f"{tag}_tx{li}_cmd.txt"
    last = None
    with open(cmd, "w", encoding="utf-8") as fh:
        for k, (op, bx, by) in enumerate(frames):
            cur = (round(op, 4), round(bx, 3), round(by, 3))
            if cur == last:
                continue
            last = cur
            parts = [f"colorchannelmixer@ta{li} {ch_} {cur[0]:.4f}" for ch_ in ("rr", "gg", "bb", "aa")]
            if blur:
                parts += [f"gblur@tb{li} sigma {cur[1] * ss:.3f}", f"gblur@tb{li} sigmaV {cur[2] * ss:.3f}"]
            fh.write(f"{k / FPS:.6f} " + ", ".join(parts) + ";\n")
    op0 = frames[0][0]
    ch += f",sendcmd=f='{rel(cmd)}',premultiply=inplace=1"
    if blur:
        E = txa_pad(max(max(f[1], f[2]) for f in frames))     # clear margin so the blur never hits the edge
        Ep = int(round(E * ss))
        ch += f",pad=iw+{2 * Ep}:ih+{2 * Ep}:{Ep}:{Ep}:color=black@0"
        W0, H0 = W0 + 2 * E, H0 + 2 * E
        ch += f",gblur@tb{li}=sigma={frames[0][1] * ss:.3f}:sigmaV={frames[0][2] * ss:.3f}:steps=3"
    # (premultiplied: scaling colour and alpha together is the opacity, with no dark fringes)
    ch += f",colorchannelmixer@ta{li}=rr={op0:.4f}:gg={op0:.4f}:bb={op0:.4f}:aa={op0:.4f}"
    CW, CH = max(W, W0), max(H, H0)
    ch += f",scale={CW}:{CH}:flags={'area' if ss > 1 and W0 * ss > CW and H0 * ss > CH else 'bicubic'}"
    # corners of the text picture: scale -> 3D tilt about X (perspective) -> rotation -> position
    Tl = FX(f"((in-1)/{FPS})")
    M = _MExpr
    dx, dy, sc, fa = txa_motion(M, a, Tl, L, t["size"])
    Tl_s = Tl.e
    S = FX(f"({kf_expr(c, 'scale', Tl_s)}/100)") * sc
    R = FX(f"({kf_expr(c, 'rot', Tl_s)}*PI/180)")
    F = fa * (_math.pi / 180) if isinstance(fa, FX) else FX(f"{fa * _math.pi / 180:.9g}")
    PX = FX(kf_expr(c, "pos", Tl_s, 0)) + dx
    PY = FX(kf_expr(c, "pos", Tl_s, 1)) + dy
    cF, sF, cR, sR = M.cos(F), M.sin(F), M.cos(R), M.sin(R)
    corners = []
    for u, v in ((-W0 / 2, -H0 / 2), (W0 / 2, -H0 / 2), (-W0 / 2, H0 / 2), (W0 / 2, H0 / 2)):
        y = v * S
        kk = TXA_PERSP / (TXA_PERSP + y * sF)
        x2, y2 = u * S * kk, y * cF * kk
        corners.append(((PX + x2 * cR - y2 * sR).e, (PY + x2 * sR + y2 * cR).e))
    ch += ",perspective=" + ":".join(f"x{i}='{cx}':y{i}='{cy}'" for i, (cx, cy) in enumerate(corners)) + \
          ":sense=destination:eval=frame:interpolation=linear"
    if skip:
        ch += f",trim=start_frame={skip},setpts=PTS-STARTPTS"
    ch += ",unpremultiply=inplace=1" + tl_place(c) + f"[ly{li}]"     # (setpts truncates: round to the frame)
    chains.append(ch)
    return f"[ly{li}]", "0", "0"



@app.get("/api/leak")
def api_leak():
    w = int(_fnum(request.args.get("w"), 1920, 16, 4000))
    h = int(_fnum(request.args.get("h"), 1080, 16, 4000))
    return send_file(leak_png(w, h), mimetype="image/png", max_age=3600)


# ---------------------------------------------------------------------------
# Render Queue: Beat Sync edits and Timeline sequences rendered one after another (e.g. overnight).
# Finished videos are saved straight into  VideoEditor/Exports/  (never auto-deleted).
# ---------------------------------------------------------------------------
QUEUE = []
QSTATE = {"running": False}
QUEUE_DIR = os.path.join(BASE_DIR, "Exports")


def _q_check(item):
    """Validate now (so mistakes show when you add it), again right before rendering."""
    if item["kind"] == "beat":
        return validate_plan(item["plan"])
    return tl_validate(item["plan"])


def _q_name(name, kind):
    base = re.sub(r'[\\/:*?"<>|\x00-\x1f]+', "_", str(name or "")).strip(" .")[:80]
    return base or ("edit" if kind == "beat" else "timeline") + time.strftime("_%Y%m%d_%H%M%S")


def _q_public(q):
    j = JOBS.get(q.get("jid") or "") or {}
    prog = j.get("progress", 0.0) if q["status"] == "rendering" else (1.0 if q["status"] == "done" else 0.0)
    return dict({k: q.get(k) for k in ("id", "kind", "name", "status", "error", "file", "added", "secs")}, progress=round(prog, 4))


def queue_worker():
    try:
        while QSTATE["running"]:
            item = next((q for q in QUEUE if q["status"] == "waiting"), None)
            if not item:
                break
            item.update(status="rendering", error=None)
            jid = uuid.uuid4().hex[:12]
            item["jid"] = jid
            t0 = time.time()
            try:
                v = _q_check(item)
                if item["kind"] == "beat":
                    JOBS[jid] = {"status": "queued", "progress": 0.0, "plan": v, "encoder": "", "started": t0,
                                 "name": item["name"] + ".mp4", "queue": item["id"]}
                    run_render(jid)
                else:
                    JOBS[jid] = {"status": "queued", "progress": 0.0, "tl": v, "plan": None, "encoder": "", "started": t0,
                                 "name": item["name"] + ".mp4", "queue": item["id"]}
                    run_timeline_render(jid)
                j = JOBS.get(jid, {})
                if item.get("cancel") or j.get("status") == "cancelled":
                    item["status"] = "waiting" if QSTATE["running"] is False and not item.get("removed") else "cancelled"
                    item.pop("cancel", None)
                elif j.get("status") == "done" and os.path.exists(j.get("path", "")):
                    os.makedirs(QUEUE_DIR, exist_ok=True)
                    qext = os.path.splitext(j["path"])[1] or ".mp4"
                    dst = os.path.join(QUEUE_DIR, item["name"] + qext)
                    i = 2
                    while os.path.exists(dst):
                        dst = os.path.join(QUEUE_DIR, f"{item['name']} ({i}){qext}")
                        i += 1
                    shutil.move(j["path"], dst)
                    j["saved"] = True
                    item.update(status="done", file=dst, secs=round(time.time() - t0, 1))
                else:
                    item.update(status="error", error=j.get("error") or "The render failed.")
            except (ValueError, KeyError, TypeError) as e:
                item.update(status="error", error=str(e) or "This edit can't be rendered any more.")
            except Exception as e:
                item.update(status="error", error=str(e))
            finally:
                JOBS.pop(jid, None)
    finally:
        QSTATE["running"] = False


@app.get("/api/queue")
def api_queue():
    cur = next((q for q in QUEUE if q["status"] == "rendering"), None)
    j = JOBS.get(cur.get("jid") or "") if cur else None
    return jsonify({"running": QSTATE["running"], "items": [_q_public(q) for q in QUEUE], "folder": QUEUE_DIR,
                    "encoder": (j or {}).get("encoder", "")})


@app.post("/api/queue")
def api_queue_add():
    d = request.get_json(force=True) or {}
    kind = d.get("kind")
    if kind not in ("beat", "tl"):
        return err("Unknown kind.")
    plan = d.get("plan") or {}
    item = {"id": uuid.uuid4().hex[:10], "kind": kind, "plan": plan, "status": "waiting", "added": time.time(),
            "name": _q_name(d.get("name"), kind), "error": None}
    try:
        _q_check(item)
    except (ValueError, KeyError, TypeError) as e:
        return err(str(e) or "Invalid edit.")
    if len(QUEUE) >= 50:
        return err("The queue is full (50 items).")
    QUEUE.append(item)
    return jsonify({"id": item["id"], "count": sum(q["status"] == "waiting" for q in QUEUE)})


@app.post("/api/queue/start")
def api_queue_start():
    if QSTATE["running"]:
        return jsonify({"ok": True})
    if any(j["status"] in ("queued", "rendering") for j in JOBS.values()):
        return err("A render is already running - start the queue when it's finished.")
    if not any(q["status"] == "waiting" for q in QUEUE):
        return err("Nothing waiting in the queue.")
    QSTATE["running"] = True
    threading.Thread(target=queue_worker, daemon=True).start()
    return jsonify({"ok": True})


@app.post("/api/queue/stop")
def api_queue_stop():
    """Stop after cancelling the current render; it goes back to waiting."""
    QSTATE["running"] = False
    for q in QUEUE:
        if q["status"] == "rendering":
            q["cancel"] = True
            j = JOBS.get(q.get("jid") or "")
            if j:
                j["cancel"] = True
                p = j.get("proc")
                if p and p.poll() is None:
                    p.kill()
    return jsonify({"ok": True})


@app.post("/api/queue/<qid>/retry")
def api_queue_retry(qid):
    q = next((x for x in QUEUE if x["id"] == qid), None)
    if q and q["status"] in ("error", "cancelled", "done"):
        q.update(status="waiting", error=None, file=None)
    return jsonify({"ok": True})


@app.delete("/api/queue/<qid>")
def api_queue_del(qid):
    q = next((x for x in QUEUE if x["id"] == qid), None)
    if q:
        if q["status"] == "rendering":
            return err("That one is rendering - stop the queue first.")
        QUEUE.remove(q)
    return jsonify({"ok": True})


@app.post("/api/queue/clear")
def api_queue_clear():
    QUEUE[:] = [q for q in QUEUE if q["status"] in ("waiting", "rendering")]
    return jsonify({"ok": True})


@app.post("/api/queue/open")
def api_queue_open():
    os.makedirs(QUEUE_DIR, exist_ok=True)
    try:
        if os.name == "nt":
            os.startfile(QUEUE_DIR)
        elif sys.platform == "darwin":
            subprocess.Popen(["open", QUEUE_DIR])
        else:
            subprocess.Popen(["xdg-open", QUEUE_DIR], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception as e:
        return err(f"Couldn't open the folder: {e}")
    return jsonify({"ok": True, "folder": QUEUE_DIR})


# ---------------------------------------------------------------------------
# Motion tracking (OpenCV CSRT). The cut is rendered exactly as it looks (no effects) at a small size,
# the tracker follows your box forwards and backwards from the frame you drew it on, and the boxes
# (output px, one per clip frame) go back to the page, which stores them on the cut.
# ---------------------------------------------------------------------------
TRACK_JOBS = {}


def make_tracker():
    """CSRT (accurate) if this OpenCV has it, else KCF, else MIL. Returns (tracker, name)."""
    import cv2
    for name, path in (("CSRT", ("TrackerCSRT_create",)), ("CSRT", ("TrackerCSRT", "create")), ("CSRT", ("legacy", "TrackerCSRT_create")),
                       ("KCF", ("TrackerKCF_create",)), ("KCF", ("legacy", "TrackerKCF_create")), ("MIL", ("TrackerMIL_create",)), ("MIL", ("TrackerMIL", "create"))):
        obj = cv2
        try:
            for p in path:
                obj = getattr(obj, p)
            return obj(), name
        except Exception:
            continue
    raise RuntimeError("This OpenCV has no object tracker. Close the tool and start it again with Start_Tool.bat "
                       "(it installs opencv-contrib-python).")


def _track_job(jid):
    global OUTPUT_W, OUTPUT_H
    job = TRACK_JOBS[jid]
    tag = os.path.join(WORK_DIR, "trk_" + jid)
    try:
        import cv2
        with RENDER_LOCK:                        # (the output size is shared with renders)
            keep = OUTPUT_W, OUTPUT_H
            OUTPUT_W, OUTPUT_H = ORIENTS[job["plan"][5].get("orient", "landscape")]
            try:
                tw, th, W, H, out, total = _track_proxy(job, tag)
            finally:
                OUTPUT_W, OUTPUT_H = keep
        _track_run(job, cv2, tw, th, W, H, out, total)
    except Cancelled:
        job["status"] = "cancelled"
    except Exception as e:
        job.update(status="error", error=str(e))
    finally:
        job["proc"] = None
        job.pop("plan", None)
        for name in os.listdir(WORK_DIR):
            if name.startswith("trk_" + jid):
                _rm(os.path.join(WORK_DIR, name))


def _track_proxy(job, tag):
    """Render the cut as it looks (no effects, no thumps) at a small size for the tracker."""
    if True:
        song, start, total, secs, trans, pulse = job["plan"]
        for s in secs:
            s.pop("fx", None)
            s.pop("ovs", None)
            cv = s.get("curve")
            s["blend"] = s.get("speed", 1.0) < 0.99 or bool(cv and min(cv["v"]) < 0.99)
            if cv:
                cv.update(L=s["f1"] - s["f0"], k0=0)
            prep_pane_timing(s, s["f1"] - s["f0"])
        pulse.update(on=False, govs=[], tag=tag)
        inputs, chains = build_video_graph(secs, trans, pulse)
        W, H = OUTPUT_W, OUTPUT_H
        k = 480 / max(W, H)
        tw, th = int(round(W * k / 2) * 2), int(round(H * k / 2) * 2)
        chains.append(f"[vout]scale={tw}:{th}:flags=area[trk]")
        with open(tag + "_g.txt", "w", encoding="utf-8") as fh:
            fh.write(";\n".join(chains))
        out = tag + ".mp4"
        cmd = (["ffmpeg", "-hide_banner", "-y", "-v", "error"] + inputs + filter_script_args(tag + "_g.txt")
               + ["-map", "[trk]", "-an", "-frames:v", str(total), "-c:v", "libx264", "-preset", "ultrafast", "-crf", "16",
                  "-pix_fmt", "yuv420p", "-progress", "pipe:1", "-nostats", out])
        job["stage"] = "Preparing the cut"
        proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, cwd=UPLOAD_DIR,
                                creationflags=NO_WINDOW, encoding="utf-8", errors="replace")
        job["proc"] = proc
        for line in proc.stdout:
            key, _, val = line.strip().partition("=")
            if key == "frame" and val.isdigit():
                job["pct"] = min(30, int(int(val) / max(1, total) * 30))
            if job.get("cancel"):
                proc.kill()
        err = proc.stderr.read()
        proc.wait()
        if job.get("cancel"):
            raise Cancelled()
        if proc.returncode != 0:
            raise RuntimeError("Couldn't prepare the cut for tracking: " + (err or "").strip()[-300:])
        return tw, th, W, H, out, total


def _track_run(job, cv2, tw, th, W, H, out, total):
    """Follow the box forwards and backwards from the frame it was drawn on."""
    if True:
        cap = cv2.VideoCapture(out)
        frames = []
        while True:
            ok, fr = cap.read()
            if not ok:
                break
            frames.append(fr)
        cap.release()
        if not frames:
            raise RuntimeError("Couldn't read the cut for tracking.")
        n = len(frames)
        k0 = min(max(0, job["k0"]), n - 1)
        bx, by, bw, bh = job["box"]
        sx, sy = tw / W, th / H
        init = (int(round(bx * sx)), int(round(by * sy)), max(4, int(round(bw * sx))), max(4, int(round(bh * sy))))
        boxes = [None] * n
        boxes[k0] = list(init)
        lost = []
        job["stage"] = "Tracking"
        done = [0]
        for order in (range(k0 + 1, n), range(k0 - 1, -1, -1)):
            trk, job["tracker"] = make_tracker()
            trk.init(frames[k0], init)
            last = list(init)
            for kk in order:
                if job.get("cancel"):
                    raise Cancelled()
                ok, b = trk.update(frames[kk])
                if ok:
                    last = [float(v) for v in b]
                else:
                    lost.append(kk)
                boxes[kk] = list(last)
                done[0] += 1
                job["pct"] = 30 + int(done[0] / max(1, n - 1) * 70)
        job["boxes"] = [[b[0] / sx, b[1] / sy, b[2] / sx, b[3] / sy] for b in boxes]
        job["lost"] = sorted(lost)
        job.update(status="done", pct=100)


@app.post("/api/track")
def api_track():
    """{plan: a one-cut render plan (no effects), k0: frame you drew on, box: [x, y, w, h] in output px}"""
    d = request.get_json(silent=True) or {}
    try:
        import cv2  # noqa: F401
    except Exception:
        return err("OpenCV isn't installed. Close the tool and start it again with Start_Tool.bat.")
    try:
        plan = validate_plan(d.get("plan") or {})
        box = [float(v) for v in (d.get("box") or [])][:4]
        if len(box) != 4 or box[2] < 4 or box[3] < 4:
            raise ValueError("Draw a box around the thing to follow first.")
    except (ValueError, KeyError, TypeError) as e:
        return err(str(e))
    jid = uuid.uuid4().hex[:12]
    TRACK_JOBS[jid] = {"status": "running", "pct": 0, "plan": plan, "k0": int(d.get("k0") or 0), "box": box, "stage": "Starting"}
    threading.Thread(target=_track_job, args=(jid,), daemon=True).start()
    return jsonify({"id": jid})


@app.get("/api/track/<jid>")
def api_track_status(jid):
    j = TRACK_JOBS.get(jid)
    if not j:
        return err("Unknown tracking job.", 404)
    r = {k: j.get(k) for k in ("status", "pct", "stage", "error", "tracker")}
    if j["status"] == "done":
        r.update(boxes=j["boxes"], lost=j["lost"])
    return jsonify(r)


@app.post("/api/track/<jid>/cancel")
def api_track_cancel(jid):
    j = TRACK_JOBS.get(jid)
    if j:
        j["cancel"] = True
        p = j.get("proc")
        if p:
            try:
                p.kill()
            except Exception:
                pass
    return jsonify({"ok": True})



@app.post("/api/clip/<cid>/matte")
def api_clip_matte(cid):
    """Start / check the AI background removal matte of a clip: {expand, clean} -> {status, pct, url, provider}."""
    d = request.get_json(silent=True) or {}
    c = CLIPS.get(cid)
    if not c or c.get("status") != "ready":
        return err("That clip isn't ready yet.", 404)
    try:
        import onnxruntime  # noqa: F401
    except Exception:
        return err("The AI isn't installed. Close the tool and start it again with Start_Tool.bat (it installs onnxruntime).")
    return jsonify(matte_state(cid, int(_fnum(d.get("expand"), 0, -20, 20)), int(_fnum(d.get("clean"), 0, 0, 10))))


@app.get("/media/matte/<cid>/<key>")
def media_matte(cid, key):
    r = ((CLIPS.get(cid) or {}).get("mref") or {}).get(key)
    if r and r.get("status") == "ready":
        return send_file(r["path"], mimetype="video/mp4", conditional=True)
    return err("Not found.", 404)



# ===========================================================================
# TIMELINE MODE (Premiere-style): multi-track compositing with keyframes
# ===========================================================================
AUDIOS = {}   # id -> {path, play_path, name, duration, peaks}
TL_TRACKS_V = tuple(f"V{i}" for i in range(1, 17))    # V1 at the bottom; the page adds / removes tracks (up to 16 + 6: a Beat Sync edit with split screens, overlays and text needs many)
TL_TRACKS_A = tuple(f"A{i}" for i in range(1, 7))
TL_ANCHORS = {"tl": (0, 0), "tc": (.5, 0), "tr": (1, 0), "ml": (0, .5), "mc": (.5, .5),
              "mr": (1, .5), "bl": (0, 1), "bc": (.5, 1), "br": (1, 1)}
# Effect Controls blend mode -> FFmpeg blend mode (None = plain alpha overlay)
TL_BLENDS = {"normal": None, "screen": "screen", "multiply": "multiply", "overlay": "overlay",
             "darken": "darken", "lighten": "lighten", "dodge": "dodge", "burn": "burn",
             "hardlight": "hardlight", "softlight": "softlight", "difference": "difference",
             "exclusion": "exclusion", "add": "addition"}
TL_KF = ("pos", "scale", "scaleW", "scaleH", "rot", "opacity", "volume")



def tl_validate(plan):
    """Check + normalise a Timeline render plan. Times are in frames (30 fps), source in-points in seconds."""
    W, H = ORIENTS.get(plan.get("orient"), ORIENTS["landscape"])
    tracks = plan.get("tracks") or {}
    out = []
    for c in (plan.get("clips") or [])[:400]:
        tr = c.get("track")
        if tr not in TL_TRACKS_V + TL_TRACKS_A:
            raise ValueError("Unknown track.")
        off = bool((tracks.get(tr) or {}).get("off"))
        if off and tr in TL_TRACKS_A:
            continue                                       # muted audio track
        # (a hidden video track hides the picture only: its clips' own sound still plays)
        mid, kind = c.get("media"), c.get("kind")
        if kind == "text":
            if tr not in TL_TRACKS_V:
                raise ValueError("Text goes on a video track (V1-V3).")
            tx = c.get("text") or {}
            tw = tx.get("tw") if isinstance(tx.get("tw"), list) else []
            media = {"kind": "text", "w": int(_fnum(tx.get("w"), 2, 2, 8000)), "h": int(_fnum(tx.get("h"), 2, 2, 8000)),
                     "audio": False, "duration": 0,
                     "text": {"img": tx.get("img"), "tw": tw[:400], "two": [u_ for u_ in (tx.get("two") if isinstance(tx.get("two"), list) else [])[:60] if isinstance(u_, str)], "n": int(_fnum(tx.get("n"), 0, 0, 400)),
                              "size": _fnum(tx.get("size"), 100, 1, 2000), "ss": _fnum(tx.get("ss"), 1, 1, 4),
                              "box": [_fnum((tx.get("box") or [1, 1])[0], 1, 1, 8000), _fnum((tx.get("box") or [1, 1])[1], 1, 1, 8000)],
                              "anim": txa_norm(tx.get("anim"))}}
            if not isinstance(media["text"]["img"], str):
                raise ValueError("A text layer's picture is missing - select it and try again.")
        elif kind == "adj":
            if tr not in TL_TRACKS_V:
                raise ValueError("An Adjustment Layer goes on a video track.")
            media = {"kind": "adj", "w": W, "h": H, "audio": False, "duration": 0}
        elif kind == "audio":
            m = AUDIOS.get(mid)
            if not m:
                raise ValueError("An audio file on the timeline is missing - add it to the bin again.")
            media = {"kind": "audio", "path": m["path"], "duration": m["duration"], "audio": True}
        else:
            m = CLIPS.get(mid)
            if not m or m.get("status") != "ready":
                raise ValueError("A clip on the timeline is missing or still processing.")
            mk = m.get("kind", "video")
            media = {"kind": mk, "path": m.get("image") if mk == "photo" and m.get("image") else m["path"],
                     "duration": m.get("duration") or 0, "w": m.get("width") or W, "h": m.get("height") or H,
                     "audio": bool(m.get("audio")) and mk == "video", "v0": m.get("v0", 0) if mk == "video" else 0,
                     "clip": m, "cid": mid, "name": m.get("name")}
        start, dur = int(c.get("start", 0)), int(c.get("dur", 0))
        if start < 0 or dur < 1:
            raise ValueError("Bad clip timing.")
        p = c.get("p") or {}
        pos = p.get("pos") or [W / 2, H / 2]
        cr = p.get("crop") or {}
        cl, crr = _fnum(cr.get("l"), 0, 0, 99), _fnum(cr.get("r"), 0, 0, 99)
        ct, cb = _fnum(cr.get("t"), 0, 0, 99), _fnum(cr.get("b"), 0, 0, 99)
        if cl + crr > 98:
            crr = 98 - cl
        if ct + cb > 98:
            cb = 98 - ct
        props = {"pos": [_fnum(pos[0], W / 2, -20000, 20000), _fnum(pos[1], H / 2, -20000, 20000)],
                 "scale": _fnum(p.get("scale"), 100, 0, 2000), "uniform": p.get("uniform", True) is not False,
                 "scaleW": _fnum(p.get("scaleW"), 100, 0, 2000), "scaleH": _fnum(p.get("scaleH"), 100, 0, 2000),
                 "rot": _fnum(p.get("rot"), 0, -36000, 36000), "anchor": p.get("anchor") if p.get("anchor") in TL_ANCHORS else "mc",
                 "opacity": _fnum(p.get("opacity"), 100, 0, 100),
                 "blend": p.get("blend") if p.get("blend") in TL_BLENDS else "normal",
                 "volume": _fnum(p.get("volume"), 100, 0, 200),
                 "fadeIn": _fnum(p.get("fadeIn"), 0, 0, 600), "fadeOut": _fnum(p.get("fadeOut"), 0, 0, 600), "mute": bool(p.get("mute")),
                 "chan": p.get("chan") if p.get("chan") in TL_CHAN else "stereo", "pan": _fnum(p.get("pan"), 0, -100, 100),
                 "gain": _fnum(p.get("gain"), 0, -40, 40), "ax": parse_afx(p.get("ax")),
                 "crop": (cl, crr, ct, cb), "blur": _fnum(p.get("blur"), 0, 0, 300),
                 "hue": _fnum(p.get("hue"), 0, -180, 180), "sat": _fnum(p.get("sat"), 0, -100, 100),
                 "bri": _fnum(p.get("bri"), 0, -100, 100),
                 "bgr": parse_bgr(p.get("bgr")) if kind != "audio" and kind != "text" else None,
                 "grade": parse_grade(p.get("grade")) if kind != "audio" and kind != "text" else None,
                 "style": tl_parse_style(p.get("st")) if kind != "audio" and kind != "text" else None,
                 "fx": tl_parse_fx(c.get("fx")) if kind != "audio" and kind != "text" else {}}
        if props["bgr"] and media.get("kind") not in ("video", "gif", "photo"):
            props["bgr"] = None
        kf = {}
        for k, lst in (c.get("kf") or {}).items():
            if k not in TL_KF or not isinstance(lst, list):
                continue
            pts = []
            for e in lst[:3000]:
                try:
                    f = int(e[0])
                    v = [float(e[1][0]), float(e[1][1])] if k == "pos" else float(e[1])
                except (TypeError, ValueError, IndexError):
                    continue
                pts.append((f, v))
            pts.sort(key=lambda x: x[0])
            dedup = []
            for f, v in pts:
                if dedup and dedup[-1][0] == f:
                    dedup[-1] = (f, v)
                else:
                    dedup.append((f, v))
            if dedup:
                kf[k] = dedup
        if kind == "text":
            props.update(anchor="mc", uniform=True, crop=(0, 0, 0, 0), blur=0, hue=0, sat=0, bri=0)
        if kind == "adj":
            props.update(bgr=None, style=None, mute=True, uniform=True, anchor="mc", crop=(0, 0, 0, 0))
            kf = {k_: v_ for k_, v_ in kf.items() if k_ in ("opacity", "pos", "scale", "rot")}
        tp = c.get("trp") if isinstance(c.get("trp"), dict) and c["trp"].get("t") in TR3 and c["trp"].get("side") in ("a", "b") and kind not in ("audio", "adj", "text") else None
        if tp:
            h1, h2 = int(_fnum(tp.get("h1"), 1, 1, 60)), int(_fnum(tp.get("h2"), 1, 1, 60))
            tp = {"t": tp["t"], "side": tp["side"], "k": str(tp.get("k"))[:24], "h1": h1, "h2": h2, "n": h1 + h2, "ez": _fnum(tp.get("ez"), 0, 0, 100) / 100}
            if dur != (h1 if tp["side"] == "a" else h2):
                tp = None
        out.append({"track": tr, "media": media, "start": start, "dur": dur, "trp": tp,
                    "in": _fnum(c.get("in"), 0, 0, 1e6), "speed": _fnum(c.get("speed"), 1, 0.1, 5), "curve": tl_parse_curve(c.get("curve"), dur, kind),
                    "p": props, "kf": kf, "audioOnly": tr in TL_TRACKS_A, "hidden": off,
                    "ke": {pr_: {int(k_): m_ for k_, m_ in (mp_ or {}).items() if str(k_).lstrip("-").isdigit() and m_ in ("in", "out", "io")}
                           for pr_, mp_ in (c.get("ke") or {}).items() if pr_ in TL_KF and isinstance(mp_, dict)} if isinstance(c.get("ke"), dict) else {}})
    if not out:
        raise ValueError("The timeline is empty.")
    total = max(c["start"] + c["dur"] for c in out)
    duck = [tr for tr in TL_TRACKS_A if (tracks.get(tr) or {}).get("duck")]
    fps = plan.get("fps")
    return {"W": W, "H": H, "total": total, "clips": out, "export": parse_export(plan.get("export")), "duck": duck,
            "fps": fps if fps in (24, 30, 60) else FPS}



TL_CHAN = ("stereo", "mono", "left", "right")


def chan_mix(chan, pan):
    """Channel Mode + Pan of a clip as four gains (LL, RL, LR, RR): left out = LL*L + RL*R, right out = LR*L + RR*R.
    Pan uses the equal-power law of a stereo panner (the page's preview uses the same numbers)."""
    a = {"mono": [0.5, 0.5, 0.5, 0.5], "left": [1, 0, 1, 0], "right": [0, 1, 0, 1]}.get(chan, [1, 0, 0, 1])
    p = max(-1.0, min(1.0, pan / 100))
    if p < 0:
        x = (p + 1) * _math.pi / 2
        c_, s_ = _math.cos(x), _math.sin(x)
        a = [a[0] + c_ * a[2], a[1] + c_ * a[3], s_ * a[2], s_ * a[3]]
    elif p > 0:
        x = p * _math.pi / 2
        c_, s_ = _math.cos(x), _math.sin(x)
        a = [c_ * a[0], c_ * a[1], a[2] + s_ * a[0], a[3] + s_ * a[1]]
    return a


def chan_filter(chan, pan):
    a = chan_mix(chan, pan)
    if all(abs(u - v) < 1e-6 for u, v in zip(a, [1, 0, 0, 1])):
        return ""
    return f",pan=stereo|c0={a[0]:.6f}*c0+{a[1]:.6f}*c1|c1={a[2]:.6f}*c0+{a[3]:.6f}*c1"


TL_FX = ("mirror", "flipv", "kmirror", "gkey", "zblur", "rgb", "chroma", "glitch", "vhs", "bloom", "leak", "vig", "bars", "mblur", "shake", "pulse", "wiggle")     # also the order they are applied in


def tl_parse_fx(fx):
    """Effects Library entries of one clip -> {type: {a, s}} (a = intensity 0..1, s = speed 0..1). Unknown / off ones drop out."""
    out = {}
    for e in (fx if isinstance(fx, list) else [])[:20]:
        if isinstance(e, dict) and e.get("t") in TL_FX and e.get("on", True):
            out[e["t"]] = {"a": _fnum(e.get("a"), 50, 0, 100) / 100, "s": _fnum(e.get("s"), 50, 0, 100) / 100}
            if e["t"] == "gkey":                           # Green Screen: the colour to remove
                col = str(e.get("col") or "")
                out["gkey"]["col"] = col[1:] if re.fullmatch(r"#[0-9a-fA-F]{6}", col) else "00ff00"
                out["gkey"]["sp"] = _fnum(e.get("sp"), 0, 0, 100) / 100      # Spill Suppression
    return out


def tl_parse_style(o):
    """Clip Style (Timeline): outline + rounded corners (in % of the picture's short side) and a drop shadow / glow (frame px)."""
    if not isinstance(o, dict):
        return None
    col = lambda v, d: v if isinstance(v, str) and re.fullmatch(r"#[0-9a-fA-F]{6}", v) else d
    st = {"ow": _fnum(o.get("ow"), 0, 0, 25), "oc": col(o.get("oc"), "#ffffff"), "rad": _fnum(o.get("rad"), 0, 0, 50),
          "sd": _fnum(o.get("sd"), 0, 0, 400), "sa": _fnum(o.get("sa"), 135, 0, 360), "sb": _fnum(o.get("sb"), 0, 0, 200),
          "so": _fnum(o.get("so"), 0, 0, 100), "sc": col(o.get("sc"), "#000000")}
    return st if (st["ow"] > 0 or st["rad"] > 0 or st["so"] > 0) else None


def tl_style_pngs(w, h, st, rad_on, tag, li):
    """(mask png or None, ring png or None) for a w x h picture: white rounded box on black; the outline ring on transparent."""
    from PIL import Image, ImageDraw
    m = min(w, h)
    K = 2 if max(w, h) <= 2400 else 1                    # drawn at 2x, shrunk: smooth edges
    r = st["rad"] / 100 * m * K if rad_on else 0
    ow = st["ow"] / 100 * m * K
    out = [None, None]
    if r > 0.5:
        im = Image.new("L", (w * K, h * K), 0)
        ImageDraw.Draw(im).rounded_rectangle([0, 0, w * K - 1, h * K - 1], radius=r, fill=255)
        out[0] = f"{tag}_stm{li}.png"
        im.resize((w, h), Image.LANCZOS).save(out[0])
    if ow > 0.3:
        c = st["oc"]
        rgb = (int(c[1:3], 16), int(c[3:5], 16), int(c[5:7], 16))
        full = Image.new("L", (w * K, h * K), 0)
        ImageDraw.Draw(full).rounded_rectangle([0, 0, w * K - 1, h * K - 1], radius=r, fill=255)
        hole = Image.new("L", (w * K, h * K), 0)
        ImageDraw.Draw(hole).rounded_rectangle([ow, ow, w * K - 1 - ow, h * K - 1 - ow], radius=max(0, r - ow), fill=255)
        from PIL import ImageChops
        a = ImageChops.subtract(full, hole).resize((w, h), Image.LANCZOS)
        ring = Image.new("RGBA", (w, h), rgb + (0,))
        ring.putalpha(a)
        out[1] = f"{tag}_str{li}.png"
        ring.save(out[1])
    return out


def tl_fx_shake(f, T):
    """Shake: (dx, dy) in frame px as expressions of T (clip-local seconds). Same numbers as the preview."""
    amp, hz = f["a"] * 40, 2 + f["s"] * 14
    return (f"{amp:.4f}*(0.6*sin(2*PI*{hz:.4f}*{T})+0.4*sin(2*PI*{hz * 1.7:.4f}*{T}+1.3))",
            f"{amp:.4f}*(0.6*cos(2*PI*{hz * 1.3:.4f}*{T}+0.7)+0.4*cos(2*PI*{hz * 2.1:.4f}*{T}))")


def tl_fx_pulse(f, T):
    """Pulse: a zoom punch that repeats, 1 + z * exp(-6 * phase)."""
    z, per = f["a"] * 0.20, 1.2 - f["s"] * 1.0
    return f"(1+{z:.5f}*exp(-6*mod({T},{per:.5f})/{per:.5f}))"


def gkey_numbers(f):
    """Green Screen sliders -> (similarity, blend) of FFmpeg's colorkey: Threshold 0..100 % = 0.02..0.60, Softness 0..100 % = 0..0.40."""
    return 0.02 + f["a"] * 0.58, f["s"] * 0.40


def tl_adjust(cur, c, W, H, inputs, n_in, chains, li, tag):
    """An Adjustment Layer: its effects, colour and blur are applied to everything under it (the picture so far), for as long as it lasts."""
    p, s, N = c["p"], c["start"], c["dur"]
    chains.append(f"{cur}split[ajA{li}][ajB{li}]")
    ch = f"[ajB{li}]trim=start_frame={s}:end_frame={s + N},setpts=PTS-STARTPTS,format=rgba"
    lead = s > 0
    fxm = {k: v for k, v in (p.get("fx") or {}).items() if k != "gkey"}
    if fxm:
        ch = tl_fx_source(fxm, ch, W, H, N, inputs, n_in, chains, f"J{li}", tag)
    if p["hue"] or p["sat"] or p["bri"]:
        ch += "," + tl_color_matrix(p["hue"], p["sat"], p["bri"])
    if p.get("grade"):
        ch += "," + ",".join(grade_filters(p["grade"])) + ",format=rgba"
    if p["blur"] > 0:
        ch += f",gblur=sigma={p['blur']:.3f}"
    fxa = p.get("fx") or {}
    on = lambda k: fxa.get(k) and fxa[k]["a"] > 0
    moved = any(k in c["kf"] for k in ("pos", "scale", "rot")) or on("shake") or on("pulse") or on("wiggle") or abs(p["scale"] - 100) > 1e-6 \
        or abs(p["rot"]) > 1e-6 or abs(p["pos"][0] - W / 2) > 1e-6 or abs(p["pos"][1] - H / 2) > 1e-6
    xo, yo = "0", "0"
    if moved:
        ROT = kf_expr(c, "rot", "t") + (f"+{tl_fx_wiggle(fxa['wiggle'], 't')}" if on("wiggle") else "")
        SC = f"({kf_expr(c, 'scale', 't')}/100)" + (f"*{tl_fx_pulse(fxa['pulse'], 't')}" if on("pulse") else "")
        PX, PY = kf_expr(c, "pos", "T", 0), kf_expr(c, "pos", "T", 1)
        if on("shake"):
            sdx, sdy = tl_fx_shake(fxa["shake"], "T")
            PX, PY = f"({PX}+{sdx})", f"({PY}+{sdy})"
        ch += (f",format=rgba,rotate=a='({ROT})*PI/180':ow=iw:oh=ih:c=black@0,"
               f"scale=w='max(2,trunc({W}*{SC}/2)*2)':h='max(2,trunc({H}*{SC}/2)*2)':eval=frame:flags=bilinear")
        TT = f"(t-{s / FPS:.6f})"
        xo, yo = f"({PX})-w/2".replace("T", TT), f"({PY})-h/2".replace("T", TT)
    if "opacity" in c["kf"]:
        cmd = f"{tag}_ajo{li}.txt"
        with open(cmd, "w", encoding="utf-8") as fh:
            for k in range(N):
                fh.write(f"{k / FPS:.6f} colorchannelmixer@ajo{li} aa {kf_value(c, 'opacity', k) / 100:.5f};\n")
        ch += f",format=rgba,sendcmd=f='{os.path.relpath(cmd, UPLOAD_DIR).replace(chr(92), '/')}',colorchannelmixer@ajo{li}=aa={kf_value(c, 'opacity', 0) / 100:.5f}"
    elif p["opacity"] < 99.99:
        ch += f",format=rgba,colorchannelmixer=aa={p['opacity'] / 100:.5f}"
    if lead:
        # The layer's copy of the picture only starts at frame s. Without anything before it, the overlay below would wait for that
        # first frame and hold EVERY earlier frame of the film in memory meanwhile (gigabytes on a long edit). So the copy is given
        # s clear frames in front: the two streams run side by side from frame 0 and nothing queues up.
        chains.append(ch + f",tpad=start={s}:start_mode=add:color=black@0[ajC{li}]")       # (tpad hands out its clear frames at once and moves the real ones s frames later)
    else:
        chains.append(ch + f",setpts='PTS+floor({s / FPS:.9f}/TB+0.5)'[ajC{li}]")
    chains.append(f"[ajA{li}][ajC{li}]overlay=x='{xo}':y='{yo}':eval=frame:eof_action=pass:format=gbrp:"
                  f"enable='between(t,{(s - 0.5) / FPS:.6f},{(s + N - 0.5) / FPS:.6f})'[v{li}]")
    return f"[v{li}]"


def tl_fx_source(fx, ch, mw, mh, N, inputs, n_in, chains, li, tag):
    """The picture effects, applied to the clip's own frame (mw x mh, RGBA) before crop / scale / position.
    Returns the continued chain. Order: mirror, zoom blur, RGB split, glitch, VHS, light leak, bars."""
    if "mirror" in fx:
        ch += ",hflip"
    if "flipv" in fx:
        ch += ",vflip"
    f = fx.get("gkey")
    if f:                                              # Green Screen (chroma key): every pixel close to that colour turns see-through.
        sim, bl = gkey_numbers(f)                      # (the page uses the same two numbers and the same distance formula)
        ch += f",colorkey=0x{f.get('col', '00ff00')}:{sim:.4f}:{bl:.4f}"
        sp, kc = f.get("sp") or 0, f.get("col", "00ff00")
        kr_, kg_, kb_ = int(kc[0:2], 16), int(kc[2:4], 16), int(kc[4:6], 16)
        if sp > 0 and max(kg_, kb_) > kr_:             # Spill Suppression: the key colour's glow on skin / hair is pulled back to neutral
            ty = "green" if kg_ >= kb_ else "blue"     # (what the green has more of than the average of the other two is taken out)
            ch += f",despill=type={ty}:mix=0.5:expand=0:red=0:green={-sp if ty == 'green' else 0:.4f}:blue={-sp if ty == 'blue' else 0:.4f}:brightness=0:alpha=0,format=rgba"
    if "kmirror" in fx:                                # Mirror: the left half reflected onto the right
        hw = max(1, mw // 2)
        chains.append(ch + f",split[kmA{li}][kmB{li}]")
        chains.append(f"[kmB{li}]crop={hw}:{mh}:0:0,hflip[kmR{li}]")
        chains.append(f"[kmA{li}]crop={hw}:{mh}:0:0[kmL{li}]")
        ch = f"[kmL{li}][kmR{li}]hstack=inputs=2,scale={mw}:{mh}:flags=bilinear,setsar=1,format=rgba"
    f = fx.get("zblur")
    if f and f["a"] > 0:
        chains.append(ch + f",split=4[tzA{li}][tzB{li}][tzC{li}][tzD{li}]")
        labs = [f"[tzA{li}]"]
        for j, lab in enumerate(("B", "C", "D"), 1):
            k = 1 + f["a"] * 0.08 * j / 3
            chains.append(f"[tz{lab}{li}]scale={int(round(mw * k / 2) * 2)}:{int(round(mh * k / 2) * 2)}:flags=bilinear,crop={mw}:{mh}[tz{lab}c{li}]")
            labs.append(f"[tz{lab}c{li}]")
        ch = "".join(labs) + "mix=inputs=4:weights='4 3 2 1',format=rgba"
    f = fx.get("rgb")
    if f and f["a"] > 0:
        A = max(1, round(f["a"] * 0.02 * mw))
        ch += f",format=gbrap,rgbashift=rh={-A}:bh={A},format=rgba"
    f = fx.get("chroma")
    if f and f["a"] > 0:                               # Chromatic aberration: red and green magnified a touch more than blue, from the centre
        e = f["a"] * 0.012
        chains.append(ch + f",split=3[caB{li}][caG{li}][caR{li}]")
        for lab, k, keep in (("G", 1 + e, "rr=0:gg=1:bb=0"), ("R", 1 + 2 * e, "rr=1:gg=0:bb=0")):
            sw_, sh_ = int(round(mw * k / 2) * 2), int(round(mh * k / 2) * 2)
            chains.append(f"[ca{lab}{li}]scale={sw_}:{sh_}:flags=bilinear,crop={mw}:{mh},colorchannelmixer={keep},format=gbrap[ca{lab}c{li}]")
        chains.append(f"[caB{li}]colorchannelmixer=rr=0:gg=0:bb=1,format=gbrap[caBc{li}]")
        chains.append(f"[caBc{li}][caGc{li}]blend=c0_mode=addition:c1_mode=addition:c2_mode=addition:c3_mode=normal[caX{li}]")
        ch = f"[caX{li}][caRc{li}]blend=c0_mode=addition:c1_mode=addition:c2_mode=addition:c3_mode=normal,format=rgba"
    f = fx.get("glitch")
    if f and f["a"] > 0:
        A = max(2, round(f["a"] * 0.03 * mw))
        A2, P, B = max(1, A // 2), max(8, round(60 - f["s"] * 50)), 4
        ch += (f",format=gbrap,rgbashift=rh={-A}:bh={A}:enable='lt(mod(n,{P}),{B})*eq(mod(n,2),0)',"
               f"rgbashift=rh={A2}:bh={-A2}:gv={max(1, A2 // 2)}:enable='lt(mod(n,{P}),{B})*eq(mod(n,2),1)',format=rgba")
    f = fx.get("vhs")
    if f and f["a"] > 0:
        A = max(1, round(f["a"] * 0.006 * mw))
        per = max(2, round(mh / 270))
        ch += (f",format=gbrap,rgbashift=rh={-A}:bh={A},noise=alls={round(f['a'] * 24)}:allf=t,format=rgba,"
               + tl_color_matrix(0, -30 * f["a"], 0) +
               f",drawgrid=x=-4:y=0:w=iw+8:h={per}:t={max(1, per // 4)}:color=black@{0.32 * f['a']:.3f}")
    f = fx.get("bloom")
    if f and f["a"] > 0:                               # Bloom / glow: a blurred copy screened back over the picture
        chains.append(ch + f",format=gbrap,split[blA{li}][blB{li}]")
        chains.append(f"[blB{li}]gblur=sigma={0.02 * mw:.3f}:steps=2[blC{li}]")
        ch = (f"[blA{li}][blC{li}]blend=c0_mode=screen:c1_mode=screen:c2_mode=screen:c3_mode=normal:"
              f"c0_opacity={0.8 * f['a']:.4f}:c1_opacity={0.8 * f['a']:.4f}:c2_opacity={0.8 * f['a']:.4f}:c3_opacity=0,format=rgba")
    f = fx.get("leak")
    if f and f["a"] > 0:
        lw = 480
        lh = max(2, int(round(lw * mh / mw / 2) * 2))
        per = 6 - f["s"] * 5
        al = lambda k: f["a"] * (0.5 - 0.5 * _math.cos(2 * _math.pi * (k / FPS) / per))
        cmd = f"{tag}_tlk{li}.txt"
        with open(cmd, "w", encoding="utf-8") as fh:
            last = None
            for k in range(N + 1):
                v = round(al(k), 4)
                if v != last:
                    fh.write(f"{k / FPS:.6f} colorchannelmixer@tlk{li} aa {v:.4f};\n")
                    last = v
        inputs.extend(["-loop", "1", "-framerate", str(FPS), "-t", f"{N / FPS + 1:.4f}", "-i", os.path.relpath(leak_png(lw, lh), UPLOAD_DIR).replace(chr(92), "/")])
        idx = n_in[0]
        n_in[0] += 1
        chains.append(ch + f"[tlkS{li}]")
        chains.append(f"[{idx}:v]format=rgba,scale={mw}:{mh}:flags=bilinear,trim=end_frame={N + 1},setpts=PTS-STARTPTS,"
                      f"sendcmd=f='{os.path.relpath(cmd, UPLOAD_DIR).replace(chr(92), '/')}',colorchannelmixer@tlk{li}=aa={al(0):.4f}[tlkL{li}]")
        ch = f"[tlkS{li}][tlkL{li}]overlay=0:0:eof_action=repeat:format=auto,format=rgba"
    f = fx.get("vig")
    if f and f["a"] > 0:                               # Vignette: black, strongest in the corners (same curve as the page: a^2 * d^2.2)
        vw, vh = 192, max(2, int(round(192 * mh / mw / 2) * 2))
        chains.append(ch + f"[vgS{li}]")
        chains.append(f"color=c=black:s={vw}x{vh}:r={FPS},format=rgba,trim=end_frame=1,"
                      f"geq=r=0:g=0:b=0:a='255*{f['a']:.4f}*pow(hypot((X+0.5-W/2)/(W/2),(Y+0.5-H/2)/(H/2))/1.41421,2.2)',"
                      f"scale={mw}:{mh}:flags=bilinear,loop=loop=-1:size=1:start=0,trim=end_frame={N + 1},setpts=N/{FPS}/TB[vgM{li}]")
        ch = f"[vgS{li}][vgM{li}]overlay=0:0:eof_action=repeat:format=auto,format=rgba"
    f = fx.get("bars")
    if f and f["a"] > 0:
        B = max(1, round(f["a"] * 0.18 * mh))
        ch += f",drawbox=x=0:y=0:w=iw:h={B}:color=black:t=fill,drawbox=x=0:y=ih-{B}:w=iw:h={B}:color=black:t=fill"
    return ch


def tl_parse_curve(cv, dur, kind):
    """A clip's speed graph (the Beat Sync keyframe graph, on a timeline clip). None when off."""
    if not isinstance(cv, dict) or not cv.get("on") or kind in ("audio", "text"):
        return None
    raw = list(cv.get("v") or [])[:12]
    if len(raw) < 2:
        return None
    vv = [min(10.0, max(0.1, float(x))) for x in raw]
    return {"v": vv, "u": curve_nodes(cv.get("u"), len(vv)), "ease": bool(cv.get("ease", True)), "L": int(dur)}


def tl_curve_pts(cv, N, off):
    """setpts expression that plays the source along the speed graph: output time as a piecewise-linear
    function of source time (the graph's offset table, inverted). `off` = seconds before the in-point in the input."""
    _, O = curve_table(cv, N)
    step = max(1, -(-N // 90))
    ks = list(range(0, N, step)) + [N]
    S = f"(PTS*TB-{off:.6f})"
    expr = None
    for j in range(len(ks) - 2, -1, -1):
        k0, k1 = ks[j], ks[j + 1]
        o0, o1 = O[k0], O[k1]
        piece = f"({k0 / FPS:.6f}+({S}-{o0:.6f})*{(k1 - k0) / FPS / max(1e-6, o1 - o0):.6f})"
        expr = piece if expr is None else f"if(lt({S},{o1:.6f}),{piece},{expr})"
    return f"setpts='{expr}/TB'", O[N]


def tl_scale_props(c):
    return ("scale", "scale") if c["p"]["uniform"] else ("scaleW", "scaleH")


def tl_color_matrix(hue, sat, bri):
    """Hue / saturation / brightness as one RGB matrix: the exact CSS filter maths
    (hue-rotate, saturate, brightness), so the render matches the preview."""
    import math
    a = math.radians(hue)
    ca, sa = math.cos(a), math.sin(a)
    Hm = [[0.213 + ca * 0.787 - sa * 0.213, 0.715 - ca * 0.715 - sa * 0.715, 0.072 - ca * 0.072 + sa * 0.928],
          [0.213 - ca * 0.213 + sa * 0.143, 0.715 + ca * 0.285 + sa * 0.140, 0.072 - ca * 0.072 - sa * 0.283],
          [0.213 - ca * 0.213 - sa * 0.787, 0.715 - ca * 0.715 + sa * 0.715, 0.072 + ca * 0.928 + sa * 0.072]]
    s = 1 + sat / 100.0
    Sm = [[0.213 + 0.787 * s, 0.715 - 0.715 * s, 0.072 - 0.072 * s],
          [0.213 - 0.213 * s, 0.715 + 0.285 * s, 0.072 - 0.072 * s],
          [0.213 - 0.213 * s, 0.715 - 0.715 * s, 0.072 + 0.928 * s]]
    b = 1 + bri / 100.0
    mul = lambda A, B: [[sum(A[i][k] * B[k][j] for k in range(3)) for j in range(3)] for i in range(3)]
    M = mul(Sm, Hm)                                   # CSS order: hue-rotate, then saturate, then brightness
    M = [[v * b for v in row] for row in M]
    n = "rgb"
    return "colorchannelmixer=" + ":".join(f"{n[i]}{n[j]}={M[i][j]:.6f}" for i in range(3) for j in range(3))


def tl_source(c, inputs, n_in):
    """Input + chain that yields exactly c['dur'] frames (30 fps, timeline-local) of the clip's picture."""
    m, N = c["media"], c["dur"]
    if m["kind"] == "photo":
        inputs.extend(["-loop", "1", "-framerate", str(FPS), "-t", f"{N / FPS + 1:.4f}", "-i", os.path.basename(m["path"])])
        idx = n_in[0]
        n_in[0] += 1
        return idx, f"[{idx}:v]trim=end_frame={N + 1},setpts=PTS-STARTPTS"
    sp, cs = c["speed"], c["in"]
    s0 = max(0.0, cs - SEEK_MARGIN)
    need = N * sp / FPS
    cshift = None
    if c.get("curve"):                       # speed graph: the frames follow the graph's own time map
        cshift, need = tl_curve_pts(c["curve"], N, cs - s0 + 0.001)
    loop = ["-stream_loop", "-1"] if m["kind"] == "gif" else []
    inputs.extend(["-threads", DECODER_THREADS, "-ss", f"{s0 + m.get('v0', 0):.6f}"] + loop +
                  ["-t", f"{cs - s0 + need + 1.0:.6f}", "-i", os.path.basename(m["path"])])
    idx = n_in[0]
    n_in[0] += 1
    off = cs - s0 + 0.001          # frame k shows the latest source frame at or before in + k*speed/30
    shift = cshift or (f"setpts=PTS-{off:.6f}/TB" if sp == 1 else f"setpts=(PTS-{off:.6f}/TB)/{sp:.6f}")
    return idx, (f"[{idx}:v]{shift},fps={FPS}:round=up,trim=start=0,setpts=PTS-STARTPTS,"
                 f"tpad=stop_mode=clone:stop_duration=5,trim=end_frame={N + 1},setpts=PTS-STARTPTS")   # (+1: the overlay never runs dry on the last frame)


def tl_mblur_sigma(c, k, a, k0, sp_):
    """Motion blur on frame k: blur (source px) across and down, from how far the clip moves until the next frame."""
    p0, p1 = kf_value(c, "pos", k), kf_value(c, "pos", k + 1)
    if not isinstance(p0, (list, tuple)):
        p0, p1 = c["p"]["pos"], c["p"]["pos"]
    s0, s1 = kf_value(c, sp_, k), kf_value(c, sp_, k + 1)
    m = c["media"]
    zoom = abs(s1 - s0) / 100 * k0 * max(m["w"], m["h"]) / 2 * 0.3   # a zoom smears too (a share of the edge speed)
    den = max(0.05, k0 * max(1.0, s0) / 100)
    return (min(120.0, a * 1.2 * (abs(p1[0] - p0[0]) + zoom) / den), min(120.0, a * 1.2 * (abs(p1[1] - p0[1]) + zoom) / den))


def tl_fx_wiggle(f, T):
    """Wiggle: the clip rocks left and right. Degrees as an expression of T (clip-local seconds)."""
    return f"({f['a'] * 8:.4f}*sin(2*PI*{0.5 + f['s'] * 5.5:.4f}*{T}))"


def tl_layer(c, W, H, inputs, n_in, chains, li, tag):
    """One video clip -> an RGBA layer + where/how it goes on the frame.
    Returns (label, overlay x expr, overlay y expr) in the layer's own time (T = clip-local seconds)."""
    m, p, N = c["media"], c["p"], c["dur"]
    idx, ch = tl_source(c, inputs, n_in)
    mw, mh = max(2, int(m["w"])), max(2, int(m["h"]))
    k0 = min(W / mw, H / mh)                                  # Scale 100 % = the clip fitted to the frame
    bw, bh = mw * k0, mh * k0
    cl, cr, ct, cb = p["crop"]
    px0, px1 = round(mw * cl / 100), mw - round(mw * cr / 100)
    py0, py1 = round(mh * ct / 100), mh - round(mh * cb / 100)
    px1, py1 = max(px0 + 2, px1), max(py0 + 2, py1)
    fx0, fx1, fy0, fy1 = px0 / mw, px1 / mw, py0 / mh, py1 / mh
    ax, ay = TL_ANCHORS[p["anchor"]]
    # A plain clip (nothing done to its own picture, nothing moving, no tilt, no crop): it is resized on the way in, in ONE pass together
    # with the change to RGBA. Otherwise a 4K clip on a 1080p timeline would first become a 4K RGBA picture (33 MB a frame) and only then
    # be made smaller: about three times the work for the same result.
    _sw, _sh = tl_scale_props(c)
    _st = p.get("style")
    direct = (m.get("kind") in ("video", "photo") and not p.get("bgr") and not (p.get("fx") or {}) and not (_st and (_st["ow"] > 0 or _st["rad"] > 0))
              and (px0, py0, px1, py1) == (0, 0, mw, mh) and not any(k_ in c["kf"] for k_ in (_sw, _sh, "rot", "pos")) and abs(p["rot"]) < 1e-6
              and not str(m.get("name") or "").lower().endswith((".png", ".webp", ".gif", ".mov", ".webm", ".tif", ".tiff")))
    if direct:
        _dw, _dh = max(1, round(bw * kf_value(c, _sw, 0) / 100)), max(1, round(bh * kf_value(c, _sh, 0) / 100))
        direct = (_dw, _dh) != (mw, mh)
    if direct:
        ch += f",scale={_dw}:{_dh}:flags={'lanczos' if _dw < mw else 'bicubic'},setsar=1,format=rgba"
    else:
        ch += f",scale={mw}:{mh},setsar=1,format=rgba"
    if p.get("bgr"):                                   # AI background removal: the matte becomes the alpha
        mc = dict(c, media=dict(m, **bgr_matte_clip(m["cid"], p["bgr"], m.get("name") or "a clip")))
        _, mch = tl_source(mc, inputs, n_in)
        chains.append(ch + f"[tla{li}]")
        chains.append(mch + f",scale={mw}:{mh}:flags=bicubic,{bgr_matte_filters(p['bgr'])}[tlm{li}]")
        ch = f"[tla{li}][tlm{li}]alphamerge,format=rgba"
        bg = bgr_background(p["bgr"], mw, mh, N, inputs, n_in, chains, f"tlg{li}")
        if bg:
            chains.append(ch + f"[tlf{li}]")
            ch = f"{bg}[tlf{li}]overlay=shortest=1:format=auto,format=rgba"
    fxm = p.get("fx") or {}
    if fxm:                                            # Effects Library: on the clip's own picture, before crop / scale
        ch = tl_fx_source(fxm, ch, mw, mh, N, inputs, n_in, chains, li, tag)
    if fxm.get("mblur") and fxm["mblur"]["a"] > 0 and ("pos" in c["kf"] or any(k_ in c["kf"] for k_ in tl_scale_props(c))):
        # Motion blur: every frame is smeared along the way the clip is moving right then (speed from its keyframes)
        cmd = f"{tag}_mb{li}.txt"
        sp_ = tl_scale_props(c)[0]
        with open(cmd, "w", encoding="utf-8") as fh:
            last = None
            for k in range(N):
                sx_, sy_ = tl_mblur_sigma(c, k, fxm["mblur"]["a"], k0, sp_)
                v = (round(sx_, 2), round(sy_, 2))
                if v != last:
                    fh.write(f"{k / FPS:.6f} gblur@mb{li} sigma {max(0.01, v[0]):.2f}, gblur@mb{li} sigmaV {max(0.01, v[1]):.2f};\n")
                    last = v
        ch += f",sendcmd=f='{os.path.relpath(cmd, UPLOAD_DIR).replace(chr(92), '/')}',gblur@mb{li}=sigma=0.01:sigmaV=0.01:steps=2"
    if (px0, py0, px1, py1) != (0, 0, mw, mh):
        ch += f",crop={px1 - px0}:{py1 - py0}:{px0}:{py0}"           # crop: the picture shrinks, nothing moves
    if p["hue"] or p["sat"] or p["bri"]:
        ch += "," + tl_color_matrix(p["hue"], p["sat"], p["bri"])
    if p.get("grade"):                                 # Colour: Lift / Gamma / Gain, then the LUT (after Hue / Sat / Brightness)
        ch += "," + ",".join(grade_filters(p["grade"])) + ",format=rgba"
    st = p.get("style")
    if st and (st["ow"] > 0 or st["rad"] > 0):          # Clip Style: rounded corners, then the outline (inside the edge), on the cropped picture
        mpng, rpng = tl_style_pngs(px1 - px0, py1 - py0, st, not p.get("bgr"), tag, li)
        for png, kind_ in ((mpng, "m"), (rpng, "r")):
            if not png:
                continue
            inputs.extend(["-loop", "1", "-framerate", str(FPS), "-t", f"{N / FPS + 1:.4f}", "-i", os.path.relpath(png, UPLOAD_DIR).replace(chr(92), "/")])
            idx = n_in[0]
            n_in[0] += 1
            chains.append(ch + f"[tsA{kind_}{li}]")
            if kind_ == "m":
                chains.append(f"[{idx}:v]format=gray,trim=end_frame={N + 1},setpts=PTS-STARTPTS[tsB{kind_}{li}]")
                ch = f"[tsA{kind_}{li}][tsB{kind_}{li}]alphamerge,format=rgba"
            else:
                chains.append(f"[{idx}:v]format=rgba,trim=end_frame={N + 1},setpts=PTS-STARTPTS[tsB{kind_}{li}]")
                ch = f"[tsA{kind_}{li}][tsB{kind_}{li}]overlay=0:0:eof_action=repeat:format=auto,format=rgba"
    swp, shp = tl_scale_props(c)
    anim_s = any(k in c["kf"] for k in (swp, shp))
    anim_r = "rot" in c["kf"]
    rot0 = p["rot"]
    wig = fxm.get("wiggle") if fxm.get("wiggle") and fxm["wiggle"]["a"] > 0 else None
    if wig:
        anim_r = True
    ROT = lambda X: f"({kf_expr(c, 'rot', X)}+{tl_fx_wiggle(wig, X)})" if wig else kf_expr(c, "rot", X)
    T = "T"
    blur = p["blur"]
    bpad = int(blur * 3 + 2) if blur > 0 else 0
    # per-axis box size (frame px) as expressions + constants for the static case
    Wexp = f"({bw:.6f}*{kf_expr(c, swp, T)}/100)"
    Hexp = f"({bh:.6f}*{kf_expr(c, shp, T)}/100)"
    sw0, sh0 = bw * kf_value(c, swp, 0) / 100, bh * kf_value(c, shp, 0) / 100
    PX, PY = kf_expr(c, "pos", T, 0), kf_expr(c, "pos", T, 1)
    if fxm.get("shake") and fxm["shake"]["a"] > 0:
        sdx, sdy = tl_fx_shake(fxm["shake"], T)
        PX, PY = f"({PX}+{sdx})", f"({PY}+{sdy})"
    if fxm.get("pulse") and fxm["pulse"]["a"] > 0:
        pm = tl_fx_pulse(fxm["pulse"], T)
        Wexp, Hexp = f"({Wexp}*{pm})", f"({Hexp}*{pm})"
        anim_s = True
    cw_f, chh_f = fx1 - fx0, fy1 - fy0
    # the drawn (cropped) part of the box, relative to the anchor point, in box fractions
    lx, ty = fx0 - ax, fy0 - ay
    anim_p = "pos" in c["kf"] or bool(fxm.get("shake") and fxm["shake"]["a"] > 0)
    # can this layer have see-through pixels? Then every resize works on premultiplied colour, so an edge never picks up
    # the (black or white) colour that sits under fully transparent pixels: no dark or light fringe.
    seethru = bool(p.get("bgr") or fxm.get("gkey") or (st and (st["ow"] > 0 or st["rad"] > 0)) or m.get("kind") == "gif"
                   or str(m.get("name") or "").lower().endswith((".png", ".webp", ".gif", ".mov", ".webm", ".tif", ".tiff")))
    # the resampler: a see-through picture must not ring (a Lanczos / bicubic overshoot on a hard alpha edge is a halo), so it is
    # averaged when it gets smaller and blended when it gets bigger, like the preview; an opaque picture gets Lanczos / bicubic
    _fl = lambda dst, src: ("area" if dst < src else "bilinear") if seethru else ("lanczos" if dst < src else "bicubic")
    if anim_s or anim_r or anim_p:
        # ---- anything that moves (keyframed position / size / rotation, Shake, Pulse, Wiggle): one perspective warp with the
        #      corners as expressions of the frame number. It places the picture to a fraction of a pixel, so a slow move or a
        #      slow zoom glides (whole-pixel steps would make it tick), and the edge is blended on premultiplied colour.
        def _mx(prop):
            return max(kf_value(c, prop, k_) for k_ in range(N)) if prop in c["kf"] else kf_value(c, prop, 0)
        grow = 1.3 if (fxm.get("pulse") and fxm["pulse"]["a"] > 0) else 1.0
        dwm, dhm = bw * _mx(swp) / 100 * cw_f * grow, bh * _mx(shp) / 100 * chh_f * grow     # the biggest it is ever drawn
        klim = min(1.0, 2.0 * W / max(1.0, dwm), 2.0 * H / max(1.0, dhm))                       # (never more than twice the frame)
        pw, ph = max(2, round(dwm * klim)), max(2, round(dhm * klim))
        pad = 2
        Cw, Ch = max(W, pw + 2 * pad), max(H, ph + 2 * pad)
        Cw, Ch = Cw + Cw % 2, Ch + Ch % 2
        ch += (f",premultiply=inplace=1,scale={pw}:{ph}:flags={_fl(pw, px1 - px0)},pad={Cw}:{Ch}:{pad}:{pad}:color=black@0")
        ux, uy = cw_f / pw, chh_f / ph                                  # one picture pixel, in box fractions
        u0, v0 = lx - pad * ux, ty - pad * uy
        u1, v1 = u0 + Cw * ux, v0 + Ch * uy
        Tl = f"((in-1)/{FPS})"            # (perspective counts its frames from 1)
        Wl = Wexp.replace("T", Tl)
        Hl = Hexp.replace("T", Tl)
        A = f"({ROT(Tl)}*PI/180)"
        PXl, PYl = PX.replace("T", Tl), PY.replace("T", Tl)
        corners = []
        for u, v in ((u0, v0), (u1, v0), (u0, v1), (u1, v1)):
            X = f"({u:.8f}*{Wl})"
            Y = f"({v:.8f}*{Hl})"
            corners.append((f"{PXl}+{X}*cos({A})-{Y}*sin({A})", f"{PYl}+{X}*sin({A})+{Y}*cos({A})"))
        ch += ",perspective=" + ":".join(f"x{i}='{cx}':y{i}='{cy}'" for i, (cx, cy) in enumerate(corners)) + \
              ":sense=destination:eval=frame:interpolation=linear"
        if (Cw, Ch) != (W, H):
            ch += f",crop={W}:{H}:0:0"
        if blur > 0:
            ch += f",gblur=sigma={blur:.3f}"
        ch += ",unpremultiply=inplace=1"
        xe, ye = "0", "0"
    elif abs(rot0) > 1e-6:
        # ---- a fixed tilt: drawn at up to twice the size, turned, then brought down with Lanczos (supersampled), all on
        #      premultiplied colour with a see-through border: a smooth edge, no staircase, no fringe
        dw, dh = max(2, round(sw0 * cw_f)), max(2, round(sh0 * chh_f))
        R = int((dw * dw + dh * dh) ** 0.5) + 8 + 2 * bpad
        R += R % 2
        ss = 2.0 if R * 2 <= 3400 else (1.5 if R * 1.5 <= 3400 else 1.0)
        RS = int(round(R * ss))
        RS += RS % 2
        ch += f",premultiply=inplace=1,scale={max(2, round(dw * ss))}:{max(2, round(dh * ss))}:flags={_fl(ss * dw, px1 - px0)},pad=iw+4:ih+4:2:2:color=black@0"
        A = f"({ROT('t')}*PI/180)"
        ch += f",rotate=a='{A}':ow={RS}:oh={RS}:c=black@0:bilinear=1"
        if RS != R:
            ch += f",scale={R}:{R}:flags=area"                       # (the supersampled picture averaged down: no ringing on the edge)
        if blur > 0:
            ch += f",gblur=sigma={blur:.3f}"
        ch += ",unpremultiply=inplace=1"
        cxr, cyr = (lx + cw_f / 2) * sw0, (ty + chh_f / 2) * sh0       # picture centre relative to the anchor
        AT = f"({ROT(T)}*PI/180)"
        xe = f"{PX}+{cxr:.6f}*cos({AT})-{cyr:.6f}*sin({AT})-{R / 2}"
        ye = f"{PY}+{cxr:.6f}*sin({AT})+{cyr:.6f}*cos({AT})-{R / 2}"
    else:
        # ---- nothing moves, no tilt: one resize (Lanczos when it gets smaller) + a fixed place on the frame
        dw, dh = max(1, round(sw0 * cw_f)), max(1, round(sh0 * chh_f))
        fl = _fl(dw, px1 - px0)
        if direct:
            pass                                          # (already at its size: see the top of this function)
        elif seethru:
            ch += f",premultiply=inplace=1,scale={dw}:{dh}:flags={fl}"
        else:
            ch += f",scale={dw}:{dh}:flags={fl}"
        xe = f"{PX}+{lx * sw0:.6f}"
        ye = f"{PY}+{ty * sh0:.6f}"
        if blur > 0:
            ch += f",pad=iw+{2 * bpad}:ih+{2 * bpad}:{bpad}:{bpad}:color=black@0"
            ch += (",gblur" if seethru else ",premultiply=inplace=1,gblur") + f"=sigma={blur:.3f},unpremultiply=inplace=1"
            xe, ye = f"{xe}-{bpad}", f"{ye}-{bpad}"
        elif seethru:
            ch += ",unpremultiply=inplace=1"
    if st and st["so"] > 0:                              # Clip Style: drop shadow / glow = the clip's own shape, blurred, coloured, shifted, under it
        import math
        sig = st["sb"] / 2
        sdx, sdy = round(-math.cos(math.radians(st["sa"])) * st["sd"]), round(math.sin(math.radians(st["sa"])) * st["sd"])
        M = int(max(abs(sdx), abs(sdy)) + 3 * sig + 2)
        sc_ = st["sc"]
        ch += (f",split[tsC{li}][tsD{li}];[tsD{li}]pad=w=iw+{2 * M}:h=ih+{2 * M}:x={M}:y={M}:color=black@0:eval=frame"
               + (f",gblur=sigma={sig:.2f}:steps=2" if sig > 0.3 else "")
               + f",format=rgba,lutrgb=r={int(sc_[1:3], 16)}:g={int(sc_[3:5], 16)}:b={int(sc_[5:7], 16)}:a='val*{st['so'] / 100:.4f}'[tsE{li}];"
               f"[tsE{li}][tsC{li}]overlay=x={M - sdx}:y={M - sdy}:eof_action=pass:format=auto,format=rgba")
        xe, ye = f"{xe}-{M - sdx}", f"{ye}-{M - sdy}"
    # opacity: fixed -> alpha multiply; keyframed -> the same, driven frame by frame from the curve
    if "opacity" in c["kf"]:
        cmd = f"{tag}_op{li}.txt"
        with open(cmd, "w", encoding="utf-8") as fh:
            for k in range(N):
                fh.write(f"{k / FPS:.6f} colorchannelmixer@op{li} aa {kf_value(c, 'opacity', k) / 100:.5f};\n")
        ch += f",sendcmd=f='{os.path.relpath(cmd, UPLOAD_DIR).replace(chr(92), '/')}',colorchannelmixer@op{li}=aa={kf_value(c, 'opacity', 0) / 100:.5f}"
    elif p["opacity"] < 99.99:
        ch += f",colorchannelmixer=aa={p['opacity'] / 100:.5f}"
    ch += tl_place(c) + f"[ly{li}]"
    chains.append(ch)
    return f"[ly{li}]", xe, ye


def tl_place(c):
    """The end of a layer's chain: its place in time. In a chunked render a clip can begin before its window (start < 0):
    it is still built from its own first frame (so every keyframe, animation and effect is where it belongs) and the frames
    before the window are dropped here."""
    s = c["start"]
    pre = f",trim=start_frame={-s},setpts=PTS-STARTPTS" if s < 0 else ""
    return pre + f",setpts='PTS+floor({max(0, s) / FPS:.9f}/TB+0.5)'"


TL_CHUNK_LEN = int(_env_num("KIRU_CHUNK_S", 120) * FPS)     # pieces of two minutes
TL_CHUNK_MIN = TL_CHUNK_LEN * 3 // 2   # a sequence longer than this (or with many layers) is rendered in pieces, so memory stays flat
TL_CHUNK_LAYERS = 28               # a piece with more picture layers than this is halved again (down to 10 s)
_TL_PLAIN_FX = {"mirror", "flipv", "kmirror", "gkey", "rgb", "chroma", "bloom", "vig", "bars"}     # effects that do not depend on the time


def tl_windows(tl):
    """Where a long / crowded sequence is cut into pieces: whole seconds, never inside a transition or a keyframed Adjustment Layer.
    None = render it in one go."""
    total = tl["total"]
    vids = [c for c in tl["clips"] if not c["audioOnly"] and not c["hidden"]]
    if total <= TL_CHUNK_MIN and len(vids) <= 40:
        return None
    forbid = []
    for c in vids:
        tp = c.get("trp")
        if tp:
            forbid.append((c["start"] - (tp["h1"] if tp["side"] == "b" else 0) - 1, c["start"] + (tp["n"] if tp["side"] == "a" else tp["h2"]) + 1))
        elif c["media"]["kind"] == "adj" and (c["kf"] or any(k in (c["p"].get("fx") or {}) for k in ("shake", "pulse", "wiggle", "glitch", "vhs"))):
            forbid.append((c["start"], c["start"] + c["dur"]))
    ok = lambda f: 0 < f < total and all(not (a < f < b) for a, b in forbid)

    def snap(f, lo, hi):
        f = int(round(f / FPS)) * FPS
        for d in range(0, 60):
            for cand in (f + d * FPS, f - d * FPS):
                if lo < cand < hi and ok(cand):
                    return cand
        return None

    cuts, pos = [], 0
    while total - pos > TL_CHUNK_LEN * 1.5:
        cpt = snap(pos + TL_CHUNK_LEN, pos + 5 * FPS, total - 5 * FPS)
        if not cpt:
            break
        cuts.append(cpt)
        pos = cpt
    wins = list(zip([0] + cuts, cuts + [total]))
    out, stack = [], wins[::-1]
    while stack:                                          # crowded pieces are halved
        a, b = stack.pop()
        n = sum(1 for c in vids if c["start"] < b and c["start"] + c["dur"] > a)
        mid = snap((a + b) / 2, a + 5 * FPS, b - 5 * FPS) if (n > TL_CHUNK_LAYERS and b - a >= 20 * FPS) else None
        if mid:
            stack.append((mid, b))
            stack.append((a, mid))
        else:
            out.append((a, b))
    return out if len(out) > 1 else None


def tl_window_clips(tl, a, b):
    """The picture clips that show between frames a and b, with their times counted from a."""
    out = []
    for c in tl["clips"]:
        if c["audioOnly"] or c["hidden"] or c["start"] >= b or c["start"] + c["dur"] <= a:
            continue
        q = dict(c)
        q["start"] = c["start"] - a
        kind = c["media"]["kind"]
        fx = c["p"].get("fx") or {}
        plain = (kind in ("video", "photo") and not c["kf"] and not c.get("curve") and not c.get("trp") and set(fx) <= _TL_PLAIN_FX
                 and not c["p"].get("bgr"))
        if kind == "adj" and not c["kf"]:                 # an Adjustment Layer without keyframes: simply shorter
            if q["start"] < 0:
                q["dur"] += q["start"]
                q["start"] = 0
            q["dur"] = min(q["dur"], b - a - q["start"])
        elif plain:                                       # a plain clip: read from the right place in its file, nothing to skip
            if q["start"] < 0:
                d = -q["start"]
                if kind == "video":
                    q["in"] = c["in"] + d * c["speed"] / FPS
                q["dur"] = c["dur"] - d
                q["start"] = 0
            q["dur"] = max(1, min(q["dur"], b - a - q["start"]))
        out.append(q)
    return out


def build_timeline_graph(tl, tag, video=True, audio=True, n0=0):
    W, H, total = tl["W"], tl["H"], tl["total"]
    inputs, chains, n_in = [], [], [n0]
    if video:
        chains.append(f"color=c=black:s={W}x{H}:r={FPS}:d={total / FPS + 0.5:.4f},trim=end_frame={total},format=gbrp[bg0]")
    cur = "[bg0]"
    vids = [c for c in tl["clips"] if not c["audioOnly"] and not c["hidden"]] if video else []
    vids.sort(key=lambda c: (TL_TRACKS_V.index(c["track"]), c["start"]))       # V1 at the bottom, V3 on top
    # 3D / shape / motion-graphic transitions: the page sends the frames of each one as two short pieces of their own
    # (the last frames of the outgoing clip, the first frames of the incoming one). Each piece holds its last / first frame past
    # the cut, both become full pictures, and tr3_graph mixes them. (Short pieces, so nothing long is ever held in memory.)
    trp_a = {}
    for li, c in enumerate(vids):
        if c["media"]["kind"] == "adj":                    # Adjustment Layer: changes the picture so far instead of adding one
            cur = tl_adjust(cur, c, W, H, inputs, n_in, chains, li, tag)
            continue
        lab, xe, ye = (tl_text_layer if c["media"]["kind"] == "text" else tl_layer)(c, W, H, inputs, n_in, chains, li, tag)
        tp = c.get("trp")
        if tp:
            n, h1, h2 = tp["n"], tp["h1"], tp["h2"]
            tbn = f"settb=1/{FPS},setpts=N"
            clear = f"color=c=black@0:s={W}x{H}:r={FPS}:d={n / FPS + 0.5:.4f},trim=end_frame={n},format=rgba"
            if tp["side"] == "a":
                xa, ya = (v.replace("T", f"min(t,{(c['dur'] - 1) / FPS:.6f})") for v in (xe, ye))
                chains.append(f"{lab}setpts=PTS-STARTPTS,tpad=stop_mode=clone:stop={h2 + 2},trim=end_frame={n},{tbn}[tw{li}]")
                chains.append(f"{clear}[tc{li}]")
                chains.append(f"[tc{li}][tw{li}]overlay=x='{xa}':y='{ya}':eval=frame:eof_action=pass:format=rgb,format=rgba,{tbn}[tf{li}]")
                trp_a[tp["k"]] = (f"[tf{li}]", c["start"])
                continue
            xb, yb = (v.replace("T", f"max(t-{h1 / FPS:.6f},0)") for v in (xe, ye))
            chains.append(f"{lab}setpts=PTS-STARTPTS,tpad=start_mode=clone:start={h1},tpad=stop_mode=clone:stop=2,trim=end_frame={n},{tbn}[tw{li}]")
            chains.append(f"{clear}[tc{li}]")
            chains.append(f"[tc{li}][tw{li}]overlay=x='{xb}':y='{yb}':eval=frame:eof_action=pass:format=rgb,format=rgba,{tbn}[tf{li}]")
            if tp["k"] not in trp_a:                         # (its other half is missing: show this piece as an ordinary clip)
                chains.append(f"[tf{li}]trim=start_frame={h1},setpts='PTS-STARTPTS+floor({c['start'] / FPS:.9f}/TB+0.5)'[tr{li}]")
                w0, n_ = c["start"], h2
            else:
                la, w0 = trp_a.pop(tp["k"])
                out3 = tr3_graph(tp["t"], la, f"[tf{li}]", n, W, H, chains, f"tq{li}", False, tp.get("ez") or 0)
                chains.append(f"{out3}setpts='PTS+floor({w0 / FPS:.9f}/TB+0.5)'[tr{li}]")
                n_ = n
            chains.append(f"{cur}[tr{li}]overlay=x=0:y=0:eof_action=pass:format=gbrp:"
                          f"enable='between(t,{(w0 - 0.5) / FPS:.6f},{(w0 + n_ - 0.5) / FPS:.6f})'[v{li}]")
            cur = f"[v{li}]"
            continue
        s, e = (c["start"] - 0.5) / FPS, (c["start"] + c["dur"] - 0.5) / FPS
        T = f"(t-{c['start'] / FPS:.6f})"                         # overlay's t is the timeline time
        xo, yo = xe.replace("T", T), ye.replace("T", T)
        en = f"enable='between(t,{s:.6f},{e:.6f})'"
        mode = TL_BLENDS[c["p"]["blend"]]
        if mode is None:
            chains.append(f"{cur}{lab}overlay=x='{xo}':y='{yo}':eval=frame:eof_action=pass:format=gbrp:{en}[v{li}]")
        else:
            # blend mode: the layer on a clear full frame, blended with what's under it, then laid on with its alpha
            chains.append(f"color=c=black@0:s={W}x{H}:r={FPS}:d={total / FPS + 0.5:.4f},trim=end_frame={total},format=rgba[cl{li}]")
            chains.append(f"[cl{li}]{lab}overlay=x='{xo}':y='{yo}':eval=frame:eof_action=pass:format=rgb:{en},split[fa{li}][fc{li}]")
            chains.append(f"[fa{li}]alphaextract[al{li}]")
            chains.append(f"[fc{li}]format=gbrp[co{li}]")
            chains.append(f"{cur}split[ba{li}][bb{li}]")
            chains.append(f"[ba{li}][co{li}]blend=all_mode={mode}[bm{li}]")
            chains.append(f"[bm{li}][al{li}]alphamerge[ma{li}]")
            chains.append(f"[bb{li}][ma{li}]overlay=format=gbrp[v{li}]")
        cur = f"[v{li}]"
    # back to video levels (BT.709, limited range) and tagged so every player shows the same colours
    if video:
        chains.append(f"{cur}trim=end_frame={total},scale=out_color_matrix=bt709:out_range=tv,format=yuv420p,setsar=1[vout]")
    if not audio:
        return inputs, chains
    # ---- audio: every clip with sound (video clips + A1/A2), its volume curve, at its place, mixed
    aud, grp = [], {}
    for ai, c in enumerate(tl["clips"]):
        m = c["media"]
        if not m.get("audio") or c["p"]["mute"] or c["p"]["volume"] <= 0 and "volume" not in c["kf"]:
            continue
        if c.get("curve"):                                 # a speed-graph clip plays without its own sound
            continue
        sp, cs, N = c["speed"], c["in"], c["dur"]
        s0 = max(0.0, cs - SEEK_MARGIN)
        need = N * sp / FPS
        inputs.extend(["-ss", f"{s0 + m.get('v0', 0):.6f}", "-t", f"{cs - s0 + need + 0.5:.6f}", "-i", os.path.basename(m["path"])])
        idx = n_in[0]
        n_in[0] += 1
        vol = kf_expr(c, "volume", "t") + "/100"
        if abs(c["p"].get("gain", 0)) > 1e-6:                  # Normalize: a fixed gain in dB on top of the volume
            vol = f"({vol})*{10 ** (c['p']['gain'] / 20):.6f}"
        tempo = "," + atempo_chain(sp) if abs(sp - 1) > 1e-6 else ""
        chmix = chan_filter(c["p"].get("chan", "stereo"), c["p"].get("pan", 0))
        ms = round(c["start"] / FPS * 1000)
        L = N / FPS
        fi, fo = min(c["p"]["fadeIn"], L), min(c["p"]["fadeOut"], L)
        fades = (f",afade=t=in:st=0:d={fi:.6f}" if fi >= 1 / FPS else "") + \
                (f",afade=t=out:st={L - fo:.6f}:d={fo:.6f}" if fo >= 1 / FPS else "")
        chains.append(f"[{idx}:a]atrim=start={cs - s0:.6f}:duration={need:.6f},asetpts=PTS-STARTPTS{tempo},"
                      f"aformat=sample_rates=48000:channel_layouts=stereo{chmix},atrim=end={L:.6f},asetpts=PTS-STARTPTS{afx_filter(c['p'].get('ax'))}{fades},"
                      f"volume='{vol}':eval=frame,adelay={ms}:all=1[a{ai}]")
        aud.append(f"[a{ai}]")
        grp[f"[a{ai}]"] = "duck" if c["track"] in (tl.get("duck") or []) else "key" if not c["audioOnly"] else "other"
    total_s = total / FPS
    ducked, keys = [a_ for a_ in aud if grp[a_] == "duck"], [a_ for a_ in aud if grp[a_] == "key"]
    if ducked and keys:
        # Auto-duck: the music track is turned down by the sound of the video clips (a side-chain compressor: about -15 dB while
        # the video speaks, back up over ~0.5 s when it is silent)
        mixn = lambda lst, lab: chains.append("".join(lst) + (f"amix=inputs={len(lst)}:normalize=0:dropout_transition=0" if len(lst) > 1 else "anull") + f",apad,atrim=end={total_s:.6f}[{lab}]")
        mixn(keys, "dkk")
        mixn(ducked, "dkm")
        chains.append("[dkk]asplit[dkk1][dkk2]")
        chains.append(f"[dkm][dkk2]sidechaincompress=threshold={DUCK_THRESHOLD}:ratio={DUCK_RATIO}:attack={DUCK_ATTACK_MS}:release={DUCK_RELEASE_MS}:makeup=1[dkd]")
        aud = ["[dkd]", "[dkk1]"] + [a_ for a_ in aud if grp[a_] == "other"]
    if aud:
        mix = "".join(aud) + (f"amix=inputs={len(aud)}:normalize=0:dropout_transition=0," if len(aud) > 1 else "anull,")
        chains.append(f"{mix}alimiter=limit=0.89:level=0,apad,atrim=end={total_s:.6f}[aout]")
    else:
        chains.append(f"anullsrc=r=48000:cl=stereo,atrim=end={total_s:.6f}[aout]")
    return inputs, chains


def run_timeline_render(jid):
    with RENDER_LOCK:
        try:
            _run_timeline_render(jid)
        finally:
            job_release(jid)


def _run_timeline_render(jid):
    job = JOBS[jid]
    tl = job["tl"]
    out_path = os.path.join(EXPORT_DIR, jid + ".mp4")
    job["path"] = out_path
    tag = os.path.join(WORK_DIR, jid)
    total = tl["total"]
    ofps = tl.get("fps") or FPS                            # Timeline frame rate (Settings): the finished picture is written at 24 / 30 / 60 fps
    out_total = max(1, round(total * ofps / FPS))
    keep_debug = False
    try:
        encoders = ["nvenc", "x264"] if nvenc_available() else ["x264"]
        last_err = ""
        for enc in encoders:
            enc_args = NVENC_ARGS if enc == "nvenc" else X264_ARGS
            job.update(status="rendering", progress=0.0, encoder="NVENC (GPU)" if enc == "nvenc" else "libx264 (CPU)")
            try:
                col = ["-colorspace", "bt709", "-color_primaries", "bt709", "-color_trc", "bt709", "-color_range", "tv"]
                wins = tl_windows(tl)
                if not wins:
                    inputs, chains = build_timeline_graph(tl, tag)
                    with open(tag + "_graph.txt", "w", encoding="utf-8") as fh:
                        fh.write(";\n".join(chains))
                    cmd = (["ffmpeg", "-hide_banner", "-y", "-v", "error"] + inputs + filter_script_args(tag + "_graph.txt")
                           + ["-map", "[vout]", "-map", "[aout]", "-frames:v", str(out_total), "-r", str(ofps)] + enc_args + col
                           + ["-c:a", "aac", "-b:a", "256k", "-t", f"{total / FPS:.4f}", "-movflags", "+faststart",
                              "-progress", "pipe:1", "-nostats", out_path])
                    run_ffmpeg(job, cmd, tag + "_ffmpeg.log", 0, out_total, out_total)
                else:
                    # a long or crowded sequence: the picture in pieces (each one a small FFmpeg job, so memory stays flat however
                    # long the edit is), then the pieces are joined without re-encoding and the sound is mixed once over all of it
                    job["chunks"] = len(wins)
                    done, lst = 0, []
                    for ci, (wa, wb) in enumerate(wins):
                        job["chunk"] = ci + 1
                        sub = dict(tl, total=wb - wa, clips=tl_window_clips(tl, wa, wb))
                        ctag = f"{tag}_w{ci:03d}"
                        inputs, chains = build_timeline_graph(sub, ctag, audio=False)
                        with open(ctag + "_graph.txt", "w", encoding="utf-8") as fh:
                            fh.write(";\n".join(chains))
                        part = f"{ctag}_part.mp4"
                        nf = max(1, round((wb - wa) * ofps / FPS))
                        cmd = (["ffmpeg", "-hide_banner", "-y", "-v", "error"] + inputs + filter_script_args(ctag + "_graph.txt")
                               + ["-map", "[vout]", "-an", "-frames:v", str(nf), "-r", str(ofps)] + enc_args + col
                               + ["-f", "mp4", "-progress", "pipe:1", "-nostats", part])
                        run_ffmpeg(job, cmd, tag + "_ffmpeg.log", done, nf, out_total, span=JOIN_AT)
                        lst.append(f"file '{os.path.basename(part)}'\nduration {nf / ofps:.6f}\n")
                        done += nf
                        for name in os.listdir(WORK_DIR):          # this piece's own work files are not needed any more
                            if name.startswith(os.path.basename(ctag) + "_") and not name.endswith(("_part.mp4", "_graph.txt")):
                                _rm(os.path.join(WORK_DIR, name))
                    job["chunk"] = "join"
                    with open(tag + "_list.txt", "w", encoding="utf-8") as fh:
                        fh.write("".join(lst))
                    ainputs, achains = build_timeline_graph(tl, tag, video=False, n0=1)
                    with open(tag + "_agraph.txt", "w", encoding="utf-8") as fh:
                        fh.write(";\n".join(achains))
                    cmd = (["ffmpeg", "-hide_banner", "-y", "-v", "error", "-f", "concat", "-safe", "0", "-i", os.path.abspath(tag + "_list.txt")]
                           + ainputs + filter_script_args(tag + "_agraph.txt")
                           + ["-map", "0:v", "-map", "[aout]", "-c:v", "copy", "-c:a", "aac", "-b:a", "256k", "-t", f"{total / FPS:.4f}",
                              "-movflags", "+faststart", "-progress", "pipe:1", "-nostats", out_path])
                    run_ffmpeg(job, cmd, tag + "_ffmpeg.log", 0, out_total, out_total, base=JOIN_AT, span=0.98 - JOIN_AT)
                    for name in os.listdir(WORK_DIR):          # joined: the pieces go at once (a long edit is gigabytes of them)
                        if name.startswith(jid + "_w") and name.endswith("_part.mp4"):
                            _rm(os.path.join(WORK_DIR, name))
                export_finish(job, out_path, tl.get("export") or parse_export(None), out_total)
                job.update(status="done", progress=1.0, finished=time.time())
                return
            except RenderError as e:
                last_err = str(e)
                _rm(out_path)
        job.update(status="error", error=last_err or "FFmpeg failed.")
        keep_debug = True
    except Cancelled:
        job["status"] = "cancelled"
        _rm(out_path)
    except Exception as e:
        job.update(status="error", error=str(e))
        keep_debug = True
    finally:
        job["proc"] = None
        for name in os.listdir(WORK_DIR):
            if name.startswith(jid) and not (keep_debug and name.endswith((".txt", ".log"))):
                _rm(os.path.join(WORK_DIR, name))


@app.post("/api/audio")
def api_audio():
    """Timeline bin: an audio file (music, voice-over, sound effect)."""
    f = media_upload()
    if not f or not f.filename:
        return err("No file received.")
    uid, path = save_upload(f, UPLOAD_DIR)
    try:
        info = probe(path)
        if not any(s.get("codec_type") == "audio" for s in info.get("streams", [])):
            raise RuntimeError("That file has no audio track.")
        play_path = path
        if audio_needs_play_copy(f.filename, info):
            play_path = os.path.join(UPLOAD_DIR, uid + "_play.wav")
            r = run(["ffmpeg", "-v", "error", "-y", "-i", path, "-vn", "-ac", "2", "-ar", "44100", play_path])
            if r.returncode != 0:
                raise RuntimeError("Could not convert audio for playback.")
        peaks, rate, dur = song_peaks(path)
    except Exception as e:
        _rm(path)
        return err(str(e))
    AUDIOS[uid] = {"path": path, "play_path": play_path, "name": f.filename, "duration": dur}
    if request.form.get("lo") == "1":                  # the Timeline: the small waveform now, the full one when it is zoomed in
        peaks, rate = peaks_low(peaks, rate)
    return jsonify({"id": uid, "name": f.filename, "url": f"/media/audio/{uid}", "duration": round(dur, 4),
                    "peaks": peaks, "peakRate": rate, "path": ORIGIN.get(uid, "")})


@app.get("/media/audio/<aid>")
def media_audio(aid):
    if aid in AUDIOS:
        return send_file(AUDIOS[aid]["play_path"], conditional=True)
    return err("Not found.", 404)


SFX = {"whoosh": "Whoosh", "whoosh_fast": "Fast whoosh", "pop": "Pop", "click": "Click", "ding": "Ding", "boom": "Boom / impact",
       "riser": "Riser", "glitch": "Glitch zap", "camera": "Camera shutter", "swipe": "Swipe"}


def sfx_make(name, path):
    """Synthesise one sound effect (nothing is downloaded): shaped noise and tones, 44.1 kHz stereo WAV."""
    import numpy as np
    import wave
    sr = 44100
    rng = np.random.default_rng(abs(hash(name)) % (2 ** 31) if False else sum(map(ord, name)))
    def noise(n):
        return rng.standard_normal(n)
    def lowpass(x, fc):                                # one-pole, fc may be an array (a sweep)
        fc = np.broadcast_to(np.asarray(fc, float), x.shape)
        a = 1 - np.exp(-2 * np.pi * fc / sr)
        y = np.empty_like(x)
        acc = 0.0
        for i in range(len(x)):
            acc += a[i] * (x[i] - acc)
            y[i] = acc
        return y
    def env(n, att, rel_pow=2.0, peak=None):
        t = np.linspace(0, 1, n)
        pk = att if peak is None else peak
        return np.where(t < pk, (t / max(1e-6, pk)) ** 1.5, ((1 - t) / max(1e-6, 1 - pk)) ** rel_pow)
    if name in ("whoosh", "whoosh_fast", "swipe"):
        d = {"whoosh": 0.9, "whoosh_fast": 0.45, "swipe": 0.3}[name]
        n = int(sr * d)
        t = np.linspace(0, 1, n)
        fc = 300 + 5200 * np.sin(np.pi * t) ** 2
        x = lowpass(noise(n), fc) - lowpass(noise(n), 180)
        y = x * env(n, 0.55 if name != "swipe" else 0.35, 2.2)
    elif name == "pop":
        n = int(sr * 0.14)
        t = np.arange(n) / sr
        f = 520 * np.exp(-t * 22) + 140
        y = np.sin(2 * np.pi * np.cumsum(f) / sr) * np.exp(-t * 34)
    elif name == "click":
        n = int(sr * 0.05)
        t = np.arange(n) / sr
        y = (np.sin(2 * np.pi * 2400 * t) * 0.6 + noise(n) * 0.4) * np.exp(-t * 160)
    elif name == "ding":
        n = int(sr * 1.1)
        t = np.arange(n) / sr
        y = sum(a_ * np.sin(2 * np.pi * f_ * t) * np.exp(-t * d_) for f_, a_, d_ in ((1318.5, 1, 4.5), (2637, 0.45, 7), (3955.5, 0.2, 10)))
    elif name == "boom":
        n = int(sr * 1.3)
        t = np.arange(n) / sr
        f = 95 * np.exp(-t * 5) + 34
        y = np.sin(2 * np.pi * np.cumsum(f) / sr) * np.exp(-t * 3.4) + lowpass(noise(n), 900) * np.exp(-t * 26) * 0.9
    elif name == "riser":
        n = int(sr * 1.8)
        t = np.linspace(0, 1, n)
        f = 180 * (2 ** (t * 3.2))
        y = (np.sin(2 * np.pi * np.cumsum(f) / sr) * 0.5 + lowpass(noise(n), 400 + 7000 * t ** 2) * 0.7) * t ** 1.6
        y[-int(sr * 0.02):] *= np.linspace(1, 0, int(sr * 0.02))
    elif name == "glitch":
        n = int(sr * 0.35)
        x = np.sign(np.sin(2 * np.pi * np.cumsum(rng.choice([220, 880, 1760, 3520, 110], n // 900 + 1).repeat(900)[:n]) / sr))
        gate = (rng.random(n // 700 + 1) > 0.35).repeat(700)[:n]
        y = (x * 0.6 + noise(n) * 0.3) * gate * np.linspace(1, 0.4, n)
    else:                                              # camera shutter: two clicks
        n = int(sr * 0.22)
        t = np.arange(n) / sr
        y = np.zeros(n)
        for t0 in (0.0, 0.11):
            m = t >= t0
            y[m] += (noise(m.sum()) * np.exp(-(t[m] - t0) * 90))
        y = lowpass(y, 5200)
    y = y / (np.abs(y).max() or 1) * 0.8
    st = np.stack([y, y], axis=1)
    if name in ("whoosh", "whoosh_fast", "swipe"):     # the whoosh travels left to right
        pan = np.linspace(0.15, 0.85, len(y))
        st = np.stack([y * np.cos(pan * np.pi / 2), y * np.sin(pan * np.pi / 2)], axis=1) * 1.2
    pcm = (np.clip(st, -1, 1) * 32767).astype("<i2")
    with wave.open(path, "wb") as w:
        w.setnchannels(2)
        w.setsampwidth(2)
        w.setframerate(sr)
        w.writeframes(pcm.tobytes())


@app.post("/api/sfx/<name>")
def api_sfx(name):
    """Timeline Sound FX library: made on this PC the first time it is used, then it behaves like any audio file in the bin."""
    if name not in SFX:
        return err("Unknown sound effect.", 404)
    uid = uuid.uuid4().hex
    path = os.path.join(UPLOAD_DIR, uid + ".wav")
    try:
        sfx_make(name, path)
        peaks, rate, dur = song_peaks(path)
    except Exception as e:
        _rm(path)
        return err("Could not make that sound effect: " + str(e), 500)
    AUDIOS[uid] = {"path": path, "play_path": path, "name": SFX[name] + ".wav", "duration": dur}
    return jsonify({"id": uid, "name": SFX[name], "url": f"/media/audio/{uid}", "duration": round(dur, 4), "peaks": peaks, "peakRate": rate})


@app.post("/api/audio/<aid>/beats")
def api_audio_beats(aid):
    """Beat markers for the Timeline (snapping): librosa beats of the whole file."""
    a = AUDIOS.get(aid) or (SONGS.get(aid))
    if not a:
        return err("Unknown audio.", 404)
    return _beats_of(a)


@app.post("/api/clip/<cid>/beats")
def api_clip_beats(cid):
    """The same beat detection on a video clip's own sound (Timeline: Auto-detect beats on a clip)."""
    c = CLIPS.get(cid)
    if not c:
        return err("Unknown clip.", 404)
    if not c.get("audio"):
        return err("This clip has no sound.")
    return _beats_of(c)


def _beats_of(a):
    try:
        librosa = get_librosa()
        import numpy as np
        wav = os.path.join(WORK_DIR, uuid.uuid4().hex + ".wav")
        out = run(["ffmpeg", "-v", "error", "-y", "-i", a["path"], "-vn", "-ac", "1", "-ar", "22050", "-f", "wav", wav], timeout=600)
        if out.returncode != 0:
            raise RuntimeError(out.stderr[-300:])
        try:
            y, sr = librosa.load(wav, sr=22050, mono=True)
        finally:
            _rm(wav)
        env = librosa.onset.onset_strength(y=y, sr=sr, hop_length=512)
        tempo, beats = librosa.beat.beat_track(onset_envelope=env, sr=sr, hop_length=512, trim=False)
        times = [round(float(t), 4) for t in librosa.frames_to_time(np.asarray(beats, dtype=int), sr=sr, hop_length=512)]
        return jsonify({"beats": times, "bpm": round(float(np.atleast_1d(tempo)[0]) if np.size(tempo) else 0.0, 1)})
    except Exception as e:
        return err(str(e))


@app.post("/api/tl/adopt_song/<sid>")
def api_tl_adopt_song(sid):
    """Send to Timeline: the Beat Sync song becomes an audio item of the Timeline bin (same file, no second upload)."""
    song = SONGS.get(sid)
    if not song:
        return err("Song not found - load it again.", 404)
    AUDIOS[sid] = {"path": song["path"], "play_path": song.get("play_path") or song["path"], "name": song["name"], "duration": song["duration"]}
    return jsonify({"id": sid, "name": song["name"], "url": f"/media/audio/{sid}", "duration": round(song["duration"], 4)})


@app.post("/api/song/from_audio/<aid>")
def api_song_from_audio(aid):
    """Send to Beat Sync: an audio item of the Timeline bin becomes the Beat Sync song (the reverse of adopt_song)."""
    a = AUDIOS.get(aid)
    if not a:
        return err("That audio is not loaded any more - import it again.", 404)
    try:
        peaks, rate, dur = song_peaks(a["path"])
    except Exception as e:
        return err(str(e))
    SONGS[aid] = {"path": a["path"], "play_path": a.get("play_path") or a["path"], "name": a["name"], "duration": dur}
    return jsonify({"id": aid, "name": a["name"], "url": f"/media/song/{aid}", "duration": round(dur, 4), "peaks": peaks, "peakRate": rate,
                    "path": ORIGIN.get(aid, "")})


@app.get("/api/disk")
def api_disk():
    """Room on the drive the export is written to, against a rough size of this export (for the warning before rendering)."""
    secs = _fnum(request.args.get("secs"), 10, 0, 86400)
    fmt = request.args.get("fmt") or "h264"
    scale = _fnum(request.args.get("scale"), 1, 0.1, 4)
    per_s = {"prores": 22e6, "hevc": 2.0e6, "vp9": 2.0e6}.get(fmt, 2.6e6) * scale * scale      # bytes per second of video, on the generous side
    need = secs * (2.6e6 + (per_s if fmt != "h264" else 0)) + secs * 0.4e6 + 150e6                # the H.264 master + the chosen format + work files
    try:
        os.makedirs(EXPORT_DIR, exist_ok=True)
        free = shutil.disk_usage(EXPORT_DIR).free
    except OSError:
        return jsonify(ok=True, free=None)
    drive = os.path.splitdrive(os.path.abspath(EXPORT_DIR))[0] or os.path.abspath(EXPORT_DIR)
    return jsonify(ok=free > max(need * 1.5, 1.0e9), free=free, need=int(need), drive=drive)


ASSET_DIR = os.path.join(BASE_DIR, "project_assets")      # the pictures of saved projects (Image Editor layers, overlay pictures): one file each, named by its content
_ASSET_EXT = {"image/png": ".png", "image/jpeg": ".jpg", "image/webp": ".webp", "image/gif": ".gif"}


@app.post("/api/asset")
def api_asset_put():
    """A picture that belongs to a saved project. The .kiru file only keeps its name (a hash of the bytes), so it stays tiny."""
    raw = request.get_data()
    if not raw or len(raw) > 120_000_000:
        return err("Empty or too big.", 413)
    ext = _ASSET_EXT.get((request.headers.get("Content-Type") or "").split(";")[0].strip().lower(), ".png")
    aid = hashlib.sha1(raw).hexdigest()[:24] + ext
    try:
        os.makedirs(ASSET_DIR, exist_ok=True)
        p = os.path.join(ASSET_DIR, aid)
        if not os.path.isfile(p) or os.path.getsize(p) != len(raw):
            with open(p + ".tmp", "wb") as fh:
                fh.write(raw)
            os.replace(p + ".tmp", p)
    except OSError as e:
        return err("The picture could not be stored: " + str(e), 500)
    return jsonify(id=aid)


@app.get("/api/asset/<aid>")
def api_asset_get(aid):
    if not re.fullmatch(r"[0-9a-f]{24}\.(png|jpg|webp|gif)", aid or ""):
        return err("Unknown picture.", 404)
    p = os.path.join(ASSET_DIR, aid)
    if not os.path.isfile(p):
        return err("That picture is not on this PC any more.", 404)
    return send_file(p, max_age=0)


CLIPBOARD_FILE = os.path.join(BASE_DIR, "clipboard.kiru_clip")     # what was last copied (a Timeline clip or an Image Editor layer): readable by any Kiru window


@app.route("/api/clipboard", methods=["GET", "POST"])
def api_clipboard():
    """Copy in one project (or one Kiru window), paste in another: the copied clip / layer is kept in a small file next to Kiru."""
    if request.method == "POST":
        raw = request.get_data()
        if not raw or len(raw) > 80_000_000:
            return err("Too big for the shared clipboard.", 413)
        if len(raw) < 4_000_000:
            try:
                o = json.loads(raw)
                md = o.get("media") if isinstance(o, dict) else None
                if isinstance(md, dict) and md.get("id") and not (md.get("path") and os.path.isfile(str(md["path"]))):
                    src = AUDIOS.get(md["id"]) if md.get("kind") == "audio" else CLIPS.get(md["id"])
                    p = src and (ORIGIN.get(md["id"]) or src.get("image") or src.get("path"))
                    if p and os.path.isfile(p):
                        md["path"] = os.path.abspath(p)
                        md["size"] = md.get("size") or os.path.getsize(p)
                        raw = json.dumps(o).encode("utf-8")
            except (ValueError, TypeError):
                pass
        try:
            tmp = CLIPBOARD_FILE + ".tmp"
            with open(tmp, "wb") as fh:
                fh.write(raw)
            os.replace(tmp, CLIPBOARD_FILE)
        except OSError as e:
            return err("The clipboard file could not be written: " + str(e), 500)
        return jsonify(ok=True)
    if not os.path.isfile(CLIPBOARD_FILE):
        return jsonify({})
    try:
        with open(CLIPBOARD_FILE, "rb") as fh:
            return app.response_class(fh.read(), mimetype="application/json")
    except OSError:
        return jsonify({})


@app.route("/api/autosave", methods=["GET", "POST", "DELETE"])
def api_autosave():
    AUTOSAVE_FILE = autosave_path()
    if request.method == "DELETE":
        _rm(AUTOSAVE_FILE)
        return jsonify(ok=True)
    if request.method == "POST":
        raw = request.get_data()
        if not raw or len(raw) > 400_000_000:
            return err("Nothing to save.")
        try:
            tmp = AUTOSAVE_FILE + ".tmp"
            with open(tmp, "wb") as fh:
                fh.write(raw)
            os.replace(tmp, AUTOSAVE_FILE)                 # never a half-written file
        except OSError as e:
            return err("Auto-save could not write its file: " + str(e), 500)
        return jsonify(ok=True, saved=time.time())
    if not os.path.isfile(AUTOSAVE_FILE):
        return jsonify(exists=False)
    if request.args.get("data") != "1":
        return jsonify(exists=True, saved=os.path.getmtime(AUTOSAVE_FILE), size=os.path.getsize(AUTOSAVE_FILE))
    return send_file(AUTOSAVE_FILE, mimetype="application/json", max_age=0)


@app.route("/api/recent", methods=["GET", "POST"])
def api_recent():
    """The 5 most recent projects. POST {name, data}: remember this one (saved or opened just now)."""
    if request.method == "GET":
        return jsonify(projects=[{"file": e["file"], "name": e.get("name"), "ts": e.get("ts"), "info": e.get("info", "")} for e in recent_index()])
    d = request.get_json(silent=True) or {}
    data = d.get("data")
    if not isinstance(data, dict) or data.get("app") != "kiru":
        return err("Not a Kiru project.")
    name = re.sub(r"[\x00-\x1f]", " ", str(d.get("name") or "project.kiru"))[:80].strip() or "project.kiru"
    safe = re.sub(r"[^A-Za-z0-9 _.()\-]+", "_", name).strip(" .")[:70] or "project.kiru"
    try:
        os.makedirs(RECENT_DIR, exist_ok=True)
        with open(os.path.join(RECENT_DIR, safe), "w", encoding="utf-8") as fh:
            json.dump(data, fh)
        lst = [{"file": safe, "name": name, "ts": time.time(), "info": str(d.get("info") or "")[:120]}] + [e for e in recent_index() if e.get("file") != safe]
        for e in lst[RECENT_MAX:]:
            _rm(os.path.join(RECENT_DIR, e["file"]))
        with open(os.path.join(RECENT_DIR, "index.json"), "w", encoding="utf-8") as fh:
            json.dump(lst[:RECENT_MAX], fh)
    except OSError as e:
        return err("Could not remember this project: " + str(e), 500)
    return jsonify(ok=True)


@app.get("/api/recent/<path:fn>")
def api_recent_get(fn):
    e = next((x for x in recent_index() if x.get("file") == fn), None)
