@app.post("/api/tl/loudness")
def api_tl_loudness():
    """Normalize: measure how loud one timeline clip is (integrated loudness, LUFS) and answer the gain that brings it to the target."""
    d = request.get_json(force=True) or {}
    m = AUDIOS.get(d.get("media")) if d.get("kind") == "audio" else CLIPS.get(d.get("media"))
    if not m or not m.get("path") or (d.get("kind") != "audio" and not m.get("audio")):
        return err("That clip has no sound to measure.")
    t0 = _fnum(d.get("in"), 0, 0, 1e6) + (m.get("v0", 0) if d.get("kind") != "audio" else 0)
    dur = _fnum(d.get("dur"), 1, 0.05, 36000)
    target = _fnum(d.get("target"), -14, -40, -5)
    af = "aformat=sample_rates=48000:channel_layouts=stereo" + chan_filter(d.get("chan") if d.get("chan") in TL_CHAN else "stereo", _fnum(d.get("pan"), 0, -100, 100)) + ",ebur128=peak=none"
    try:
        out = run(["ffmpeg", "-hide_banner", "-nostats", "-ss", f"{t0:.6f}", "-t", f"{dur:.6f}", "-i", m["path"], "-vn", "-af", af, "-f", "null", "-"], timeout=180)
    except Exception as e:                                  # noqa: BLE001
        return err("Could not measure the loudness: " + str(e))
    tail = out.stderr[out.stderr.rfind("Summary:"):] if "Summary:" in out.stderr else ""
    mm = re.search(r"I:\s*(-?[0-9.]+|-inf)\s*LUFS", tail)
    if not mm or mm.group(1) == "-inf" or float(mm.group(1)) < -69:
        return err("That clip is silent (or too short to measure), so there is nothing to normalize.")
    lufs = float(mm.group(1))
    return jsonify({"lufs": round(lufs, 2), "gain": round(max(-40.0, min(40.0, target - lufs)), 2), "target": target})


@app.post("/api/tl/render")
def api_tl_render():
    try:
        tl = tl_validate(request.get_json(force=True) or {})
    except (ValueError, KeyError, TypeError) as e:
        return err(str(e) or "Invalid timeline.")
    if any(j["status"] in ("queued", "rendering") for j in JOBS.values()):
        return err("A render is already running.")
    jid = uuid.uuid4().hex[:12]
    JOBS[jid] = {"status": "queued", "progress": 0.0, "tl": tl, "plan": None, "encoder": "",
                 "started": time.time(), "name": time.strftime("timeline_%Y%m%d_%H%M%S.mp4")}
    threading.Thread(target=run_timeline_render, args=(jid,), daemon=True).start()
    return jsonify({"id": jid})



# ---------------------------------------------------------------------------
# Auto Reframe (Timeline, 9:16): where is the subject across the used part of a wide clip?
# RVM matte centroid (already made, or run on samples), else OpenCV face / person / motion.
# Returns Position X keyframes as [clip frame, centre x 0..1 of the source width].
# ---------------------------------------------------------------------------
def _reframe_frames(src, t0, span, sw, sh, sfps=4.0):
    """Small RGB frames (numpy) sampled at sfps from t0 for span seconds."""
    import numpy as np
    pw = 320
    ph = max(2, int(round(sh * pw / max(1, sw) / 2)) * 2)
    out = subprocess.run(["ffmpeg", "-v", "error", "-ss", f"{t0:.3f}", "-t", f"{max(0.1, span):.3f}", "-i", src, "-map", "0:v:0",
                          "-vf", f"fps={sfps},scale={pw}:{ph}:flags=bilinear", "-f", "rawvideo", "-pix_fmt", "rgb24", "-"],
                         capture_output=True, timeout=900, creationflags=NO_WINDOW)
    raw = out.stdout or b""
    fb = pw * ph * 3
    n = len(raw) // fb
    if not n:
        raise RuntimeError("Couldn't read frames from this clip.")
    return [np.frombuffer(raw[i * fb:(i + 1) * fb], np.uint8).reshape(ph, pw, 3) for i in range(n)], pw, ph


def _centroid(mask):
    import numpy as np
    m = mask.astype(np.float32)
    tot = float(m.sum())
    if tot < 0.002 * m.size * 255:
        return None
    xs = np.arange(m.shape[1], dtype=np.float32)
    return float((m.sum(axis=0) * xs).sum() / tot) / max(1, m.shape[1] - 1)


def _reframe_rvm(frames):
    import numpy as np
    sess, prov = rvm_session()
    rec = [np.zeros((1, 1, 1, 1), np.float32)] * 4
    ds = np.array([1.0], np.float32)
    xs = []
    for f in frames:
        x = f.transpose(2, 0, 1)[None].astype(np.float32) / 255
        sess, (_, pha, *rec) = rvm_run(sess, {"src": x, "r1i": rec[0], "r2i": rec[1], "r3i": rec[2], "r4i": rec[3], "downsample_ratio": ds})
        xs.append(_centroid((pha[0, 0] * 255).clip(0, 255)))
    return xs, "AI subject (" + (ai_label() or prov) + ")"


def _reframe_cv(frames):
    import cv2
    import numpy as np
    face = None
    try:
        face = cv2.CascadeClassifier(os.path.join(cv2.data.haarcascades, "haarcascade_frontalface_default.xml"))
        if face.empty():
            face = None
    except Exception:
        face = None
    hog = cv2.HOGDescriptor()
    hog.setSVMDetector(cv2.HOGDescriptor_getDefaultPeopleDetector())
    xs, prev, used = [], None, set()
    for f in frames:
        g = cv2.cvtColor(f, cv2.COLOR_RGB2GRAY)
        W = g.shape[1]
        cx = None
        if face is not None:
            fs = face.detectMultiScale(g, 1.15, 5, minSize=(18, 18))
            if len(fs):
                x, y, w, h = max(fs, key=lambda r: r[2] * r[3])
                cx, _ = (x + w / 2) / W, used.add("face")
        if cx is None:
            rs, ws = hog.detectMultiScale(cv2.cvtColor(f, cv2.COLOR_RGB2BGR), winStride=(8, 8), padding=(8, 8), scale=1.05)
            if len(rs):
                ws = np.ravel(ws) if len(ws) else np.ones(len(rs))
                tot = float(sum(r[2] * r[3] * max(0.05, float(wt)) for r, wt in zip(rs, ws)))
                cx = sum((r[0] + r[2] / 2) * r[2] * r[3] * max(0.05, float(wt)) for r, wt in zip(rs, ws)) / tot / W
                used.add("person")
        if cx is None and prev is not None:
            d = cv2.GaussianBlur(cv2.absdiff(g, prev), (9, 9), 0)
            _, d = cv2.threshold(d, 18, 255, cv2.THRESH_BINARY)
            cx = _centroid(d)
            if cx is not None:
                used.add("motion")
        prev = g
        xs.append(cx)
    return xs, "OpenCV " + (" + ".join(sorted(used)) or "centre")


def reframe_points(cid, t_in, dur_f, speed):
    import numpy as np
    c = CLIPS.get(cid)
    if not c:
        raise ValueError("Unknown clip.")
    w, h, fps, vd, rate = _video_info(c["path"])
    if not w or not h:
        raise ValueError("This clip has no picture.")
    span = dur_f / FPS * speed
    sfps = 4.0
    m = c.get("matte") or {}
    xs, method = None, ""
    if m.get("status") == "ready" and os.path.exists(m.get("path", "")):
        fr, _, _ = _reframe_frames(m["path"], max(0.0, t_in - m.get("vd", 0)), span, m["w"], m["h"], sfps)
        xs, method = [_centroid(f[:, :, 0]) for f in fr], "AI matte"
    if xs is None:
        fr, _, _ = _reframe_frames(c["path"], t_in, span, w, h, sfps)
        try:
            import onnxruntime  # noqa: F401
            xs, method = _reframe_rvm(fr)
        except Exception:
            xs = None
        if xs is None or all(x is None for x in xs):
            xs, method = _reframe_cv(fr)
    n = len(xs)
    known = [i for i, x in enumerate(xs) if x is not None]
    if not known:
        arr = np.full(n, 0.5)
        method += " - no subject found, centred"
    else:
        arr = np.interp(np.arange(n), known, [xs[i] for i in known])
    # smooth: median then a moving average (~1 s) so the frame glides rather than jitters
    k = 2
    med = np.array([np.median(arr[max(0, i - k):i + k + 1]) for i in range(n)])
    sm = np.convolve(np.pad(med, (2, 2), mode="edge"), np.ones(5) / 5, mode="valid")
    pts, step = [], max(1, int(round(FPS * 0.5)))
    for kf in list(range(0, max(1, int(dur_f)), step)) + [max(0, int(dur_f) - 1)]:
        ts = kf / FPS * speed                       # source seconds from in
        i = min(n - 1, max(0, ts * sfps))
        lo = int(i)
        hi = min(n - 1, lo + 1)
        v = float(sm[lo] + (sm[hi] - sm[lo]) * (i - lo))
        if pts and pts[-1][0] == kf:
            continue
        pts.append([kf, round(min(1.0, max(0.0, v)), 4)])
    return pts, method


@app.post("/api/tl/reframe")
def api_tl_reframe():
    d = request.get_json(force=True) or {}
    try:
        cid = str(d.get("clip") or "")
        c = CLIPS.get(cid)
        if not c or c.get("kind") == "photo":
            raise ValueError("Select a video clip first.")
        t_in = _fnum(d.get("in"), 0, 0, 1e6)
        dur_f = int(_fnum(d.get("dur"), FPS, 1, 1e7))
        speed = _fnum(d.get("speed"), 1, 0.05, 20)
        pts, method = reframe_points(cid, t_in, dur_f, speed)
        return jsonify({"points": pts, "method": method})
    except ValueError as e:
        return err(str(e))
    except Exception as e:
        return err(f"Auto Reframe failed: {e}")



@app.post("/api/lut")
def api_lut():
    """A .cube LUT for the Timeline's Colour section; returns an id + its grid (the preview applies it too)."""
    f = request.files.get("file")
    if not f or not f.filename.lower().endswith(".cube"):
        return err("Choose a .cube LUT file.")
    lid = uuid.uuid4().hex[:12]
    path = os.path.join(UPLOAD_DIR, lid + ".cube")
    f.save(path)
    try:
        size, data, dmin, dmax = None, [], [0.0, 0.0, 0.0], [1.0, 1.0, 1.0]
        with open(path, encoding="utf-8", errors="replace") as fh:
            for line in fh:
                t = line.strip()
                if not t or t.startswith("#"):
                    continue
                k = t.split()
                if k[0].upper() == "LUT_3D_SIZE":
                    size = int(k[1])
                elif k[0].upper() == "DOMAIN_MIN":
                    dmin = [float(x) for x in k[1:4]]
                elif k[0].upper() == "DOMAIN_MAX":
                    dmax = [float(x) for x in k[1:4]]
                elif k[0].upper() == "LUT_1D_SIZE":
                    raise ValueError("That's a 1D LUT. Use a 3D .cube LUT.")
                elif k[0][0] in "-.0123456789" and len(k) >= 3:
                    data.append([float(k[0]), float(k[1]), float(k[2])])
        if not size or len(data) != size ** 3 or size > 129:
            raise ValueError("That .cube file isn't a readable 3D LUT.")
    except (ValueError, IndexError) as e:
        _rm(path)
        return err(str(e))
    LUTS[lid] = {"path": path, "size": size, "name": f.filename}
    flat = [round(min(1.0, max(0.0, v)), 5) for row in data for v in row]
    return jsonify({"id": lid, "name": f.filename, "size": size, "data": flat, "dmin": dmin, "dmax": dmax})


@app.post("/api/render")
def api_render():
    try:
        plan = validate_plan(request.get_json(force=True) or {})
    except (ValueError, KeyError, TypeError) as e:
        return err(str(e) or "Invalid render plan.")
    if any(j["status"] in ("queued", "rendering") for j in JOBS.values()):
        return err("A render is already running.")
    jid = uuid.uuid4().hex[:12]
    JOBS[jid] = {"status": "queued", "progress": 0.0, "plan": plan, "encoder": "",
                 "started": time.time(),
                 "name": time.strftime("edit_%Y%m%d_%H%M%S.mp4")}
    threading.Thread(target=run_render, args=(jid,), daemon=True).start()
    return jsonify({"id": jid})


@app.get("/api/render/<jid>")
def api_render_status(jid):
    j = JOBS.get(jid)
    if not j:
        return err("Unknown render.", 404)
    status = j["status"]
    if status == "done" and not os.path.exists(j.get("path", "")):
        status = "saved" if j.get("saved") else "expired"
    return jsonify({"status": status, "progress": round(j["progress"], 4),
                    "encoder": j.get("encoder", ""), "error": j.get("error"),
                    "chunk": j.get("chunk"), "chunks": j.get("chunks", 1),
                    "elapsed": round(time.time() - j["started"], 1)})


@app.post("/api/render/<jid>/cancel")
def api_render_cancel(jid):
    j = JOBS.get(jid)
    if j:
        j["cancel"] = True
        proc = j.get("proc")
        if proc and proc.poll() is None:
            proc.kill()
    return jsonify({"ok": True})


NEST_DIR = os.path.join(BASE_DIR, "project_assets", "nested")


@app.post("/api/render/<jid>/adopt")
def api_render_adopt(jid):
    """A project dropped into Kiru as ONE flat clip: its finished render is kept as a file in project_assets/nested
    (so a saved project finds it again) and the page then imports that file like any other media."""
    j = JOBS.get(jid)
    if not j or j["status"] != "done" or not os.path.exists(j.get("path", "")):
        return err("This render is no longer available.", 404)
    name = re.sub(r"[^A-Za-z0-9 _.()\-]+", "_", str((request.get_json(silent=True) or {}).get("name") or "Nested project")).strip(" .")[:60] or "Nested project"
    try:
        os.makedirs(NEST_DIR, exist_ok=True)
        dst = os.path.join(NEST_DIR, f"{name} {time.strftime('%Y%m%d_%H%M%S')}{os.path.splitext(j['path'])[1]}")
        shutil.move(j["path"], dst)
    except OSError as e:
        return err("The nested clip could not be written: " + str(e), 500)
    JOBS.pop(jid, None)
    return jsonify(path=dst, size=os.path.getsize(dst), name=os.path.basename(dst))


@app.delete("/api/render/<jid>")
def api_render_discard(jid):
    j = JOBS.pop(jid, None)
    if j:
        _rm(j.get("path"))
    return jsonify({"ok": True})


def clip_file(path, text=""):
    """Put a FILE (and, on Windows, a caption as text beside it) on the system clipboard, so it can be pasted straight into
    Discord, a browser's upload field, Explorer... No window is shown. -> None, or a sentence saying why it could not."""
    path = os.path.abspath(path)
    try:
        if os.name == "nt":
            ps = ("Add-Type -AssemblyName System.Windows.Forms;"
                  "$d = New-Object System.Windows.Forms.DataObject;"
                  "$c = New-Object System.Collections.Specialized.StringCollection;"
                  "[void]$c.Add($env:KIRU_CLIP_PATH); $d.SetFileDropList($c);"
                  "if ($env:KIRU_CLIP_TEXT) { $d.SetText($env:KIRU_CLIP_TEXT) };"
                  "[System.Windows.Forms.Clipboard]::SetDataObject($d, $true)")
            r = subprocess.run(["powershell", "-NoProfile", "-NonInteractive", "-STA", "-WindowStyle", "Hidden", "-Command", ps], capture_output=True, text=True, timeout=30,
                               env=dict(os.environ, KIRU_CLIP_PATH=path, KIRU_CLIP_TEXT=text or ""), creationflags=NO_WINDOW)
            return None if r.returncode == 0 else (r.stderr or "PowerShell could not set the clipboard.").strip()[:300]
        if sys.platform == "darwin":
            r = subprocess.run(["osascript", "-e", f'set the clipboard to (POSIX file "{path}")'], capture_output=True, text=True, timeout=30)
            return None if r.returncode == 0 else (r.stderr or "osascript failed").strip()[:300]
        uri = "file://" + path.replace(" ", "%20") + "\n"
        for cmd in (["wl-copy", "--type", "text/uri-list"], ["xclip", "-selection", "clipboard", "-t", "text/uri-list"]):
            if shutil.which(cmd[0]):
                r = subprocess.run(cmd, input=uri, text=True, capture_output=True, timeout=30)
                return None if r.returncode == 0 else (r.stderr or cmd[0] + " failed").strip()[:300]
        return "Install xclip (X11) or wl-clipboard (Wayland) to copy files to the clipboard."
    except Exception as e:
        return str(e)[:300]


@app.post("/api/render/<jid>/copy")
def api_render_copy(jid):
    """Copy Video & Caption: the finished export goes to Exports/ (so it outlives the temp folder) and onto the clipboard as a file."""
    j = JOBS.get(jid)
    if not j or j["status"] != "done":
        return err("This render is no longer available.", 404)
    kept = j.get("kept")
    if not kept or not os.path.exists(kept):
        if not os.path.exists(j.get("path", "")):
            return err("The temp copy is gone (it is deleted after Save). Copy the file from where you saved it.", 404)
        os.makedirs(QUEUE_DIR, exist_ok=True)
        kept = os.path.join(QUEUE_DIR, time.strftime("Kiru_%Y-%m-%d_%H%M%S") + os.path.splitext(j["path"])[1])
        shutil.copy2(j["path"], kept)
        j["kept"] = kept
    cap = str((request.get_json(silent=True) or {}).get("caption") or "")[:2000]
    why = clip_file(kept, cap)
    if why:
        return err(f"The video is saved in the Exports folder, but it could not be put on the clipboard: {why}", 500)
    return jsonify(ok=True, file=kept, caption=bool(cap) and os.name == "nt")


@app.get("/api/render/<jid>/download")
def api_render_download(jid):
    j = JOBS.get(jid)
    if not j or j["status"] != "done" or not os.path.exists(j.get("path", "")):
        return err("This render is no longer available.", 404)
    path = j["path"]

    def stream():
        # Stream it ourselves so we know when the LAST byte went out.
        # Only then is the temp copy deleted - an aborted download keeps it.
        complete = False
        try:
            with open(path, "rb") as fh:
                while True:
                    chunk = fh.read(1024 * 1024)
                    if not chunk:
                        break
                    yield chunk
            complete = True
        finally:
            if complete:
                j["saved"] = True
                _rm(path)

    return Response(stream(), mimetype=j.get("mime", "video/mp4"), headers={
        "Content-Disposition": f'attachment; filename="{j["name"]}"',
        "Content-Length": str(os.path.getsize(path)),
    })


# ===========================================================================
# TEMPLATE ENGINE
# A template is the *structure* of an edit, with no footage in it: where the cuts fall (in seconds and in
# beats), which transition sits on each cut and how it eases, the thumps, the text layers and the colour look.
#   - analyze_reference(): reads any finished video and writes that structure down (OpenCV + optional
#     PySceneDetect for the cuts, phase correlation for the transition motion, Tesseract for the text).
#   - the page applies a template to the project (cuts -> the cut grid, transitions, text layers, Look), and
#     the normal render pipeline builds the video from the user's own clips.
#   - the page can also write the current edit out as a template.json to share.
# ===========================================================================
TPL_VERSION = 1
TPL_DIR = os.path.join(BASE_DIR, "templates")
TPL_JOBS = {}
TPL_FPS = 30
TPL_W = 160                       # analysis width (px): plenty for cuts and global motion, and fast
TPL_MAX_SEC = 360.0               # a reference longer than this is analyzed up to here
TPL_ASPECTS = {"landscape": 16 / 9, "portrait": 9 / 16, "square": 1.0, "tall": 4 / 5, "wide": 64 / 27}


def tpl_capabilities():
    """Which optional analyzers are installed (the Template Lab shows this)."""
    caps = {"opencv": False, "scenedetect": False, "ocr": False, "ocr_note": ""}
    try:
        import cv2  # noqa: F401
        caps["opencv"] = True
    except Exception:
        pass
    try:
        import scenedetect  # noqa: F401
        caps["scenedetect"] = True
    except Exception:
        pass
    try:
        import pytesseract
        _tess_setup(pytesseract)
        pytesseract.get_tesseract_version()
        caps["ocr"] = True
    except Exception as e:
        caps["ocr_note"] = ("Tesseract isn't installed, so on-screen text is not read (cuts, transitions and colour still are)."
                            if "pytesseract" in str(type(e)).lower() or "tesseract" in str(e).lower() or isinstance(e, ImportError) else str(e)[:200])
    return caps


def _tess_setup(pytesseract):
    """Windows: Tesseract's installer doesn't add itself to PATH - look in its usual folders."""
    if shutil.which("tesseract"):
        return
    for p in (r"C:\Program Files\Tesseract-OCR\tesseract.exe", r"C:\Program Files (x86)\Tesseract-OCR\tesseract.exe",
              os.path.join(os.environ.get("LOCALAPPDATA", ""), "Programs", "Tesseract-OCR", "tesseract.exe"),
              os.path.join(BASE_DIR, "tesseract", "tesseract.exe")):
        if p and os.path.isfile(p):
            pytesseract.pytesseract.tesseract_cmd = p
            return


def _tpl_read_frames(path, info, job):
    """Every frame of the reference at 30 fps, small (BGR uint8, N x h x w x 3) - one FFmpeg pipe."""
    import numpy as np
    w = TPL_W
    h = max(2, int(round(w * info["height"] / info["width"] / 2)) * 2)
    dur = min(info["duration"], TPL_MAX_SEC)
    cmd = ["ffmpeg", "-v", "error", "-i", path, "-t", f"{dur:.3f}", "-an", "-vf", f"fps={TPL_FPS},scale={w}:{h}:flags=area,setsar=1",
           "-pix_fmt", "bgr24", "-f", "rawvideo", "-"]
    proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, creationflags=NO_WINDOW)
    job["proc"] = proc
    n_exp = max(1, int(dur * TPL_FPS))
    size = w * h * 3
    frames = []
    while True:
        buf = proc.stdout.read(size)
        if len(buf) < size:
            break
        frames.append(np.frombuffer(buf, np.uint8).reshape(h, w, 3))
        if len(frames) % 60 == 0:
            job.update(pct=min(24, int(24 * len(frames) / n_exp)), stage="Reading the video")
            if job.get("cancel"):
                proc.kill()
                raise Cancelled()
    proc.wait()
    job.pop("proc", None)
    if len(frames) < 4:
        raise RuntimeError("Could not read that video (FFmpeg decoded no frames).")
    return np.stack(frames), w, h


def _tpl_scores(frames):
    """Per-frame change (0-255): mean |delta| of H, S and V between neighbours - the PySceneDetect content score."""
    import cv2
    import numpy as np
    n = len(frames)
    hsv = np.empty(frames.shape, np.int16)
    for i in range(n):
        hsv[i] = cv2.cvtColor(frames[i], cv2.COLOR_BGR2HSV)
    d = np.abs(hsv[1:] - hsv[:-1]).astype(np.float32)
    dh = np.minimum(d[..., 0], 180 - d[..., 0]) * (255.0 / 90.0)          # hue is a circle
    sc = np.zeros(n, np.float32)
    sc[1:] = (dh.mean(axis=(1, 2)) + d[..., 1].mean(axis=(1, 2)) + d[..., 2].mean(axis=(1, 2))) / 3.0
    luma = (frames[..., 0].reshape(n, -1).mean(axis=1) * 0.114 + frames[..., 1].reshape(n, -1).mean(axis=1) * 0.587
            + frames[..., 2].reshape(n, -1).mean(axis=1) * 0.299).astype(np.float32)        # real brightness (not HSV value)
    return sc, luma


def _tpl_hard_cuts(sc):
    """Frame-accurate hard cuts, the AdaptiveDetector rule: the score must clear a floor AND stand 3x above its
    neighbours (so fast motion, which is high everywhere around it, is not a cut)."""
    import numpy as np
    n = len(sc)
    cuts = []
    for i in range(1, n):
        a, b = max(1, i - 2), min(n, i + 3)
        nb = np.concatenate([sc[a:i], sc[i + 1:b]])
        base = float(nb.mean()) if len(nb) else 0.0
        if sc[i] >= 15.0 and sc[i] >= 3.0 * max(base, 1.0):
            cuts.append(i)
    return cuts


def _tpl_psd_cuts(path, dur):
    """The same question asked of PySceneDetect itself (when it is installed) - used to cross-check our cuts."""
    try:
        from scenedetect import AdaptiveDetector, detect
        scenes = detect(path, AdaptiveDetector(min_scene_len=3), end_time=dur)
        return sorted({int(round((s[0].seconds if hasattr(s[0], "seconds") else s[0].get_seconds()) * TPL_FPS)) for s in scenes[1:]})
    except Exception:
        return None


def _tpl_motion(a, b, win):
    """Global motion between two gray frames: (dx, dy) in fractions of the frame, zoom factor, rotation (degrees),
    and how sure the match is. Phase correlation for the shift; the same on log-polar copies for zoom + spin."""
    import cv2
    import numpy as np
    h, w = a.shape
    (dx, dy), r1 = cv2.phaseCorrelate(a.copy(), b.copy(), win)
    c = (w / 2.0, h / 2.0)
    M = w / np.log(max(2.0, min(w, h) / 2.0))
    la = cv2.warpPolar(a, (w, h), c, min(w, h) / 2.0, cv2.WARP_POLAR_LOG + cv2.INTER_LINEAR)
    lb = cv2.warpPolar(b, (w, h), c, min(w, h) / 2.0, cv2.WARP_POLAR_LOG + cv2.INTER_LINEAR)
    (lx, ly), r2 = cv2.phaseCorrelate(la.copy(), lb.copy(), win)
    zoom = float(np.exp(lx / M))
    rot = float(ly * 360.0 / h)
    return dx / w, dy / h, zoom, rot, float(r1), float(r2)


def _tpl_ease(speeds):
    """Name the easing of a move from its per-frame speed profile, and give the progress curve (9 samples 0..1)."""
    import numpy as np
    v = np.asarray(speeds, np.float64)
    if len(v) < 3 or v.sum() <= 1e-9:
        return "snappy", None
    v = v / v.sum()
    cum = np.concatenate([[0.0], np.cumsum(v)])
    curve = [round(float(np.interp(q, np.linspace(0, 1, len(cum)), cum)), 3) for q in np.linspace(0, 1, 9)]
    centre = float((np.arange(len(v)) * v).sum() / max(1, len(v) - 1))
    peak = float(v.max() * len(v))                       # peak speed / mean speed (an ease-in-out of power n peaks at n)
    if centre < 0.36:
        return "out", curve
    if centre > 0.64:
        return "in", curve
    if peak < 1.5:
        return "linear", curve
    return ("smooth" if peak < 3.2 else "snappy" if peak < 5.0 else "punchy"), curve


def _tpl_slide(f, A, B, denom):
    """Is frame f 'A pushed out by B'? Try every offset in the four directions; returns (direction, progress 0..1, error)."""
    h, w = f.shape[:2]
    best = (None, 0.0, 1e9)
    for d in ("left", "right", "up", "down"):
        horiz = d in ("left", "right")
        size = w if horiz else h
        for sft in range(0, size + 1, max(2, size // 40)):
            if horiz:
                if d == "left":                       # A leaves to the left, B comes in from the right
                    e = ((f[:, :w - sft] - A[:, sft:]) ** 2).sum() + ((f[:, w - sft:] - B[:, :sft]) ** 2).sum()
                else:
                    e = ((f[:, sft:] - A[:, :w - sft]) ** 2).sum() + ((f[:, :sft] - B[:, w - sft:]) ** 2).sum()
            else:
                if d == "up":
                    e = ((f[:h - sft] - A[sft:]) ** 2).sum() + ((f[h - sft:] - B[:sft]) ** 2).sum()
                else:
                    e = ((f[sft:] - A[:h - sft]) ** 2).sum() + ((f[:sft] - B[h - sft:]) ** 2).sum()
            e = float(e) / denom
            if e < best[2]:
                best = (d, sft / size, e)
    return best


def _tpl_classify(frames, gray, sc, luma, a, b, hard, win):
    """What happens between frames a..b (a transition window)? Tested in this order:
    through black / white (the brightness says so) -> a blend of the shot before and the shot after (dissolve, or a
    soft wipe if the blend sweeps across the picture) -> a push (the old shot slides out) -> zoom / spin (global
    motion) -> otherwise a plain cut."""
    import numpy as np
    n = len(frames)
    a, b = max(2, a), min(n - 3, b)
    span = b - a + 1
    out = {"type": "none", "frames": 0, "ease": "snappy", "confidence": 0.0}
    if span < 1:
        return out
    lum = luma[max(0, a - 1):min(n, b + 2)]
    pre, post = float(luma[max(0, a - 3)]), float(luma[min(n - 1, b + 3)])
    if float(lum.max()) > 215 and float(lum.max()) - pre > 40 and float(lum.max()) - post > 35:
        out["flash"] = True
    if float(lum.min()) < 14 and min(pre, post) - float(lum.min()) > 25 and span >= 3:
        return dict(out, type="dip", frames=min(30, span + span % 2), confidence=0.85, ease="linear")
    import cv2
    shp = lambda i: float(cv2.Laplacian(gray[i], cv2.CV_32F).var()) / (float(gray[i].var()) + 4.0)
    mids = [shp(i) for i in range(a, b + 1) if luma[i] < 236] or [shp(a), shp(b)]
    ref_ = max(1e-6, min(shp(max(0, a - 3)), shp(min(n - 1, b + 4))))
    soft = min(mids) < 0.35 * ref_
    bright = float(lum.max()) > 185 and float(lum.max()) - min(pre, post) > 30
    if span >= 3 and ((out.get("flash") and float(lum.max()) > 232) or (soft and bright)):
        return dict(out, type="bflash" if soft else "flashw", frames=min(30, span + span % 2), confidence=0.8, ease="linear", flash=False)
    A, B = frames[a - 2].astype(np.float32), frames[min(n - 1, b + 2)].astype(np.float32)
    D = B - A
    denom = float((D ** 2).sum())
    if denom / D.size < 60:                              # the picture before and after is the same shot
        return out
    if span >= 3:
        alphas, resid, slopes = [], [], []
        colE = (D ** 2).sum(axis=(0, 2))
        for k in range(a, b + 1):
            F = frames[k].astype(np.float32) - A
            al = float((F * D).sum()) / denom
            alphas.append(al)
            resid.append(float(((F - al * D) ** 2).sum()) / denom)
            ca = (F * D).sum(axis=(0, 2)) / np.maximum(colE, 1.0)          # how far along each column is
            wq = len(ca) // 5
            good = colE > colE.mean() * 0.25
            l, r = ca[:wq][good[:wq]], ca[-wq:][good[-wq:]]
            slopes.append(float(r.mean() - l.mean()) if len(l) and len(r) else 0.0)
        alphas, resid = np.array(alphas), np.array(resid)
        rising = float(np.mean(np.diff(alphas) > -0.03)) if len(alphas) > 1 else 0.0
        between = (alphas > 0.08) & (alphas < 0.92)             # frames that really are in between the two shots
        zs_, rs_ = [], []
        for i in range(a, b + 1):
            if i in hard:
                continue
            _, _, z, r, c1, c2 = _tpl_motion(gray[i - 1], gray[i], win)
            zs_.append(np.log(max(1e-3, z))); rs_.append(r)
        zoomy = len(zs_) >= 3 and abs(float(np.sum(zs_))) > 0.3 and float(np.mean(np.sign(zs_) == np.sign(np.sum(zs_)))) > 0.8
        spinny = len(rs_) >= 3 and abs(float(np.sum(rs_))) > 45 and float(np.mean(np.sign(rs_) == np.sign(np.sum(rs_)))) > 0.8
        if between.sum() >= 2 and not zoomy and not spinny and float(np.median(resid[between])) < 0.16 and rising > 0.7 and alphas[-1] - alphas[0] > 0.45:
            sw = float(np.max(np.abs(slopes)))
            typ = "fade"
            if sw > 0.55:
                typ = "wipel" if slopes[int(np.argmax(np.abs(slopes)))] > 0 else "wiper"
            sp = np.clip(np.diff(np.concatenate([[0.0], np.clip(alphas, 0, 1), [1.0]])), 0, None)
            ease_name, curve = _tpl_ease(sp)
            out.update(type=typ, frames=min(30, max(2, span + span % 2)), ease="linear" if typ == "fade" else ease_name,
                       confidence=round(float(1 - min(0.9, np.median(resid) * 3)), 2))
            if curve:
                out["curve"] = curve
            return out
        # a push: A slides out, B slides in
        prog, errs, dirs = [], [], []
        for k in range(a, b + 1):
            d, pg, e = _tpl_slide(frames[k].astype(np.float32), A, B, denom)
            prog.append(pg); errs.append(e); dirs.append(d)
        mids = [i for i, pg in enumerate(prog) if 0.04 < pg < 0.96]
        if mids:
            dom = max(set(dirs[i] for i in mids), key=[dirs[i] for i in mids].count)
            agree = np.mean([dirs[i] == dom for i in mids])
            e_mid = float(np.median([errs[i] for i in mids]))
            mono = float(np.mean(np.diff(prog) > -0.05))
            if agree > 0.7 and e_mid < 0.5 and mono > 0.7 and prog[-1] - prog[0] > 0.4:
                sp = np.clip(np.diff(np.concatenate([[0.0], prog, [1.0]])), 0, None)
                ease_name, curve = _tpl_ease(sp)
                out.update(type=dom, frames=min(30, max(2, span + span % 2)), ease=ease_name, confidence=round(float(1 - e_mid), 2))
                if curve:
                    out["curve"] = curve
                return out
    # zoom / spin: global motion between neighbouring frames (skipping the pair that straddles a hard cut)
    zs, rs = [], []
    for i in range(a, b + 1):
        if i in hard:
            continue
        _, _, z, r, c1, c2 = _tpl_motion(gray[i - 1], gray[i], win)
        if c2 > 0.03:
            zs.append(np.log(max(1e-3, z))); rs.append(r)
    if len(zs) >= 2:
        mz, mr = float(np.sum(zs)), float(np.sum(rs))
        cands = []
        if abs(mz) > 0.25 and np.mean(np.sign(zs) == np.sign(mz)) > 0.7:
            cands.append((abs(mz) * 1.2, "zoomin" if mz > 0 else "zoomout", np.abs(zs)))
        if abs(mr) > 40 and np.mean(np.sign(rs) == np.sign(mr)) > 0.7:
            cands.append((abs(mr) / 90.0, "spin", np.abs(rs)))
        if cands:
            cands.sort(key=lambda c: -c[0])
            ease_name, curve = _tpl_ease(cands[0][2])
            out.update(type=cands[0][1], frames=min(30, max(2, span + span % 2)), ease=ease_name, confidence=round(min(0.9, 0.35 + cands[0][0] / 2), 2))
            if curve:
                out["curve"] = curve
    return out


TPL_HI = 320                      # width of the sharper frames used to double-check every cut


def _tpl_new_types(frames, f, a, b, n, lim=None):
    """The 3D / shape / motion-graphic transitions, measured on the small frames round one cut (frame f, busy frames a..b).
    The two shots are compared with every frame between them: which pixels already show the next shot (a growing shape = a wipe),
    and what is in the frame that is in neither shot (sparkles, a white star, a warm glow, black sides of a turning card).
    -> {"type", "confidence", "frames"} or None."""
    import cv2
    import numpy as np
    lo, hi = max(1, min(a - 1, f - 9)), min(n - 2, max(b + 1, f + 9))
    if lim:                                                # never reach into the neighbouring cuts
        lo, hi = max(lo, min(lim[0], f - 3)), min(hi, max(lim[1], f + 3))
    lo, hi = max(1, lo), min(n - 2, hi)
    A, B = frames[lo - 1].astype(np.float32), frames[hi + 1].astype(np.float32)
    h, w = A.shape[:2]
    valid = np.abs(A - B).sum(axis=2) > 60
    if valid.mean() < 0.2:
        return None
    gA, gB = cv2.cvtColor(frames[lo - 1], cv2.COLOR_BGR2GRAY), cv2.cvtColor(frames[hi + 1], cv2.COLOR_BGR2GRAY)
    ker = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (7, 7))
    thAB = np.maximum(cv2.morphologyEx(gA, cv2.MORPH_TOPHAT, ker), cv2.morphologyEx(gB, cv2.MORPH_TOPHAT, ker)).astype(np.int16)
    yy, xx = np.mgrid[0:h, 0:w]
    ang = (np.arctan2(xx - w / 2.0, h / 2.0 - yy) + 2 * np.pi) % (2 * np.pi)
    abin = np.minimum(23, (ang / (2 * np.pi) * 24).astype(np.int32))
    rows, votes = [], {}
    vote = lambda t, c: votes.__setitem__(t, max(votes.get(t, 0), c))
    for k in range(lo, hi + 1):
        F8 = frames[k]
        F = cv2.GaussianBlur(F8, (0, 0), 0.8).astype(np.float32)
        eA, eB = np.abs(F - A).sum(axis=2), np.abs(F - B).sum(axis=2)
        mB = (eB < eA) & valid
        r = float(mB.sum()) / max(1, int(valid.sum()))
        fit = float(np.minimum(eA, eB)[valid].mean())
        rows.append((k, r, fit, mB))
        g = cv2.cvtColor(F8, cv2.COLOR_BGR2GRAY)
        # sparkles: many small bright dots that are in neither shot
        ex = cv2.morphologyEx(g, cv2.MORPH_TOPHAT, ker).astype(np.int16) - thAB
        nl, _l, st, _c = cv2.connectedComponentsWithStats((ex > 55).astype(np.uint8), 8)
        dots = sum(1 for j in range(1, nl) if 1 <= st[j, cv2.CC_STAT_AREA] <= max(6, 0.004 * w * h))
        bright = float(g[ex > 55].mean()) if dots else 0
        if dots >= 14 and bright > 185 and float(np.minimum(eA, eB).mean()) < 42:     # (the frame is still one of the two shots, plus bright dots)
            vote("_spark", votes.get("_spark", 0) + 1)
            vote("_dots", dots)
        if k in (lo, hi) and dots >= 5:                    # dots that are there before and after belong to the footage
            vote("_nospark", 1)
        # a big white star
        white = (F8.min(axis=2) > 212).astype(np.uint8)
        wf = float(white.mean())
        if 0.05 < wf < 0.9 and float((frames[lo - 1].min(axis=2) > 212).mean()) < wf * 0.5 and float((frames[hi + 1].min(axis=2) > 212).mean()) < wf * 0.5:
            cs, _h = cv2.findContours(white, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
            c = max(cs, key=cv2.contourArea)
            ar, hull = cv2.contourArea(c), cv2.contourArea(cv2.convexHull(c))
            mo = cv2.moments(c)
            if hull > 0 and ar > 0.03 * w * h and mo["m00"] > 0 and abs(mo["m10"] / mo["m00"] - w / 2) < 0.15 * w and abs(mo["m01"] / mo["m00"] - h / 2) < 0.18 * h \
                    and ar / hull < 0.8 and len(cv2.approxPolyDP(c, 0.02 * cv2.arcLength(c, True), True)) >= 7:
                vote("mgstar", 0.85)
        elif wf >= 0.9 and votes.get("mgstar"):
            vote("mgstar", 0.9)
        # a warm glow that is brighter than both shots
        up = F - np.maximum(A, B)
        warm = (up[..., 2] > 22) & (up[..., 2] > up[..., 0] + 8)
        if float(warm.mean()) > 0.2 and float(cv2.GaussianBlur(warm.astype(np.float32), (0, 0), 6)[warm].mean()) > 0.6:
            vote("_leak", votes.get("_leak", 0) + 0.25)
            lx_ = float(xx[warm].mean())
            votes["_lx0"], votes["_lx1"] = min(votes.get("_lx0", lx_), lx_), max(votes.get("_lx1", lx_), lx_)
        # a card turning: black on both sides, the picture squeezed into the middle
        col = g.mean(axis=0)
        dl, dr = int((col[: w // 2] < 14).sum()), int((col[w // 2:] < 14).sum())
        if dl > 0.1 * w and dr > 0.1 * w and float((gA.mean(axis=0) < 14).mean()) < 0.1 and float((gB.mean(axis=0) < 14).mean()) < 0.1 and float(col[w // 2 - 4: w // 2 + 4].mean()) > 24:
            vote("flip", 0.75)
    if votes.get("_leak", 0) >= 0.75 and votes.get("_lx1", 0) - votes.get("_lx0", 0) > 0.18 * w:      # (a light leak travels across; a flash stays put)
        vote("mgleak", min(0.8, votes["_leak"] * 0.7))
    if votes.get("_spark", 0) >= 3 and not votes.get("_nospark"):
        vote("mgspark", min(0.9, 0.55 + votes.get("_dots", 0) / 60))
    for k_ in ("_leak", "_spark", "_dots", "_nospark", "_lx0", "_lx1"):
        votes.pop(k_, None)
    # ---- a shape that grows and shows the next shot
    part = [x for x in rows if 0.1 < x[1] < 0.9 and x[2] < 48]             # (frames that really are "partly the old shot, partly the new one")
    if len(part) >= 2 and rows[0][1] < 0.35 and rows[-1][1] > 0.65:
        def bins(mB):
            full = part_ = 0
            fl = []
            for q in range(24):
                sel = (abin == q) & valid
                v = float(mB[sel].mean()) if sel.sum() > 8 else -1
                fl.append(v)
                if v > 0.85:
                    full += 1
                elif 0.15 <= v <= 0.85:
                    part_ += 1
            return full, part_, fl
        k, r, _fit, mB = min(part, key=lambda x: abs(x[1] - 0.45))
        m8 = cv2.morphologyEx(mB.astype(np.uint8), cv2.MORPH_OPEN, np.ones((3, 3), np.uint8))
        m8 = cv2.morphologyEx(m8 | (~valid).astype(np.uint8) & cv2.dilate(m8, np.ones((5, 5), np.uint8)), cv2.MORPH_CLOSE, np.ones((5, 5), np.uint8))
        cs, _h = cv2.findContours(m8, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        if cs:
            c = max(cs, key=cv2.contourArea)
            ar = cv2.contourArea(c)
            x0, y0, bw, bh = cv2.boundingRect(c)
            hull = cv2.contourArea(cv2.convexHull(c))
            mo = cv2.moments(c)
            centred = mo["m00"] > 0 and abs(mo["m10"] / mo["m00"] - w / 2) < 0.1 * w and abs(mo["m01"] / mo["m00"] - h / 2) < 0.12 * h
            inside = x0 > 1 and y0 > 1 and x0 + bw < w - 1 and y0 + bh < h - 1
            sol, ext = ar / max(1.0, hull), ar / max(1.0, float(bw * bh))
            nv = len(cv2.approxPolyDP(c, 0.02 * cv2.arcLength(c, True), True))
            if centred and ar > 0.02 * w * h and (inside or sol < 0.8):
                if sol < 0.8 and nv >= 7:
                    vote("star", 0.85)
                elif sol > 0.9 and 0.42 <= ext <= 0.6 and nv <= 6:
                    vote("diamond", 0.8)
            # the old shot squeezed to an upright band in the middle
            a8 = ((~mB) & valid).astype(np.uint8)
            ca, _h = cv2.findContours(cv2.morphologyEx(a8, cv2.MORPH_OPEN, np.ones((3, 3), np.uint8)), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
            if ca:
                c2 = max(ca, key=cv2.contourArea)
                xa, ya, wa, ha = cv2.boundingRect(c2)
                if ha > 0.85 * h and wa < 0.85 * w and xa > 0.04 * w and xa + wa < 0.96 * w and abs(xa + wa / 2 - w / 2) < 0.08 * w and cv2.contourArea(c2) / float(wa * ha) > 0.7:
                    vote("squeeze", 0.75)
            # a clock hand: at every moment each direction from the centre is either all new or all old
            two = [x for x in part if x[1] < 0.4] + [x for x in part if x[1] > 0.55]
            if len(two) >= 2 and not votes.get("star") and not votes.get("diamond") and not votes.get("squeeze"):
                ok = 0
                for x in (min(part, key=lambda q: abs(q[1] - 0.28)), min(part, key=lambda q: abs(q[1] - 0.7))):
                    full, part_, fl = bins(x[3])
                    runs = sum(1 for q in range(24) if (fl[q] > 0.5) != (fl[q - 1] > 0.5))
                    if part_ <= 4 and runs <= 2 and abs(full / 24.0 - x[1]) < 0.16:
                        ok += 1
                if ok == 2:
                    vote("radial", 0.75)
            # a box turning: the old shot is pressed towards one side (not just pushed out) while the new one comes in from the other
            if not votes and bh > 0.9 * h and (x0 + bw >= w - 2 or x0 <= 1) and 0.2 < r < 0.8:
                xb = x0 if x0 + bw >= w - 2 else x0 + bw
                Ag = cv2.cvtColor(frames[lo - 1], cv2.COLOR_BGR2GRAY).astype(np.float32)
                Fg = cv2.cvtColor(frames[k], cv2.COLOR_BGR2GRAY).astype(np.float32)
                if x0 + bw >= w - 2 and xb > 12:
                    reg = Fg[:, :xb]
                    slide = Ag[:, w - xb:]
                    press = cv2.resize(Ag, (xb, h), interpolation=cv2.INTER_AREA)
                elif xb < w - 12:
                    reg = Fg[:, xb:]
                    slide = Ag[:, : w - xb]
                    press = cv2.resize(Ag, (w - xb, h), interpolation=cv2.INTER_AREA)
                else:
                    reg = None
                if reg is not None:
                    e1, e2 = float(np.abs(reg - slide).mean()), float(np.abs(reg - press).mean())
                    if e2 < 0.6 * e1 and e2 < 30:
                        vote("cube", 0.7)
    if not votes:
        return None
    t = "mgstar" if "mgstar" in votes else max(votes, key=votes.get)
    busy = [x[0] for x in rows if 0.04 < x[1] < 0.96] or [f]
    fr = max(4, min(30, ((max(b, max(busy)) - min(a, min(busy)) + 2) // 2) * 2)) if t in ("star", "diamond", "radial", "squeeze", "cube", "flip") else 14
    return {"type": t, "confidence": round(votes[t], 2), "frames": int(fr)}


def _tpl_thumbs(frames, a, b, n, count=7):
    """A few small frames across one transition (JPEG data URLs), for the Transition Matcher."""
    import base64
    import cv2
    lo, hi = max(0, a - 2), min(n - 1, b + 2)
    idx = sorted(set(int(round(lo + (hi - lo) * q / (count - 1))) for q in range(count)))
    out = []
    for k in idx:
        ok, buf = cv2.imencode(".jpg", frames[k], [cv2.IMWRITE_JPEG_QUALITY, 72])
        if ok:
            out.append("data:image/jpeg;base64," + base64.b64encode(buf.tobytes()).decode("ascii"))
    return out


def _tpl_grab(path, dur, idxs, job=None):
    """A handful of exact frames (30 fps numbering, same as the small ones) at TPL_HI wide, gray. {index: image}"""
    import numpy as np
    idxs = sorted(set(int(i) for i in idxs if i >= 0))
    out = {}
    if not idxs:
        return out
    pr = probe(path)
    vs = next((x for x in pr.get("streams", []) if x.get("codec_type") == "video"), None) or {}
    rot = abs(int(float(((vs.get("side_data_list") or [{}])[0]).get("rotation", 0) or 0))) % 180 == 90
    sw, sh = (int(vs.get("height", 0)), int(vs.get("width", 0))) if rot else (int(vs.get("width", 0)), int(vs.get("height", 0)))
    if not sw or not sh:
        return out
    w = TPL_HI
    h = max(2, int(round(w * sh / sw / 2)) * 2)
    for k in range(0, len(idxs), 70):
        part = idxs[k:k + 70]
        if job is not None and job.get("cancel"):
            raise Cancelled()
        sel = "+".join(f"eq(n\\,{i})" for i in part)
        t0 = max(0.0, part[0] / TPL_FPS - 1.0)
        # seek close to the first wanted frame, then count frames from there
        base = int(round(t0 * TPL_FPS))
        sel = "+".join(f"eq(n\\,{i - base})" for i in part)
        cmd = ["ffmpeg", "-v", "error", "-i", path, "-t", f"{dur:.3f}", "-an",
               "-vf", f"fps={TPL_FPS},trim=start_frame={base},setpts=PTS-STARTPTS,select='{sel}',scale={w}:{h}:flags=area,setsar=1",
               "-vsync", "0", "-pix_fmt", "gray", "-f", "rawvideo", "-"]
        r = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, creationflags=NO_WINDOW)
        buf = r.stdout
        for j, i in enumerate(part):
            if len(buf) >= (j + 1) * w * h:
                out[i] = np.frombuffer(buf[j * w * h:(j + 1) * w * h], np.uint8).reshape(h, w)
    return out


def _tpl_same(A, B):
    """Is B still the same shot as A (moved, shaken, punched in) - or a different picture?
    Matches corner features and fits one move+zoom to them. Things that did not move at all while the rest did
    (a title, a watermark) are set aside so they cannot vote."""
    import cv2
    import numpy as np
    res = {"moving": 0, "cover": 0, "still": 0, "still_cover": 0, "scale": 1.0, "dx": 0.0, "dy": 0.0}
    orb = cv2.ORB_create(1200, scaleFactor=1.2, nlevels=6, edgeThreshold=8, fastThreshold=8)
    ka, da = orb.detectAndCompute(A, None)
    kb, db = orb.detectAndCompute(B, None)
    if da is None or db is None or len(ka) < 12 or len(kb) < 12:
        return res
    m = cv2.BFMatcher(cv2.NORM_HAMMING).knnMatch(da, db, k=2)
    good = [x[0] for x in m if len(x) == 2 and x[0].distance < 0.78 * x[1].distance]
    if len(good) < 4:
        return res
    pa = np.float32([ka[g.queryIdx].pt for g in good])
    pb = np.float32([kb[g.trainIdx].pt for g in good])

    def cover(pts, g=6):
        if not len(pts):
            return 0
        cx = np.clip((pts[:, 0] / A.shape[1] * g).astype(int), 0, g - 1)
        cy = np.clip((pts[:, 1] / A.shape[0] * g).astype(int), 0, g - 1)
        return len(set(zip(cx.tolist(), cy.tolist())))
    still = np.hypot(*(pa - pb).T) < 1.5
    res["still"], res["still_cover"] = int(still.sum()), cover(pa[still])
    mv = ~still
    if mv.sum() >= 6:
        M, inl = cv2.estimateAffinePartial2D(pa[mv], pb[mv], method=cv2.RANSAC, ransacReprojThreshold=3.0)
        if M is not None and inl is not None:
            inl = inl.ravel().astype(bool)
            sc_ = float(np.hypot(M[0, 0], M[1, 0]))
            if 0.5 < sc_ < 2.0:
                cxy = np.float32([A.shape[1] / 2, A.shape[0] / 2])
                moved = M[:, :2] @ cxy + M[:, 2] - cxy
                res.update(moving=int(inl.sum()), cover=cover(pa[mv][inl]), scale=sc_,
                           dx=float(moved[0] / A.shape[1]), dy=float(moved[1] / A.shape[0]))
    return res


def _tpl_recolored(A, B):
    """Two small colour frames: has the COLOUR of most of the picture changed (not its brightness)? The same graphic on a red
    card and then on a blue card is two shots, however alike their shapes are."""
    import cv2
    import numpy as np
    la, lb = cv2.cvtColor(A, cv2.COLOR_BGR2LAB).astype(np.float32), cv2.cvtColor(B, cv2.COLOR_BGR2LAB).astype(np.float32)
    g = 6
    h, w = la.shape[:2]
    d = []
    for y in range(g):
        for x in range(g):
            ca, cb = la[y * h // g:(y + 1) * h // g, x * w // g:(x + 1) * w // g], lb[y * h // g:(y + 1) * h // g, x * w // g:(x + 1) * w // g]
            d.append(abs(float(ca[..., 1].mean() - cb[..., 1].mean())) + abs(float(ca[..., 2].mean() - cb[..., 2].mean())))
    d = np.array(d)
    return bool((d > 14).mean() >= 0.3 and float(np.median(d)) > 6)


def _tpl_verify(path, dur, events, n, luma, job, protect=(), frames=None):
    """Second look at every cut: a 'cut' where the picture after it is still the same shot is not a cut.
    It is a thump (the editor jolted, punched in or flashed the clip on the beat). Returns (real cuts, thumps)."""
    want, plan = set(), []
    for k, e in enumerate(events):
        c, a, b, ti = e
        if (ti["type"] == "fade" and not ti.get("soft_cut")) or b - a > 34 or any(pa <= c <= pb for pa, pb in protect):
            plan.append(None)                            # (a cut-out scene's backdrop never changes: its cuts cannot be judged this way)
            continue
        nxt = events[k + 1][1] - 2 if k + 1 < len(events) else n - 1
        prv = events[k - 1][2] + 2 if k else 0
        pre = max(prv, a - 2)
        posts = sorted(set(q for q in (b + 3, b + 6, b + 10) if pre < q <= min(nxt, n - 1)))
        if not posts and b + 2 <= min(nxt + 1, n - 1):
            posts = [b + 2]                             # another event follows straight away: look just after this one
        if not posts or pre >= a:
            plan.append(None)
            continue
        far = max(prv, a - 9)                            # and a frame well before it: a cut hidden inside a blur must not pass as "same shot"
        plan.append((pre, posts, far))
        want.add(pre)
        want.add(far)
        want.update(posts)
    hi = _tpl_grab(path, dur, want, job)
    keep, thumps = [], []
    for e, pl in zip(events, plan):
        c, a, b, ti = e
        if pl is None or pl[0] not in hi:
            keep.append(e)
            continue
        best, static = None, False
        if frames is not None and all(_tpl_recolored(frames[min(n - 1, pl[0])], frames[min(n - 1, q)]) for q in pl[1]):
            keep.append(e)                               # the whole picture changed colour and stayed that way: a different shot
            continue
        for q in pl[1]:
            if q not in hi:
                continue
            r = _tpl_same(hi[pl[0]], hi[q])
            if r["moving"] >= 20 and r["cover"] >= 4 and (best is None or r["moving"] > best["moving"]):
                best = r
            if r["still_cover"] >= 20 and r["still"] >= 150:
                static = True
        if (best is not None or static) and pl[2] != pl[0] and pl[2] in hi:
            ok_far = False
            for q in pl[1]:
                if q in hi:
                    r = _tpl_same(hi[pl[2]], hi[q])
                    if (r["moving"] >= 14 and r["cover"] >= 3) or (r["still_cover"] >= 20 and r["still"] >= 150):
                        ok_far = True
            if not ok_far:
                best, static = None, False
        if best is None and not static:
            keep.append(e)                               # a different picture: a real cut
            continue
        lum = luma[max(0, a - 1):min(n, b + 3)]
        flash = bool(len(lum) and float(lum.max()) > 200 and float(lum.max()) - float(luma[max(0, a - 3)]) > 40)
        if flash:                                       # a jump cut through a flash: the editor did cut here
            keep.append((c, a, b, dict(ti, type="bflash" if ti["type"] in ("none", "zoomin", "zoomout", "flashw") else ti["type"],
                                       frames=max(4, int(ti.get("frames") or 4)), ease="linear", same_clip=True)))
        elif best is not None and not ti.get("soft_cut"):
            jolt = abs(best["scale"] - 1) * 4.0 + (best["dx"] ** 2 + best["dy"] ** 2) ** 0.5 * 2.2
            thumps.append({"t": round(c / TPL_FPS, 4), "kind": "zoom", "strength": int(max(60, min(200, 60 + jolt * 260))),
                           "why": "jolt on the same shot"})
        # static picture and no flash: something was laid over it (the overlay finder deals with that)
    return keep, thumps


def _tpl_overlays(gray, events, n):
    """Clips laid over the main picture: a box-shaped part of the frame changes at once and stays changed
    while everything around it carries on as before."""
    import cv2
    import numpy as np
    h, w = gray.shape[1:3]
    bounds = [0] + [e[0] for e in events] + [n]
    busy = np.zeros(n, bool)
    for c, a, b, _ in events:
        busy[max(0, a - 2):min(n, b + 3)] = True
    out = []
    ker = np.ones((3, 3), np.uint8)
    for si in range(len(bounds) - 1):
        a, b = bounds[si] + 2, bounds[si + 1] - 2
        i = a + 1
        while i < b - 7:
            if busy[i]:
                i += 1
                continue
            d = np.abs(gray[min(b - 1, i + 5)] - gray[i - 1])   # pops in or fades in over a few frames
            ch = cv2.morphologyEx((d > 26).astype(np.uint8), cv2.MORPH_OPEN, ker)
            frac = float(ch.mean())
            if not 0.03 < frac < 0.55:
                i += 1
                continue
            ys, xs = np.nonzero(ch)
            x0, x1, y0, y1 = np.percentile(xs, 2), np.percentile(xs, 98), np.percentile(ys, 2), np.percentile(ys, 98)
            x0, x1, y0, y1 = int(x0), int(x1) + 1, int(y0), int(y1) + 1
            bw, bh = (x1 - x0) / w, (y1 - y0) / h
            if bw * bh > 0.72 or bw < 0.14 or bh < 0.12:
                i += 1
                continue
            box = np.zeros((h, w), bool)
            box[y0:y1, x0:x1] = True
            fill = float(ch[box].mean())
            later = np.abs(gray[min(b - 1, i + 10)] - gray[i - 1])
            if fill < 0.42 or float(d[~box].mean()) > 5.0 or float(later[box].mean()) < 16 or float(later[~box].mean()) > 9.0:
                i += 1
                continue
            # how long it stays: until the region looks like it did before, or the shot ends
            ref_in, end = gray[min(b - 1, i + 10)][box], b
            for q in range(i + 12, b):
                if float(np.abs(gray[q][box] - ref_in).mean()) > 30 and float(np.abs(gray[q][box] - gray[i - 1][box]).mean()) < 12:
                    end = q
                    break
            out.append({"t0": round(i / TPL_FPS, 4), "t1": round(end / TPL_FPS, 4), "x": round((x0 + x1) / 2 / w, 4), "y": round((y0 + y1) / 2 / h, 4),
                        "w": round(bw, 4), "h": round(bh, 4), "anim": "pop"})
            i += 8
    merged = []
    for o in out:                                       # the same box found twice in a row is one overlay
        if merged and abs(o["x"] - merged[-1]["x"]) < 0.06 and abs(o["y"] - merged[-1]["y"]) < 0.06 and o["t0"] - merged[-1]["t0"] < 0.5:
            continue
        merged.append(o)
    return merged[:60]


def _tpl_text_merge(text, dur):
    """OCR reads the same title a little differently every few frames. Fold those readings into one layer."""
    from difflib import SequenceMatcher
    norm = lambda t: re.sub(r"[^a-z0-9 ]", "", t.lower().replace("-", " ")).strip()
    out = []
    for x in sorted(text, key=lambda x: x["t0"]):
        nx = norm(x["text"])
        if len(nx.replace(" ", "")) < (2 if x.get("confidence", 0) >= 0.86 else 3):
            continue
        hit = None
        for e in reversed(out):
            ne = norm(e["text"])
            r_ = SequenceMatcher(None, nx, ne).ratio()
            close = x["t0"] - e["t1"] < 1.3 and (abs(x["y"] - e["y"]) < 0.09 or r_ > 0.8)
            alike = r_ > 0.6 or (len(nx) >= 3 and (nx in ne or ne in nx))
            if re.findall(r"\d+", nx) and re.findall(r"\d+", ne) and re.findall(r"\d+", nx) != re.findall(r"\d+", ne):
                alike = False                               # "PICTURE 1" and "PICTURE 2" are two texts, however alike they read
            if close and alike:
                hit = e
                break
        if hit is None:
            out.append(dict(x, _n=1, _votes={x["text"]: x["t1"] - x["t0"] + x.get("confidence", 0.8)}))
            continue
        hit["_votes"][x["text"]] = hit["_votes"].get(x["text"], 0) + (x["t1"] - x["t0"]) + x.get("confidence", 0.8) + 0.02 * len(x["text"])
        hit["t1"] = max(hit["t1"], x["t1"])
        hit["_n"] += 1
        if len(norm(x["text"])) > len(norm(hit["text"])):   # the fullest reading carries the position and the size
            for k_ in ("x", "y", "height", "width", "color", "align", "text"):
                hit[k_] = x[k_]
    changed = True
    while changed:                                      # a fragment of a longer line that is on screen at the same time is that line
        changed = False
        for a_ in list(out):
            na = norm(a_["text"])
            for b_ in out:
                if a_ is b_:
                    continue
                nb = norm(b_["text"])
                overlap = a_["t0"] < b_["t1"] + 0.9 and b_["t0"] < a_["t1"] + 0.9
                if overlap and abs(a_["y"] - b_["y"]) < 0.09 and len(na) <= len(nb) and (na in nb or SequenceMatcher(None, na, nb).ratio() > 0.8) \
                        and not (re.findall(r"\d+", na) and re.findall(r"\d+", nb) and re.findall(r"\d+", na) != re.findall(r"\d+", nb)):
                    b_["t0"], b_["t1"] = min(a_["t0"], b_["t0"]), max(a_["t1"], b_["t1"])
                    b_["_n"] += a_["_n"]
                    for t_, v_ in a_["_votes"].items():
                        if len(norm(t_)) >= len(nb) * 0.8:
                            b_["_votes"][t_] = b_["_votes"].get(t_, 0) + v_
                    out.remove(a_)
                    changed = True
                    break
            if changed:
                break
    res = []
    for e in out:
        votes = e.pop("_votes")
        longest = max(len(norm(t)) for t in votes)
        full = {t: v for t, v in votes.items() if len(norm(t)) >= longest * 0.8}
        e["text"] = max(full, key=full.get).replace("-", " ") if re.search(r"[A-Za-z]-[A-Za-z]", max(full, key=full.get)) and " " in max(full, key=full.get) else max(full, key=full.get)
        n_ = e.pop("_n")
        if e["t1"] - e["t0"] < 0.45 and n_ < 2 and e.get("confidence", 1) < 0.9:
            continue
        res.append(e)
    joined = []
    for e in res:                                       # caption words popping up one after another are one caption
        j = joined[-1] if joined else None
        if j and e["t0"] - j["t1"] < 0.5 and abs(e["y"] - j["y"]) < 0.17 and j["t1"] - j["t0"] < 2.5 and e["t1"] - e["t0"] < 2.5 and j.get("_cap", True) \
                and not re.sub(r"[^A-Za-z]", "", e["text"] + j["text"]).isupper():
            j["t1"] = max(j["t1"], e["t1"])
            if norm(e["text"]) not in norm(j["text"]) and len(j["text"]) < 90:
                below = e["y"] > j["y"] + 0.02
                j["text"] = (j["text"] + ("\n" if below else " ") + e["text"]) if e["x"] >= j["x"] - 0.2 or below else (e["text"] + " " + j["text"])
            j["x"], j["width"] = 0.5 if abs(j["x"] - 0.5) < 0.2 else j["x"], max(j["width"], e["width"])
            j.setdefault("anim", {})["in"] = "pop"      # word-by-word captions: each word pops
            j["caption"] = True
            continue
        joined.append(e)
    # captions: lower-third, lower-case lines that keep re-appearing (often two lines, re-popped on every shot) are ONE caption layer
    caps = [e for e in joined if e["y"] > 0.74 and not re.sub(r"[^A-Za-z]", "", e["text"]).isupper()]
    if len(caps) >= 2 or (caps and caps[0].get("caption")):
        raw = [x for x in text if x["y"] > 0.74 and not re.sub(r"[^A-Za-z]", "", x["text"]).isupper() and len(norm(x["text"]).replace(" ", "")) >= 3]
        t0, t1 = min(e["t0"] for e in caps), max(e["t1"] for e in caps)
        if raw and all(b_["t0"] - a_["t1"] < 2.5 for a_, b_ in zip(sorted(caps, key=lambda e: e["t0"]), sorted(caps, key=lambda e: e["t0"])[1:])):
            # line 1 = the longest confident reading; line 2 = the longest reading that shares no words with it and was seen below one of line 1's readings
            best1 = max(raw, key=lambda x: (len(norm(x["text"])), x.get("confidence", 0)))
            w1 = set(norm(best1["text"]).split())
            rest = [x for x in raw if not (set(norm(x["text"]).split()) & w1) and not any(SequenceMatcher(None, w_, v_).ratio() > 0.7 for w_ in norm(x["text"]).split() for v_ in w1)]
            line2 = max(rest, key=lambda x: (len(norm(x["text"])), x.get("confidence", 0)))["text"] if rest else ""
            cap = dict(best1, t0=t0, t1=t1, text=best1["text"] + ("\n" + line2 if line2 else ""), x=0.5, align="center", caption=True,
                       y=round(min(0.9, float(min(x["y"] for x in raw if SequenceMatcher(None, norm(x["text"]), norm(best1["text"])).ratio() > 0.6))
                                   + (0.6 * float(sorted(x["height"] for x in raw)[len(raw) // 2]) if line2 else 0.0)), 4), width=max(x["width"] for x in raw),
                       height=round(float(sorted(x["height"] for x in raw)[len(raw) // 2]), 4), anim={"in": "pop", "out": "fadeout"})
            joined = [e for e in joined if e not in caps] + [cap]
            joined.sort(key=lambda e: e["t0"])
    for e in joined:
        try:
            lum_ = (int(e.get("color", "#ffffff")[1:3], 16) * 0.3 + int(e.get("color", "#ffffff")[3:5], 16) * 0.59 + int(e.get("color", "#ffffff")[5:7], 16) * 0.11)
        except ValueError:
            lum_ = 255
        if lum_ < 70 and e.get("height", 1) < 0.045 and not e.get("caption"):
            e["watermark"] = True                         # (dark, small and faint: a signature tucked into the picture)
    for e in joined:                                      # small words that sit in one place for most of the edit = the editor's watermark
        if dur > 4 and e["t1"] - e["t0"] >= 0.6 * dur and e.get("height", 1) < 0.07 and not e.get("caption") and len(e["text"]) <= 24:
            e["watermark"] = True
            e["anim"] = {"in": "fade", "out": "none"}
    return joined


def _tpl_text_style(path, dur, text, job, part="both"):
    """How each text layer is dressed and how it arrives: glow / shadow / outline, and pop, slide, fade or type-on."""
    import cv2
    import numpy as np
    if not text:
        return
    want = set()
    for x in text:
        f0 = int(round(x["t0"] * TPL_FPS))
        mid = int(round(min(x["t1"] - 0.1, x["t0"] + max(0.6, (x["t1"] - x["t0"]) / 2)) * TPL_FPS))
        x["_mid"], x["_seq"] = mid, [f0 + d for d in range(-8, 16, 2)]
        want.add(mid)
        want.update(q for q in x["_seq"] if q >= 0)
    hi = _tpl_grab(path, dur, want, job)
    for x in text:
        mid, seq = x.pop("_mid"), x.pop("_seq")
        cands_ = [g_ for g_ in (hi.get(mid), hi.get(seq[-1]), hi.get(seq[-3])) if g_ is not None]
        if not cands_:
            continue
        def _lit(g_):                                   # (judge the style on a frame where the words are well lit, not on a dark blink between jump cuts)
            hh_, ww_ = g_.shape
            r_ = g_[max(0, int((x["y"] - x.get("height", 0.05)) * hh_)):int((x["y"] + x.get("height", 0.05)) * hh_) + 1, max(0, int((x["x"] - x.get("width", 0.3) / 2) * ww_)):int((x["x"] + x.get("width", 0.3) / 2) * ww_) + 1]
            return float(np.percentile(r_, 97)) if r_.size else 0.0
        G = max(cands_, key=_lit)
        H, W = G.shape
        bw, bh = max(8, int(x.get("width", 0.3) * W)), max(5, int(x.get("height", 0.05) * H))
        cx, cy = int(x["x"] * W), int(x["y"] * H)
        x0, x1, y0, y1 = max(0, cx - bw // 2), min(W, cx + bw // 2), max(0, cy - bh // 2), min(H, cy + bh // 2)
        if x1 - x0 < 6 or y1 - y0 < 4:
            continue
        patch = G[y0:y1, x0:x1].astype(np.float32)
        rimv_ = np.concatenate([G[max(0, y0 - bh):y0, x0:x1].ravel(), G[y1:min(H, y1 + bh), x0:x1].ravel()]).astype(np.float32)
        on_dark = patch.mean() < 150 or (rimv_.size > 20 and float(np.median(rimv_)) < patch.mean() - 25)     # heavy bright caps fill their box: look at what is around it
        ink = patch > (patch.max() * 0.72) if on_dark else patch < (patch.min() + (255 - patch.min()) * 0.28)
        light = on_dark or float(patch[ink].mean() if ink.any() else 255) > 170
        pad = max(3, bh // 2)
        X0, X1, Y0, Y1 = max(0, x0 - pad), min(W, x1 + pad), max(0, y0 - pad), min(H, y1 + pad)
        big = G[Y0:Y1, X0:X1].astype(np.float32)
        m = np.zeros(big.shape, np.uint8)
        sub = m[y0 - Y0:y1 - Y0, x0 - X0:x1 - X0]
        sub[ink] = 1
        near = cv2.dilate(m, np.ones((5, 5), np.uint8)) - m
        far = cv2.dilate(m, np.ones((2 * pad + 1, 2 * pad + 1), np.uint8)) - cv2.dilate(m, np.ones((9, 9), np.uint8))
        style = "plain"
        if near.sum() > 10 and far.sum() > 10 and ink.any():
            nv, fv, iv = float(big[near > 0].mean()), float(big[far > 0].mean()), float(big[m > 0].mean())
            if light and iv < nv:                       # the box sat beside the letters: take the bright letters of the whole neighbourhood instead
                m = (big > big.max() * 0.72).astype(np.uint8)
                near = cv2.dilate(m, np.ones((5, 5), np.uint8)) - m
                far = cv2.dilate(m, np.ones((2 * pad + 1, 2 * pad + 1), np.uint8)) - cv2.dilate(m, np.ones((9, 9), np.uint8))
                if m.sum() > 10 and near.sum() > 10 and far.sum() > 10:
                    nv, fv, iv = float(big[near > 0].mean()), float(big[far > 0].mean()), float(big[m > 0].mean())
            if light and (nv - fv > 14 or (nv - fv > 8 and iv > 205)) and nv < iv - 12:
                style = "glow"                          # a soft halo of the letter's own light around it
            elif light and fv - nv > 22:
                style = "outline"                       # a dark edge hugging bright letters
            elif light and fv - nv > 9:
                style = "shadow"
        if x.get("caption") and light and style == "plain":
            style = "outline"                           # a white caption over footage always carries a dark edge (and is unreadable on a bright shot without one)
        if part != "anim":
            x["style"] = style
        letters = re.sub(r"[^A-Za-z0-9]", "", x["text"].split("\n")[0])
        if part != "anim" and letters and x.get("width") and x.get("height"):     # tall, narrow capitals = a condensed display face (Bebas / Impact kind)
            per = (x["width"] * W) / max(1, len(x["text"].split("\n")[0])) / max(1.0, x["height"] * H)
            x["glyph_aspect"] = round(per, 3)
            if letters.isupper() and per < 0.62:
                x["font"] = "Impact"
                x["font_like"] = "Bebas Neue"
        # arrival: watch the letter box over the first half second
        ser = []
        for q in seq:
            F = hi.get(q)
            if F is None:
                continue
            reg = F[max(0, y0 - bh):min(H, y1 + bh), x0:x1].astype(np.float32)
            core = F[y0:y1, x0:x1].astype(np.float32)
            thr_ = 0.72 * 255 if light else None
            on = (core > thr_) if light else (core < 80)
            cols = on.any(axis=0)
            rows_ = (reg > thr_).any(axis=1) if light else (reg < 80).any(axis=1)
            ser.append((q, float(on.mean()), float(cols.mean()), float(rows_.mean()),
                        (float(np.nonzero(cols)[0].max()) / max(1, len(cols))) if cols.any() else 0.0))
        if len(ser) >= 5 and part != "style":
            full = max(1e-3, float(np.median([v[1] for v in ser[-3:]])))
            rise = [v for v in ser if v[1] > 0.15 * full]
            if rise:
                first = rise[0]
                steps = [v for v in ser if 0.15 * full < v[1] < 0.85 * full]
                tall = max(v[3] for v in ser) / max(1e-3, float(np.median([v[3] for v in ser[-3:]])))
                cur = x.get("anim", {}).get("in", "fade")
                if cur not in ("typewriter", "slideup") and not x.get("caption"):
                    if len(steps) >= 2 and steps[0][4] < 0.7 and first[4] < 0.75:
                        cur = "typewriter"              # it fills in from the left, a bit more each frame
                    elif tall > 1.35:
                        cur = "pop"                     # it was bigger than it ends up: it overshoots and settles
                    elif len(steps) >= 2:
                        cur = "fade"
                    else:
                        cur = "pop" if tall > 1.15 else "fade"
                x.setdefault("anim", {})["in"] = cur


def _tpl_bars(frames, n):
    """Black bars that move: the frame closing in or opening up over time (a cinematic squeeze). [[t, amount 0-0.5]]"""
    import numpy as np
    h = frames.shape[1]
    step = 2
    vals = []
    for i in range(0, n, step):
        rows = frames[i].max(axis=2).mean(axis=1)
        lit = rows > 14
        if not lit.any() or frames[i].mean() < 10:
            vals.append(None)
            continue
        top = int(np.argmax(lit))
        bot = int(np.argmax(lit[::-1]))
        vals.append(min(top, bot) / h if abs(top - bot) <= 3 else 0.0)
    known = [v for v in vals if v is not None]
    if len(known) < 8 or max(known) - min(known) < 0.035:
        return None
    last = known[0]
    ser = []
    for v in vals:
        last = last if v is None else v
        ser.append(last)
    ser = np.array(ser)
    k = np.ones(5) / 5
    ser = np.convolve(np.pad(ser, 2, mode="edge"), k, mode="valid")
    keys = [[0.0, round(float(ser[0]), 4)]]
    for j in range(1, len(ser)):
        if abs(ser[j] - keys[-1][1]) > 0.012 and (j == len(ser) - 1 or abs(ser[j + 1] - ser[j]) < 0.004 or j % 4 == 0):
            keys.append([round(j * step / TPL_FPS, 3), round(float(ser[j]), 4)])
    return keys[:80] if len(keys) > 1 else None


def _tpl_audio(path, dur):
    """The reference's own soundtrack, kept so the template brings its music along. -> id (a file in the work folder)"""
    aid = uuid.uuid4().hex[:16]
    out = os.path.join(WORK_DIR, f"tplaud_{aid}.m4a")
    r = run(["ffmpeg", "-v", "error", "-y", "-i", path, "-t", f"{dur:.3f}", "-vn", "-ac", "2", "-ar", "44100", "-c:a", "aac", "-b:a", "192k", out])
    if r.returncode != 0 or not os.path.exists(out) or os.path.getsize(out) < 2000:
        _rm(out)
        return None
    return aid


def _tpl_shot_motion(path, dur, events, n, sc, pulses, job):
    """What each shot does between its cuts: a slow push-in / pull-out, a zoom punch across a hard cut, and a speed ramp
    (fast - slow - fast, fast -> slow, slow -> fast) read from how much the picture changes over the shot. -> {shot index: {...}}"""
    import numpy as np
    bounds = [0] + [e[0] for e in events] + [n]
    tails = [0] + [e[2] for e in events]                 # last frame of the transition into each shot
    heads = [e[1] for e in events] + [n]                 # first frame of the transition out of each shot
    want, plan = set(), {}
    for i in range(len(bounds) - 1):
        a, b = max(bounds[i], tails[i]) + 3, min(bounds[i + 1], heads[i]) - 3
        if b - a >= 8:
            plan[i] = (a, b)
            want.update((a, b))
        if i and events[i - 1][3]["type"] == "none":     # a hard cut: does the new shot land from a zoom?
            c = events[i - 1][0]
            if c + 8 < n and c - 8 > 0:
                want.update((c + 1, c + 7, c - 7, c - 1))
    hi = _tpl_grab(path, dur, want, job)
    out = {}
    thump = np.zeros(n, bool)
    for p_ in pulses:
        k = int(round(p_["t"] * TPL_FPS))
        thump[max(0, k - 2):k + 5] = True
    for i in range(len(bounds) - 1):
        info = {}
        if i in plan and plan[i][0] in hi and plan[i][1] in hi:
            a, b = plan[i]
            r = _tpl_same(hi[a], hi[b])
            L = bounds[i + 1] - bounds[i]
            if r["moving"] >= 12 and r["cover"] >= 3:
                z = r["scale"] ** (L / max(1.0, b - a))      # over the whole shot
                if z >= 1.03:
                    info["kb"] = {"dir": "in", "amt": int(max(5, min(60, round((z - 1) * 100))))}
                elif z <= 0.97:
                    info["kb"] = {"dir": "out", "amt": int(max(5, min(60, round((1 / z - 1) * 100))))}
            e = [float(sc[k]) for k in range(a + 2, b - 1) if not thump[k]]
            if len(e) >= 9:
                th = len(e) // 3
                e1, e2, e3 = float(np.median(e[:th])), max(0.6, float(np.median(e[th:2 * th]))), float(np.median(e[2 * th:]))
                r1, r3 = e1 / e2, e3 / e2
                k1, k3 = min(2.6, max(1.0, r1 ** 0.6)), min(2.6, max(1.0, r3 ** 0.6))
                if r1 >= 1.8 and r3 >= 1.8:
                    info["ramp"] = {"kind": "fast-slow-fast", "v": [round(k1, 2), round(1 / max(k1, k3) ** 0.8, 2), round(1 / max(k1, k3) ** 0.8, 2), round(k3, 2)]}
                elif r1 >= 1.8 and e1 > 3:
                    info["ramp"] = {"kind": "fast-slow", "v": [round(k1 * 1.1, 2), 1.0, round(1 / k1 ** 0.7, 2), round(1 / k1 ** 0.9, 2)]}
                elif r3 >= 1.8 and e3 > 3:
                    info["ramp"] = {"kind": "slow-fast", "v": [round(1 / k3 ** 0.9, 2), round(1 / k3 ** 0.7, 2), 1.0, round(k3 * 1.1, 2)]}
        if i and events[i - 1][3]["type"] == "none":
            c = events[i - 1][0]
            if all(q in hi for q in (c + 1, c + 7, c - 7, c - 1)):
                rb, ra = _tpl_same(hi[c + 1], hi[c + 7]), _tpl_same(hi[c - 7], hi[c - 1])
                land = rb["moving"] >= 15 and rb["scale"] <= 0.955
                push = ra["moving"] >= 15 and ra["scale"] >= 1.045
                if land or push:
                    info["punch"] = True
        if info:
            out[i] = info
    return out


def _tpl_look_segments(frames, events, n):
    """Parts of the edit that are graded differently (a dark, moody half and a bright, glowing half): the edit split
    where the brightness of the shots jumps and stays. -> [(first frame, last frame + 1)] or None when it is one look."""
    import numpy as np
    bounds = [0] + [e[0] for e in events] + [n]
    stats = []
    for i in range(len(bounds) - 1):
        a, b = bounds[i], bounds[i + 1]
        core = frames[min(b - 1, a + 3):max(a + 4, b - 3):2]
        if not len(core):
            core = frames[a:b]
        stats.append(float(core.mean()))
    segs, start = [], 0
    for i in range(1, len(stats)):
        left = float(np.median(stats[start:i]))
        right = float(np.median(stats[i:i + 3]))
        long_enough = (bounds[i] - bounds[start]) >= 30 and (n - bounds[i]) >= 30
        if abs(right - left) > 42 and long_enough and abs(stats[i] - left) > 30:
            segs.append((bounds[start], bounds[i]))
            start = i
    segs.append((bounds[start], n))
    return segs if len(segs) > 1 else None


def _tpl_glow(frames):
    """Bloom: how much of the picture is blown out to white and how bright it is overall -> glow amount 0-100."""
    import numpy as np
    if not len(frames):
        return 0
    smp = frames[::max(1, len(frames) // 40)].astype(np.float32)
    lum = smp[..., 0] * 0.114 + smp[..., 1] * 0.587 + smp[..., 2] * 0.299
    white = float((lum > 232).mean())
    mean = float(lum.mean())
    if white < 0.05 or mean < 120:
        return 0
    return int(max(0, min(85, round(20 + white * 220 + (mean - 120) * 0.25))))


def _tpl_trans_profile(frames, gray, luma, a, b, n, win):
    """Look INSIDE one transition, frame by frame: how soft the picture gets, how white, how far it pushes in or twists,
    and whether it mirrors. -> the Blur flash options that rebuild it."""
    import cv2
    import numpy as np
    a, b = max(3, a), min(n - 4, b)
    shp = lambda i: float(cv2.Laplacian(gray[i], cv2.CV_32F).var()) / (float(gray[i].var()) + 4.0)
    ref_ = max(1e-6, min(shp(a - 3), shp(b + 3)))
    ratios = [shp(i) / ref_ for i in range(a, b + 1)]
    soft_n = sum(1 for r in ratios if r < 0.5)
    blur = int(max(30, min(160, round(60 + (1 - min(ratios)) * 60 + soft_n * 6))))
    base = float(min(luma[a - 3], luma[b + 3]))
    peak = float(luma[a - 1:b + 2].max())
    white = int(max(0, min(100, round((peak - base) / max(1.0, 250 - base) * 100))))
    # push-in / twist: add up the frame-to-frame zoom and rotation over the half before the cut (while the match still holds)
    mid = (a + b + 1) // 2
    z, rot = 1.0, 0.0
    for i in range(max(1, a - 2), mid):
        _, _, zz, rr, c1, c2 = _tpl_motion(gray[i - 1], gray[i], win)
        if c2 > 0.06 and 0.8 < zz < 1.35:
            z *= zz
            rot += rr if abs(rr) < 25 else 0.0
    zoom = int(max(0, min(70, round((z - 1) * 100)))) if z > 1.02 else (22 if soft_n >= 2 else 8)
    spin = int(max(-60, min(60, round(rot)))) if abs(rot) >= 6 else 0
    # mirror: at the peak the picture is its own reflection (top/bottom or left/right) although it was not before
    def sym(i):
        g = cv2.GaussianBlur(gray[i], (0, 0), 2.0)
        h, w = g.shape
        t_, b_ = g[:h // 2], g[h - h // 2:][::-1]
        l_, r_ = g[:, :w // 2], g[:, w - w // 2:][:, ::-1]
        cc = lambda u, v: float(np.corrcoef(u.ravel(), v.ravel())[0, 1]) if u.std() > 2 and v.std() > 2 else 0.0
        return cc(t_, b_), cc(l_, r_)
    sv = max(sym(i)[0] for i in range(a, b + 1))
    sh_ = max(sym(i)[1] for i in range(a, b + 1))
    pv, ph = sym(a - 3)
    qv, qh = sym(b + 3)
    mirror = "v" if sv > 0.93 and sv - max(pv, qv) > 0.25 and sv >= sh_ else "h" if sh_ > 0.93 and sh_ - max(ph, qh) > 0.25 else None
    # Mirror smear, measured with dense optical flow (Farneback) on every frame pair of the transition and its landing:
    #   - opposite vectors: one side of the frame streams left while the other streams right (a fixed mirror axis), or
    #   - a mirrored whip: the whole picture streams sideways only, fast, with its own reflection next to it (a seam the
    #     picture is mirrored around), and stays readable while it does.
    fm = _tpl_flow_smear(gray, luma, a, b, n)
    smear = bool(fm["smear"])
    return {"blur": blur, "white": white, "zoom": zoom, "spin": spin, "mirror": mirror or ("h" if smear else None), "smear": smear,
            "flow": {k: fm[k] for k in ("kind", "peak", "frames", "seam")} if smear else None}


TPL_SMEAR_U = 2.0          # % of the frame width per frame: slower sideways motion is not a smear
TPL_SMEAR_PEAK = 4.0       # a mirrored whip peaks at least this fast
TPL_SMEAR_COL = 1.5        # a column "streams" left / right from this speed


def _fps_of(vs):
    try:
        num, _, den = str(vs.get("avg_frame_rate") if vs.get("avg_frame_rate") not in (None, "0/0") else vs.get("r_frame_rate") or "30/1").partition("/")
        return float(num) / float(den or 1)
    except (ValueError, ZeroDivisionError):
        return 30.0


def _tpl_flow(g0, g1, win=15):
    """Dense optical flow (Farneback) between two gray frames, in pixels."""
    import cv2
    import numpy as np
    u8 = lambda g: g if g.dtype == np.uint8 else np.clip(g, 0, 255).astype(np.uint8)
    return cv2.calcOpticalFlowFarneback(u8(g0), u8(g1), None, 0.5, 4, win, 3, 7, 1.5, 0)


def _tpl_flow_global(fl, step=4):
    """The camera's part of a flow field: a robust affine fit (pan + zoom + stretch). -> (pu, pv), each (ax, ay, c) on
    coordinates centred on the frame and divided by its width; flow in fractions of the width."""
    import numpy as np
    h, w = fl.shape[:2]
    ys, xs = np.mgrid[0:h:step, 0:w:step].astype(np.float32)
    A = np.stack([(xs.ravel() - w / 2) / w, (ys.ravel() - h / 2) / w, np.ones(xs.size, np.float32)], 1)
    u, v = fl[::step, ::step, 0].ravel() / w, fl[::step, ::step, 1].ravel() / w
    keep = np.ones(len(u), bool)
    pu = pv = np.zeros(3, np.float32)
    for _ in range(3):                                    # drop the 30% that fit worst (things moving on their own), fit again
        if keep.sum() < 12:
            break
        pu = np.linalg.lstsq(A[keep], u[keep], rcond=None)[0]
        pv = np.linalg.lstsq(A[keep], v[keep], rcond=None)[0]
        r = np.hypot(u - A @ pu, v - A @ pv)
        keep = r <= np.percentile(r, 70)
    return pu, pv


def _tpl_mirror_seam(g):
    """Is this frame a picture next to its own reflection? -> (match 0..1, where the seam is 0..1 across)."""
    import cv2
    import numpy as np
    g = cv2.GaussianBlur(np.asarray(g, np.float32), (0, 0), 1.5)
    h, w = g.shape
    best = (0.0, 0.5)
    for xa in range(int(w * 0.15), int(w * 0.86), 2):
        s_ = int(min(xa, w - xa, w * 0.22))
        if s_ < w * 0.12:
            continue
        l_, r_ = g[:, xa - s_:xa], g[:, xa:xa + s_][:, ::-1]
        if l_.std() < 6 or r_.std() < 6:
            continue
        c = float(np.corrcoef(l_.ravel(), r_.ravel())[0, 1])
        if c > best[0]:
            best = (c, xa / w)
    return best


def _tpl_flow_smear(gray, luma, a, b, n):
    """Optical flow through one transition (a few frames before it to 8 after) -> is it a mirror smear?"""
    import numpy as np
    whip, opp, peak, seam = [], [], 0.0, 0.0
    lo, hi = max(1, a - 2), min(n - 1, b + 8)
    for i in range(lo, hi + 1):
        if luma[i] > 236 or luma[i - 1] > 236:            # inside the white of a flash there is nothing to follow
            continue
        fl = _tpl_flow(gray[i - 1], gray[i], 21)
        w = fl.shape[1]
        u = float(np.median(fl[..., 0])) / w * 100
        v = float(np.median(np.abs(fl[..., 1]))) / w * 100
        cu = np.median(fl[..., 0], axis=0) / w * 100      # how each column of the picture moves sideways
        pos, neg = float((cu > TPL_SMEAR_COL).mean()), float((cu < -TPL_SMEAR_COL).mean())
        if pos >= 0.2 and neg >= 0.2 and v <= 1.0:
            opp.append(i)
        if abs(u) >= TPL_SMEAR_U and v <= 0.25 * abs(u) and max(pos, neg) >= 0.7:
            whip.append(i)
            peak = max(peak, abs(u))
    if len(whip) >= 3 and peak >= TPL_SMEAR_PEAK:
        for i in sorted(set([whip[0] - 1] + whip[:3])):
            if 1 <= i < n and luma[i] <= 236:
                seam = max(seam, _tpl_mirror_seam(gray[i])[0])
    kind = "opposite" if len(opp) >= 2 else "whip" if len(whip) >= 3 and peak >= TPL_SMEAR_PEAK and seam >= 0.9 else None
    return {"smear": kind is not None, "kind": kind, "peak": round(peak, 1), "frames": len(opp) if kind == "opposite" else len(whip), "seam": round(seam, 2)}


TPL_SCATTER_W = 480        # the title's exit is studied on bigger frames than the rest of the analysis


def _tpl_text_scatter(path, x, src_fps, total):
    """Does this text leave by flying apart (Letter Scatter)? Measured on the frames around its end:
    letter-sized strokes in the text's colour are found in every frame; when the text scatters, the strokes leave its
    box, their number OUTSIDE the box jumps, and optical flow (Farneback, camera motion taken out) shows them moving
    every which way. -> None, or {"t0": when it starts, "t1": when the last letters are gone, ...}."""
    import cv2
    import numpy as np
    letters = sum(ch.isalnum() for ch in x.get("text", ""))
    cx, cy, bw, bh = float(x.get("x", 0.5)), float(x.get("y", 0.5)), float(x.get("width", 0)), float(x.get("height", 0))
    if letters < 4 or bw <= 0 or bh <= 0:
        return None
    t1 = float(x["t1"])
    t_a, t_b = max(0.0, t1 - 0.35), min(total, t1 + 0.95)
    if t_b - t_a < 0.4:
        return None
    fps = int(max(24, min(60, round(src_fps or 30))))
    pr = probe(path)
    vs = next((q for q in pr.get("streams", []) if q.get("codec_type") == "video"), None)
    W = TPL_SCATTER_W
    H = int(round(W * int(vs["height"]) / int(vs["width"]) / 2)) * 2
    r = subprocess.run(["ffmpeg", "-v", "error", "-ss", f"{t_a:.3f}", "-t", f"{t_b - t_a:.3f}", "-i", path, "-vf", f"fps={fps},scale={W}:{H}",
                        "-f", "rawvideo", "-pix_fmt", "gray", "-"], capture_output=True)
    G = np.frombuffer(r.stdout, np.uint8)
    if len(G) < W * H * 6:
        return None
    G = G[:len(G) // (W * H) * W * H].reshape(-1, H, W)
    c = str(x.get("color") or "#ffffff").lstrip("#")
    try:
        lum = (int(c[0:2], 16) * 299 + int(c[2:4], 16) * 587 + int(c[4:6], 16) * 114) / 1000
    except ValueError:
        lum = 255.0
    light = lum > 127
    hp = bh * H
    k = int(max(5, round(hp * 1.1))) | 1
    ker = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (k, k))
    X0, X1 = int(max(0, (cx - bw * 0.75 - bh * 2) * W)), int(min(W, (cx + bw * 0.75 + bh * 2) * W))
    Y0, Y1 = int(max(0, (cy - bh * 5) * H)), int(min(H, (cy + bh * 5) * H))
    rows = []                                             # per frame: strokes in the box, strokes outside it, chaos, speed
    for i in range(1, len(G)):
        g = G[i]
        th = cv2.morphologyEx(g, cv2.MORPH_TOPHAT if light else cv2.MORPH_BLACKHAT, ker)
        m = ((th > 35) & ((g >= max(190, lum - 40)) if light else (g <= min(80, lum + 40)))).astype(np.uint8)
        nc, _lab, st, cen = cv2.connectedComponentsWithStats(m[Y0:Y1, X0:X1], 8)
        ins, out = 0, []
        for j in range(1, nc):
            _x, _y, w_, h_, a_ = st[j]
            if 0.3 * hp <= max(w_, h_) <= 1.9 * hp and min(w_, h_) >= 0.08 * hp and a_ >= 0.06 * hp * hp:
                px, py = cen[j][0] + X0, cen[j][1] + Y0
                if abs(px / W - cx) <= bw / 2 + bh * 0.3 and abs(py / H - cy) <= bh * 0.85:
                    ins += 1
                else:
                    out.append((px, py))
        chaos = speed = spread = 0.0
        if len(out) >= 3 and g.mean() < 236:
            fl = _tpl_flow(G[i - 1], g, 15)
            pu, pv = _tpl_flow_global(fl)
            P = np.array(out, np.float32)
            xi, yi = np.clip(P[:, 0].astype(int), 0, W - 1), np.clip(P[:, 1].astype(int), 0, H - 1)
            xn, yn = (P[:, 0] - W / 2) / W, (P[:, 1] - H / 2) / W
            gu = fl[yi, xi, 0] / W - (pu[0] * xn + pu[1] * yn + pu[2])        # each stroke's own motion, the camera's taken out
            gv = fl[yi, xi, 1] / W - (pv[0] * xn + pv[1] * yn + pv[2])
            mg = np.hypot(gu, gv)
            mv = mg > 0.001
            speed = float(np.median(mg)) * 100
            if mv.sum() >= 3:                             # 0 = all moving the same way, 1 = every direction at once
                chaos = 1 - float(np.hypot((gu[mv] / mg[mv]).mean(), (gv[mv] / mg[mv]).mean()))
            spread = float(np.percentile(P[:, 1], 90) - np.percentile(P[:, 1], 10)) / H / bh
        rows.append((ins, len(out), chaos, speed, spread))
    tt = lambda i: t_a + (i + 1) / fps
    pre = [r_[1] for i, r_ in enumerate(rows) if tt(i) < t1 - 0.12]
    base = float(np.median(pre)) if pre else 0.0
    seen = [r_[0] for i, r_ in enumerate(rows) if tt(i) < t1 - 0.12]
    if not seen or float(np.median(seen)) < 0.5 * letters:    # the letters must be seen sitting in their box first, or there is nothing to follow
        return None
    need = base + max(4.0, 0.4 * letters)                 # that many more strokes outside the box than before
    hot = [i for i, r_ in enumerate(rows) if tt(i) >= t1 - 0.15 and r_[1] >= need and r_[0] <= 0.6 * letters
           and r_[2] >= 0.3 and r_[3] >= 0.1 and r_[4] >= 2.0]
    if len(hot) < max(3, int(round(0.07 * fps))):
        return None
    if rows[hot[0]][1] > 0.75 * max(rows[i][1] for i in hot):      # it has to GROW: letters keep leaving the box, they are not all there at once
        return None
    end = hot[-1]
    for i in range(hot[-1] + 1, len(rows)):               # the letters may hang in the air after they stop: until they are gone
        if rows[i][1] >= base + max(3.0, 0.25 * letters):
            end = i
        elif i - end > max(2, fps // 10):
            break
    return {"t0": round(tt(hot[0]), 3), "t1": round(min(total, tt(end)), 3), "frames": len(hot), "fps": fps,
            "chaos": round(float(np.mean([rows[i][2] for i in hot])), 2), "spread": round(float(np.max([rows[i][4] for i in hot])), 1),
            "strokes": [int(base), int(max(rows[i][1] for i in hot))]}


def _tpl_bg_masks(fr):
    """One small frame -> (backdrop mask, dark mask): the flat, light, colourless studio backdrop and the near-black parts."""
    import cv2
    hsv = cv2.cvtColor(fr, cv2.COLOR_BGR2HSV)
    return (hsv[..., 1] < 46) & (hsv[..., 2] > 120), hsv[..., 2] < 62


def _tpl_is_backdrop(fr):
    """Is this frame a cut-out on a flat studio backdrop? Most of it (and its border) is light and colourless, and that area is
    ONE colour (real footage of a white wall still drifts between warm and cool)."""
    import numpy as np
    bg, _ = _tpl_bg_masks(fr)
    if bg.mean() < 0.5:
        return False
    hh, ww = bg.shape
    r = max(2, hh // 12)
    ring = float(np.concatenate([bg[:r].ravel(), bg[-r:].ravel(), bg[:, :r].ravel(), bg[:, -r:].ravel()]).mean())
    px = fr[bg].astype(np.int32)
    return ring >= 0.45 and float(np.std(px[:, 2] - px[:, 0])) <= 8.5


def _tpl_backdrop_ranges(frames, events, n):
    """The shots (between the cuts found so far) that are cut-out scenes: [(first frame, end frame)]."""
    import numpy as np
    bounds = [0] + [e[0] for e in events] + [n]
    out = []
    for a, b in zip(bounds, bounds[1:]):
        if b - a >= 8:
            votes = [_tpl_is_backdrop(frames[k]) for k in np.linspace(a + 2, b - 3, 5).astype(int)]
            if sum(votes) >= 2:
                out.append((a, b))
    return out


def _tpl_subject_box(fr):
    """The cut-out standing on a flat backdrop: the biggest solid thing that is not backdrop. -> (mask, box) or (None, None)"""
    import cv2
    import numpy as np
    bg, _ = _tpl_bg_masks(fr)
    h, w = bg.shape
    sub = cv2.morphologyEx((~bg).astype(np.uint8), cv2.MORPH_OPEN, np.ones((7, 7), np.uint8))
    sub = cv2.morphologyEx(sub, cv2.MORPH_CLOSE, np.ones((9, 9), np.uint8))
    nlab, lab, st, _ = cv2.connectedComponentsWithStats(sub, 8)
    if nlab < 2:
        return None, None
    k = 1 + int(np.argmax(st[1:, cv2.CC_STAT_AREA]))
    area = st[k, cv2.CC_STAT_AREA] / (w * h)
    if not 0.05 < area < 0.75:
        return None, None
    x0, y0, bw, bh = st[k, cv2.CC_STAT_LEFT], st[k, cv2.CC_STAT_TOP], st[k, cv2.CC_STAT_WIDTH], st[k, cv2.CC_STAT_HEIGHT]
    return lab == k, {"x": round((x0 + bw / 2) / w, 4), "y": round((y0 + bh / 2) / h, 4), "w": round(bw / w, 4), "h": round(bh / h, 4)}


def _tpl_backdrop_scenes(frames, events, n):
    """Cut-out scenes: a picture (PNG) standing on a flat studio backdrop, often swapped behind a dark shape that sweeps across.
    Finds which shots are like that, splits them where the cut-out changes, and says where the cut-out sits.
    -> (events with the extra scene changes, {first frame of a scene: {"backdrop": {...}, "overlays": [...]}})"""
    import numpy as np
    bounds = [0] + [e[0] for e in events] + [n]
    extra, scenes = [], {}
    for i in range(len(bounds) - 1):
        a, b = bounds[i], bounds[i + 1]
        if b - a < 12:
            continue
        if sum(_tpl_is_backdrop(frames[k]) for k in np.linspace(a + 2, b - 3, 5).astype(int)) < 2:
            continue
        # walk the shot: a dark shape swelling over the backdrop marks a swap; where it clears, look whether the cut-out changed
        dark = np.array([float(_tpl_bg_masks(frames[k])[1].mean()) for k in range(a, b)])
        base = float(np.percentile(dark, 20))
        starts, k, cur0 = [a], 0, a
        while k < len(dark):
            if dark[k] - base > 0.16:
                j = k
                while j < len(dark) and dark[j] - base > 0.07:
                    j += 1
                f_end = a + j
                if f_end + 4 < b and f_end - cur0 > 20:
                    m0, _ = _tpl_subject_box(frames[min(b - 1, cur0 + 4)])
                    m1, _ = _tpl_subject_box(frames[min(b - 1, f_end + 4)])
                    iou = 1.0 if m0 is None or m1 is None else float((m0 & m1).sum()) / max(1.0, float((m0 | m1).sum()))
                    if iou < 0.62 or (m0 is None) != (m1 is None):
                        starts.append(f_end)
                        extra.append((f_end, max(a, a + k - 2), f_end, {"type": "fade", "frames": 10, "ease": "smooth", "confidence": 0.6, "wipe": "shape"}))
                        cur0 = f_end
                k = j
            k += 1
        for si, f0 in enumerate(starts):
            f1 = starts[si + 1] if si + 1 < len(starts) else b
            mid = frames[min(b - 1, f0 + max(4, min(20, (f1 - f0) // 3)))]
            bg, _ = _tpl_bg_masks(mid)
            _, box = _tpl_subject_box(mid)
            hh, ww = bg.shape
            cen = mid[hh // 4:3 * hh // 4, ww // 4:3 * ww // 4][bg[hh // 4:3 * hh // 4, ww // 4:3 * ww // 4]]
            col = np.median(cen, axis=0) if len(cen) > 20 else np.median(mid[bg], axis=0) if bg.any() else np.array([240, 240, 240])
            rr = max(2, hh // 8)
            cm = np.concatenate([mid[:rr, :rr][bg[:rr, :rr]], mid[:rr, -rr:][bg[:rr, -rr:]], mid[-rr:, :rr][bg[-rr:, :rr]], mid[-rr:, -rr:][bg[-rr:, -rr:]]])
            vig = float(1 - cm.mean() / max(1.0, float(col.mean()))) if len(cm) > 10 else 0.3
            q8 = lambda v: int(min(255, round(float(v) / 12) * 12))      # (near-identical backdrops become one)
            scenes[f0] = {"backdrop": {"color": "#%02x%02x%02x" % (q8(col[2]), q8(col[1]), q8(col[0])), "vignette": int(max(0, min(90, round(vig * 110 / 15) * 15)))},
                          "overlays": [dict(box, cut=True, shadow=True, anim="fade")] if box else []}
    if extra:
        events = sorted(events + extra, key=lambda e: e[0])
    return events, scenes


def _tpl_gradual(frames, gray, luma, events, n):
    """Scene changes the frame-to-frame detector cannot see: a long blur / shake / dissolve in an edit that never sits still.
    Compares what the picture is MADE OF (colour layout) a little before and a little after every frame; where that jumps and
    no cut is known yet, there is one. -> extra events"""
    import cv2
    import numpy as np
    G = 8
    hs = []
    for i in range(n):
        hsv = cv2.cvtColor(frames[i], cv2.COLOR_BGR2HSV)
        hh, ww = hsv.shape[:2]
        parts = []
        for (y0, y1, x0, x1) in ((0, hh // 2, 0, ww // 2), (0, hh // 2, ww // 2, ww), (hh // 2, hh, 0, ww // 2), (hh // 2, hh, ww // 2, ww)):
            h_ = cv2.calcHist([hsv[y0:y1, x0:x1]], [0, 1, 2], None, [8, 3, 4], [0, 180, 0, 256, 0, 256]).ravel()
            parts.append(h_ / max(1.0, h_.sum()))
        hs.append(np.concatenate(parts))
    hs = np.array(hs, np.float32)
    D = np.zeros(n, np.float32)
    for k in range(G, n - G):
        D[k] = float(np.abs(hs[k - G] - hs[k + G]).sum()) / 4.0        # 0 (same) .. 2 (nothing in common)
    known = [e[0] for e in events]
    out, k = [], G
    while k < n - G:
        if D[k] > 0.9 and D[k] == D[max(G, k - 6):k + 7].max():
            if not any(abs(k - c) <= 12 for c in known) and not any(abs(k - e[0]) <= 12 for e in out):
                a, b = k, k
                while a > G and D[a - 1] > 0.45 and k - a < 14:
                    a -= 1
                while b < n - G - 1 and D[b + 1] > 0.45 and b - k < 14:
                    b += 1
                a, b = max(2, a + G // 2), min(n - 3, b - G // 2)          # (the window looks G frames each way)
                if b <= a:
                    a, b = max(2, k - 3), min(n - 3, k + 3)
                shp = lambda i: float(cv2.Laplacian(gray[i], cv2.CV_32F).var()) / (float(gray[i].var()) + 4.0)
                ref_ = max(1e-6, min(shp(max(0, a - 4)), shp(min(n - 1, b + 4))))
                soft = min(shp(i) for i in range(a, b + 1)) < 0.5 * ref_
                span = int(max(4, min(24, (b - a + 1) // 2 * 2)))
                out.append((k, a, b, {"type": "bflash" if soft else "fade", "frames": span, "ease": "linear", "confidence": 0.55, "soft_cut": True}))
            k += 6
        k += 1
    return out


def _tpl_frame_at(path, t, width=0):
    """One full-size frame (BGR) at time t."""
    import cv2
    import numpy as np
    vf = ["-vf", f"scale={width}:-2"] if width else []
    r = subprocess.run(["ffmpeg", "-v", "error", "-ss", f"{max(0.0, t):.3f}", "-i", path, "-frames:v", "1"] + vf + ["-f", "image2pipe", "-vcodec", "png", "-"],
                       stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, creationflags=NO_WINDOW)
    return cv2.imdecode(np.frombuffer(r.stdout, np.uint8), cv2.IMREAD_COLOR) if r.stdout else None


def _tpl_read_crop(img, x, y, w, h):
    """Read ONE piece of text properly: cut it out of the full-size frame, enlarge it, try it light-on-dark and dark-on-light,
    as one line and as a block. -> (text, confidence 0-100) - far more reliable on display fonts than reading the whole frame."""
    import cv2
    import numpy as np
    H, W = img.shape[:2]
    px, py = w * W * 0.12 + 6, h * H * 0.3 + 6
    x0, x1 = int(max(0, (x - w / 2) * W - px)), int(min(W, (x + w / 2) * W + px))
    y0, y1 = int(max(0, (y - h / 2) * H - py)), int(min(H, (y + h / 2) * H + py))
    if x1 - x0 < 8 or y1 - y0 < 6:
        return "", 0.0
    k_up = max(1.0, min(3.0, 96.0 / max(1.0, h * H)))             # letters about 100 px tall read best
    big_ = cv2.resize(img[y0:y1, x0:x1], None, fx=k_up, fy=k_up, interpolation=cv2.INTER_CUBIC)
    rr_ = _poster_ocr(big_)
    if rr_:                                               # the ONNX reader first: its lines, top to bottom
        rr_ = sorted([e_ for e_ in rr_ if e_["conf"] >= 60], key=lambda e_: min(p_[1] for p_ in e_["quad"]))
        if rr_:
            outl = []
            for e_ in rr_:
                t_ = e_["text"]
                if " " not in t_:
                    xs_, ys_ = [p_[0] for p_ in e_["quad"]], [p_[1] for p_ in e_["quad"]]
                    c_ = cv2.cvtColor(big_[max(0, int(min(ys_))):int(max(ys_)), max(0, int(min(xs_))):int(max(xs_))], cv2.COLOR_BGR2GRAY)
                    if c_.size > 50:
                        _, mk_ = cv2.threshold(c_, 0, 255, cv2.THRESH_BINARY + cv2.THRESH_OTSU)
                        ink_ = mk_ > 0
                        if ink_.mean() > 0.5:
                            ink_ = ~ink_
                        t_ = _poster_spaces(t_, ink_)
                outl.append(t_)
            return "\n".join(outl), float(np.mean([e_["conf"] for e_ in rr_]))
    try:
        import pytesseract
    except Exception:
        return "", 0.0
    crop = cv2.cvtColor(img[y0:y1, x0:x1], cv2.COLOR_BGR2GRAY)
    k = max(1.0, min(6.0, 70.0 / max(8.0, h * H)))
    crop = cv2.resize(crop, None, fx=k, fy=k, interpolation=cv2.INTER_CUBIC)
    crop = cv2.copyMakeBorder(crop, 14, 14, 14, 14, cv2.BORDER_REPLICATE)
    best = ("", 0.0)
    for src in (crop, 255 - crop, cv2.threshold(crop, 0, 255, cv2.THRESH_BINARY + cv2.THRESH_OTSU)[1], 255 - cv2.threshold(crop, 0, 255, cv2.THRESH_BINARY + cv2.THRESH_OTSU)[1]):
        for psm in (7, 6):
            try:
                d = pytesseract.image_to_data(src, config=f"--psm {psm} --oem 1", output_type=pytesseract.Output.DICT)
            except Exception:
                continue
            lines = {}
            for j, tx in enumerate(d["text"]):
                tx = (tx or "").strip()
                try:
                    cf = float(d["conf"][j])
                except (TypeError, ValueError):
                    cf = -1
                if tx and cf >= 35:
                    lines.setdefault((d["block_num"][j], d["par_num"][j], d["line_num"][j]), []).append((tx, cf))
            if not lines:
                continue
            txt = "\n".join(" ".join(t_ for t_, _ in ws) for ws in lines.values())
            cf = float(np.mean([c_ for ws in lines.values() for _, c_ in ws]))
            score = cf * min(1.0, len(re.sub(r"[^A-Za-z0-9]", "", txt)) / 3.0)
            if score > best[1] * min(1.0, len(re.sub(r"[^A-Za-z0-9]", "", best[0])) / 3.0 + 1e-6) and re.search(r"[A-Za-z0-9]", txt):
                best = (txt, cf)
    return best


def _tpl_text_refine(path, dur, text, job):
    """Second reading of every text layer, from its own enlarged cut-out (see _tpl_read_crop)."""
    for x in text:
        if job.get("cancel"):
            raise Cancelled()
        img = _tpl_frame_at(path, min(dur - 0.05, x["t0"] + min(0.6, max(0.15, (x["t1"] - x["t0"]) * 0.6))))
        if img is None:
            continue
        txt, cf = _tpl_read_crop(img, x["x"], x["y"], max(0.05, x.get("width", 0.3)), max(0.02, x.get("height", 0.05)))
        old = re.sub(r"[^A-Za-z0-9]", "", x["text"])
        new = re.sub(r"[^A-Za-z0-9]", "", txt)
        if new and cf >= 55 and len(new) >= len(old) * 0.7 and (cf >= x.get("confidence", 0) * 100 - 8 or len(new) > len(old)):
            x["text"], x["confidence"] = txt[:120], round(cf / 100, 2)


def _tpl_backdrop_words(path, dur, frames, scenes, bounds_of, text, job):
    """On a flat backdrop every word is a little island of ink. Find the islands the first reading missed, when each one
    appears, where, how big and what colour - then read each one from its own cut-out. Adds text layers."""
    import cv2
    import numpy as np
    n = len(frames)
    hh, ww = frames[0].shape[:2]
    added = []
    for f0 in sorted(scenes):
        f1 = bounds_of(f0)
        _, sbox = _tpl_subject_box(frames[min(n - 1, f0 + max(4, min(20, (f1 - f0) // 3)))])
        words = []                                       # open islands: [x0, y0, x1, y1, first frame, last frame, colour]
        for k in range(f0 + 2, f1 - 1, 3):
            fr = frames[k]
            bg, dark = _tpl_bg_masks(fr)
            if dark.mean() > 0.3:
                continue                                 # the dark shape is sweeping across
            ink = (~bg).astype(np.uint8)
            if sbox:                                     # not the cut-out itself
                sx0, sx1 = int((sbox["x"] - sbox["w"] / 2) * ww) - 3, int((sbox["x"] + sbox["w"] / 2) * ww) + 3
                sy0, sy1 = int((sbox["y"] - sbox["h"] / 2) * hh) - 3, int((sbox["y"] + sbox["h"] / 2) * hh) + 3
                ink[max(0, sy0):sy1, max(0, sx0):sx1] = 0
            joined = cv2.dilate(ink, np.ones((3, 9), np.uint8))
            nlab, lab, st, _ = cv2.connectedComponentsWithStats(joined, 8)
            for j in range(1, nlab):
                x0, y0, bw, bh, area = st[j]
                if not (5 <= bh <= hh * 0.2 and 6 <= bw <= ww * 0.9 and bw >= bh * 0.9 and area >= 40):
                    continue
                if float(ink[y0:y0 + bh, x0:x0 + bw].mean()) < 0.18 or x0 <= 5 or y0 <= 3 or x0 + bw >= ww - 5 or y0 + bh >= hh - 3:
                    continue                             # (too sparse, or it hangs off the edge: the dark corners of the backdrop)
                hit = None
                for w_ in words:
                    ix = max(0, min(w_[2], x0 + bw) - max(w_[0], x0)) * max(0, min(w_[3], y0 + bh) - max(w_[1], y0))
                    if ix > 0.4 * min((w_[2] - w_[0]) * (w_[3] - w_[1]), bw * bh):
                        hit = w_
                        break
                if hit:
                    hit[0], hit[1], hit[2], hit[3], hit[5] = min(hit[0], x0), min(hit[1], y0), max(hit[2], x0 + bw), max(hit[3], y0 + bh), k
                else:
                    pix = fr[y0:y0 + bh, x0:x0 + bw][ink[y0:y0 + bh, x0:x0 + bw] > 0]
                    col = np.median(pix, axis=0) if len(pix) else np.array([40, 40, 40])
                    words.append([x0, y0, x0 + bw, y0 + bh, k, k, "#%02x%02x%02x" % (int(col[2]), int(col[1]), int(col[0]))])
        for w_ in words:
            if w_[5] - w_[4] < 9:
                continue                                 # a flicker, not a word
            t0, t1 = w_[4] / TPL_FPS, min(dur, (w_[5] + 3) / TPL_FPS)
            cx, cy, bw, bh = float((w_[0] + w_[2]) / 2 / ww), float((w_[1] + w_[3]) / 2 / hh), float((w_[2] - w_[0] - 8) / ww), float((w_[3] - w_[1] - 2) / hh)
            if any(abs(x["x"] - cx) < max(0.12, x.get("width", 0.2) / 2 + bw / 2) and abs(x["y"] - cy) < 0.06 and x["t0"] < t1 and x["t1"] > t0 for x in text + added):
                continue                                 # the first reading already has this one
            img = _tpl_frame_at(path, min(dur - 0.05, (t0 + t1) / 2))
            txt, cf = _tpl_read_crop(img, cx, cy, max(0.04, bw), max(0.02, bh)) if img is not None else ("", 0)
            added.append({"t0": round(t0, 3), "t1": round(t1, 3), "text": (txt if cf >= 45 else "TEXT")[:60], "x": round(cx, 4), "y": round(cy, 4),
                          "height": round(max(0.02, bh), 4), "width": round(max(0.04, bw), 4), "color": w_[6], "align": "center",
                          "anim": {"in": "pop", "out": "fadeout"}, "confidence": round(cf / 100, 2), "found_by": "shape"})
    return added


def _tpl_runs(sc, thr):
    """Stretches of frames that all change a lot (a transition, or fast action). A long stretch is split where it
    dips well below its own peak, so two transitions close together stay two."""
    import numpy as np
    n = len(sc)

    def find(a0, b0, t):
        out, i = [], a0
        while i <= b0:
            if sc[i] >= t:
                j = i
                while j + 1 <= b0 and sc[j + 1] >= t * 0.7:
                    j += 1
                out.append((i, j))
                i = j + 1
            else:
                i += 1
        return out

    todo, done = find(1, n - 1, thr), []
    while todo:
        a, b = todo.pop()
        if b - a + 1 > 12:
            t2 = max(thr * 1.3, 0.33 * float(np.max(sc[a:b + 1])))
            parts = find(a, b, t2)
            if len(parts) > 1 or (parts and (parts[0][1] - parts[0][0]) < (b - a) - 2):
                todo += [p for p in parts if p != (a, b)]
                continue
        done.append((a, b))
    return sorted(r for r in done if r[1] - r[0] + 1 >= 2)


def _tpl_dissolves(frames, sc, busy):
    """Cross dissolves have no spike at all. Look for stretches where frames far apart differ a lot, neighbours only
    a little, and the middle frame is the average of the two ends."""
    import numpy as np
    n = len(frames)
    g = 6
    out = []
    f = frames.astype(np.int16)
    i = g + 1
    while i < n - g - 1:
        if busy[i - g:i + g + 1].any():
            i += 1
            continue
        far = float(np.abs(f[i + g] - f[i - g]).mean())
        if far < 22:
            i += 1
            continue
        loc = sc[i - g + 1:i + g + 1]
        if float(loc.max()) > 0.45 * far + 6 or float(loc.min()) < 0.6:
            i += 1
            continue
        mid = (f[i - g] + f[i + g]) // 2
        err = float(np.abs(f[i] - mid).mean())
        if err < 0.22 * far:
            a, b = i - g, i + g                       # grow the window while it stays a blend
            while a > 2 and sc[a] > 0.8 and not busy[a - 1] and (i - a) < 24:
                a -= 1
            while b < n - 2 and sc[b + 1] > 0.8 and not busy[b + 1] and (b - i) < 24:
                b += 1
            out.append((a, b))
            i = b + g
        else:
            i += 1
    return out


def _tpl_text(path, info, dur, job):
    """On-screen text with Tesseract: what it says, where, how big, what colour, from when to when."""
    import cv2
    import numpy as np
    from difflib import SequenceMatcher
    use_r = _poster_ocr(np.zeros((48, 160, 3), np.uint8)) is not None     # the ONNX reader (far better on display type, lyrics, script fonts)
    pytesseract = None
    try:
        import pytesseract
        _tess_setup(pytesseract)
        pytesseract.get_tesseract_version()
    except Exception:
        pytesseract = None
    if not use_r and pytesseract is None:
        return None
    step = (0.1 if dur <= 20 else 0.2) if dur <= 40 else 0.4 if dur <= 90 else 0.6 if dur <= 180 else 1.0
    W = 960 if info["width"] >= info["height"] else 540
    H = max(2, int(round(W * info["height"] / info["width"] / 2)) * 2)
    cmd = ["ffmpeg", "-v", "error", "-i", path, "-t", f"{dur:.3f}", "-an", "-vf", f"fps={1 / step:.5f},scale={W}:{H}:flags=bicubic,setsar=1",
           "-pix_fmt", "bgr24", "-f", "rawvideo", "-"]
    proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, creationflags=NO_WINDOW)
    job["proc"] = proc
    size = W * H * 3
    seen, k = [], 0                                    # open events
    done = []
    total = max(1, int(dur / step))
    while True:
        buf = proc.stdout.read(size)
        if len(buf) < size:
            break
        if job.get("cancel"):
            proc.kill()
            raise Cancelled()
        t = k * step
        k += 1
        job.update(pct=62 + min(30, int(30 * k / total)), stage="Reading the text (OCR)")
        img = np.frombuffer(buf, np.uint8).reshape(H, W, 3)
        gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
        lines = {}
        for j_, e_ in enumerate((_poster_ocr(img) or []) if use_r else []):
            xs_, ys_ = [p_[0] for p_ in e_["quad"]], [p_[1] for p_ in e_["quad"]]
            x0_, y0_, x1_, y1_ = max(0, int(min(xs_))), max(0, int(min(ys_))), min(W, int(max(xs_))), min(H, int(max(ys_)))
            if e_["conf"] < 62 or len(re.sub(r"[^A-Za-z0-9]", "", e_["text"])) < 2 or (y1_ - y0_) < H * 0.018 or x1_ - x0_ < 6:
                continue
            txt_ = e_["text"]
            if " " not in txt_:                            # (the reader drops the gaps between words: put them back from the letters)
                pg_ = gray[y0_:y1_, x0_:x1_]
                _, mk_ = cv2.threshold(pg_, 0, 255, cv2.THRESH_BINARY + cv2.THRESH_OTSU)
                ink_ = mk_ > 0
                if ink_.mean() > 0.5:
                    ink_ = ~ink_
                txt_ = _poster_spaces(txt_, ink_)
            lines[("r", j_)] = {"words": [txt_], "x0": x0_, "y0": y0_, "x1": x1_, "y1": y1_, "conf": [max(e_["conf"], 87.0 if e_["conf"] >= 75 else e_["conf"])]}
        for src in ((gray, 255 - gray) if not use_r else ()):                # dark-on-light and light-on-dark
            try:
                d = pytesseract.image_to_data(src, config="--psm 11 --oem 1", output_type=pytesseract.Output.DICT)
            except Exception:
                continue
            for j, txt in enumerate(d["text"]):
                txt = (txt or "").strip()
                try:
                    cf = float(d["conf"][j])
                except (TypeError, ValueError):
                    cf = -1
                if cf < 70 or len(re.sub(r"[^A-Za-z0-9]", "", txt)) < 2 or d["height"][j] < H * 0.018:
                    continue
                key = (d["block_num"][j], d["par_num"][j], d["line_num"][j], id(src))
                L = lines.setdefault(key, {"words": [], "x0": 1e9, "y0": 1e9, "x1": 0, "y1": 0, "conf": []})
                L["words"].append(txt)
                L["conf"].append(cf)
                L["x0"], L["y0"] = min(L["x0"], d["left"][j]), min(L["y0"], d["top"][j])
                L["x1"], L["y1"] = max(L["x1"], d["left"][j] + d["width"][j]), max(L["y1"], d["top"][j] + d["height"][j])
        found = []
        for L in lines.values():
            text = " ".join(L["words"])
            if len(re.sub(r"[^A-Za-z0-9]", "", text)) < (2 if float(np.mean(L["conf"])) >= 86 else 3):
                continue
            if any(SequenceMatcher(None, text.lower(), f["text"].lower()).ratio() > 0.8 and abs(f["cy"] - (L["y0"] + L["y1"]) / 2 / H) < 0.05 for f in found):
                continue                                # the inverted pass read the same line again
            x0, y0, x1, y1 = int(L["x0"]), int(L["y0"]), int(L["x1"]), int(L["y1"])
            patch = img[max(0, y0):y1, max(0, x0):x1]
            col = "#ffffff"
            if patch.size:
                pg = cv2.cvtColor(patch, cv2.COLOR_BGR2GRAY)
                thr, mask = cv2.threshold(pg, 0, 255, cv2.THRESH_BINARY + cv2.THRESH_OTSU)
                ink = mask > 0
                if ink.mean() > 0.5:                    # the letters are the smaller class
                    ink = ~ink
                if ink.any():
                    b_, g_, r_ = [int(np.median(patch[..., c][ink])) for c in range(3)]
                    col = f"#{r_:02x}{g_:02x}{b_:02x}"
            found.append({"text": text, "cx": (x0 + x1) / 2 / W, "cy": (y0 + y1) / 2 / H, "h": (y1 - y0) / H, "w": (x1 - x0) / W,
                          "color": col, "conf": float(np.mean(L["conf"]))})
        nxt = []
        for f in found:
            hit = None
            for e in seen:
                r = SequenceMatcher(None, f["text"].lower(), e["text"].lower()).ratio()
                grow = e["text"] and f["text"].lower().startswith(e["text"].lower()[:max(2, len(e["text"]) - 1)]) and len(f["text"]) > len(e["text"])
                if (r > 0.72 or grow) and abs(f["cy"] - e["cy"]) < 0.08 and e.get("_live"):
                    hit = e
                    break
            if hit:
                if len(f["text"]) > len(hit["text"]) + 1 and t - hit["t0"] <= 1.6:
                    hit["typed"] = True                 # it got longer as it went: a typewriter
                if f["conf"] >= hit["conf"] or len(f["text"]) > len(hit["text"]):
                    hit.update(text=f["text"], cx=f["cx"], h=f["h"], w=f["w"], color=f["color"], conf=f["conf"])
                if f["cy"] < hit["cy0"] - 0.03 and t - hit["t0"] <= 1.0:
                    hit["rose"] = True                  # it moved up as it came in: a slide up
                hit["cy"] = f["cy"]
                hit["t1"] = t + step
                hit["_seen"] = True
            else:
                e = dict(f, t0=t, t1=t + step, cy0=f["cy"], _live=True, _seen=True)
                seen.append(e)
        for e in seen:
            if e.get("_live") and not e.pop("_seen", False):
                e["_live"] = False
                done.append(e)
            else:
                nxt.append(e)
        seen = [e for e in nxt if e.get("_live")]
    proc.wait()
    job.pop("proc", None)
    done += seen
    out = []
    for e in sorted(done, key=lambda e: e["t0"]):
        if e["t1"] - e["t0"] < step * 1.5 and e["conf"] < 85:      # one lucky frame of noise
            continue
        out.append({"t0": round(max(0.0, e["t0"] - step / 2), 3), "t1": round(min(dur, e["t1"] - step / 2), 3), "text": e["text"][:120],
                    "x": round(e["cx"], 4), "y": round(e["cy"], 4), "height": round(e["h"], 4), "width": round(e["w"], 4), "color": e["color"],
                    "align": "left" if e["cx"] < 0.34 else "right" if e["cx"] > 0.66 else "center",
                    "anim": {"in": "typewriter" if e.get("typed") else "slideup" if e.get("rose") else "fade", "out": "fadeout"},
                    "confidence": round(e["conf"] / 100.0, 2)})
    return out


def _tpl_look(frames, hard, n):
    """The colour look, measured against an ordinary ungraded picture (so it can be laid over other footage)."""
    import cv2
    import numpy as np
    idx = np.linspace(0, n - 1, min(n, 80)).astype(int)
    smp = frames[idx].astype(np.float32)
    hh, ww = smp.shape[1:3]
    lum = smp[..., 0] * 0.114 + smp[..., 1] * 0.587 + smp[..., 2] * 0.299
    rows = lum.mean(axis=(0, 2))
    top = int(np.argmax(rows > 12)) if (rows > 12).any() else 0
    bot = int(np.argmax(rows[::-1] > 12)) if (rows > 12).any() else 0
    bars = (top + bot) / hh if min(top, bot) >= 2 and abs(top - bot) <= 3 else 0.0
    core = smp[:, top:hh - bot if bot else hh] if bars else smp
    cl = lum[:, top:hh - bot if bot else hh] if bars else lum
    b, g, r = [float(core[..., c].mean()) for c in range(3)]
    hsv_s = np.array([cv2.cvtColor(f.astype(np.uint8), cv2.COLOR_BGR2HSV)[..., 1].mean() for f in core[:: max(1, len(core) // 30)]]).mean() / 255.0
    std = float(cl.std())
    mean = float(cl.mean())
    ch, cw = cl.shape[1:3]
    centre = float(cl[:, ch // 3:2 * ch // 3, cw // 3:2 * cw // 3].mean())
    k = max(2, ch // 6), max(2, cw // 6)
    corner = float(np.mean([cl[:, :k[0], :k[1]].mean(), cl[:, :k[0], -k[1]:].mean(), cl[:, -k[0]:, :k[1]].mean(), cl[:, -k[0]:, -k[1]:].mean()]))
    cl_ = lambda v, lo, hi: int(round(max(lo, min(hi, v))))
    look = {"on": True,
            "contrast": cl_(100 * (std / 58.0) ** 0.6, 75, 145),
            "bright": cl_((mean - 112) / 255 * (95 if mean < 112 else 60), -38, 22),      # (a dark grade is far below an ordinary picture: say so)
            "sat": cl_(100 * (max(0.02, hsv_s) / 0.33) ** 0.7, 0 if hsv_s < 0.04 else 55, 175),
            "temp": cl_((r - b) / max(1.0, r + b) * 420, -70, 70),
            "tint": cl_(-(g - (r + b) / 2) / max(1.0, mean) * 260, -50, 50),
            "vig": cl_((1 - corner / max(1.0, centre)) * 130 - 12, 0, 65)}
    stats = {"luma_mean": round(mean, 1), "luma_std": round(std, 1), "saturation": round(float(hsv_s), 3),
             "rgb_mean": [round(r, 1), round(g, 1), round(b, 1)], "letterbox": round(float(bars), 3)}
    return look, stats


_TPL_HITS = {}


def _tpl_beats(path, dur):
    """BPM + beat times of the reference's own soundtrack (so cuts can be written down in beats)."""
    try:
        librosa = get_librosa()
        import numpy as np
        wav = os.path.join(WORK_DIR, "tpl_" + uuid.uuid4().hex + ".wav")
        r = run(["ffmpeg", "-v", "error", "-y", "-i", path, "-t", f"{dur:.3f}", "-vn", "-ac", "1", "-ar", "22050", "-f", "wav", wav])
        if r.returncode != 0 or not os.path.exists(wav):
            return None, []
        try:
            y, sr = librosa.load(wav, sr=22050, mono=True)
        finally:
            _rm(wav)
        if len(y) < sr:
            return None, []
        env = librosa.onset.onset_strength(y=y, sr=sr, hop_length=512)
        tempo, beats = librosa.beat.beat_track(onset_envelope=env, sr=sr, hop_length=512, trim=False)
        times = [float(t) for t in librosa.frames_to_time(np.asarray(beats, dtype=int), sr=sr, hop_length=512)]
        bpm = float(np.atleast_1d(tempo)[0]) if np.size(tempo) else 0.0
        _TPL_HITS[path] = []
        try:                                           # the loud hits (kicks, drops, impacts) whether or not they sit on the grid
            on = librosa.onset.onset_detect(onset_envelope=env, sr=sr, hop_length=512, backtrack=False, units="frames")
            if len(on):
                st = env[on]
                lim = max(float(np.percentile(st, 70)), float(env.mean() + 1.2 * env.std()))
                top = float(st.max()) or 1.0
                _TPL_HITS[path] = [{"t": round(float(librosa.frames_to_time(int(f), sr=sr, hop_length=512)), 3), "strength": round(float(v) / top, 3)}
                                   for f, v in zip(on, st) if v >= lim][:600]
        except Exception:
            pass
        return (bpm if bpm > 30 and len(times) >= 4 else None), times
    except Exception:
        return None, []


def _beat_pos(t, beats):
    """Time -> position on the beat grid (0 = first beat, fractional between beats, extrapolated outside)."""
    import numpy as np
    if len(beats) < 2:
        return None
    b = np.asarray(beats)
    ibi = float(np.median(np.diff(b)))
    if t <= b[0]:
        return float((t - b[0]) / ibi)
    if t >= b[-1]:
        return float(len(b) - 1 + (t - b[-1]) / ibi)
    i = int(np.searchsorted(b, t) - 1)
    return float(i + (t - b[i]) / max(1e-6, b[i + 1] - b[i]))


# ---------------------------------------------------------------------------
# The 15-pass template engine. One reference video is looked at fifteen times; every pass looks for ONE kind of thing
# and writes down what it found, so a later pass can check an earlier one. Accuracy is what counts here: nothing in
# this pipeline has a time limit.
# ---------------------------------------------------------------------------
TPL_PASSES = [
    "Cuts: hard cuts and scene changes",
    "Thumps: flashes, pulses and quick zooms inside a shot",
    "Basic transitions: the dominant motion at every cut",
    "Compound transitions: several motions at once, stacked",
    "Transition verification against the measured optical flow",
    "Basic overlays: pictures and clips on top of the video",
    "Multiple overlays: separating the ones that overlap",
    "Overlay consolidation: following every overlay along its path",
    "Basic text: where it is, what it says and when",
    "Multiple texts: lines, captions and overlapping blocks",
    "Text 2D / 3D: depth, perspective and extrusion",
    "Text styles: font, size, weight, colour, outline, shadow and glow",
    "Text animation: how every text arrives and leaves",
    "Full audit: nothing missed, every gap fixed",
    "Accuracy score: the template rendered and compared with the reference",
]
TPL_NPASS = len(TPL_PASSES)
TPL_CONF_MIN = 0.90           # a transition verified below this is never a guessed preset: it is rebuilt from its measured motion
TPL_SCORE_MIN = 85            # an accuracy score below this opens the Transition Matcher by itself


class TplJob(dict):
    """The state of one analysis. The measuring functions report with job.update(pct=..., stage=...); while a pass is
    running that becomes the pass's own progress and its detail line, and the pass number stays what the pipeline set."""

    def update(self, *a, **k):
        d = dict(*a, **k)
        if self.get("npass") is not None and self.get("status") == "running" and not d.get("status"):
            if "stage" in d:
                dict.__setitem__(self, "detail", d.pop("stage"))
            if "pct" in d:
                lo, hi = self.get("span") or (0, 100)
                fr = min(1.0, max(0.0, (float(d.pop("pct")) - lo) / max(1e-6, hi - lo)))
                dict.__setitem__(self, "pct", int(100 * (max(1, self["npass"]) - 1 + fr) / TPL_NPASS) if self["npass"] else 0)
        dict.update(self, d)


def _tp(job, k, span=(0, 100)):
    """Start pass k (1..15). Closes the pass before it in the log."""
    if job.get("cancel"):
        raise Cancelled()
    now = time.time()
    log = job.setdefault("log", [])
    if log and "secs" not in log[-1]:
        log[-1]["secs"] = round(now - log[-1].pop("_t"), 1)
    if k:
        log.append({"n": k, "name": TPL_PASSES[k - 1], "_t": now, "found": ""})
        dict.update(job, npass=k, stage=TPL_PASSES[k - 1], detail="", span=span, pct=int(100 * (k - 1) / TPL_NPASS))


def _tfound(job, text):
    if job.get("log"):
        job["log"][-1]["found"] = text


def _tpl_step(g0, g1, win):
    """The camera's move from one frame to the next, MEASURED: two estimators (phase correlation, which finds a move of any
    size, and dense optical flow with a robust fit, which is finer on small ones) each propose shift + zoom + turn; the one
    whose prediction of the second frame is closest wins. -> (dx, dy in fractions of the frame, log zoom, turn in degrees,
    how much of the change between the two frames that move explains: 0 = none of it ... 1 = all of it)"""
    import cv2
    import numpy as np
    h, w = g0.shape
    cands = [(0.0, 0.0, 0.0, 0.0)]
    try:
        dx, dy, z, rot, r1, r2 = _tpl_motion(g0, g1, win)
        if abs(dx) < 0.95 and abs(dy) < 0.95:
            cands.append((dx, dy, 0.0, 0.0))
            if 0.5 < z < 2.0 and abs(rot) < 60:
                cands += [(dx, dy, float(np.log(z)), rot), (dx, dy, float(np.log(z)), -rot), (dx, dy, float(np.log(z)), 0.0)]
    except Exception:
        pass
    try:
        pu, pv = _tpl_flow_global(_tpl_flow(g0, g1))
        cands.append((float(pu[2]), float(pv[2]) * w / h, float((pu[0] + pv[1]) / 2), float(np.degrees((pv[0] - pu[1]) / 2))))
    except Exception:
        pass
    m = np.zeros((h, w), np.uint8)
    m[h // 8:h - h // 8, w // 8:w - w // 8] = 1
    best, berr, zero = cands[0], None, None
    for c in cands:
        M = cv2.getRotationMatrix2D((w / 2.0, h / 2.0), -c[3], float(np.exp(c[2])))
        M[0, 2] += c[0] * w
        M[1, 2] += c[1] * h
        pred = cv2.warpAffine(g0, M, (w, h), flags=cv2.INTER_LINEAR, borderMode=cv2.BORDER_REFLECT)
        e = float(np.abs(pred - g1)[m > 0].mean())
        if zero is None:
            zero = e
        if berr is None or e < berr - 1e-6:
            best, berr = c, e
    return best[0], best[1], best[2], best[3], float(max(0.0, 1.0 - berr / max(1e-6, zero))) if zero > 0.5 else 1.0


def _tpl_series(gray, luma, a, b, n, win, cut=None):
    """Everything measurable about frames a..b of one transition, frame by frame: the camera's move (see _tpl_step),
    the brightness and how sharp the picture is. The step across the cut itself joins two different pictures, so it has no
    move of its own: it gets the mean of the steps beside it (a whip or a zoom carries on through its cut)."""
    import cv2
    import numpy as np
    a, b = max(1, int(a)), min(n - 1, int(b))
    idx = list(range(a, b + 1))
    st = [_tpl_step(gray[i - 1], gray[i], win) for i in idx]
    diff = [float(np.abs(gray[i] - gray[i - 1]).mean()) for i in idx]
    jump = None
    if cut is not None and a <= cut <= b:
        jump = int(cut) - a
    elif idx:
        j = int(np.argmax(diff))
        if diff[j] > 18 and st[j][4] < 0.25:
            jump = j
    dx, dy, lz, rot = ([s[k] for s in st] for k in range(4))
    if jump is not None and st[jump][4] < 0.35:
        nb = [q for q in (jump - 1, jump + 1) if 0 <= q < len(idx)]
        for arr in (dx, dy, lz, rot):
            arr[jump] = float(np.mean([arr[q] for q in nb])) if nb else 0.0
    shp = lambda i: float(cv2.Laplacian(gray[i], cv2.CV_32F).var()) / (float(gray[i].var()) + 4.0)
    ref = max(1e-6, (shp(max(0, a - 3)) + shp(min(n - 1, b + 3))) / 2)
    return {"a": a, "b": b, "jump": jump, "dx": dx, "dy": dy, "lz": lz, "rot": rot, "expl": [s[4] for s in st],
            "lum": [float(luma[i]) for i in idx], "lum0": float(luma[max(0, a - 2)]), "lum1": float(luma[min(n - 1, b + 2)]),
            "sharp": [shp(i) / ref for i in idx]}


def _tpl_stack(ti, se):
    """Pass 4: every motion that happens AT THE SAME TIME in one transition, each with its measured size."""
    import numpy as np
    sx, sy, sz, sr = float(np.sum(se["dx"])), float(np.sum(se["dy"])), float(np.sum(se["lz"])), float(np.sum(se["rot"]))
    out = []
    if abs(sx) >= 0.06 or abs(sy) >= 0.06:
        d = ("left" if sx < 0 else "right") if abs(sx) >= abs(sy) else ("up" if sy < 0 else "down")
        out.append({"kind": "slide", "dir": d, "x": round(sx, 3), "y": round(sy, 3)})
    if abs(sz) >= 0.05:
        out.append({"kind": "zoom", "dir": "in" if sz > 0 else "out", "amount": round(float(np.exp(sz)), 3)})
    if abs(sr) >= 4.0:
        out.append({"kind": "spin", "degrees": round(sr, 1)})
    base = max(se["lum0"], se["lum1"])
    if se["lum"] and max(se["lum"]) > 205 and max(se["lum"]) - base > 40:
        out.append({"kind": "flash", "peak": round(max(se["lum"]), 1)})
    if se["lum"] and min(se["lum"]) < 22 and min(se["lum0"], se["lum1"]) - min(se["lum"]) > 30:
        out.append({"kind": "dip", "low": round(min(se["lum"]), 1)})
    if se["sharp"] and min(se["sharp"]) < 0.45:
        out.append({"kind": "blur", "amount": round(1 - min(se["sharp"]), 2)})
    if ti.get("type") in ("fade", "wipel", "wiper", "circle", "star", "diamond", "radial"):
        out.append({"kind": "blend" if ti["type"] == "fade" else "wipe", "shape": ti["type"]})
    return out


TPL_T_AXIS = {"left": ("dx", -1), "right": ("dx", 1), "up": ("dy", -1), "down": ("dy", 1), "zoomin": ("lz", 1), "zoomout": ("lz", -1),
              "slowmo": ("lz", 1), "slowin": ("lz", 1), "slowout": ("lz", -1), "punch": ("lz", 1)}


def _tpl_confidence(ti, se, frames):
    """Pass 5: how well does the transition named in pass 3 agree with what was MEASURED? Every measured motion the preset
    does not have, has in the other direction, or (for a slide) has far too little of, takes its weight off the confidence.
    A blend is checked as a blend: is the middle frame really a mix of the pictures on both sides."""
    import numpy as np
    tot = {"dx": float(np.sum(se["dx"])), "dy": float(np.sum(se["dy"])), "lz": float(np.sum(se["lz"])), "rot": float(np.sum(se["rot"]))}
    wt = {"dx": min(1.0, abs(tot["dx"]) / 0.45), "dy": min(1.0, abs(tot["dy"]) / 0.45), "lz": min(1.0, abs(tot["lz"]) / 0.22), "rot": min(1.0, abs(tot["rot"]) / 22.0)}
    typ = ti.get("type", "none")
    explained = {}
    if typ in TPL_T_AXIS:
        ax, sg = TPL_T_AXIS[typ]
        explained[ax] = sg
    if typ == "spin":
        explained["rot"] = 0                                 # (either way)
    if typ == "bflash":
        fx = ti.get("fx") or {}
        if fx.get("zoom"):
            explained["lz"] = 1
        if fx.get("spin"):
            explained["rot"] = 0
    un = [wt[ax] for ax in ("dx", "dy", "lz", "rot")
          if wt[ax] >= 0.18 and (ax not in explained or (explained[ax] and np.sign(tot[ax]) != explained[ax]))]      # (under 0.18: too small to be a motion of its own)
    lost = min(1.0, max(un) + 0.25 * (sum(un) - max(un))) if un else 0.0
    conf = 1.0 - 0.75 * lost
    for ax, sg in explained.items():                        # the preset says "it moves this way": it has to
        if ax in ("dx", "dy") and typ in ("left", "right", "up", "down") and wt[ax] < 0.3:
            conf = min(conf, 0.55 + wt[ax])
        if ax == "lz" and typ in ("zoomin", "zoomout") and wt[ax] < 0.2:
            conf = min(conf, 0.6 + wt[ax])
    if typ == "spin" and wt["rot"] < 0.3:
        conf = min(conf, 0.55 + wt["rot"])
    a, b = se["a"], se["b"]
    if typ == "fade" and b - a >= 2:                         # a mix of both sides?
        A, B, Mi = frames[max(0, a - 1)].astype(np.float32), frames[min(len(frames) - 1, b + 1)].astype(np.float32), frames[(a + b) // 2].astype(np.float32)
        den = float(((A - B) ** 2).sum())
        if den > 1:
            al = float(np.clip(((Mi - B) * (A - B)).sum() / den, 0, 1))
            res = float(np.abs(Mi - (al * A + (1 - al) * B)).mean()) / (float(np.abs(A - B).mean()) + 1e-6)
            conf = min(conf, float(np.clip(1.08 - res, 0.3, 1.0)) if 0.12 < al < 0.88 else 0.6)
    if typ in ("dip", "flashw") and se["lum"]:
        ok = (min(se["lum"]) < 0.45 * max(8.0, min(se["lum0"], se["lum1"]))) if typ == "dip" else (max(se["lum"]) > 200)
        conf = min(conf, 0.95 if ok else 0.7)
    if typ == "bflash" and se["sharp"]:
        conf = min(conf, 0.95 if (min(se["sharp"]) < 0.6 or max(se["lum"]) > 200) else 0.72)
    if typ not in ("none", "fade", "dip", "flashw", "bflash", "spin") and typ not in TPL_T_AXIS:
        conf = min(conf, float(ti.get("confidence", 0.7)))   # (shape wipes and motion graphics: what their own detector said)
    if typ == "none" and (ti.get("soft_cut") or (se["sharp"] and min(se["sharp"]) < 0.4 and b - a >= 3)):
        conf = min(conf, 0.7)                                # a "plain cut" inside a smear is not a plain cut
    return round(float(np.clip(conf, 0.05, 1.0)), 2), tot, wt


def _tpl_measured(ti, se, c, tot, wt):
    """The No Preset rule: a transition that could not be verified is rebuilt from its own measured motion. The two shots
    carry the camera's measured path, frame by frame: the old shot from where it rested to where the move had taken it, the
    new shot from where it comes in to where it rests. (The renderer turns these lists into keyframed FFmpeg expressions.)
    -> {"base", "frames", "out": {dx, dy, sc, rot}, "in": {...}} or None when nothing moves."""
    import numpy as np
    if max(wt.values()) < 0.18:
        return None
    a, b = se["a"], se["b"]
    c = int(min(max(c, a), b))
    n = b - a + 1
    cx, cy, cz, cr = (np.cumsum(se[k]) for k in ("dx", "dy", "lz", "rot"))
    slide = max(wt["dx"], wt["dy"]) >= 0.18
    shrink = float(np.min(cz)) < -0.03 or float(cz[-1] - np.max(cz)) < -0.03
    base = "fade" if (slide or shrink or ti.get("type") == "fade") else "none"
    half = min(15, max(1, n // 2)) if base == "fade" else 0
    frames = 2 * half
    r4 = lambda v: round(float(v), 4)
    j = c - a                                             # index of the first frame that shows the new shot
    lo, hi = max(0, j - half), min(n, j + half)
    o_rng = range(0, hi) if base == "fade" else range(0, max(0, j))
    i_rng = range(lo, n) if base == "fade" else range(j, n)
    out = {"dx": [r4(cx[i]) for i in o_rng], "dy": [r4(cy[i]) for i in o_rng], "sc": [r4(np.exp(cz[i])) for i in o_rng], "rot": [r4(cr[i]) for i in o_rng]}
    inn = {"dx": [r4(cx[i] - cx[-1]) for i in i_rng], "dy": [r4(cy[i] - cy[-1]) for i in i_rng], "sc": [r4(np.exp(cz[i] - cz[-1])) for i in i_rng], "rot": [r4(cr[i] - cr[-1]) for i in i_rng]}
    if not out["dx"] and not inn["dx"]:
        return None
    return {"base": base, "frames": int(frames), "out": out, "in": inn, "total": {k: r4(v) for k, v in tot.items()}}


def _tpl_overlay_layers(overlays):
    """Pass 7: overlays that are on screen together and touch are separate layers, the smaller one on top."""
    def hit(p, q):
        return (min(p["t1"], q["t1"]) - max(p["t0"], q["t0"]) > 0.1 and abs(p["x"] - q["x"]) < (p["w"] + q["w"]) / 2 and abs(p["y"] - q["y"]) < (p["h"] + q["h"]) / 2)
    groups = 0
    for i, o in enumerate(overlays):
        o["id"] = i
        o["z"] = 0
        o["with"] = []
    for i, o in enumerate(overlays):
        for j in range(i + 1, len(overlays)):
            q = overlays[j]
            if hit(o, q):
                o["with"].append(j)
                q["with"].append(i)
    for o in sorted(overlays, key=lambda o: -(o["w"] * o["h"])):
        if o["with"]:
            o["z"] = 1 + max([overlays[k]["z"] for k in o["with"] if overlays[k]["w"] * overlays[k]["h"] > o["w"] * o["h"]] + [-1])
            groups += 1
    return groups


def _tpl_overlay_split(gray, o, n):
    """Pass 7, inside one overlay: does a SECOND thing appear inside its box later (a sparkle over a logo)? -> an extra overlay or None."""
    import cv2
    import numpy as np
    h, w = gray.shape[1:3]
    f0, f1 = int(round(o["t0"] * TPL_FPS)) + 6, int(round(o["t1"] * TPL_FPS)) - 4
    x0, x1 = max(0, int((o["x"] - o["w"] / 2) * w)), min(w, int((o["x"] + o["w"] / 2) * w))
    y0, y1 = max(0, int((o["y"] - o["h"] / 2) * h)), min(h, int((o["y"] + o["h"] / 2) * h))
    if f1 - f0 < 10 or x1 - x0 < 12 or y1 - y0 < 10:
        return None
    ker = np.ones((3, 3), np.uint8)
    for i in range(f0 + 1, f1 - 6):
        d = np.abs(gray[i + 4][y0:y1, x0:x1] - gray[i - 1][y0:y1, x0:x1])
        ch = cv2.morphologyEx((d > 30).astype(np.uint8), cv2.MORPH_OPEN, ker)
        fr = float(ch.mean())
        if not 0.04 < fr < 0.4:
            continue
        ys, xs = np.nonzero(ch)
        bx0, bx1, by0, by1 = int(np.percentile(xs, 3)), int(np.percentile(xs, 97)) + 1, int(np.percentile(ys, 3)), int(np.percentile(ys, 97)) + 1
        if (bx1 - bx0) < 6 or (by1 - by0) < 6 or (bx1 - bx0) * (by1 - by0) > 0.6 * d.size or float(ch[by0:by1, bx0:bx1].mean()) < 0.45:
            continue
        still = np.abs(gray[min(f1, i + 9)][y0:y1, x0:x1] - gray[i + 4][y0:y1, x0:x1])
        if float(still[by0:by1, bx0:bx1].mean()) > 14:
            continue                                        # it did not stay: movement inside the overlay, not a second layer
        end = f1
        ref = gray[i + 4][y0:y1, x0:x1][by0:by1, bx0:bx1]
        for q in range(i + 8, f1):
            if float(np.abs(gray[q][y0:y1, x0:x1][by0:by1, bx0:bx1] - ref).mean()) > 28:
                end = q
                break
        return {"t0": round(i / TPL_FPS, 4), "t1": round(end / TPL_FPS, 4), "x": round((x0 + (bx0 + bx1) / 2) / w, 4), "y": round((y0 + (by0 + by1) / 2) / h, 4),
                "w": round((bx1 - bx0) / w, 4), "h": round((by1 - by0) / h, 4), "anim": "pop", "inside": True}
    return None


def _tpl_overlay_track(gray, o, n):
    """Pass 8: follow one overlay from its first settled frame to its last (its picture is searched for in every 2nd frame).
    -> (path [[t, x, y]] when it moves, the frame it was last really there, how sure the match was)"""
    import cv2
    import numpy as np
    h, w = gray.shape[1:3]
    f0, f1 = min(n - 1, int(round(o["t0"] * TPL_FPS)) + 6), min(n - 1, int(round(o["t1"] * TPL_FPS)) - 1)
    bw, bh = max(8, int(o["w"] * w)), max(8, int(o["h"] * h))
    x0, y0 = int(np.clip(o["x"] * w - bw / 2, 0, w - bw)), int(np.clip(o["y"] * h - bh / 2, 0, h - bh))
    if f1 - f0 < 4:
        return None, f1, 0.0
    tpl_ = gray[f0][y0:y0 + bh, x0:x0 + bw]
    if float(tpl_.std()) < 4:
        return None, f1, 0.0
    path, last, scores = [], f0, []
    px, py = x0, y0
    for f in range(f0, f1 + 1, 2):
        pad = max(6, bw // 3)
        sx0, sy0, sx1, sy1 = max(0, px - pad), max(0, py - pad), min(w, px + bw + pad), min(h, py + bh + pad)
        reg = gray[f][sy0:sy1, sx0:sx1]
        if reg.shape[0] < bh or reg.shape[1] < bw:
            break
        res = cv2.matchTemplate(reg, tpl_, cv2.TM_CCOEFF_NORMED)
        _mn, mx, _l, loc = cv2.minMaxLoc(res)
        if mx < 0.45:
            break                                           # it is not there any more
        px, py = sx0 + loc[0], sy0 + loc[1]
        scores.append(float(mx))
        last = f
        path.append([round(f / TPL_FPS, 4), round((px + bw / 2) / w, 4), round((py + bh / 2) / h, 4)])
    if len(path) < 2:
        return None, last, float(np.mean(scores)) if scores else 0.0
    xs, ys = [p[1] for p in path], [p[2] for p in path]
    moved = max(max(xs) - min(xs), max(ys) - min(ys)) > 0.03
    return (path if moved else None), last, float(np.mean(scores))


def _tpl_text_lines(text):
    """Pass 10: lines that stand under each other with the same timing are ONE multi-line block; texts that share the
    screen and the place are marked as overlapping (each keeps its own layer)."""
    text.sort(key=lambda x: (x["t0"], x["y"]))
    used, out, joined = set(), [], 0
    for i, x in enumerate(text):
        if i in used:
            continue
        blk = [x]
        for j in range(i + 1, len(text)):
            y = text[j]
            if j in used or y.get("caption") != x.get("caption") or y.get("watermark") or x.get("watermark"):
                continue
            last = blk[-1]
            hh = max(last.get("height", 0.05), y.get("height", 0.05))
            same_t = abs(y["t0"] - x["t0"]) <= 0.12 and abs(y["t1"] - x["t1"]) <= 0.2
            under = 0.4 * hh < (y["y"] - last["y"]) < 2.3 * hh and abs(y["x"] - last["x"]) < max(last.get("width", 0.3), y.get("width", 0.3)) * 0.6
            alike = 0.6 < (y.get("height", 0.05) / max(1e-4, last.get("height", 0.05))) < 1.6 and (y.get("color") or "") == (last.get("color") or "")
            if same_t and under and alike and "\n" not in y["text"]:
                blk.append(y)
                used.add(j)
        if len(blk) > 1:
            joined += len(blk) - 1
            top, bot = blk[0], blk[-1]
            x = dict(x, text="\n".join(b["text"] for b in blk), y=round((top["y"] + bot["y"]) / 2, 4), lines=len(blk),
                     width=round(max(b.get("width", 0.3) for b in blk), 4), line_height=round(top.get("height", 0.05), 4),
                     t1=max(b["t1"] for b in blk), confidence=round(min(b.get("confidence", 0.5) for b in blk), 2))
        else:
            x["lines"] = x["text"].count("\n") + 1
        out.append(x)
    over = 0
    for i, x in enumerate(out):
        x["overlaps"] = []
        for j, y in enumerate(out):
            if i != j and min(x["t1"], y["t1"]) - max(x["t0"], y["t0"]) > 0.15 and abs(x["x"] - y["x"]) < (x.get("width", 0.3) + y.get("width", 0.3)) / 2 \
                    and abs(x["y"] - y["y"]) < (x.get("height", 0.05) * x.get("lines", 1) + y.get("height", 0.05) * y.get("lines", 1)) / 2:
                x["overlaps"].append(j)
        over += bool(x["overlaps"])
    text[:] = out
    return joined, over


def _tpl_text_ink(G, x):
    """The letters of one text as a mask, cut out of a sharp gray frame (with some room around). -> (mask, patch, box) or None"""
    import numpy as np
    H, W = G.shape
    lines = max(1, x.get("lines", 1))
    bw, bh = max(8, int(x.get("width", 0.3) * W)), max(6, int(x.get("height", 0.05) * H * (1.25 * lines if lines > 1 else 1)))
    cx, cy = int(x["x"] * W), int(x["y"] * H)
    pad = max(4, bh // 2)
    X0, X1, Y0, Y1 = max(0, cx - bw // 2 - pad), min(W, cx + bw // 2 + pad), max(0, cy - bh // 2 - pad), min(H, cy + bh // 2 + pad)
    if X1 - X0 < 10 or Y1 - Y0 < 8:
        return None
    patch = G[Y0:Y1, X0:X1].astype(np.float32)
    rim = np.concatenate([patch[:2].ravel(), patch[-2:].ravel(), patch[:, :2].ravel(), patch[:, -2:].ravel()])
    light = float(np.percentile(patch, 97)) - float(np.median(rim)) > float(np.median(rim)) - float(np.percentile(patch, 3))
    ink = patch > (float(np.median(rim)) + 0.55 * (float(patch.max()) - float(np.median(rim)))) if light else patch < (float(np.median(rim)) - 0.55 * (float(np.median(rim)) - float(patch.min())))
    if ink.sum() < 12 or ink.mean() > 0.7:
        return None
    return ink.astype(np.uint8), patch, light


def _tpl_text_3d(path, dur, text, job):
    """Pass 11: is a text flat or does it have depth? Three things are measured on its sharpest frame:
    tilt (the letters' baseline is not level), perspective (one side of the block is taller than the other, or the top is
    narrower than the bottom) and extrusion (a hard, solid copy of the letters pushed out to one side: the side of 3D type)."""
    import cv2
    import numpy as np
    want = {int(round(min(x["t1"] - 0.1, x["t0"] + max(0.5, (x["t1"] - x["t0"]) / 2)) * TPL_FPS)) for x in text}
    hi = _tpl_grab(path, dur, want, job)
    n3 = 0
    for x in text:
        x["dim"] = {"mode": "2d", "tilt": 0.0, "perspective": 0.0, "extrude": 0}
        G = hi.get(int(round(min(x["t1"] - 0.1, x["t0"] + max(0.5, (x["t1"] - x["t0"]) / 2)) * TPL_FPS)))
        if G is None or x.get("watermark"):
            continue
        got = _tpl_text_ink(G, x)
        if not got:
            continue
        ink, patch, light = got
        ys, xs = np.nonzero(ink)
        if len(xs) < 30:
            continue
        hh, ww = ink.shape
        tilt = persp = 0.0
        if x.get("lines", 1) == 1 and (xs.max() - xs.min()) > 3 * (ys.max() - ys.min()):
            cols = np.unique(xs)
            top = np.array([ys[xs == c].min() for c in cols], np.float32)
            bot = np.array([ys[xs == c].max() for c in cols], np.float32)
            if len(cols) >= 12:
                kb = np.polyfit(cols, bot, 1)[0]              # slope of the baseline, slope of the cap line
                kt = np.polyfit(cols, top, 1)[0]
                tilt = float(np.degrees(np.arctan((kb + kt) / 2)))
                span = float(cols.max() - cols.min())
                hl, hr = float(np.median((bot - top)[:max(3, len(cols) // 5)])), float(np.median((bot - top)[-max(3, len(cols) // 5):]))
                if min(hl, hr) > 3:
                    persp = float((hr - hl) / max(hl, hr))    # + = the right side is nearer
                if abs(kb - kt) * span < 1.5:
                    persp = 0.0
        # extrusion: next to the letters, in ONE direction, a band of a different, even tone (not a soft falloff)
        ext, edir = 0, None
        k3 = np.ones((3, 3), np.uint8)
        inkv = float(patch[ink > 0].mean())
        bgv = float(np.median(patch[cv2.dilate(ink, np.ones((15, 15), np.uint8)) == 0])) if (cv2.dilate(ink, np.ones((15, 15), np.uint8)) == 0).any() else float(np.median(patch))
        best = 0.0
        for name, (ox, oy) in {"right-down": (1, 1), "left-down": (-1, 1), "down": (0, 1), "right": (1, 0), "left": (-1, 0), "up": (0, -1), "right-up": (1, -1), "left-up": (-1, -1)}.items():
            depth = 0
            for d in range(1, max(3, hh // 4)):
                sh_ = np.roll(np.roll(ink, oy * d, 0), ox * d, 1)
                band = (sh_ > 0) & (cv2.dilate(ink, k3) == 0)
                if band.sum() < 0.12 * ink.sum():
                    break
                v = patch[band]
                if abs(float(v.mean()) - bgv) < 22 or abs(float(v.mean()) - inkv) < 18 or float(v.std()) > 30:
                    break
                depth = d
            opp = np.roll(np.roll(ink, -oy * 2, 0), -ox * 2, 1)
            ob = (opp > 0) & (cv2.dilate(ink, k3) == 0)
            if depth >= 2 and ob.sum() > 5 and abs(float(patch[ob].mean()) - bgv) < 20 and depth > best:
                best, ext, edir = depth, depth, name                 # (the other side is plain background: one-sided, so not an outline or a glow)
        scale_ = G.shape[0]
        x["dim"] = {"mode": "3d" if (abs(persp) > 0.12 or ext >= 2 or abs(tilt) > 6) else "2d", "tilt": round(tilt, 1), "perspective": round(persp, 2),
                    "extrude": round(ext / scale_, 4), "extrude_dir": edir}
        n3 += x["dim"]["mode"] == "3d"
    return n3


def _tpl_text_weight(path, dur, text, job):
    """Pass 12, the numbers behind the style: stroke weight, exact size, and how wide the outline / how far the shadow / how big the glow is."""
    import cv2
    import numpy as np
    want = {int(round(min(x["t1"] - 0.1, x["t0"] + max(0.5, (x["t1"] - x["t0"]) / 2)) * TPL_FPS)) for x in text}
    hi = _tpl_grab(path, dur, want, job)
    for x in text:
        G = hi.get(int(round(min(x["t1"] - 0.1, x["t0"] + max(0.5, (x["t1"] - x["t0"]) / 2)) * TPL_FPS)))
        got = _tpl_text_ink(G, x) if G is not None else None
        x["size"] = round(x.get("line_height", x.get("height", 0.05)), 4)             # cap height as a part of the frame's height
        if not got:
            continue
        ink, patch, light = got
        H = G.shape[0]
        dist = cv2.distanceTransform(ink, cv2.DIST_L2, 3)
        cap = max(4.0, float(x.get("line_height", x.get("height", 0.05)) * H))
        stroke = 2.0 * float(np.percentile(dist[ink > 0], 80)) if (ink > 0).any() else 0.0
        ratio = stroke / cap
        x["stroke"] = round(ratio, 3)
        x["weight"] = 900 if ratio > 0.2 else 700 if ratio > 0.135 else 500 if ratio > 0.095 else 400 if ratio > 0.06 else 300
        x["bold"] = bool(ratio > 0.135)
        st = x.get("style", "plain")
        ring = lambda r0, r1: (cv2.dilate(ink, np.ones((2 * r1 + 1, 2 * r1 + 1), np.uint8)) > 0) & (cv2.dilate(ink, np.ones((2 * r0 + 1, 2 * r0 + 1), np.uint8)) == 0)
        far_m = ring(max(3, int(cap * 0.6)), max(5, int(cap * 0.9)))
        bg = float(np.median(patch[far_m])) if far_m.any() else float(np.median(patch))
        inkv = float(patch[ink > 0].mean())
        prof = []
        for r in range(1, max(4, int(cap * 0.6))):
            m_ = ring(r - 1, r)
            if not m_.any():
                break
            prof.append(float(patch[m_].mean()))
        if st == "outline" and prof:
            wpx = next((r for r, v in enumerate(prof) if abs(v - bg) < 0.4 * abs(prof[0] - bg) + 2), len(prof))
            x["outline"] = {"width": round(max(1, wpx) / H, 4), "color": "#000000" if prof[0] < bg else "#ffffff"}
        if st == "glow" and prof:
            half = next((r for r, v in enumerate(prof) if (v - bg) < 0.5 * (prof[0] - bg)), len(prof))
            x["glow"] = {"size": round(max(1, half) * 2.2 / H, 4), "strength": round(float(np.clip((prof[0] - bg) / max(8.0, inkv - bg), 0, 1)), 2)}
        if st == "shadow":
            best = (0, 0, 0.0)
            dark = (patch < bg - 14).astype(np.float32)
            for oy in range(-1, max(3, int(cap * 0.4)) + 1):
                for ox in range(-max(2, int(cap * 0.25)), max(2, int(cap * 0.25)) + 1):
                    if ox == 0 and oy == 0:
                        continue
                    s_ = float((np.roll(np.roll(ink, oy, 0), ox, 1) * dark * (1 - ink)).sum())
                    if s_ > best[2]:
                        best = (ox, oy, s_)
            x["shadow"] = {"x": round(best[0] / H, 4), "y": round(best[1] / H, 4), "strength": round(float(np.clip((bg - float(np.percentile(patch, 3))) / 120.0, 0.2, 1)), 2)}


def _tpl_text_out(path, dur, text, job):
    """Pass 13, the way out: watch every text over its last half second. Does it thin out evenly (fade), slide away, or is
    it simply gone with a cut (none)? (A scatter of the letters is measured separately, with optical flow.)"""
    import numpy as np
    want = set()
    for x in text:
        f1 = int(round(x["t1"] * TPL_FPS))
        x["_oseq"] = [f1 + d for d in range(-14, 3, 2)]
        want.update(q for q in x["_oseq"] if q >= 0)
    hi = _tpl_grab(path, dur, want, job)
    for x in text:
        seq = x.pop("_oseq")
        ser = []
        for q in seq:
            G = hi.get(q)
            if G is None:
                continue
            H, W = G.shape
            bw, bh = max(8, int(x.get("width", 0.3) * W)), max(5, int(x.get("height", 0.05) * H * max(1, x.get("lines", 1))))
            cx, cy = int(x["x"] * W), int(x["y"] * H)
            x0, x1, y0, y1 = max(0, cx - bw // 2), min(W, cx + bw // 2), max(0, cy - bh), min(H, cy + bh)
            reg = G[y0:y1, x0:x1].astype(np.float32)
            if reg.size < 40:
                continue
            on = reg > max(150.0, float(np.percentile(reg, 99)) * 0.72)
            rows = np.nonzero(on.any(axis=1))[0]
            ser.append((q, float(on.mean()), float(rows.mean() / max(1, reg.shape[0])) if len(rows) else -1.0, float(np.percentile(reg, 98))))
        cur = (x.get("anim") or {}).get("out")
        if len(ser) >= 5 and cur != "scatterout":
            full = max(1e-4, float(np.median([v[1] for v in ser[:3]])))
            tail = [v for v in ser if v[0] <= int(round(x["t1"] * TPL_FPS))]
            part = [v for v in tail[-5:] if 0.12 * full < v[1] < 0.8 * full]
            drift = [v[2] for v in tail[-5:] if v[2] >= 0]
            moved = (drift[-1] - drift[0]) if len(drift) >= 2 else 0.0
            dim = (tail[-1][3] < 0.8 * tail[0][3]) if len(tail) >= 2 else False
            if len(part) >= 2 and moved > 0.12:
                cur = "slidedown"
            elif len(part) >= 2 or (dim and len(tail) >= 3 and tail[-2][3] < 0.92 * tail[0][3]):
                cur = "fadeout"
            else:
                cur = "none"
            x.setdefault("anim", {})["out"] = cur
            x["out_rule"] = "measured"


def _tpl_text_presence(path, dur, text, job):
    """Pass 14, for every text: is it really there for as long as the earlier passes say? Its box is compared (letter edges)
    at eight moments of its life with the moment it was read best. Its times are pulled in to the stretch where it is
    really there; a text that is only there for a sliver of its claimed life was a misreading and goes. -> (trimmed, removed)"""
    import cv2
    import numpy as np
    plan, want = [], set()
    for x in text:
        f0, f1 = int(round(x["t0"] * TPL_FPS)), int(round(x["t1"] * TPL_FPS)) - 1
        if f1 - f0 < 24 or x.get("watermark") or (x.get("anim") or {}).get("out") == "scatterout" or (x.get("anim") or {}).get("in") == "typewriter":
            plan.append(None)                             # (a scatter and a type-on change the letters: their looks are meant to differ over time)
            continue
        fs = sorted(set(int(round(f0 + (f1 - f0) * q)) for q in (0.04, 0.17, 0.3, 0.43, 0.5, 0.57, 0.7, 0.83, 0.96)))
        mid = int(round(min(x["t1"] - 0.1, x["t0"] + max(0.6, (x["t1"] - x["t0"]) / 2)) * TPL_FPS))
        plan.append((fs, mid))
        want.update(fs)
        want.add(mid)
    hi = _tpl_grab(path, dur, want, job)
    trimmed, out = 0, []

    def edges(G, x):
        H, W = G.shape
        bw, bh = x.get("width", 0.3) * W, x.get("height", 0.05) * H * max(1, x.get("lines", 1)) * 1.3
        x0, x1, y0, y1 = int(max(0, x["x"] * W - bw / 2 - 3)), int(min(W, x["x"] * W + bw / 2 + 3)), int(max(0, x["y"] * H - bh / 2 - 3)), int(min(H, x["y"] * H + bh / 2 + 3))
        if x1 - x0 < 8 or y1 - y0 < 6:
            return None
        p = G[y0:y1, x0:x1].astype(np.float32)
        return cv2.GaussianBlur(cv2.magnitude(cv2.Sobel(p, cv2.CV_32F, 1, 0), cv2.Sobel(p, cv2.CV_32F, 0, 1)), (0, 0), 2.0)
    for x, pl in zip(text, plan):
        if pl is None or hi.get(pl[1]) is None:
            out.append(x)
            continue
        fs, mid = pl
        ref = edges(hi[pl[1]], x)
        if ref is None or float(ref.std()) < 2.0:
            out.append(x)
            continue
        here = []
        for f in fs:
            e = edges(hi[f], x) if hi.get(f) is not None else None
            if x.get("caption"):                            # a caption changes its words: ask only whether letters are there at all
                here.append(e is not None and e.shape == ref.shape and (_tpl_ncc(ref, e) >= 0.3 or (float(e.mean()) >= 0.45 * float(ref.mean()) and float(e.std()) >= 0.45 * float(ref.std()))))
                continue
            here.append(e is not None and e.shape == ref.shape and _tpl_ncc(ref, e) >= 0.3)
        k = min(range(len(fs)), key=lambda q: abs(fs[q] - mid))
        if not here[k]:
            here[k] = True
        a = b = k
        while a > 0 and here[a - 1]:
            a -= 1
        while b < len(fs) - 1 and here[b + 1]:
            b += 1
        life = x["t1"] - x["t0"]
        if (b - a + 1) <= 2 and life > 3.0 and sum(here) <= 3:
            continue                                        # there for a sliver of what was claimed: a misreading
        cut_a, cut_b = a > 1 and not any(here[:a]), b < len(fs) - 2 and not any(here[b + 1:])      # (only when it is clearly gone on that side: two or more moments, none of them a match)
        if x.get("caption"):                                # a caption with moments where no letters are there at all: it lives in the unbroken stretch round its best reading
            cut_a, cut_b = a > 0, b < len(fs) - 1
        if cut_a:
            x["t0"] = round((fs[a - 1] + fs[a]) / 2 / TPL_FPS, 4)
        if cut_b:
            x["t1"] = round((fs[b] + fs[b + 1]) / 2 / TPL_FPS, 4)
        trimmed += cut_a or cut_b
        out.append(x)
    removed = len(text) - len(out)
    text[:] = out
    return trimmed, removed


def _tpl_audit(tpl_events, pulses, overlays, text, n, frames, sc):
    """Pass 14: one more walk over everything that was found, looking for what does not fit together.
    -> (events, pulses, overlays, text, report)"""
    import numpy as np
    rep = {"cuts_added": 0, "cuts_merged": 0, "thumps_removed": 0, "overlays_fixed": 0, "texts_fixed": 0, "texts_removed": 0}
    ev = sorted(tpl_events, key=lambda e: e[0])
    out = []
    for e in ev:                                          # two cuts closer than 3 frames are one; none on the first or last frames
        if e[0] < 2 or e[0] > n - 2:
            rep["cuts_merged"] += 1
            continue
        if out and e[0] - out[-1][0] < 3:
            rep["cuts_merged"] += 1
            if e[3].get("type", "none") != "none" and out[-1][3].get("type", "none") == "none":
                out[-1] = e
            continue
        out.append(e)
    # a shot that changes completely somewhere with no cut on record: a cut was missed
    marks = [0] + [int(e[0]) for e in out] + [n - 1]
    fd = lambda p, q: float(np.abs(frames[p].astype(np.int16) - frames[q].astype(np.int16)).mean())
    add = []
    for g0, g1 in zip(marks[:-1], marks[1:]):
        if g1 - g0 < 16:
            continue
        i = g0 + 5 + int(np.argmax(sc[g0 + 5:g1 - 5])) if g1 - g0 > 12 else None
        if i is None:
            continue
        before, after = fd(max(g0 + 1, i - 6), max(g0 + 1, i - 2)), fd(min(g1 - 1, i + 2), min(g1 - 1, i + 6))
        across = fd(max(g0 + 1, i - 3), min(g1 - 1, i + 3))
        if across > 38 and across > 3.2 * max(before, after, 4.0) and sc[i] > 3.5 * max(1.0, float(np.median(sc[g0 + 1:g1]))) and sc[i] > 14:
            add.append((i, i, i, {"type": "none", "frames": 0, "ease": "snappy", "confidence": 0.9, "audit": True}))
    if add:
        rep["cuts_added"] = len(add)
        out = sorted(out + add, key=lambda e: e[0])
    cutf = [int(e[0]) for e in out]
    win = [(int(e[1]) - 1, int(e[2]) + 1) for e in out]
    keep = []
    for p in pulses:                                      # a thump on a cut, or inside a transition, is that cut's own motion
        f = int(round(p["t"] * TPL_FPS))
        if any(abs(f - c) <= 1 for c in cutf) or any(a <= f <= b for a, b in win if b - a > 2):
            rep["thumps_removed"] += 1
            continue
        if keep and f - int(round(keep[-1]["t"] * TPL_FPS)) < 3:
            rep["thumps_removed"] += 1
            continue
        keep.append(p)
    total = n / TPL_FPS
    for o in overlays:
        t0, t1 = max(0.0, min(total, o["t0"])), max(0.0, min(total, o["t1"]))
        if t1 - t0 < 0.1:
            t1 = min(total, t0 + 0.2)
        if (t0, t1) != (o["t0"], o["t1"]):
            rep["overlays_fixed"] += 1
        o["t0"], o["t1"] = round(t0, 4), round(t1, 4)
    good = []
    for x in text or []:
        t0, t1 = max(0.0, min(total, x["t0"])), max(0.0, min(total, x["t1"]))
        if not str(x.get("text", "")).strip() or t0 >= total - 0.05:
            rep["texts_removed"] += 1
            continue
        if t1 - t0 < 0.2:
            t1 = min(total, t0 + 0.2)
        if (round(t0, 4), round(t1, 4)) != (round(x["t0"], 4), round(x["t1"], 4)):
            rep["texts_fixed"] += 1
        x["t0"], x["t1"] = round(t0, 4), round(t1, 4)
        x["x"], x["y"] = round(min(1.0, max(0.0, x.get("x", 0.5))), 4), round(min(1.0, max(0.0, x.get("y", 0.5))), 4)
        good.append(x)
    return out, keep, overlays, good, rep


def analyze_reference(path, name, job):
    """Reference video -> template dict."""
    import cv2
    import numpy as np
    pr = probe(path)
    vs = next((x for x in pr.get("streams", []) if x.get("codec_type") == "video"), None)
    if not vs or not vs.get("width"):
        raise RuntimeError("That file has no video in it.")
    rot = abs(int(float(((vs.get("side_data_list") or [{}])[0]).get("rotation", 0) or 0))) % 180 == 90
    info = {"width": int(vs["height"] if rot else vs["width"]), "height": int(vs["width"] if rot else vs["height"]),
            "duration": float(pr.get("format", {}).get("duration") or vs.get("duration") or 0)}
    if info["duration"] <= 0.2:
        raise RuntimeError("That video is too short to analyze.")
    dur = min(float(info["duration"]), TPL_MAX_SEC)
    _tp(job, 0)
    dict.update(job, npass=0, stage="Preparing: reading every frame of the video", detail="", span=(0, 24), pct=0)
    frames, w, h = _tpl_read_frames(path, dict(info, duration=dur), job)
    n = len(frames)
    R = {}                                              # what every pass found, for the report

    # ================================================================ PASS 1: cuts (hard cuts + scene changes), nothing else
    _tp(job, 1, (26, 54))
    sc, luma = _tpl_scores(frames)
    hard = _tpl_hard_cuts(sc)
    engine = "kiru (adaptive content detector)"
    psd = _tpl_psd_cuts(path, dur) if job.get("use_psd", True) else None
    if psd is not None:
        engine = "PySceneDetect AdaptiveDetector + kiru"
        ours = set(hard)
        for c in psd:                                  # add cuts PySceneDetect saw that we missed (never drop ours)
            if 0 < c < n and not any(abs(c - o) <= 2 for o in ours) and sc[max(1, c - 1):c + 2].max() >= 10:
                ours.add(int(max(1, c - 1) + int(np.argmax(sc[max(1, c - 1):c + 2]))))
        hard = sorted(ours)
    job.update(stage="Measuring the motion")
    gray = np.empty((n, h, w), np.float32)
    for i in range(n):
        gray[i] = cv2.cvtColor(frames[i], cv2.COLOR_BGR2GRAY)
    win = cv2.createHanningWindow((w, h), cv2.CV_32F)
    # busy runs: several frames in a row that all change a lot = something is moving the whole picture
    med = float(np.median(sc[1:])) if n > 2 else 0.0
    thr = max(7.0, 3.0 * med)
    runs = _tpl_runs(sc, thr)
    events = []                                         # (frame of the cut, a, b, info)
    used = set()
    fdiff = lambda p, q: float(np.abs(frames[p].astype(np.int16) - frames[q].astype(np.int16)).mean())
    for ri, (a, b) in enumerate(runs):
        if job.get("cancel"):
            raise Cancelled()
        job.update(pct=34 + int(16 * ri / max(1, len(runs))))
        inside = [c for c in hard if a - 1 <= c <= b + 1]
        changed = fdiff(max(0, a - 2), min(n - 1, b + 2)) > 14
        if not inside and not changed:
            continue                                    # a fast move inside one shot, not a transition
        if b - a + 1 > 34:
            continue                                    # longer than any transition: an action shot
        if b - a + 1 <= 2 and inside:
            continue                                    # just the cut itself (handled below as a plain cut)
        tinfo = _tpl_classify(frames, gray, sc, luma, a, b, set(inside), win)
        if tinfo["type"] == "none" and not inside:
            if changed and b - a + 1 >= 3:               # the picture changed under a smear: a cut hidden in a blur
                events.append(((a + b + 1) // 2, a, b, {"type": "bflash", "frames": int(max(4, min(16, (b - a + 1) // 2 * 2))), "ease": "linear", "confidence": 0.5, "soft_cut": True}))
            continue
        if tinfo["type"] == "none":
            continue                                    # a hard cut with busy frames round it: still a plain cut
        events.append(((a + b + 1) // 2, a, b, tinfo))
        used.update(inside)
    for c in hard:
        if c in used:
            continue
        tinfo = {"type": "none", "frames": 0, "ease": "snappy", "confidence": 0.9}
        lum = luma[max(0, c - 1):c + 3]
        if len(lum) and float(lum.max()) > 215 and float(lum.max()) - float(luma[max(0, c - 3)]) > 45 and float(lum.max()) - float(luma[min(n - 1, c + 5)]) > 35:
            tinfo["flash"] = True
        events.append((c, c, c, tinfo))
    busy = np.zeros(n, bool)
    for c, a, b, _ in events:
        busy[max(0, a - 3):min(n, b + 4)] = True
    job.update(stage="Looking for dissolves")
    for a, b in _tpl_dissolves(frames, sc, busy):
        events.append(((a + b + 1) // 2, a, b, {"type": "fade", "frames": max(2, (b - a + 1) // 2 * 2), "ease": "linear", "confidence": 0.7}))
    events.sort(key=lambda e: e[0])
    merged = []
    for e in events:                                    # two events on (almost) the same frame are one cut
        if merged and e[0] - merged[-1][0] < 3:
            if e[3]["type"] != "none" and merged[-1][3]["type"] == "none":
                merged[-1] = e
            continue
        if e[0] < 2 or e[0] > n - 2:
            continue
        merged.append(e)
    events = merged
    job.update(stage="Looking for scene changes hidden in long blurs and shakes")
    try:
        events = sorted(events + _tpl_gradual(frames, gray, luma, events, n), key=lambda e: e[0])
    except Exception:
        pass
    job.update(stage="Double-checking every cut (same shot or a new one?)")
    found_cuts = len(events)
    try:
        protect = _tpl_backdrop_ranges(frames, events, n)
    except Exception:
        protect = ()
    events, jolts = _tpl_verify(path, dur, events, n, luma, job, protect, frames)
    busy = np.zeros(n, bool)
    for c, a, b, _ in events:
        busy[max(0, a - 3):min(n, b + 4)] = True
    events0 = list(events)
    busy0 = busy.copy()
    job.update(stage="Looking for cut-outs on a backdrop (what is an overlay and what is the picture)")
    try:
        events, scenes = _tpl_backdrop_scenes(frames, events, n)
    except Exception:
        scenes = {}
    # the 3D / shape / motion-graphic transitions; anything gradual that still is not recognised for sure goes to the Transition Matcher
    # (a slow wipe changes only a little per frame, so the busy-run search above can miss it: look once more inside every long shot)
    marks = [0] + sorted(int(e[0]) for e in events) + [n - 1]
    for g0, g1 in zip(marks[:-1], marks[1:]):
        if g1 - g0 < 26:
            continue
        s0, s1 = g0 + 4, g1 - 4 - 14
        if s1 <= s0:
            continue
        i = max(range(s0, s1 + 1), key=lambda q: float(sc[q:q + 14].sum()))
        if float(sc[i:i + 14].sum()) > 12 and fdiff(max(0, i - 2), min(n - 1, i + 16)) > 20:
            try:
                nt = _tpl_new_types(frames, i + 7, i, i + 13, n, (g0 + 2, g1 - 2))
            except Exception:
                nt = None
            if nt and nt["confidence"] >= 0.7:
                events.append((i + 7, i, i + 13, {"type": "fade", "frames": nt["frames"], "ease": "smooth", "confidence": 0.4}))    # (what it looks like is suggested below, and you confirm it)

    events.sort(key=lambda e: e[0])
    R["cuts"] = [round(e[0] / TPL_FPS, 4) for e in events]
    _tfound(job, f"{len(events)} cuts ({found_cuts - len(events0)} that only looked like cuts were dropped)")

    # ================================================================ PASS 2: thumps inside the shots
    _tp(job, 2)
    # thumps: a quick zoom-in that settles back inside one shot, or a white pop
    pulses = []
    bounds = [0] + [e[0] for e in events0] + [n]
    for si in range(len(bounds) - 1):
        a, b = bounds[si] + 3, bounds[si + 1] - 3
        if b - a < 8 or busy0[a:b].mean() > 0.5:
            continue
        i = a
        while i < b - 3:
            if sc[i] > max(4.0, 2.2 * med) and not busy0[i]:
                _, _, z, _, _, c2 = _tpl_motion(gray[i - 1], gray[i], win)
                if z > 1.02:
                    back = sum(np.log(max(1e-3, _tpl_motion(gray[q - 1], gray[q], win)[2])) for q in range(i + 1, min(b, i + 8)))
                    if back < -0.4 * np.log(z):
                        pulses.append({"t": round(i / TPL_FPS, 4), "kind": "zoom", "strength": int(max(40, min(200, (z - 1) / 0.07 * 100)))})
                        i += 6
                        continue
                if luma[i] - luma[i - 1] > 45 and luma[i] > 200 and i + 3 < n and luma[i + 3] < luma[i] - 30:
                    pulses.append({"t": round(i / TPL_FPS, 4), "kind": "flicker", "strength": 100})
                    i += 5
                    continue
            i += 1
    for j_ in jolts:                                    # the jolts the double-check found (they looked like cuts)
        if not any(abs(j_["t"] - p_["t"]) < 2.5 / TPL_FPS for p_ in pulses):
            pulses.append(j_)
    pulses.sort(key=lambda p_: p_["t"])
    job.update(stage="Measuring every shot (push-ins, zoom punches, speed ramps)")
    try:
        motion = _tpl_shot_motion(path, dur, events, n, sc, pulses, job)
    except Cancelled:
        raise
    except Exception:
        motion = {}
    R["thumps"] = [p_["t"] for p_ in pulses]
    _tfound(job, f"{len(pulses)} thumps, {sum(1 for m_ in motion.values() if m_.get('kb'))} slow push-ins, {sum(1 for m_ in motion.values() if m_.get('ramp'))} speed ramps")

    # ================================================================ PASS 3: the dominant motion at every cut
    _tp(job, 3)
    series = []
    for k_e, (c_e, a_e, b_e, ti_e) in enumerate(events):
        if job.get("cancel"):
            raise Cancelled()
        job.update(detail=f"cut {k_e + 1} of {len(events)}")
        ti_e = dict(ti_e)
        if b_e - a_e + 1 >= 3 and not ti_e.get("soft_cut") and ti_e.get("type") in ("none", "left", "right", "up", "down", "zoomin", "zoomout", "spin"):
            try:                                        # look at this cut again, on its own
                again = _tpl_classify(frames, gray, sc, luma, a_e, b_e, {int(c_e)}, win)
                if again.get("type") != "none" and again.get("confidence", 0) > ti_e.get("confidence", 0):
                    ti_e = dict(again)
            except Exception:
                pass
        try:
            se = _tpl_series(gray, luma, a_e, b_e, n, win, cut=int(c_e))
        except Exception:
            se = {"a": int(a_e), "b": int(b_e), "jump": None, "dx": [0.0], "dy": [0.0], "lz": [0.0], "rot": [0.0], "expl": [0.0], "lum": [float(luma[int(c_e)])], "lum0": float(luma[int(c_e)]), "lum1": float(luma[int(c_e)]), "sharp": [1.0]}
        series.append(se)
        tx_, ty_, tz_, tr_ = float(np.sum(se["dx"])), float(np.sum(se["dy"])), float(np.sum(se["lz"])), float(np.sum(se["rot"]))
        if ti_e.get("type") == "none" and not ti_e.get("soft_cut") and b_e - a_e + 1 >= 3:      # nothing was named, but the camera moves through this cut
            if max(abs(tx_), abs(ty_)) >= 0.3:
                ti_e.update(type=("left" if tx_ < 0 else "right") if abs(tx_) >= abs(ty_) else ("up" if ty_ < 0 else "down"), frames=int(max(2, min(30, (b_e - a_e + 1) // 2 * 2))), ease="snappy", confidence=0.6)
            elif abs(tz_) >= 0.15:
                ti_e.update(type="zoomin" if tz_ > 0 else "zoomout", frames=int(max(2, min(30, (b_e - a_e + 1) // 2 * 2))), ease="snappy", confidence=0.6)
        dom = max((("slide", max(abs(tx_), abs(ty_)) / 0.45), ("zoom", abs(tz_) / 0.22), ("spin", abs(tr_) / 22.0)), key=lambda v: v[1])
        ti_e["dominant"] = ({"fade": "dissolve", "dip": "dip to black", "flashw": "flash", "bflash": "blur flash"}.get(ti_e.get("type")) or
                            ("wipe" if ti_e.get("type") in ("wipel", "wiper", "circle", "star", "diamond", "radial") else None) or (dom[0] if dom[1] >= 0.18 else "cut"))
        events[k_e] = (c_e, a_e, b_e, ti_e)
    for i_, m_ in motion.items():                       # a hard cut that lands from a zoom is a Zoom Punch
        if m_.get("punch") and 1 <= i_ <= len(events) and events[i_ - 1][3]["type"] == "none":
            events[i_ - 1] = (events[i_ - 1][0], events[i_ - 1][1], events[i_ - 1][2], dict(events[i_ - 1][3], type="punch", frames=6, ease="punchy", confidence=0.7, dominant="zoom"))
    _h3 = {}
    for e in events:
        _h3[e[3]["dominant"]] = _h3.get(e[3]["dominant"], 0) + 1
    _tfound(job, ", ".join(f"{v} {k}" for k, v in sorted(_h3.items(), key=lambda kv: -kv[1])) or "no cuts")

    # ================================================================ PASS 4: several motions at once
    _tp(job, 4)
    n_comp = 0
    for k_e, (c_e, a_e, b_e, ti_e) in enumerate(events):
        if job.get("cancel"):
            raise Cancelled()
        if ti_e["type"] == "bflash":
            try:
                events[k_e] = (c_e, a_e, b_e, dict(ti_e, fx=_tpl_trans_profile(frames, gray, luma, a_e, b_e, n, win),
                                                    frames=int(max(4, min(16, (b_e - a_e + 1 + 1) // 2 * 2)))))
            except Exception:
                pass
    for k_e, (c_e, a_e, b_e, ti_e) in enumerate(events):
        ti_e = dict(ti_e)
        ti_e["stack"] = _tpl_stack(ti_e, series[k_e])
        if any(p_["kind"] == "flash" for p_ in ti_e["stack"]) and ti_e.get("type") not in ("flashw", "bflash"):
            ti_e["flash"] = True                        # a flash stacked on the motion
        ti_e["compound"] = len([p_ for p_ in ti_e["stack"] if p_["kind"] in ("slide", "zoom", "spin")]) >= 2 or (len(ti_e["stack"]) >= 3)
        n_comp += bool(ti_e["compound"])
        events[k_e] = (c_e, a_e, b_e, ti_e)
    _tfound(job, f"{n_comp} compound transitions (two or more things at once), {sum(1 for e in events if e[3].get('flash'))} with a flash on top")

    # ================================================================ PASS 5: every transition against the measured optical flow
    _tp(job, 5)
    ev2 = []
    efr = [int(e[0]) for e in events]
    for ei, (f_, a_, b_, ti_) in enumerate(events):
        ti_ = dict(ti_)
        lim_ = ((efr[ei - 1] + int(f_)) // 2 + 1 if ei else 1, (efr[ei + 1] + int(f_)) // 2 - 1 if ei + 1 < len(efr) else n - 2)
        try:
            nt = _tpl_new_types(frames, int(f_), int(a_), int(b_), n, lim_)
        except Exception:
            nt = None
        gradual = int(b_) - int(a_) + 1 >= 3
        # A new look never replaces what the analyzer already found by itself: it becomes a suggestion ("alt") that the
        # Transition Matcher shows you, and only your Yes puts it into the template. (Flashes fool the star / sparkle tests.)
        if nt and nt["confidence"] >= 0.7 and nt["type"] != ti_.get("type") and not (ti_.get("type") in ("bflash", "flashw", "dip") and nt["type"] in ("star", "mgstar", "mgspark", "mgleak")):
            ti_["alt"] = {"type": nt["type"], "frames": nt["frames"], "confidence": nt["confidence"]}
        guess_ = float(ti_.get("confidence", 0.9))
        conf_, tot_, wt_ = _tpl_confidence(ti_, series[ei], frames)
        if ti_.get("alt"):
            conf_ = min(conf_, 0.8)                     # two detectors disagree about what this is
        if gradual and ti_.get("type") != "none" and guess_ < 0.6:
            conf_ = min(conf_, max(0.3, guess_ + 0.2))
        ti_["guess"] = round(guess_, 2)
        ti_["confidence"] = conf_
        ti_["flow"] = {k_: round(float(v_), 4) for k_, v_ in tot_.items()}
        if conf_ < TPL_CONF_MIN:
            ti_["unsure"] = True                        # -> the Interactive Matcher shows it
            ms_ = _tpl_measured(ti_, series[ei], int(f_), tot_, wt_)
            if not ms_ and ti_.get("type") not in ("none", "bflash") and int(b_) - int(a_) + 1 >= 3:
                # nothing moves in the measurement, so a preset that moves would be a guess. What WAS measured decides:
                # a soft / bright stretch -> a Blur flash carrying the measured blur and white; a mix of both shots -> a dissolve of the measured length; else a cut
                kinds_ = {p_["kind"] for p_ in ti_.get("stack", [])}
                ti_["preset"] = ti_.get("type")
                ti_["custom"] = f"Measured (cut {ei + 1})"
                if kinds_ & {"blur", "flash"}:
                    try:
                        ti_.update(type="bflash", fx=dict(_tpl_trans_profile(frames, gray, luma, int(a_), int(b_), n, win), zoom=0, spin=0), frames=int(max(4, min(16, (int(b_) - int(a_) + 2) // 2 * 2))))
                    except Exception:
                        ti_.update(type="fade", frames=int(max(2, min(30, (int(b_) - int(a_) + 1) // 2 * 2))))
                elif "dip" in kinds_:
                    ti_.update(type="dip", frames=int(max(2, min(30, (int(b_) - int(a_) + 1) // 2 * 2))))
                elif "blend" in kinds_ or ti_["preset"] == "fade":
                    ti_.update(type="fade", frames=int(max(2, min(30, (int(b_) - int(a_) + 1) // 2 * 2))))
                else:
                    ti_.update(type="none", frames=0)
                    ti_.pop("custom", None)
            if ms_:                                     # the No Preset rule: built from the measured motion, not from the nearest preset
                ti_["preset"] = ti_.get("type")
                ti_["measured"] = ms_
                ti_["custom"] = f"Measured motion (cut {ei + 1})"
                ti_["type"] = "bflash" if (ti_.get("type") == "bflash" and ti_.get("fx")) else ms_["base"]
                if ti_["type"] == "bflash":
                    ti_["fx"] = dict(ti_["fx"], zoom=0, spin=0)      # (the move itself is in the measured lists now)
                else:
                    ti_["frames"] = ms_["frames"]
            if gradual or ti_.get("alt"):
                ti_["ref"] = _tpl_thumbs(frames, int(a_), int(b_), n)
        ev2.append((f_, a_, b_, ti_))
    events = ev2
    n_low = sum(1 for e in events if e[3].get("unsure"))
    n_ms = sum(1 for e in events if e[3].get("measured"))
    R["confidence"] = [e[3].get("confidence") for e in events]
    _tfound(job, f"{len(events) - n_low} of {len(events)} verified at 90% or more; {n_low} flagged for the Transition Matcher, {n_ms} of them rebuilt from their measured motion")

    # ================================================================ PASS 6: overlays
    _tp(job, 6)
    overlays = _tpl_overlays(gray, events0, n)
    _tfound(job, f"{len(overlays)} overlays" + (f", {sum(len(v_['overlays']) for v_ in scenes.values())} cut-outs on a backdrop" if scenes else ""))

    # ================================================================ PASS 7: overlapping overlays
    _tp(job, 7)
    extra_ = []
    for o_ in overlays:
        if job.get("cancel"):
            raise Cancelled()
        try:
            o2_ = _tpl_overlay_split(gray, o_, n)
        except Exception:
            o2_ = None
        if o2_:
            extra_.append(o2_)
    overlays = sorted(overlays + extra_, key=lambda o_: o_["t0"])
    n_grp = _tpl_overlay_layers(overlays)
    _tfound(job, f"{len(extra_)} second layers found inside an overlay; {n_grp} overlays share the screen with another one (each is its own layer)")

    # ================================================================ PASS 8: each overlay along its path
    _tp(job, 8)
    n_path = n_short = 0
    for o_ in overlays:
        if job.get("cancel"):
            raise Cancelled()
        try:
            path_, last_, sure_ = _tpl_overlay_track(gray, o_, n)
        except Exception:
            path_, last_, sure_ = None, None, 0.0
        o_["tracked"] = round(sure_, 2)
        if path_:
            o_["path"] = path_
            n_path += 1
        if last_ is not None and sure_ >= 0.6 and (last_ + 2) / TPL_FPS < o_["t1"] - 0.2 and (last_ + 2) / TPL_FPS > o_["t0"] + 0.2:
            o_["t1"] = round((last_ + 2) / TPL_FPS, 4)  # it left earlier than the shot did
            n_short += 1
    _tfound(job, f"{n_path} overlays move (their path is recorded), {n_short} end before their shot does, {len(overlays) - n_path} stand still")

    # ================================================================ PASS 9: text (what, where, when)
    _tp(job, 9, (62, 92))
    text = _tpl_text(path, info, dur, job) if job.get("use_ocr", True) else None
    if text is not None:
        text = _tpl_text_merge(text, dur)
    _tfound(job, f"{len(text)} texts" if text is not None else "text reading is switched off (or Tesseract is not installed)")

    # ================================================================ PASS 10: several texts
    _tp(job, 10)
    if text is not None:
        try:
            _tpl_text_refine(path, dur, text, job)
            if scenes:
                bnds = sorted([0] + [e[0] for e in events] + [n])
                text += _tpl_backdrop_words(path, dur, frames, scenes, lambda f0: next((b_ for b_ in bnds if b_ > f0), n), text, job)
                text.sort(key=lambda x: x["t0"])
        except Cancelled:
            raise
        except Exception:
            pass
        cut_t = sorted({round(e[0] / TPL_FPS, 4) for e in events} | {0.0, round(dur, 4)})
        for x_ in text:                                   # text nearly always comes and goes ON a cut: move its times onto the cut next to them
            for key_ in ("t0", "t1"):
                near_ = min(cut_t, key=lambda c_: abs(c_ - x_[key_]))
                if abs(near_ - x_[key_]) <= 0.24:
                    x_[key_] = near_
            if x_["t1"] - x_["t0"] < 0.2:
                x_["t1"] = x_["t0"] + 0.2
        try:
            j10, o10 = _tpl_text_lines(text)
        except Exception:
            j10, o10 = 0, 0
        _tfound(job, f"{len(text)} text blocks: {sum(1 for x_ in text if x_.get('lines', 1) > 1)} with several lines ({j10} lines joined), {sum(1 for x_ in text if x_.get('caption'))} captions, {o10} overlapping")
    job["_bd_ranges"] = [(r_[0], r_[1]) for r_ in (protect or [])]

    # ================================================================ PASS 11: flat or 3D
    _tp(job, 11)
    if text:
        try:
            n3 = _tpl_text_3d(path, dur, text, job)
        except Cancelled:
            raise
        except Exception:
            n3 = 0
        _tfound(job, f"{n3} of {len(text)} texts have depth (tilt, perspective or an extruded side); the rest are flat")

    # ================================================================ PASS 12: text styles
    _tp(job, 12)
    if text:
        try:
            _tpl_text_style(path, dur, text, job, "style")
            _tpl_text_weight(path, dur, text, job)
        except Cancelled:
            raise
        except Exception:
            pass
        _st = {}
        for x_ in text:
            _st[x_.get("style", "plain")] = _st.get(x_.get("style", "plain"), 0) + 1
        _tfound(job, ", ".join(f"{v_} {k_}" for k_, v_ in _st.items()) + f"; {sum(1 for x_ in text if x_.get('bold'))} bold")

    # ================================================================ PASS 13: text animation
    _tp(job, 13)
    if text:
        try:
            _tpl_text_style(path, dur, text, job, "anim")
        except Cancelled:
            raise
        except Exception:
            pass
    if True:
        bd_ = job.get("_bd_ranges") or []
        src_fps_ = _fps_of(vs)
        cand_ = [x_ for x_ in (text or []) if not x_.get("caption") and not x_.get("watermark")
                 and len(re.sub(r"[^A-Za-z0-9]", "", x_["text"])) >= 4 and not any(a_ <= x_["t1"] * TPL_FPS <= b_ for a_, b_ in bd_)]
        cand_.sort(key=lambda x_: -x_.get("height", 0) * x_.get("width", 0))
        for x_ in cand_[:16]:
            try:
                sc_ = _tpl_text_scatter(path, x_, src_fps_, dur)
            except Exception:
                sc_ = None
            if sc_:
                x_.setdefault("anim", {})["out"] = "scatterout"
                x_["t1"] = round(max(x_["t1"], min(dur, sc_["t1"])), 4)
                x_["out_rule"] = "flow"
                x_["out_flow"] = sc_
    job.pop("_bd_ranges", None)
    if text:
        try:
            _tpl_text_out(path, dur, text, job)
        except Cancelled:
            raise
        except Exception:
            pass
        _an = {}
        for x_ in text:
            k_ = (x_.get("anim") or {}).get("in", "fade") + " in / " + (x_.get("anim") or {}).get("out", "none") + " out"
            _an[k_] = _an.get(k_, 0) + 1
        _tfound(job, ", ".join(f"{v_} x {k_}" for k_, v_ in sorted(_an.items(), key=lambda kv: -kv[1])[:5]))

    # ================================================================ PASS 14: the audit (and the things round the edit: music, colour, bars)
    _tp(job, 14)
    n_before = len(events)
    tp14 = (0, 0)
    if text:
        try:
            tp14 = _tpl_text_presence(path, dur, text, job)
        except Cancelled:
            raise
        except Exception:
            pass
    events, pulses, overlays, text_a, audit = _tpl_audit(events, pulses, overlays, text, n, frames, sc)
    audit["texts_fixed"] += tp14[0]
    audit["texts_removed"] += tp14[1]
    if text is not None:
        text = text_a
        cut_t14 = sorted({round(e[0] / TPL_FPS, 4) for e in events} | {0.0, round(dur, 4)})
        for x_ in text:                                   # (times that were pulled in land on the cut next to them)
            for key_ in ("t0", "t1"):
                near_ = min(cut_t14, key=lambda c_: abs(c_ - x_[key_]))
                if abs(near_ - x_[key_]) <= 0.2:
                    x_[key_] = near_
            if x_["t1"] - x_["t0"] < 0.2:
                x_["t1"] = x_["t0"] + 0.2
    if len(events) != n_before:                         # a cut came or went: the shots are counted again
        try:
            motion = _tpl_shot_motion(path, dur, events, n, sc, pulses, job)
        except Cancelled:
            raise
        except Exception:
            motion = {}
    job.update(stage="Listening to the music (beat, hits, soundtrack)")
    bpm, beats = _tpl_beats(path, dur)
    hits = _TPL_HITS.pop(path, [])
    has_audio = any(x.get("codec_type") == "audio" for x in pr.get("streams", []))
    aud = _tpl_audio(path, dur) if has_audio else None
    job.update(stage="Measuring the colour")
    look, stats = _tpl_look(frames, hard, n)
    look["glow"] = 0 if scenes else _tpl_glow(frames)
    segs = _tpl_look_segments(frames, events, n)
    look_segs = []
    if segs:                                            # e.g. a dark half and a bright, glowing half: each gets its own look
        for (fa, fb) in segs:
            lk_, _st = _tpl_look(frames[fa:fb], [], fb - fa)
            lk_["glow"] = _tpl_glow(frames[fa:fb])
            lk_["sharp"] = 35
            m_l = float(frames[fa:fb:3].mean())
            lk_["bright"] = int(max(-38, min(28, round((m_l - 112) / 255 * (135 if m_l < 112 else 70)))))    # (a crushed, moody grade sits far below an ordinary picture)
            dark_ = float((frames[fa:fb:3].max(axis=3) < 28).mean())      # crushed blacks = a hard, contrasty grade
            if dark_ > 0.2:
                lk_["contrast"] = int(max(lk_["contrast"], min(140, round(104 + dark_ * 70))))
                lk_["vig"] = max(lk_["vig"], 25)
            if any(fa <= f_ < fb for f_ in scenes):     # cut-outs on a backdrop: the white is the backdrop, not a grade
                lk_.update(glow=0, bright=0, contrast=min(lk_["contrast"], 108), vig=0, sat=max(lk_["sat"], 90))
            look_segs.append({"t0": round(fa / TPL_FPS, 4), "t1": round(fb / TPL_FPS, 4), "look": lk_,
                              "name": "Dark" if m_l < 85 else "Bright" if m_l > 150 else "Normal"})
    # The "4K / HD quality" filter cannot be measured from a re-encoded upload (compression eats the halos), and nearly
    # every edit of this kind uses it - so an analyzed template starts with a moderate sharpen the user can turn down.
    look["sharp"] = 35
    stats["sharp_assumed"] = True
    bars = _tpl_bars(frames, n)
    ratio = info["width"] / info["height"]
    if stats["letterbox"] > 0.12 and ratio > 1.5:
        ratio = ratio / (1 - stats["letterbox"])        # 16:9 with bars = a wider picture
    aspect = min(TPL_ASPECTS, key=lambda k: abs(np.log(TPL_ASPECTS[k] / ratio)))
    _tfound(job, f"{audit['cuts_added']} missed cuts added, {audit['cuts_merged']} doubles merged, {audit['thumps_removed']} thumps that were really a cut's own motion removed, "
                 f"{audit['texts_fixed'] + audit['overlays_fixed']} timings fixed, {audit['texts_removed']} empty texts removed")
    cuts = []
    times = [0.0] + [e[0] / TPL_FPS for e in events]
    total = n / TPL_FPS
    for k, t in enumerate(times):
        end = times[k + 1] if k + 1 < len(times) else total
        c = {"t": round(t, 4), "dur": round(end - t, 4)}
        if beats:
            bp = _beat_pos(t, beats)
            c["beat"] = round(bp, 3)
            c["beats"] = round(_beat_pos(end, beats) - bp, 3)
            c["on_beat"] = bool(abs(bp * 2 - round(bp * 2)) < 0.16)
        if k > 0:
            ti = dict(events[k - 1][3])
            ti["frames"] = int(min(30, ti.get("frames", 0)))
            c["transition"] = ti                         # the transition INTO this cut
        m_ = motion.get(k) or {}
        kk = {}
        if m_.get("kb"):                                 # slow push-in / pull-out over the shot
            kk["tf"] = {"zoom": 100, "x": 0, "y": 0, "kb": True, "dir": m_["kb"]["dir"], "amt": m_["kb"]["amt"], "lock": True, "zx": 100, "zy": 100}
            c["zoom"] = m_["kb"]
        if m_.get("ramp"):                               # speed ramp: the Kiru speed graph of this cut
            kk["curve"] = {"on": True, "v": m_["ramp"]["v"], "ease": True}
            c["ramp"] = m_["ramp"]["kind"]
        if kk:
            c["kiru"] = kk
        sc_ = scenes.get(int(round(t * TPL_FPS)))
        if sc_:                                          # a cut-out scene: the backdrop is the picture, the subject is an overlay spot
            c["backdrop"] = sc_["backdrop"]
            c["overlays"] = sc_["overlays"]
            c.pop("kiru", None)
        cuts.append(c)
    hist = {}
    for c in cuts[1:]:
        hist[c["transition"]["type"]] = hist.get(c["transition"]["type"], 0) + 1
    tr_frames = [c["transition"]["frames"] for c in cuts[1:] if c["transition"]["frames"]]
    eases = [c["transition"]["ease"] for c in cuts[1:] if c["transition"]["type"] in ("left", "right", "up", "down", "zoomin", "zoomout", "spin")
             and c["transition"]["ease"] in EASE_FEEL]
    tpl = {"kiru_template": TPL_VERSION, "name": os.path.splitext(name)[0][:60], "created": time.strftime("%Y-%m-%d %H:%M"),
           "source": {"kind": "analysis", "file": name, "duration": round(total, 3), "width": info["width"], "height": info["height"],
                      "engine": engine, "ocr": text is not None},
           "aspect": aspect, "duration": round(total, 3), "bpm": round(bpm, 2) if bpm else None,
           "beat_offset": round(beats[0], 4) if beats else None,
           "transition_frames": int(np.median(tr_frames) // 2 * 2) if tr_frames else TLEN_DEFAULT,
           "feel": max(set(eases), key=eases.count) if eases else "snappy",
           "cuts": cuts, "pulses": pulses, "text": text or [], "look": look, "look_segments": look_segs, "overlays": overlays, "hits": hits, "bars": bars,
           "audio": {"id": aud, "name": os.path.splitext(name)[0][:60]} if aud else None,
           "stats": dict(stats, cuts=len(cuts), thumps=len(pulses), overlays=len(overlays), looks=max(1, len(look_segs)),
                         push_ins=sum(1 for c in cuts if c.get("zoom")), cutout_scenes=sum(1 for c in cuts if c.get("backdrop")), speed_ramps=sum(1 for c in cuts if c.get("ramp")), false_cuts=found_cuts - len(events), avg_shot=round(total / max(1, len(cuts)), 3), transitions=hist,
                         on_beat=round(float(np.mean([c.get("on_beat", False) for c in cuts[1:]])), 2) if beats and len(cuts) > 1 else None)}
    tpl["engine"] = {"passes": TPL_NPASS, "version": 2, "confidence_min": TPL_CONF_MIN, "audit": audit}
    for c_, e_ in zip(cuts[1:], events):               # (the frames of each transition window: the accuracy pass compares exactly these)
        c_["transition"]["window"] = [int(e_[1]), int(e_[2])]
    _tp(job, 0)
    tpl["passes"] = [dict(p_) for p_ in job.get("log", [])]
    return tpl




# ---------------------------------------------------------------------------
# Pass 15: the accuracy score. The template is rendered by Kiru's real renderer onto stills of the reference (one calm
# frame per shot, its text painted out), with everything the template says: cuts, transitions, thumps, text. That render
# is then compared with the reference, frame for frame. Four numbers, each 0..1:
#   shots        is the right shot on screen on every frame (a cut in the wrong place shows the wrong picture)
#   transitions  inside every transition: the camera's measured path, the brightness and the sharpness, render against reference
#   thumps       zoom and brightness jolts inside the shots, render against reference
#   text         the letters themselves (their edges) inside every text's box, render against reference
# ---------------------------------------------------------------------------
TPL_SCORE_W = {"shots": 0.30, "transitions": 0.30, "thumps": 0.15, "text": 0.25}


def _tpl_small(path, w, h, dur, job=None):
    """Every frame at 30 fps, forced to w x h (BGR uint8)."""
    import numpy as np
    cmd = ["ffmpeg", "-v", "error", "-i", path, "-t", f"{dur:.3f}", "-an", "-vf", f"fps={TPL_FPS},scale={w}:{h}:flags=area,setsar=1", "-pix_fmt", "bgr24", "-f", "rawvideo", "-"]
    proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, creationflags=NO_WINDOW)
    size, out = w * h * 3, []
    while True:
        buf = proc.stdout.read(size)
        if len(buf) < size:
            break
        out.append(np.frombuffer(buf, np.uint8).reshape(h, w, 3))
        if job is not None and job.get("cancel"):
            proc.kill()
            raise Cancelled()
    proc.wait()
    if len(out) < 4:
        raise RuntimeError("the preview render could not be read")
    return np.stack(out)


def _tpl_still_frames(tpl):
    """For every shot of the template: the frame of the reference that stands for it (calm, away from its transitions and thumps)."""
    cuts = tpl["cuts"]
    n = int(round(tpl["duration"] * TPL_FPS))
    thump = [int(round(p["t"] * TPL_FPS)) for p in tpl.get("pulses") or []]
    out = []
    for k, c in enumerate(cuts):
        f0 = int(round(c["t"] * TPL_FPS))
        f1 = int(round(cuts[k + 1]["t"] * TPL_FPS)) if k + 1 < len(cuts) else n
        lo = ((c.get("transition") or {}).get("window") or [f0, f0])[1] + 2 if k else 1
        hi = ((cuts[k + 1].get("transition") or {}).get("window") or [f1, f1])[0] - 2 if k + 1 < len(cuts) else n - 2
        lo, hi = max(f0, min(lo, f1 - 1)), min(f1 - 1, max(hi, f0))
        if hi < lo:
            lo = hi = (f0 + f1) // 2
        f = (lo + hi) // 2
        for _ in range(12):                               # not on a thump
            if not any(-2 <= f - t <= 6 for t in thump) or f + 1 > hi:
                break
            f += 1
        out.append(int(max(0, min(n - 1, f))))
    return out


def _tpl_ncc(a, b, keep=None):
    import numpy as np
    a, b = a.astype(np.float32), b.astype(np.float32)
    if keep is not None:                                  # only the pixels in "keep" are compared
        a, b = a[keep], b[keep]
        if a.size < 50:
            return 1.0
    sa, sb = float(a.std()), float(b.std())
    if sa < 3 and sb < 3:
        return 1.0 if abs(float(a.mean()) - float(b.mean())) < 40 else 0.0
    if sa < 3 or sb < 3:
        return 0.0
    return float(((a - a.mean()) * (b - b.mean())).mean() / (sa * sb))


def _tpl_score(ref, ren, tpl, job=None):
    import cv2
    import numpy as np
    pr = probe(ref)
    vs = next(x for x in pr.get("streams", []) if x.get("codec_type") == "video")
    rot = abs(int(float(((vs.get("side_data_list") or [{}])[0]).get("rotation", 0) or 0))) % 180 == 90
    sw, sh = (int(vs["height"]), int(vs["width"])) if rot else (int(vs["width"]), int(vs["height"]))
    dur = float(tpl["duration"])
    w = TPL_W
    h = max(2, int(round(w * sh / sw / 2)) * 2)
    say = (lambda t: job.update(detail=t)) if job is not None else (lambda t: None)
    say("Comparing: reading both videos")
    R, G = _tpl_small(ref, w, h, dur, job), _tpl_small(ren, w, h, dur, job)
    n = min(len(R), len(G))
    R, G = R[:n], G[:n]
    gR = np.stack([cv2.cvtColor(f, cv2.COLOR_BGR2GRAY) for f in R]).astype(np.float32)
    gG = np.stack([cv2.cvtColor(f, cv2.COLOR_BGR2GRAY) for f in G]).astype(np.float32)
    lR, lG = gR.reshape(n, -1).mean(axis=1), gG.reshape(n, -1).mean(axis=1)
    win = cv2.createHanningWindow((w, h), cv2.CV_32F)
    cuts = tpl["cuts"]
    cf = [int(round(c["t"] * TPL_FPS)) for c in cuts] + [n]
    wins = []
    for c in cuts[1:]:
        a, b = (c["transition"].get("window") or [int(round(c["t"] * TPL_FPS))] * 2)
        wins.append((max(1, int(a)), min(n - 2, int(b)), int(min(n - 2, max(1, round(c["t"] * TPL_FPS))))))
    inwin = np.zeros(n, bool)
    for a, b, _c in wins:
        if b - a >= 2:
            inwin[max(0, a - 1):min(n, b + 2)] = True
    # ---- shots: on every frame, is the render showing the shot the reference shows?
    say("Comparing: is the right shot on screen on every frame")
    stills = _tpl_still_frames(tpl)
    still_g = [gR[min(n - 1, f)] for f in stills]
    shot_of = np.zeros(n, int)
    for k in range(len(cuts)):
        shot_of[cf[k]:cf[k + 1]] = k
    vals = []
    tboxes = [(x["t0"] - 0.1, x["t1"] + 0.1, max(0, int((x["x"] - x.get("width", 0.3) * 0.6) * w)), min(w, int((x["x"] + x.get("width", 0.3) * 0.6) * w) + 1),
               max(0, int((x["y"] - x.get("height", 0.05) * max(1, x.get("lines", 1)) * 0.95) * h)), min(h, int((x["y"] + x.get("height", 0.05) * max(1, x.get("lines", 1)) * 0.95) * h) + 1))
              for x in (tpl.get("text") or [])]
    for i in range(0, n):
        if inwin[i]:
            continue
        k = int(shot_of[i])
        keep = None                                         # text is judged on its own (below): here only the picture around it counts
        act = [b_ for b_ in tboxes if b_[0] <= i / TPL_FPS <= b_[1]]
        if act:
            keep = np.ones((h, w), bool)
            for b_ in act:
                keep[b_[4]:b_[5], b_[2]:b_[3]] = False
            if keep.mean() < 0.3:
                continue
        best = max(_tpl_ncc(gR[i], still_g[q], keep) for q in range(max(0, k - 2), min(len(still_g), k + 3)))     # what a perfect still-based render could reach here
        got = _tpl_ncc(gR[i], gG[i], keep)
        if best < 0.25:
            continue                                        # (the reference itself looks like none of its stills here: nothing can be judged)
        vals.append(float(np.clip(got / best, 0.0, 1.0)))
    shots = float(np.mean(vals)) if vals else 1.0
    # ---- transitions: measured path + brightness + sharpness inside every window
    per_cut = []
    for q, (a, b, c) in enumerate(wins):
        if job is not None and job.get("cancel"):
            raise Cancelled()
        say(f"Comparing: transition {q + 1} of {len(wins)}")
        if b - a < 2:
            a2, b2 = max(1, c - 2), min(n - 2, c + 2)       # a plain cut: the two frames either side must be the right pictures, at the right brightness
            pic = float(np.mean([max(0.0, _tpl_ncc(gR[i], gG[i])) / max(0.25, max(_tpl_ncc(gR[i], s_) for s_ in still_g[max(0, q - 1):q + 3])) for i in (c - 1, c) if 0 <= i < n]))
            lum = 1.0 - min(1.0, float(np.abs(lR[a2:b2 + 1] - lG[a2:b2 + 1]).mean()) / 64.0)
            per_cut.append(round(float(np.clip(0.7 * min(1.0, pic) + 0.3 * lum, 0, 1)), 3))
            continue
        sR, sG = _tpl_series(gR, lR, a, b, n, win, cut=c), _tpl_series(gG, lG, a, b, n, win, cut=c)
        err = mag = 0.0
        for key, wgt in (("dx", 1 / 0.45), ("dy", 1 / 0.45), ("lz", 1 / 0.22), ("rot", 1 / 22.0)):
            pR, pG = np.cumsum(sR[key]), np.cumsum(sG[key])
            err += float(np.abs(pR - pG).mean()) * wgt
            mag += max(float(np.abs(pR).max()), float(np.abs(pG).max())) * wgt
        motion = 1.0 - min(1.0, err / (mag + 0.2))
        lum = 1.0 - min(1.0, float(np.abs(np.array(sR["lum"]) - np.array(sG["lum"])).mean()) / 64.0)
        shp = 1.0 - min(1.0, float(np.abs(np.clip(sR["sharp"], 0, 1.5) - np.clip(sG["sharp"], 0, 1.5)).mean()) / 0.6)
        per_cut.append(round(0.5 * motion + 0.25 * lum + 0.25 * shp, 3))
    trans = float(np.mean(per_cut)) if per_cut else 1.0
    # ---- thumps: zoom and brightness jolts inside the shots
    say("Comparing: the thumps inside the shots")
    def jolts(g):
        d = np.zeros(n)
        d[1:] = np.abs(g[1:] - g[:-1]).reshape(n - 1, -1).mean(axis=1)
        out = []
        for k in range(len(cuts)):
            a_, b_ = cf[k] + 2, cf[k + 1] - 2
            if b_ - a_ < 6:
                continue
            seg = d[a_:b_]
            base = float(np.median(seg))
            thr = max(4.0, 2.6 * base + 2.5)
            i = 0
            while i < len(seg):
                if seg[i] >= thr and not inwin[a_ + i] and seg[i] >= seg[max(0, i - 2):i + 3].max() - 1e-6:
                    out.append(a_ + i)
                    i += 4
                else:
                    i += 1
        return out
    jR, jG = jolts(gR), jolts(gG)
    used, tp = set(), 0
    for f in jR:
        m_ = next((q for q in jG if q not in used and abs(q - f) <= 2), None)
        if m_ is not None:
            used.add(m_)
            tp += 1
    thumps = 1.0 if not jR and not jG else 2.0 * tp / (len(jR) + len(jG))
    # ---- text: the letters' edges inside every text's box
    text = [x for x in (tpl.get("text") or []) if x.get("t1", 0) - x.get("t0", 0) >= 0.2]
    tvals = []
    if text:
        say("Comparing: every text, letter edges against letter edges")
        want = {}
        for x in text:
            for fr in (0.5, 0.8):
                want.setdefault(int(min(n - 2, max(1, round((x["t0"] + fr * (x["t1"] - x["t0"])) * TPL_FPS)))), []).append(x)
        hR, hG = _tpl_grab(ref, dur, want.keys(), job), _tpl_grab(ren, dur, want.keys(), job)
        for f, xs in want.items():
            A, B = hR.get(f), hG.get(f)
            if A is None or B is None:
                continue
            if B.shape != A.shape:
                B = cv2.resize(B, (A.shape[1], A.shape[0]), interpolation=cv2.INTER_AREA)
            H, W = A.shape
            for x in xs:
                bw, bh = x.get("width", 0.3) * W, x.get("height", 0.05) * H * max(1, x.get("lines", 1)) * 1.3
                pad = max(4, bh * 0.5)
                x0, x1, y0, y1 = int(max(0, x["x"] * W - bw / 2 - pad)), int(min(W, x["x"] * W + bw / 2 + pad)), int(max(0, x["y"] * H - bh / 2 - pad)), int(min(H, x["y"] * H + bh / 2 + pad))
                if x1 - x0 < 8 or y1 - y0 < 6:
                    continue
                ea = cv2.magnitude(cv2.Sobel(A[y0:y1, x0:x1].astype(np.float32), cv2.CV_32F, 1, 0), cv2.Sobel(A[y0:y1, x0:x1].astype(np.float32), cv2.CV_32F, 0, 1))
                eb = cv2.magnitude(cv2.Sobel(B[y0:y1, x0:x1].astype(np.float32), cv2.CV_32F, 1, 0), cv2.Sobel(B[y0:y1, x0:x1].astype(np.float32), cv2.CV_32F, 0, 1))
                # fine: letter outline against letter outline. coarse: where the ink is (place, size, line layout), whatever the typeface
                fine = _tpl_ncc(cv2.GaussianBlur(ea, (0, 0), 1.6), cv2.GaussianBlur(eb, (0, 0), 1.6))
                coarse = _tpl_ncc(cv2.GaussianBlur(ea, (0, 0), 4.5), cv2.GaussianBlur(eb, (0, 0), 4.5))
                tvals.append(float(np.clip(0.5 * fine + 0.5 * coarse, 0.0, 1.0)))
    parts = {"shots": shots, "transitions": trans, "thumps": thumps}
    if tvals:
        parts["text"] = float(np.mean(tvals))
    wsum = sum(TPL_SCORE_W[k] for k in parts)
    score = 100.0 * sum(TPL_SCORE_W[k] * v for k, v in parts.items()) / wsum
    return {"score": int(round(score)), "parts": {k: int(round(100 * v)) for k, v in parts.items()}, "per_cut": per_cut,
            "frames": int(n), "texts_compared": len(tvals), "min": TPL_SCORE_MIN}


def _tpl_drop(job):
    """An analysis is over (scored, cancelled or left behind): its copy of the reference goes."""
    _rm(job.pop("ref", None))
    for cid in job.pop("stills", None) or []:
        c = CLIPS.pop(cid, None)
        if c:
            _rm(c.get("path"))
            _rm(c.get("thumb"))


def tpl_job(jid, path, name):
    job = TPL_JOBS[jid]
    try:
        tpl = analyze_reference(path, name, job)
        if job.get("cancel"):
            raise Cancelled()
        job["template"] = tpl
        job["ref"] = path
        _tp(job, 15)
        # pass 15 needs Kiru's real renderer and the page's own text drawing: the page builds the preview, the engine compares it
        dict.update(job, status="render", detail="Rendering a preview of the template", pct=int(100 * 14 / TPL_NPASS))
    except Cancelled:
        dict.update(job, status="cancelled", stage="Cancelled")
        _rm(path)
    except Exception as e:
        import traceback
        traceback.print_exc()
        dict.update(job, status="error", error=str(e) or type(e).__name__)
        _rm(path)


def _tpl_finish(job, score=None, why=None):
    tpl = job.get("template")
    log = job.get("log") or []
    if log and "secs" not in log[-1]:
        log[-1]["secs"] = round(time.time() - log[-1].pop("_t"), 1)
    if tpl is not None:
        if score:
            tpl["score"] = score
            if log:
                log[-1]["found"] = f"accuracy {score['score']}% (" + ", ".join(f"{k} {v}%" for k, v in score["parts"].items()) + ")"
        else:
            tpl["score"] = None
            tpl["score_note"] = why or "The preview could not be rendered, so there is no score."
            if log:
                log[-1]["found"] = tpl["score_note"]
        tpl["passes"] = [{k: v for k, v in p.items() if k != "_t"} for p in log]
    _tpl_drop(job)
    dict.update(job, status="done", pct=100, stage="Done", detail="")


@app.post("/api/template/job/<jid>/stills")
def api_tpl_stills(jid):
    """Pass 15, step 1: one still of the reference per shot, its text painted out, as pictures the page can put on the cuts."""
    import cv2
    import numpy as np
    j = TPL_JOBS.get(jid)
    if not j or j.get("status") != "render" or not j.get("ref") or not os.path.isfile(j["ref"]):
        return err("That analysis is not waiting for its preview.", 404)
    tpl = j["template"]
    if not j.get("stills"):
        ids = []
        frames = _tpl_still_frames(tpl)
        for k, f in enumerate(frames):
            j.update(detail=f"Preparing the preview: shot {k + 1} of {len(frames)}")
            img = _tpl_frame_at(j["ref"], f / TPL_FPS)
            if img is None:
                img = np.zeros((int(tpl["source"]["height"]), int(tpl["source"]["width"]), 3), np.uint8)
            H, W = img.shape[:2]
            mask = np.zeros((H, W), np.uint8)
            for x in tpl.get("text") or []:
                if x["t0"] - 0.15 <= f / TPL_FPS <= x["t1"] + 0.15:
                    bw, bh = x.get("width", 0.3) * W * 1.12, x.get("height", 0.05) * H * max(1, x.get("lines", 1)) * 1.7
                    cv2.rectangle(mask, (int(x["x"] * W - bw / 2), int(x["y"] * H - bh / 2)), (int(x["x"] * W + bw / 2), int(x["y"] * H + bh / 2)), 255, -1)
            if mask.any() and mask.mean() < 0.6 * 255:
                img = cv2.inpaint(img, mask, 4, cv2.INPAINT_TELEA)
            uid = uuid.uuid4().hex[:12]
            p = os.path.join(UPLOAD_DIR, uid + ".png")
            cv2.imwrite(p, img)
            CLIPS[uid] = {"path": p, "play_path": p, "play_mime": "video/mp4", "name": f"shot {k + 1}.png", "duration": PHOTO_SECONDS, "width": W, "height": H,
                          "audio": False, "fps": 30.0, "kind": "photo", "status": "processing"}
            make_thumb(uid)
            convert_still(uid)
            ids.append(uid)
        j["stills"] = ids
    return jsonify(stills=[clip_json(c) for c in j["stills"]])


@app.post("/api/template/job/<jid>/score")
def api_tpl_score(jid):
    """Pass 15, step 2: the page has rendered the preview (render job id), or says why it could not. -> the finished template with its score."""
    j = TPL_JOBS.get(jid)
    if not j or j.get("status") != "render":
        return err("That analysis is not waiting for its preview.", 404)
    d = request.get_json(silent=True) or {}
    rj = JOBS.get(str(d.get("render") or ""))
    try:
        if not rj or rj.get("status") != "done" or not os.path.isfile(rj.get("path") or ""):
            _tpl_finish(j, None, str(d.get("why") or "The preview could not be rendered, so there is no score.")[:300])
        else:
            j.update(detail="Comparing the preview with the reference")
            if os.environ.get("KIRU_TPL_KEEP"):                 # (for looking at a preview by hand: KIRU_TPL_KEEP=<folder>)
                try:
                    shutil.copy(rj["path"], os.path.join(os.environ["KIRU_TPL_KEEP"], re.sub(r"[^A-Za-z0-9_]", "_", j["template"].get("name", "tpl")) + "_preview.mp4"))
                except OSError:
                    pass
            sc = _tpl_score(j["ref"], rj["path"], j["template"], j)
            _tpl_finish(j, sc)
    except Cancelled:
        dict.update(j, status="cancelled", stage="Cancelled")
        _tpl_drop(j)
    except Exception as e:
        import traceback
        traceback.print_exc()
        _tpl_finish(j, None, "The comparison failed: " + (str(e) or type(e).__name__)[:200])
    finally:
        if rj:
            _rm(rj.get("path"))
            JOBS.pop(str(d.get("render")), None)
    return jsonify(status=j["status"], template=j.get("template") if j["status"] == "done" else None)


def tpl_clean(t):
    """Keep only what a template may contain (it is plain data - never trusted, never executed)."""
    if not isinstance(t, dict) or not isinstance(t.get("cuts"), list) or not t["cuts"]:
        raise ValueError("That file isn't a Kiru template (no cuts in it).")
    if len(json.dumps(t)) > 4_000_000 or len(t["cuts"]) > 5000:
        raise ValueError("That template is too big.")
    t = dict(t)
    t["kiru_template"] = TPL_VERSION
    t["name"] = re.sub(r"[\x00-\x1f]", " ", str(t.get("name") or "Template"))[:60].strip() or "Template"
    return t


def _tpl_file(name):
    safe = re.sub(r"[^A-Za-z0-9 _.()\-]+", "_", name).strip(" .")[:60] or "template"
    return os.path.join(TPL_DIR, safe + ".json")


@app.get("/api/template/caps")
def api_tpl_caps():
    return jsonify(tpl_capabilities())


@app.post("/api/template/analyze")
def api_tpl_analyze():
    f = request.files.get("file")
    if not f or not f.filename:
        return err("Drop a reference video first.")
    try:
        import cv2  # noqa: F401
    except ImportError:
        return err("OpenCV is not installed. Close Kiru and run Start_Tool.bat again: it installs it.", 500)
    if any(j["status"] == "running" for j in TPL_JOBS.values()):
        return err("An analysis is already running.")
    for j in TPL_JOBS.values():                           # an analysis whose preview was never made (its window was closed): let go of its files
        if j.get("status") == "render":
            dict.update(j, status="cancelled", stage="Cancelled")
            _tpl_drop(j)
    _u, path = save_upload(f, WORK_DIR)
    jid = uuid.uuid4().hex[:12]
    TPL_JOBS[jid] = TplJob({"status": "running", "pct": 0, "stage": "Starting", "detail": "", "npass": None, "use_ocr": request.form.get("ocr", "1") != "0", "t0": time.time()})
    threading.Thread(target=tpl_job, args=(jid, path, f.filename), daemon=True).start()
    return jsonify(id=jid)


@app.get("/api/template/job/<jid>")
def api_tpl_job(jid):
    j = TPL_JOBS.get(jid)
    if not j:
        return err("Unknown job.", 404)
    return jsonify(status=j["status"], pct=j.get("pct", 0), stage=j.get("stage", ""), detail=j.get("detail", ""), npass=j.get("npass") or 0, passes=TPL_NPASS,
                   error=j.get("error"), template=j.get("template") if j["status"] in ("done", "render") else None, elapsed=round(time.time() - j["t0"], 1))


@app.post("/api/template/job/<jid>/cancel")
def api_tpl_cancel(jid):
    j = TPL_JOBS.get(jid)
    if j:
        j["cancel"] = True
        p = j.get("proc")
        if p:
            try:
                p.kill()
            except Exception:
                pass
        if j.get("status") in ("running", "render"):       # free at once: the worker stops at its next step and its result is thrown away
            was = j.get("status")
            dict.update(j, status="cancelled", stage="Cancelled")
            if was == "render":
                _tpl_drop(j)
    return jsonify(ok=True)


@app.get("/api/templates")
def api_tpl_list():
    """The template library: the templates folder next to app.py (yours to keep, share and edit)."""
    out = []
    if os.path.isdir(TPL_DIR):
        for fn in sorted(os.listdir(TPL_DIR)):
            if not fn.lower().endswith(".json"):
                continue
            try:
                with open(os.path.join(TPL_DIR, fn), encoding="utf-8") as fh:
                    t = tpl_clean(json.load(fh))
                out.append({"file": fn, "name": t["name"], "cuts": len(t["cuts"]), "duration": t.get("duration"), "bpm": t.get("bpm"),
                            "aspect": t.get("aspect"), "kind": (t.get("source") or {}).get("kind", "saved"), "text": len(t.get("text") or []),
                            "transitions": (t.get("stats") or {}).get("transitions"), "music": bool(_tpl_audio_path(t.get("audio"))),
                            "thumps": len(t.get("pulses") or []), "overlays": len(t.get("overlays") or [])})
            except Exception:
                continue
    return jsonify(templates=out, folder=TPL_DIR)


@app.get("/api/templates/<path:fn>")
def api_tpl_get(fn):
    p = os.path.join(TPL_DIR, os.path.basename(fn))
    if not os.path.isfile(p):
        return err("Not found.", 404)
    try:
        with open(p, encoding="utf-8") as fh:
            return jsonify(tpl_clean(json.load(fh)))
    except Exception as e:
        return err(str(e))


@app.post("/api/templates")
def api_tpl_save():
    try:
        t = tpl_clean(request.get_json(force=True))
    except (ValueError, TypeError) as e:
        return err(str(e))
    os.makedirs(TPL_DIR, exist_ok=True)
    p = _tpl_file(t["name"])
    src = _tpl_audio_path(t.get("audio"))
    if src:                                            # the template keeps its music: saved right next to the .json
        dst = os.path.splitext(p)[0] + os.path.splitext(src)[1]
        if os.path.abspath(src) != os.path.abspath(dst):
            shutil.copyfile(src, dst)
        t["audio"] = {"file": os.path.basename(dst), "name": str((t.get("audio") or {}).get("name") or t["name"])[:60]}
    else:
        t["audio"] = None
    with open(p, "w", encoding="utf-8") as fh:
        json.dump(t, fh, indent=1)
    return jsonify(ok=True, file=os.path.basename(p), folder=TPL_DIR, audio=t["audio"])


def _tpl_audio_path(a):
    """Where a template's music is: fresh from an analysis (work folder) or saved beside the template."""
    if not isinstance(a, dict):
        return None
    if a.get("file"):
        p = os.path.join(TPL_DIR, os.path.basename(str(a["file"])))
        if os.path.splitext(p)[1].lower() in (".m4a", ".mp3", ".wav", ".ogg", ".flac", ".aac") and os.path.isfile(p):
            return p
    if a.get("id") and re.fullmatch(r"[0-9a-f]{8,32}", str(a["id"])):
        p = os.path.join(WORK_DIR, f"tplaud_{a['id']}.m4a")
        if os.path.isfile(p):
            return p
    return None


@app.post("/api/template/backdrop")
def api_tpl_backdrop():
    """A flat studio backdrop for cut-out scenes (colour + soft dark corners), made as a PNG the page adds to the bin like any picture."""
    import numpy as np
    from PIL import Image
    import io
    body = request.get_json(force=True) or {}
    col = str(body.get("color") or "#f2efec")
    if not re.fullmatch(r"#[0-9a-fA-F]{6}", col):
        col = "#f2efec"
    vig = _fnum(body.get("vignette"), 35, 0, 100) / 100
    W, H = ORIENTS.get(body.get("orient"), ORIENTS["landscape"])
    w, h = W // 2, H // 2
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    d = np.hypot((xx - w / 2) / (w / 2), (yy - h / 2) / (h / 2)) / 1.41421
    k = 1 - vig * np.clip(d, 0, 1) ** 2.2
    rgb = np.array([int(col[i:i + 2], 16) for i in (1, 3, 5)], np.float32)
    img = Image.fromarray(np.clip(k[..., None] * rgb[None, None, :], 0, 255).astype(np.uint8), "RGB").resize((W, H), Image.BICUBIC)
    buf = io.BytesIO()
    img.save(buf, "PNG")
    return Response(buf.getvalue(), mimetype="image/png")


@app.post("/api/template/song")
def api_tpl_song():
    """A template project starts with the template's own music as its song."""
    body = request.get_json(force=True) or {}
    src = _tpl_audio_path(body.get("audio"))
    if not src:
        return err("This template's music file is missing (it lives next to the template in the templates folder).", 404)
    uid = uuid.uuid4().hex
    path = os.path.join(UPLOAD_DIR, uid + os.path.splitext(src)[1])
    shutil.copyfile(src, path)
    name = str((body.get("audio") or {}).get("name") or "Template music")[:60] + " (template music)"
    try:
        info = probe(path)
        play_path = path
        if audio_needs_play_copy(os.path.basename(path), info):
            play_path = os.path.join(UPLOAD_DIR, uid + "_play.wav")
            r = run(["ffmpeg", "-v", "error", "-y", "-i", path, "-vn", "-ac", "2", "-ar", "44100", play_path])
            if r.returncode != 0:
                raise RuntimeError("Could not convert the template music for playback.")
        peaks, rate, dur = song_peaks(path)
    except Exception as e:
        _rm(path)
        return err(str(e))
    SONGS[uid] = {"path": path, "play_path": play_path, "name": name, "duration": dur, "from_template": True}
    return jsonify({"id": uid, "name": name, "url": f"/media/song/{uid}", "duration": round(dur, 4), "peaks": peaks, "peakRate": rate, "fromTemplate": True})


@app.delete("/api/templates/<path:fn>")
def api_tpl_del(fn):
    base = os.path.splitext(os.path.join(TPL_DIR, os.path.basename(fn)))[0]
    for ext in (".json", ".m4a", ".mp3", ".wav"):
        _rm(base + ext)
    return jsonify(ok=True)


